  str_homestory_chat_14751007 = "딱히 희귀한 것도 아냐, 내가 알 정도니까.",
  str_homestory_chat_14751008 = "그래서 뭐냐니까?",
  str_homestory_chat_14751009 = "이제 좀 급해졌어? 근데 아쉽지만 알려줄 수 없어.",
  str_homestory_chat_14751010 = "내 연구에... 지금 필요한 게 있거든.",
  str_homestory_chat_14751011 = "너도 밀당이란 걸 하는구나...",
  str_homestory_chat_14751012 = "전부 다 히이로 님을 위해... 흠흠, 이 얘긴 됐고.",
  str_homestory_chat_14751013 = "네가 우람의 희과수 씨앗을 찾아주면 알려줄게.\n아주 공평하지?",
  str_homestory_chat_14751014 = "좋아, 바로 출발할게.",
  str_homestory_chat_13299999 = "안녕, 내 도움이 필요해?",
  str_homestory_chat_13201001 = "안녕, 안젤.",
  str_homestory_chat_13201002 = "딱히 도움이 필요한 건 아니고,\n그냥 인사하고 싶어서 온 거야.",
  str_homestory_chat_13201003 = "당신이 안부를 물어줘서 기뻐.",
  str_homestory_chat_13201004 = "그래도 도움이 필요하면 언제든 말해줘.",
  str_homestory_chat_13221001 = "무슨 문제라도 있어?",
  str_homestory_chat_13221002 = "응, PlayerName, 혹시 이곳의 건축 구조\n설계 이념에 대해 설명해 줄 수 있을까?",
  str_homestory_chat_13221003 = "모두가 편하게 지낼 수 있는 곳...",
  str_homestory_chat_13221004 = "설계 이념은 이거 딱 하나뿐이야.",
  str_homestory_chat_13221005 = "하지만 이 모퉁이는 그 설계 이념에 부합하지 않아.",
  str_homestory_chat_13221006 = "여기 부딪히는 사람이 생기지 않을까?",
  str_homestory_chat_13221007 = "모두가 편히 쉴 수 있는 곳?",
  str_homestory_chat_13221008 = "거창하게 설계 이념이라고 하기도 민망하지만 말이야.",
  str_homestory_chat_13221009 = "하지만 이 모퉁이는 사람들이 쉽게 부딪히게\n설계되어 있는걸.",
  str_homestory_chat_13221010 = "이러면 편히 쉬긴 힘들 것 같아.",
  str_homestory_chat_13221011 = "음, 어디 보자...",
  str_homestory_chat_13221012 = "이건 그래... 네 말이 맞아.",
  str_homestory_chat_13221013 = "규격에 안 맞는 구조물은 문제가 생기기 마련이야.",
  str_homestory_chat_13222001 = "오늘 날씨 진짜 좋네.",
  str_homestory_chat_13222002 = "초대해 줘서 고마워.",
  str_homestory_chat_13222003 = "볕도 잘 들고, 날씨도 좋고...",
  str_homestory_chat_13222004 = "빛의 신이 이곳을 보살펴 주고 있다는\n느낌이 들 정도야.",
  str_homestory_chat_13222005 = "그거 칭찬 같네.",
  str_homestory_chat_13222006 = "맞아. 마음에서 우러난 칭찬이야.",
  str_homestory_chat_13222007 = "여기가 점점 좋아지는 모습을 직접\n보게 되니까 정말 기뻐.",
  str_homestory_chat_13222008 = "그리고 당신과 함께 이곳을 지킬 수\n있다는 것도 영광이고.",
  str_homestory_chat_13222009 = "아, 고마워!",
  str_homestory_chat_13251001 = "이상한 섬광을 봤다고?",
  str_homestory_chat_13251002 = "응, 저번에 강가를 걷다가 강에서\n이상한 그림자를 봤어.",
  str_homestory_chat_13251003 = "그림자? 섬광이 아니고?",
  str_homestory_chat_13251004 = "정확히는 그림자도 있고 섬광도 있고,\n뭔가 이상한 물고기 같은 느낌이었어...",
  str_homestory_chat_13251005 = "물고기! 아주 이상한 물고기라 이거지?",
  str_homestory_chat_13251006 = "가서 확인해 봐.\n난 꽃가지 플로레나무의 씨앗을 좀 찾아볼게...",
  str_homestory_chat_13251007 = "잠깐만! 그거 내가 도와줄게!",
  str_homestory_chat_13252001 = "또 뭔가 발견한 거 있어?",
  str_homestory_chat_13252002 = "음... 아직은 거기뿐이야.",
  str_homestory_chat_13253001 = "더 발견한 거 있어?",
  str_homestory_chat_13253002 = "PlayerName, 가끔은 좀 쉬는 게 좋아.\n내일 다시 와 줘.",
  str_homestory_chat_15299999 = "안녕, PlayerName.",
  str_homestory_chat_15221001 = "나한테 무슨 할 말 있어?",
  str_homestory_chat_15221002 = "하고 싶은 말이 있긴 한데...",
  str_homestory_chat_15221003 = "일단은 자는 게 더 중요해. 괜찮지?",
  str_homestory_chat_15221004 = "...대화까지 거절할 정도로 게으른 거야?",
  str_homestory_chat_15222001 = "무슨 생각해?",
  str_homestory_chat_15222002 = "PlayerName, 이 대륙에서 나한테 가장\n잘 맞는 곳은 헤븐즈 밸리라고 생각하지 않아?",
  str_homestory_chat_15222003 = "왜 그렇게 생각하는데?",
  str_homestory_chat_15222004 = "헤븐즈 밸리에는 무자비한 착취도,\n끝이 안 보이는 잔업도 없잖아...",
  str_homestory_chat_15222005 = "그중에서도 가장 중요한 건 자고 싶은 만큼\n잘 수 있다는 거야!",
  str_homestory_chat_15222006 = "착취가 없어서?",
  str_homestory_chat_15222007 = "나쁘지 않은 대답이야. 정답은 아니지만.",
  str_homestory_chat_15222008 = "헤븐즈 밸리에서 낮잠 자기 딱 좋은 장소를\n네 곳이나 발견했는데.",
  str_homestory_chat_15222009 = "저녁이 될 때까지 자도 깨우는 사람이 없더라고.",
  str_homestory_chat_15222010 = "헤븐즈 밸리가 무척 마음에 든 모양이네.",
  str_homestory_chat_15222011 = "이 세상에 헤븐즈 밸리가 마음에 안 드는\n사람은 없을걸!",
  str_homestory_chat_15223001 = "지금 바빠?",
  str_homestory_chat_15223002 = "아! PlayerName, 내가 꾸구구하지 않기\n챌린지 리스트를 만들어 봤거든. 같이 도전해 볼래?",
  str_homestory_chat_15223003 = "너... 갑자기 부지런해지니까 다른 사람 같잖아.",
  str_homestory_chat_15223004 = "어디 보자...",
  str_homestory_chat_15223005 = "꾸구구 안 하고 제때 자기... 꾸구구 안 하고 산책하기...",
  str_homestory_chat_15223006 = "꾸구구 안 하고 유통기한이 다 돼가는 감자칩 먹기...",
  str_homestory_chat_15223007 = "참 너답다...",
  str_homestory_chat_15223008 = "칭찬해 줘서 고마워.",
  str_homestory_chat_15223009 = "그게 무슨 챌린지야!",
  str_homestory_chat_15223010 = "「꾸구구 안 하고 산책」만 해도\n엄청 도전적이잖아...",
  str_homestory_chat_15251001 = "무슨 특별한 물고기를 봤다면서?",
  str_homestory_chat_15251002 = "저번에 강가에서 빈둥거릴... 구!\n어떻게 하면 더 열심히 일할까 생각하고 있을 때...",
  str_homestory_chat_15251003 = "어떻게 하면 더 빈둥거릴지 생각한 거겠지.",
  str_homestory_chat_15251004 = "구! 일이라고! 일!\n아무튼 물고기 얘기로 돌아가자. 관심 없어?",
  str_homestory_chat_15251005 = "있어.",
  str_homestory_chat_15251006 = "하지만 내 일을 마치려면 필요한 것들이 있어. 구구!",
  str_homestory_chat_15251007 = "그래. 그럴 줄 알았다니까... 뭐가 필요해?",
  str_homestory_chat_15251008 = "짧은잎 애시르나무 씨앗이 필요해.",
  str_homestory_chat_15251009 = "지금 바로 찾아올게.",
  str_homestory_chat_14899999 = "나한테 인사한 거야?",
  str_homestory_chat_14801001 = "응, 맞아.",
  str_homestory_chat_14801002 = "인사하는 게... 뭐 잘못됐어?",
  str_homestory_chat_14801003 = "아니, 근데 난 멈춰서 인사나 할 정도로\n한가하지 않거든.",
  str_homestory_chat_14801004 = "처리해야 할 일들이 무척 많으니까 말이야.",
  str_homestory_chat_14801005 = "야... 지금 이런 식으로 대화를 끝내겠다는 거야?",
  str_homestory_chat_14801006 = "할 말이 있었으면 처음부터 말했어야지.",
  str_homestory_chat_14821001 = "뭐 찾아?",
  str_homestory_chat_14821002 = "로빈 봤어?",
  str_homestory_chat_14821003 = "로빈! 로빈!",
  str_homestory_chat_14821004 = "못 봤는데...",
  str_homestory_chat_14821005 = "급하게 찾는 거야? 내가 도와줄게.",
  str_homestory_chat_14821006 = "당연히 급하지.\n벌써 10분이나 로빈을 못 봤단 말이야!",
  str_homestory_chat_14821007 = "이렇게 오랫동안 로빈을 못 본 적은 없었어!",
  str_homestory_chat_14821008 = "저기... 그건 좀 오버 같은데...",
  str_homestory_chat_14821009 = "저기 있잖아...",
  str_homestory_chat_14821010 = "근데 왜 넌 볼 때마다 로빈을 찾고 있는 것 같지?",
  str_homestory_chat_14821011 = "무슨 뜻이야? 하고 싶은 말이 뭐야?",
  str_homestory_chat_14821012 = "아, 아니야. 그냥 해 본 소리야...",
  str_homestory_chat_14821013 = "얼른 로빈 찾으러 가 봐...",
  str_homestory_chat_14822001 = "멍때리는 중이야?",
  str_homestory_chat_14822002 = "음... 여긴 뭐 재미있는 거 없어?",
  str_homestory_chat_14822003 = "「재미있는 거」?",
  str_homestory_chat_14822004 = "골동품 꽃병이라든가,\n고대 문자가 새겨진 돌이라든가...",
  str_homestory_chat_14822005 = "그런 거 있어?",
  str_homestory_chat_14822006 = "있지!",
  str_homestory_chat_14822007 = "다음에 갖다줄게.",
  str_homestory_chat_14822008 = "나쁘지 않네. 네가 보물찾기 동반 서비스도\n제공하는 줄은 몰랐어.",
  str_homestory_chat_14822009 = "없는데...",
  str_homestory_chat_14822010 = "역시 예상대로네.",
  str_homestory_chat_14822011 = "됐어. 없다고 무슨 큰일 나는 것도 아니니까.",
  str_homestory_chat_14823001 = "너 심심해 보이네.",
  str_homestory_chat_14823002 = "따분해. 전투도 없고.",
  str_homestory_chat_14823003 = "피비린내 나는 일상은 지겨워졌으니까,\n이제 평온한 날들을 보낼 때가 됐다고 했던 건...",
  str_homestory_chat_14823004 = "어디 사는 누구실까?",
  str_homestory_chat_14823005 = "그래, 그래. 네 말이 맞아.",
  str_homestory_chat_14823006 = "비켜봐.",
  str_homestory_chat_14823007 = "뭐 하려고?",
  str_homestory_chat_14823008 = "나무를 좀 베면 손이 근질거리는 것도\n좀 나아지겠지...",
  str_homestory_chat_14823009 = "그러고 나면 다시 평온한 날들을 보낼 수 있을 거야.",
  str_homestory_chat_14823010 = "잠깐! 환경 파괴는 안 돼!",
  str_homestory_chat_14824001 = "새로운 계획 있어?",
  str_homestory_chat_14824002 = "계획? 전혀 생각 안 하는데.",
  str_homestory_chat_14824003 = "매일 계획대로 살면 재미없잖아.",
  str_homestory_chat_14824004 = "설마 넌 매일 계획대로 살고 있는 거야?",
  str_homestory_chat_14824005 = "맞아!",
  str_homestory_chat_14824006 = "매일 계획을 세우면 뭔가 안심이 되거든.",
  str_homestory_chat_14824007 = "PlayerName 너 그런 생각을 하고\n있었단 말이야?",
  str_homestory_chat_14824008 = "난 네가 좀 더 제멋대로인 녀석일 줄 알았는데!",
  str_homestory_chat_14824009 = "아니...",
  str_homestory_chat_14824010 = "아무리 계획해도 계획 밖의 일이 벌어지거든.",
  str_homestory_chat_14824011 = "그렇다니까!",
  str_homestory_chat_14824012 = "매일 다른 일이 일어나야 기대하는\n재미가 있는 법이야!",
  str_homestory_chat_14825001 = "옷을 사고 싶다고?",
  str_homestory_chat_14825002 = "너네 헤븐즈 가든에든 옷 가게가 없는 것 같던데?",
  str_homestory_chat_14825003 = "그야 필요하지 않으니까... 디나 너, 옷이 필요하면 움브라톤에 가면 되잖아?",
  str_homestory_chat_14825004 = "너 사주려고 그러지, 배잡이.",
  str_homestory_chat_14825005 = "하아? 나한테?",
  str_homestory_chat_14825006 = "왜?",
  str_homestory_chat_14825007 = "맨날 똑같은 옷만 입는 게 보기 지겨워서 그러지.",
  str_homestory_chat_14825008 = "아... 듣고 보니 좀 그렇겠네.",
  str_homestory_chat_14825009 = "필요 없어.",
  str_homestory_chat_14825010 = "그래서 나랑 움브라톤에 갈래 말래?",
  str_homestory_chat_14825011 = "생각해 볼게.",
  str_homestory_chat_14825012 = "생각할 게 뭐가 있어?\n그 옷으로 더 돌아다니면 츄브도 질려할걸.",
  str_homestory_chat_14826001 = "연습?",
  str_homestory_chat_14826002 = "가끔 칼 쓰는 연습을 좀 해야 하는데,\n물고기랑 나무 가지고 할 순 없잖아.",
  str_homestory_chat_14826003 = "아, 그럼 저 나무에 생긴 자국... 네가 그런 거였구나...",
  str_homestory_chat_14826004 = "스파링 상대 좀 찾아 줘!",
  str_homestory_chat_14826005 = "여긴 없어.",
  str_homestory_chat_14826006 = "역시 나무를 쓰는 게 좋겠어.",
  str_homestory_chat_14826007 = "아니면... 바위?",
  str_homestory_chat_14826008 = "대충 넘어가려는 거야? 배잡이.",
  str_homestory_chat_14826009 = "여긴 평화로운 곳이야. 여기 왔을 땐 편안해야 한다구.",
  str_homestory_chat_14826010 = "그럼 내가 알아서 찾아야지 뭐.\n츄브들도 나쁘지 않겠네!",
  str_homestory_chat_14826011 = "움직임도 느리고, 반격도 안 하고,\n거기다 꽤나 튼튼해 보이니까.",
  str_homestory_chat_14826012 = "제발 하지 마!",
  str_homestory_chat_12299999 = "날씨가 참 좋네. 디젤 오일 한잔할래?",
  str_homestory_chat_12221001 = "사양할게.",
  str_homestory_chat_12221002 = "진짜 맛있는 빈티지 디젤 오일인데...\n진짜 한 모금도 안 마실 거야?",
  str_homestory_chat_12221003 = "빈티지 디젤 오일이라니... 정말 이해가 안 되네.",
  str_homestory_chat_12222001 = "넌 여기가 어떤 것 같아?",
  str_homestory_chat_12222002 = "꽤 괜찮은 곳이지만...",
  str_homestory_chat_12222003 = "디젤 오일값이 좀 비싸.",
  str_homestory_chat_12222004 = "먼 곳에서 운송해 와야 하니까 당연히 그렇겠지.",
  str_homestory_chat_12222005 = "일루미나 녀석들이 몰래 값을 올리고\n있는 게 분명해!",
  str_homestory_chat_12222006 = "...이걸 말을 해줘야 하나 말아야 하나...",
  str_homestory_chat_12222007 = "무슨 말인데 그래?",
  str_homestory_chat_12222008 = "그게 말이지...\n디젤 오일은 전부 다 레디젤 렌치 쪽에서 가져오는 거야.",
  str_homestory_chat_12222009 = "!!!",
  str_homestory_chat_12222010 = "화났어?",
  str_homestory_chat_12222011 = "알려줘서 고마워, 형씨...",
  str_homestory_chat_12222012 = "드디어 무료로 디젤 오일을 마실 수 있겠어!",
  str_homestory_chat_12223001 = "디젤 오일이 문제가 아닐 텐데...",
  str_homestory_chat_12223002 = "뭘 그렇게 두리번거리고 있어?",
  str_homestory_chat_12223003 = "형씨, 라비 봤어?",
  str_homestory_chat_12223004 = "라비는 왜 찾아?",
  str_homestory_chat_12223005 = "반나절이나 라비를 못 봐서...",
  str_homestory_chat_12223006 = "무슨 일이라도 생겼는데 내가 곁에서\n지켜주지 못했다면...",
  str_homestory_chat_12223007 = "난 평생을 후회하며 살 거야!",
  str_homestory_chat_12223008 = "형씨, 라비 좀 살려줘! 나도 좀 살려줘!",
  str_homestory_chat_12223009 = "...일단 진정해. 그건 다 네 망상이니까.",
  str_homestory_chat_11299999 = "안녕하세요.",
  str_homestory_chat_11201001 = "안녕, 네메시스 씨.",
  str_homestory_chat_11201002 = "오늘도 함께 정의를 실현하시겠습니까?",
  str_homestory_chat_11201003 = "네메시스 씨가 있으니까 여기가 더 안전해진 것 같아.",
  str_homestory_chat_11201004 = "당연하죠. 저는 아무리 작은 어둠이라도\n놓치지 않으니까요.",
  str_homestory_chat_11221001 = "요즘은 참 평화롭네.",
  str_homestory_chat_11221002 = "그렇습니다. 하지만 순찰 횟수를 줄일 수는 없습니다.",
  str_homestory_chat_11221003 = "그렇게까지 안 해도 돼.",
  str_homestory_chat_11221004 = "여기서는 다들 친구니까 치고받고 다툴 일은 없어.",
  str_homestory_chat_11221005 = "어느 정도는 일리 있는 말이군요.",
  str_homestory_chat_11221006 = "하지만 저는 집행자로서 불상사를 사전에\n방지해야만 합니다.",
  str_homestory_chat_11221007 = "좋은 생각이네.",
  str_homestory_chat_11221008 = "다들 친구인 건 맞지만 어느 정도는\n마찰이 생기기 마련이거든.",
  str_homestory_chat_11221009 = "서로 싸우는 건 좋지 않은 일이야.",
  str_homestory_chat_11221010 = "제가 하는 일의 가치를 인정해 주셔서 감사합니다.",
  str_homestory_chat_11221011 = "이곳의 평온함은 제가 지켜내겠습니다.",
  str_homestory_chat_11222001 = "무슨 일이야?",
  str_homestory_chat_11222002 = "헤븐즈 밸리의 환경을 파괴하는 녀석을\n방금 막 제재했습니다.",
  str_homestory_chat_11222003 = "음, 그 사람이 무슨 짓을 했는데?",
  str_homestory_chat_11222004 = "꽃밭에서 꽃을 꺾어 가려고 하더군요.",
  str_homestory_chat_11222005 = "그렇게 규칙을 파괴하는 행동은\n절대 용납할 수 없습니다!",
  str_homestory_chat_11222006 = "그래서 어떻게 했어?",
  str_homestory_chat_11222007 = "심판의 칼을 사용해서 5m 밖으로 날려 보냈습니다.",
  str_homestory_chat_11222008 = "음... 네메시스 씨, 이곳의 환경을 지켜줘서 고마워.",
  str_homestory_chat_11222009 = "대신 나도 꽃밭에 경고 팻말을 세워 둬야겠어...",
  str_homestory_chat_11222010 = "뭘 경고할 거죠?",
  str_homestory_chat_11222011 = "꽃을 꺾으면 아주 위험한 일이 일어날 거라고 말이야...",
  str_homestory_chat_11223001 = "기분이 무척 좋아 보이네...",
  str_homestory_chat_11223002 = "무슨 좋은 일이라도 있었어?",
  str_homestory_chat_11223003 = "길 잃은 고양이가 제 도움으로 주인을 찾았습니다.",
  str_homestory_chat_11223004 = "주인과 고양이 모두 제게 무척 고마워하더군요.",
  str_homestory_chat_11223005 = "오늘의 햇빛은 유난히 더 눈부시네요.",
  str_homestory_chat_11223006 = "확실히 아름다운 하루네.",
  str_homestory_chat_11223007 = "저희가 같은 경험을 할 수 있어서 정말 기쁩니다.",
  str_homestory_chat_11223008 = "이런 날 속에서 정의를 집행하고 타인을 돕는 것이야말로\n제가 해야 할 일이죠.",
  str_homestory_chat_11224001 = "사람을 더 뽑으려고 하는 거야?",
  str_homestory_chat_11224002 = "네, 이곳의 치안 유지를 위해 순찰대를\n하나 조직하려고 합니다.",
  str_homestory_chat_11224003 = "여긴 일루미나 연방이 아니니까... 좀 여유를 부려도 되는데.",
  str_homestory_chat_11224004 = "이대로면 정신이 해이해지고 말 것 같습니다.\n요즘은 제게도 그럴 기미가 보이기 시작했거든요...",
  str_homestory_chat_11224005 = "일하고 싶단 마음이 전혀 들지 않습니다.\n이런 상황이 지속돼서는 안 됩니다.",
  str_homestory_chat_11224006 = "그럼 가끔은 모두가 해이해지지 않도록 네메시스 씨가\n채찍질해 주는 역할을 맡으면 어떨까?",
  str_homestory_chat_11224007 = "좋은 생각입니다. 지금 당장 그렇게 하죠.",
  str_homestory_chat_11224008 = "엄청난 행동력이네!",
  str_homestory_chat_11225001 = "츄브들을 찾고 있다면서?",
  str_homestory_chat_11225002 = "네. 당신은 츄브들에 대해 어떻게 생각하나요?",
  str_homestory_chat_11225003 = "좋은 동료라고 생각해.",
  str_homestory_chat_11225004 = "그냥 동료일 뿐인가요...",
  str_homestory_chat_11225005 = "헤븐즈 가든의 건설자들이라고 생각해.",
  str_homestory_chat_11225006 = "건설자들이요?",
  str_homestory_chat_11225007 = "음, 당신은 아직 츄브들이 좋은 소질을 가지고\n있단 걸 눈치채지 못한 모양이군요.",
  str_homestory_chat_11225008 = "어떤 소질?",
  str_homestory_chat_11225009 = "규율을 잘 지키는 점이요.\n당신이 츄브들에게 명령을 내리면,\n저들은 모두 완수할 수 있잖아요.",
  str_homestory_chat_11225010 = "만약 츄브들로 치안대를 조직해 헤븐즈 가든의\n치안을 지키게 한다면... 정말 완벽할 겁니다.",
  str_homestory_chat_11225011 = "그렇지만 츄브들에게 의향을 물어보니,\n아쉽게도 다들 관심이 없는지\n「츄브」라고만 대답하더군요.",
  str_homestory_chat_11225012 = "관심이 없는 게 아니라 싫다는 걸 거야...",
  str_homestory_chat_11226001 = "혹시 뭐 생각 중이야?",
  str_homestory_chat_11226002 = "헤븐즈 가든에 규칙들을 좀 정해야 할지\n생각 중이었습니다.",
  str_homestory_chat_11226003 = "규칙들?",
  str_homestory_chat_11226004 = "쓰레기 분류라든가, 정해진 시간에 방 청소를\n한다든가 하는 것들이요.",
  str_homestory_chat_11226005 = "아무리 생각해도 그렇게 하면 헤븐즈 가든이\n점점 일루미나가 돼 버릴 거 같은데...",
  str_homestory_chat_11226006 = "여기서 생활하면서 마음에 안 드는 부분이라도 있는 거야?",
  str_homestory_chat_11226007 = "없습니다. 아주 편안해요.\n하지만 왠지 모르게 조금 적응이 안 됩니다.",
  str_homestory_chat_11226008 = "일을 조금이라도 하지 않으면\n밤에 잠을 통 못 잡니다.",
  str_homestory_chat_11226009 = "내가 보기엔... 네메시스 씨가 일루미나 생활에 너무 익숙해져서\n그런 거 같으니까, 여기엔 휴가를 온 거라고 생각해 봐.",
  str_homestory_chat_11226010 = "휴가도 일루미나에서 실시 중인 제도 중 하나인 만큼,\n네메시스 씨가 따라야 하는 거잖아.",
  str_homestory_chat_11226011 = "나름대로... 일리는 있군요.",
  str_homestory_chat_12599999 = "반갑군, 새로운 하루에는 새로운 아이디어가\n샘솟는 법이다.",
  str_homestory_chat_12521001 = "공연 이야기인가요?",
  str_homestory_chat_12521002 = "아... PlayerName,\n혹시 내 공연을 기대하고 있나?",
  str_homestory_chat_12521003 = "보는 눈이 있군.\n내 공연이 관객을 실망시킨 적은 단 한 번도 없지.",
  str_homestory_chat_12521004 = "...그 얘기를 하려던 건 아니었지만요...",
  str_homestory_chat_12521005 = "그래도 카론 씨가 공연하고 싶다면 뭐 문제없죠.",
  str_homestory_chat_12522001 = "극본 이야기인가요?",
  str_homestory_chat_12522002 = "대사 이야기다. 어디 들어 보겠나?",
  str_homestory_chat_12522003 = "이 말은 꼭 해야겠군. 네 심미안은 갈수록\n높아지고 있다.",
  str_homestory_chat_12522004 = "크흠. 이 칠흑 같은 밤에 나는 들었노라.\n마음이 산산이 부서지는 소리를...",
  str_homestory_chat_12522005 = "너무 슬픈 느낌 아니에요?",
  str_homestory_chat_12522006 = "그렇다. 화려한 표현 속에 가려져 있지만...",
  str_homestory_chat_12522007 = "사실 전하고자 하는 건 슬픔과 절망이지...",
  str_homestory_chat_12522008 = "그게 바로 우리가 사는 이 세상의 본모습이니까!",
  str_homestory_chat_12522009 = "PlayerName, 아무래도 내가 사람을\n제대로 본 것 같군.",
  str_homestory_chat_12522010 = "네 심미안은 나에게 감화되어 점차 높아지고 있다.",
  str_homestory_chat_12522011 = "너무 무서운 느낌 아니에요?",
  str_homestory_chat_12522012 = "무섭다고? 느끼지 못한 건가...?",
  str_homestory_chat_12522013 = "그 무서운 표현 속에 담긴 깊은 근심과 슬픔을!",
  str_homestory_chat_12522014 = "어... 못 느꼈어요...",
  str_homestory_chat_12522015 = "정말 유감이군. 방금 네게 내렸던 평가를 철회해야겠어.",
  str_homestory_chat_12523001 = "요즘 좀 어때요?",
  str_homestory_chat_12523002 = "PlayerName, 여긴 너무 좁지 않나?",
  str_homestory_chat_12523003 = "왜 좁은데요?",
  str_homestory_chat_12523004 = "피안호는 절대 이곳을 지나가지 못할 것 같단 말이다!",
  str_homestory_chat_12523005 = "분명히 벽이나 나무 같은 곳에 부딪히고 말 거다...",
  str_homestory_chat_12523006 = "안 부딪혀요.",
  str_homestory_chat_12523007 = "하지만 피안호가 지나기에 좁은 건 맞네요.",
  str_homestory_chat_12523008 = "그럼 설마 나의 피안호가 수고스럽게\n허공에 떠 있어야 한다는 말인가?",
  str_homestory_chat_12523009 = "잠깐만요! 그것보다 왜 사람이 지나다니는 곳에서\n기차를 몰려고 하는 건데요?!",
  str_homestory_chat_12524001 = "카론 씨한테 무슨 계획이 있다고 들었는데요...",
  str_homestory_chat_12524002 = "그렇다, PlayerName.\n이 공터에 뭔가 짓지 않겠나?",
  str_homestory_chat_12524003 = "뭘 짓는데요?",
  str_homestory_chat_12524004 = "무대...",
  str_homestory_chat_12524005 = "예술가인 나와 피안호의 무대 말이다!",
  str_homestory_chat_12524006 = "어떤가? 아주 격정적이면서도 창의적인 제안 아닌가?",
  str_homestory_chat_12524007 = "아무것도 안 지을 거예요.",
  str_homestory_chat_12524008 = "이 공터를 봐라, PlayerName.\n실로 창백해 보이지 않나?",
  str_homestory_chat_12524009 = "진정한 격정과 예술이 자신을 덧칠해 주기를\n기다리고 있지 않나!",
  str_homestory_chat_12524010 = "그래서요?",
  str_homestory_chat_12524011 = "그러니 무대를 하나 짓는 거다!\n예술가와 피안호를 위해서 말이야!",
  str_homestory_chat_12524012 = "음, 생각 좀 해 볼게요.",
  str_homestory_chat_12525001 = "오늘 무도회 말인데요...",
  str_homestory_chat_12525002 = "...오늘 밤에 무도회를 개최할 생각이냐?",
  str_homestory_chat_12525003 = "나는 참가하지 않겠다!\n악령 예술가의 운명은 바로 고독일지니!",
  str_homestory_chat_12525004 = "무척 가고 싶으신 것 같은데요...",
  str_homestory_chat_12525005 = "크흠, 잘못 본 것이다.",
  str_homestory_chat_12525006 = "허나 네가 굳이 초대한다면,\n얼굴 정도는 비춰 줄 수 있다...",
  str_homestory_chat_12525007 = "좋아요. 그럼 카론 씨는 싫지만\n제가 애써 초대하는 거라고 치죠.",
  str_homestory_chat_12525008 = "알겠어요. 그럼 다음에 또 연락할게요.",
  str_homestory_chat_12525009 = "...계속 초대하지 않는 거냐?",
  str_homestory_chat_12525010 = "알았어요...",
  str_homestory_chat_12525011 = "크흠, 카론 씨,\n오늘 밤 무도회에 꼭 참석해 주셨으면 좋겠어요.",
  str_homestory_chat_12525012 = "좋다. 그리 내키지는 않지만...\n나의 벗인 네 체면도 있으니 가도록 하지.",
  str_homestory_chat_12526001 = "하나 물어보고 싶은 게 있어요.",
  str_homestory_chat_12526002 = "호오? PlayerName의 질문이라면\n기꺼이 답해주지.",
  str_homestory_chat_12526003 = "대체 무엇이 널 곤란하게 하고 있는 거지?\n나의 친구여.",
  str_homestory_chat_12526004 = "다른 열차는 전부 선로 위를 달리는데...",
  str_homestory_chat_12526005 = "왜 카론 씨의 피안호는 선로에서 달리지 않는 거죠?!",
  str_homestory_chat_12526006 = "하하하, 좋은 질문이다!",
  str_homestory_chat_12526007 = "피안호는 내 친구이자 내 영감이다.\n그리고 영감이란 자유로운 것이지.",
  str_homestory_chat_12526008 = "선로 따위처럼 틀에 박힌 것에 얽매여서는\n자유라고 부를 수 없지 않겠나?",
  str_homestory_chat_12526009 = "그렇다고 헤븐즈 밸리를 멋대로 다니게 만들면 곤란하죠!",
  str_homestory_chat_10699999 = "PlayerName, 나랑 이야기하고 싶어?",
  str_homestory_chat_10601001 = "그래.",
  str_homestory_chat_10601002 = "물론 좋지만, 대신 네 시간도 주의해야 돼.",
  str_homestory_chat_10601003 = "이 뒤로도 할 일이 많잖아. 그걸 잊으면 안 돼.",
  str_homestory_chat_10621001 = "디저트 말인데...",
  str_homestory_chat_10621002 = "어떤 종류가 좋을지 조언 좀 해 줄래?",
  str_homestory_chat_10621003 = "디저트를 만들려고?",
  str_homestory_chat_10621004 = "응. 모두한테 간식을 만들어 주고 싶어서.",
  str_homestory_chat_10621005 = "음, 내 추천은 딸기 코코넛 밀크 케이크야...",
  str_homestory_chat_10621006 = "만들기 너무 힘들다면 다른 거로 바꿔도 돼.",
  str_homestory_chat_10621007 = "딸기 코코넛 밀크 케이크...",
  str_homestory_chat_10621008 = "카렌이 제일 좋아하는 디저트야?",
  str_homestory_chat_10621009 = "내가 먹고 싶은 게 아니라...\n그냥... 그냥 추천만 해 준 거야.",
  str_homestory_chat_10621010 = "이번에는 솜씨 좋은 사람이 도와주기로 했어!",
  str_homestory_chat_10621011 = "분명히 문제없을 거야.",
  str_homestory_chat_10621012 = "아무튼 다 만들고 나면 꼭 먹어줘!",
  str_homestory_chat_10622001 = "오늘 날씨 진짜 좋네!",
