  str_homestory_chat_10223005 = "「타분」이 뭔가요?",
  str_homestory_chat_10223006 = "검날에 묻어 있는 기름을 제거하기 위해\n가루봉으로 두들기는 작업입니다.",
  str_homestory_chat_10223007 = "에이카쿠를 관리하는 방법이라고 할 수 있죠.",
