  str_homestory_chat_10223009 = "조금 더 봐도 될까요?",
  str_homestory_chat_10223010 = "그럼요.",
  str_homestory_chat_10224001 = "정말 조용하네요...",
  str_homestory_chat_10224002 = "여긴 명상에 적합하죠.",
  str_homestory_chat_10224003 = "명상하기 좋은 곳을 발견하셨나 봐요?",
  str_homestory_chat_10224004 = "산기슭, 시냇가, 산속...\n눈을 감고 마음 깊은 곳을 들여다보는 겁니다.",
  str_homestory_chat_10224005 = "당신도 해 보세요. 당신의 역량을 길러줄 것입니다.",
  str_homestory_chat_10224006 = "음, 한번 해볼 만할 것 같긴 하네요.",
