  str_homestory_chat_10224010 = "하지만 여긴 시끄러운 속세와 멀리 떨어져 있으니,\n마음을 가라앉히기도 쉽겠군요.",
  str_homestory_chat_10224011 = "PlayerName, 당신도 해 보세요.",
