  str_homestory_chat_10225006 = "(아무래도 히이로 씨가 단련하는 데 내가 방해가 되는 모양이네.)",
  str_homestory_chat_10225007 = "그렇게 긴장하실 필요 없어요.",
  str_homestory_chat_10225008 = "여기서는 모두가 친구니까요.",
