  str_homestory_chat_14423007 = "영감이 다 메말라 버렸어...",
  str_homestory_chat_14423008 = "자신을 너무 몰아붙이지 말고 천천히 생각해 봐요.\n적당한 휴식이 있어야 좋은 거니까요.",
  str_homestory_chat_14423009 = "그렇지만 계획이 있다면 언제든 절 찾아와도 좋아요.",
  str_homestory_chat_14423010 = "목록을 적어 주시면 최고의 효율로 실현해 드릴게요.",
  str_homestory_chat_14424001 = "왜 그래?",
  str_homestory_chat_14424002 = "꼭 제대로 해명하라고 해야겠어요!",
  str_homestory_chat_14424003 = "어째서 일을 이런 식으로 처리했는지 말이에요!",
  str_homestory_chat_14424004 = "무슨 일 있었어?",
  str_homestory_chat_14424005 = "헤븐즈 가든 개조 계획을 위해\n해야 할 일도 잘 나누고...",
  str_homestory_chat_14424006 = "완료 시간까지 계산해서 책임자에게 분배했어요...",
  str_homestory_chat_14424007 = "그렇게 어려운 일도 아니었을 건데... 어째서...",
  str_homestory_chat_14424008 = "제시간에 못 하는 사람이 나올 수 있는 거죠?!",
  str_homestory_chat_14424009 = "그렇게 빡빡하게 안 해도 돼.",
  str_homestory_chat_14424010 = "안 돼요. 참을 수 없어요! 제대로 따질 거예요!",
  str_homestory_chat_14425001 = "무슨 제안 있어?",
  str_homestory_chat_14425002 = "최근 헤븐즈 가든 개조 계획 때문에\n저도 바쁘게 지내고 있어요.",
  str_homestory_chat_14425003 = "다만 사람마다 임무의 수행 효율이 달라서...",
  str_homestory_chat_14425004 = "매번 다양한 상황이 발생하고 있네요.",
  str_homestory_chat_14425005 = "예를 들면?",
  str_homestory_chat_14425006 = "도브는 매번 벌목 임무를 줄 때마다\n목표를 달성하지 못해요.",
  str_homestory_chat_14425007 = "아아... 그래야 도브답지.",
  str_homestory_chat_14425008 = "다들 도브가 열심히 일할 거라는 기대는 이미 버리고 있잖아.",
  str_homestory_chat_14425009 = "아무래도 제 헤븐즈 가든 개조 계획은\n아직 개선이 더 필요할 것 같네요.",
  str_homestory_chat_14425010 = "역시 성격이나 특성, 근무 습관을 고려해야겠어요!",
  str_homestory_chat_14425011 = "너, 너무 무리하지 마. 비비안 씨.",
  str_homestory_chat_12199999 = "아, 인사에서 당신의 무한한 애정이 느껴졌어요.",
  str_homestory_chat_12101001 = "그, 그 정도까지는...",
  str_homestory_chat_12101002 = "설마 이 애정을 부정하려는 건가요?",
  str_homestory_chat_12101003 = "제 마음이 장미 가시 같은 냉담함에\n피를 흘리네요...",
  str_homestory_chat_12101004 = "으으, 평범하게 좀 해주면 안 될까?!",
  str_homestory_chat_12101005 = "그냥 인사일 뿐이잖아!",
  str_homestory_chat_12121001 = "요즘 꽃 키우는 중이야?",
  str_homestory_chat_12121002 = "네, PlayerName. 제가 요즘 가꾸는\n장미 정원을 구경하러 오시겠어요?",
  str_homestory_chat_12121003 = "모든 꽃송이가 당신이 와 주기를 기다리고 있답니다.",
  str_homestory_chat_12121004 = "됐어...",
  str_homestory_chat_12121005 = "처리해야 할 일이 너무 많거든. 나중에 보러 갈게.",
  str_homestory_chat_12121006 = "와 주겠다고 약속했으니 안심이네요.",
  str_homestory_chat_12121007 = "꽃들과 절 실망하게 하지 말아 주세요.",
  str_homestory_chat_12121008 = "당연하지!",
  str_homestory_chat_12121009 = "여긴 햇볕이 가득하니까 원예 재능을\n마음껏 발휘할 수 있을 거야.",
  str_homestory_chat_12121010 = "아, 정말 너무 다정하시네요.",
  str_homestory_chat_12121011 = "그 말이 맞아요.\n여긴 자연의 아름다움이 가득하죠...",
  str_homestory_chat_12121012 = "저와 아주 잘 어울리는 곳이에요.",
  str_homestory_chat_12122001 = "왜 웃는 거야?",
  str_homestory_chat_12122002 = "아이들이 많이 들어왔군요...",
  str_homestory_chat_12122003 = "정말 기뻐요.",
  str_homestory_chat_12122004 = "아이들을 정말 좋아하나 봐?",
  str_homestory_chat_12122005 = "그럼요. 아이들의 천진한 눈과\n발그레한 볼을 보면...",
  str_homestory_chat_12122006 = "저도 모르게 다양한 꽃들이 생각나거든요.",
  str_homestory_chat_12122007 = "잘못 자라난 꽃가지처럼 말 안 듣는 아이가\n있긴 하지만...",
  str_homestory_chat_12122008 = "저는 그런 꽃을 보면 가차 없이 잘라내 버린답니다.",
  str_homestory_chat_12122009 = "음... 뭔가 엄청 무서운 이야기를 들은 것 같은데?",
  str_homestory_chat_11499999 = "PlayerName, 이렇게 만나니 반갑군.",
  str_homestory_chat_11401001 = "안녕하세요, 솔라드 성주님.",
  str_homestory_chat_11401002 = "그대의 터전에 초대해 주어 고맙다.",
  str_homestory_chat_11401003 = "별말씀을요. 대단한 일도 아닌걸요.",
  str_homestory_chat_11401004 = "그대가 통치하는 이곳이 앞으로 계속\n번영해 나가기를 바라마.",
  str_homestory_chat_11421001 = "솔라드 성주님은 여길 어떻게 생각하세요?",
  str_homestory_chat_11421002 = "질서정연하더군. 무척 공을 들였음을 알 수 있다.",
  str_homestory_chat_11421003 = "PlayerName, 이곳을 다스리다 보면\n어려움도 겪게 되겠지.",
  str_homestory_chat_11421004 = "도움이 필요하면 언제든 도와주겠다.",
  str_homestory_chat_11421005 = "진짜요? 정말 감사해요!",
  str_homestory_chat_11421006 = "이런 쪽으로는 성주님한테 많이 배워야겠네요.",
  str_homestory_chat_11421007 = "한 지역을 다스릴 때 질서는 모든 것의 핵심이 되지.",
  str_homestory_chat_11421008 = "질서는 냉혹할 수 있으나, 부족해서는 안 되는 법.",
  str_homestory_chat_11421009 = "(어... 토론이 시작되는 건가...)",
  str_homestory_chat_11421010 = "아직은 괜찮지 않을까요...",
  str_homestory_chat_11421011 = "다들 친구니까 「다스리다」라고 하기에는 좀 그렇겠죠.",
  str_homestory_chat_11421012 = "부디 그대의 방식으로도 이곳에 번영을\n선사할 수 있었으면 좋겠군.",
  str_homestory_chat_11422001 = "헤븐즈 가든에 오신 걸 환영해요.",
  str_homestory_chat_11422002 = "그대의 터전도 백야성과 같이 가슴이 후련해지는\n맑은 날씨를 가지고 있군.",
  str_homestory_chat_11422003 = "이런 날씨에 놓칠 수 없는 건...",
  str_homestory_chat_11422004 = "바로 낚시죠!",
  str_homestory_chat_11422005 = "강가에 앉아 사냥감이 낚이기를 기다리다니...",
  str_homestory_chat_11422006 = "이곳에서 유행하는 휴식 방식인가?",
  str_homestory_chat_11422007 = "한번 해보실래요?",
  str_homestory_chat_11422008 = "그것도 나쁘지 않겠지.",
  str_homestory_chat_11422009 = "바로 달리기죠!",
  str_homestory_chat_11422010 = "그것은 젊은이들의 운동이다.",
  str_homestory_chat_11422011 = "나는 즐겁게 구경하도록 하지.",
  str_homestory_chat_11423001 = "독서 중이신가요?",
  str_homestory_chat_11423002 = "이렇게 햇볕이 좋은 날에는 독서를 하는 것이\n좋은 소일거리다.",
  str_homestory_chat_11423003 = "PlayerName, 그대도 관심이 있다면\n책을 빌려주겠다.",
  str_homestory_chat_11423004 = "좋아요! 감사해요!",
  str_homestory_chat_11423005 = "성주님이 빠져드신 책이라면 분명히 재미있겠죠?",
  str_homestory_chat_11423006 = "나는 「재미」로 책을 읽지 않는다.",
  str_homestory_chat_11423007 = "오히려 책 속에서 끝없는 우주를 누비며\n인간의 깊은 본성을 탐구하는 것을 즐기지.",
  str_homestory_chat_11423008 = "허나 그대가 독서에 재미를 느낀다면,\n그것도 좋은 일이다.",
  str_homestory_chat_11423009 = "괜찮아요...",
  str_homestory_chat_11423010 = "책이라도 읽으면서 쉬고 싶지만 일이 너무 많네요...",
  str_homestory_chat_11423011 = "감당이 어렵다면 내게 부탁하는 것도\n좋은 선택이 될 것이다.",
  str_homestory_chat_12999999 = "어머... 역시 너였구나...",
  str_homestory_chat_12921001 = "응, 맞아.",
  str_homestory_chat_12921002 = "바람으로 네가 온다는 걸 알고 있었어.",
  str_homestory_chat_12921003 = "그런 게 가능하단 말이야?",
  str_homestory_chat_12921004 = "넌 특별한 기운을 가지고 있거든.",
  str_homestory_chat_12922001 = "무척 한가해 보이네.",
  str_homestory_chat_12922002 = "새장 안에서 햇볕을 쬐고 있으면\n재미있는 일들이 일어나곤 해...",
  str_homestory_chat_12922003 = "어떤 일들?",
  str_homestory_chat_12922004 = "얼굴의 어떤 부분은 뜨거워지고\n어떤 부분은 차가워져.",
  str_homestory_chat_12922005 = "왜 그렇게 되는 거야?",
  str_homestory_chat_12922006 = "그건 나도 모르겠어...",
  str_homestory_chat_12922007 = "생각하고 싶지 않아. 생각하는 건 너무 피곤해.",
  str_homestory_chat_12922008 = "새장 때문인가?",
  str_homestory_chat_12922009 = "새장이 얼굴에 그늘을 드리우면 햇볕이 안 닿으니까\n차가워지는 거지.",
  str_homestory_chat_12922010 = "네 말이 맞을 수도 있겠네.",
  str_homestory_chat_12922011 = "하지만 구분 짓고 싶지는 않아.\n생각하는 건 너무 피곤해.",
  str_homestory_chat_12923001 = "여기가 아주 마음에 든 모양이네.",
  str_homestory_chat_12923002 = "따뜻한 햇빛...",
  str_homestory_chat_12923003 = "...쿨... 맞아. 내가 솜뭉치가 된 것 같거든...",
  str_homestory_chat_12923004 = "...쿠울 ...으응, 나 안 자...",
  str_homestory_chat_12923005 = "(낮잠을 방해하지 않는 게 좋겠네.)",
  str_homestory_chat_12924001 = "뭐 해?",
  str_homestory_chat_12924002 = "들었어?",
  str_homestory_chat_12924003 = "여긴 소리가 가득해...",
  str_homestory_chat_12924004 = "계곡물, 숲, 계곡에서 다양한 소리가 들려.",
  str_homestory_chat_12924005 = "맞아.",
  str_homestory_chat_12924006 = "백야성에서 가장 많이 들리는 건 바람 소리야.\n다른 소리는 전부 오로리안들이 내는 거고.",
  str_homestory_chat_12924007 = "비교해보자면 난 이곳의 소리가 더 마음에 들어.",
  str_homestory_chat_12924008 = "난 하나도 안 들렸어.",
  str_homestory_chat_12924009 = "그렇게 말하니까 이제야 나도 느낀 것 같아...",
  str_homestory_chat_12924010 = "귀를 기울여 들으면 뜻밖의 즐거움이 생겨.",
  str_homestory_chat_12925001 = "나무?",
  str_homestory_chat_12925002 = "어머, 정확히는 목재야. 가볍고 튼튼한 걸로 어디 없을까?",
  str_homestory_chat_12925003 = "음... 갑자기 목재가 필요하다니, 뭐 만들려고 그래?",
  str_homestory_chat_12925004 = "지금 이 새장이 너무 크기도 하고 무거워서,\n개조해 볼 생각이야.",
  str_homestory_chat_12925005 = "하긴, 목재를 사용하면 가벼워질 테니까,\n힘이 지금보단 덜 들 것 같긴 한데.",
  str_homestory_chat_12925006 = "헤븐즈 가든에서 가볍고 튼튼한 목재를 구하긴 쉽지 않을 것 같아.",
  str_homestory_chat_12925007 = "여기엔 목재로 쓰긴 어려워 보이는 희한한 나무들만 자라고 있거든.",
  str_homestory_chat_12925008 = "그리고... 츄브들도 허락 안 해 줄걸.",
  str_homestory_chat_12926001 = "높은 곳?",
  str_homestory_chat_12926002 = "여기 어디 경치가 좋은 곳은 없을까 찾던 중이었거든.\n그래서 봤는데...",
  str_homestory_chat_12926003 = "헤븐즈 가든 전체가 내려다보일 정도로\n높은 곳이면 더 좋을 것 같았어.",
  str_homestory_chat_12926004 = "그래서 네게 물어보려고 한 거야.",
  str_homestory_chat_12926005 = "경치도 좋고 높은 곳이라면 있어.",
  str_homestory_chat_12926006 = "저기 저 바람의 탑이면 될까?",
  str_homestory_chat_12926007 = "하지만 츄브들이 허락해 주려나?",
  str_homestory_chat_12926008 = "안 해 줄게... 뻔하지.",
  str_homestory_chat_12926009 = "없는 것 같아.",
  str_homestory_chat_12926010 = "어머... 그럼 역시 무리겠네.",
  str_homestory_chat_12926011 = "뭘 하려고 했는데?",
  str_homestory_chat_12926012 = "새장을 높은 곳에 매달아서, 산들바람에 새장이 살랑이는\n느낌을 느껴 보려고 했어.",
  str_homestory_chat_12926013 = "그러면 기분이 참 좋아서 잠도 잘 오거든.",
  str_homestory_chat_12926014 = "바람이 살랑이면 잠이 잘 오는 건 맞는데,\n높은 곳은 바람이 세서 살랑이는 게 아니라 막 덜컹거릴걸.",
  str_homestory_chat_12926015 = "그렇네, 일리 있는 의견이야.",
  str_homestory_chat_12926016 = "그래서 말하는 건데, 아무래도 지금 이대로가 더 나을 것 같아.",
  str_homestory_chat_12699999 = "아... 나한테 너무 가까이 다가오지 마.",
  str_homestory_chat_12601001 = "왜?",
  str_homestory_chat_12601002 = "내 힘 때문에... 화상을 입을 거야...",
  str_homestory_chat_12601003 = "괜찮아, 조심할게.",
  str_homestory_chat_12601004 = "난... 너한테 상처입히기 싫어.",
  str_homestory_chat_12621001 = "이야기 좀 할래?",
  str_homestory_chat_12621002 = "이야기?",
  str_homestory_chat_12621003 = "무슨 이야기를 해야 하는데...? 잘 모르겠어...",
  str_homestory_chat_12621004 = "요즘에 했던 일이라든지?",
  str_homestory_chat_12621005 = "무의미한 일은 기억하지 않아...",
  str_homestory_chat_12621006 = "하지만 의미 있는 일은 뭘까? ...잘 모르겠어.",
  str_homestory_chat_12621007 = "요즘에 본 풍경에 대한 건?",
  str_homestory_chat_12621008 = "고폭 격납함 속의 새카만 그림자를\n말하는 거야...?",
  str_homestory_chat_12621009 = "가끔 내 불꽃 때문에 밝아지긴 하지만...",
  str_homestory_chat_12621010 = "으엑... 그, 그것도 풍경은 풍경이겠지.",
  str_homestory_chat_12622001 = "방금 뭐라고 했어?",
  str_homestory_chat_12622002 = "... 무슨 말을 해야 하지... 생각 좀 해볼게.",
  str_homestory_chat_12622003 = "저기... 잠깐만!",
  str_homestory_chat_12622004 = "...왜 그래?",
  str_homestory_chat_12622005 = "너 말이야, 또 다른 데 정신이 팔렸던 것 같아.",
  str_homestory_chat_12622006 = "...정신이 팔린 게 아니라...\n그냥... 생각 중이었어...",
  str_homestory_chat_12622007 = "나 같은 사람이랑 이야기하는 거 힘들지...?",
  str_homestory_chat_12622008 = "그래!",
  str_homestory_chat_12622009 = "자기만의 세계에 빠지더라도 가끔은 고개를 들고 우리도 봐줘...",
  str_homestory_chat_12622010 = "어렵지 않은 일이니까 한번 해 봐!",
  str_homestory_chat_12622011 = "아니야...",
  str_homestory_chat_12622012 = "가끔은 침묵이 긴장을 풀어주기도 하거든...",
  str_homestory_chat_12622013 = "함께 하는 이 순간을 마음껏 즐겨 봐.",
  str_homestory_chat_12623001 = "네 화염 제어환에 대해 얘기해 보자.",
  str_homestory_chat_12623002 = "그거? 그건 내 과거와 관계가 있는 거야...",
  str_homestory_chat_12623003 = "과거를 떠올리는 건 괴로운 일이야...",
  str_homestory_chat_12623004 = "그, 그럼 그 이야기는 하지 말자.",
  str_homestory_chat_12623005 = "하지만 괴로움을 참는 건 항상 있는 일이긴 해.",
  str_homestory_chat_12623006 = "너랑 얘기하는 것도 문제 될 건 없어.",
  str_homestory_chat_12624001 = "뭔가 새로운 일이라도 있어?",
  str_homestory_chat_12624002 = "...무슨 이야기를 하고 싶어?",
  str_homestory_chat_12624003 = "바이스 일행이 밖에서 요리를 만들다가\n실수로 냅킨에 불이 붙었는데...",
  str_homestory_chat_12624004 = "네가 화염 제어환으로 불을 꺼 줬다고 들었어.",
  str_homestory_chat_12624005 = "...맞아.",
  str_homestory_chat_12624006 = "화염 제어환은 불꽃을 흡수할 수 있으니까...",
  str_homestory_chat_12624007 = "진짜 멋있네!",
  str_homestory_chat_12624008 = "그래? 음... 칭찬해 줘서 고마워.",
  str_homestory_chat_12625001 = "요즘 어떻게 지내?",
  str_homestory_chat_12625002 = "좋지는 않아...",
  str_homestory_chat_12625003 = "호, 혹시 내 준비가 부족한 게 있었어?",
  str_homestory_chat_12625004 = "아니... 그냥 조금 곤란해서...",
  str_homestory_chat_12625005 = "헤븐즈 밸리는... 어딜 가도 나무랑 꽃들이 있어...",
  str_homestory_chat_12625006 = "깜빡 졸다 보면... 나도 모르게... 그만...",
  str_homestory_chat_12625007 = "풀밭이나 나무에 불을 붙여버려...",
  str_homestory_chat_12625008 = "뭐?!",
  str_homestory_chat_12625009 = "그래도... 그럴 때마다 내가 화염 제어환으로\n불꽃을 흡수하고 있어...",
  str_homestory_chat_12625010 = "대신, 풀밭에 탄 자국이 남아...",
  str_homestory_chat_12625011 = "괘, 괜찮아...",
  str_homestory_chat_12625012 = "풀은 타도 다시 자라니까!",
  str_homestory_chat_12625013 = "네가 다치거나 건물이 불타서 무너지지만 않으면 돼.",
  str_homestory_chat_14699999 = "안녕하세요.",
  str_homestory_chat_14601001 = "안녕, 다른 애들은?",
  str_homestory_chat_14601002 = "다른 일을 하고 있어요.",
  str_homestory_chat_14601003 = "조종사님은 할 일이 없나요?",
  str_homestory_chat_14601004 = "...갈게.",
  str_homestory_chat_14621001 = "식사했어?",
  str_homestory_chat_14621002 = "야채는 안 먹어요♪",
  str_homestory_chat_14621003 = "쓴맛은 싫으니까요♪",
  str_homestory_chat_14621004 = "야채는 건강에 좋은 거야!",
  str_homestory_chat_14621005 = "조종사님, 전 원래 건강해요.",
  str_homestory_chat_14621006 = "건강하지 않은 조종사님이나 야채를 먹어야죠.",
