  str_homestory_chat_14622001 = "요즘 책 좀 읽었어?",
  str_homestory_chat_14622002 = "동화책을 읽고 싶어요♪",
  str_homestory_chat_14622003 = "기나긴 하루가 힘들어요♪",
  str_homestory_chat_14622004 = "할 일을 좀 찾아서 하면 되잖아.",
  str_homestory_chat_14622005 = "조종사님, 동화책을 많이 읽어 두는 게 좋을 거예요.",
