  str_homestory_chat_12301001 = "그렇게 긴장할 거 없어.",
  str_homestory_chat_12301002 = "아, 알겠어요. 각오부터 하고 올게요...",
  str_homestory_chat_12301003 = "PlayerName, 안녕하세요!",
  str_homestory_chat_12301004 = "으앗! 너무 크잖아!",
  str_homestory_chat_12321001 = "연주할 수 있지?",
  str_homestory_chat_12321002 = "코놀리는 클라리넷의 실력자라고 들었거든.",
  str_homestory_chat_12321003 = "네? 뭐, 뭐라고요?\n파티를 위해 준비해야 하는 건가요?",
  str_homestory_chat_12321004 = "다들 네 연주를 듣고 싶어해.",
