  str_homestory_chat_12321006 = "하기 싫은 거야?",
  str_homestory_chat_12321007 = "아, 아니에요. 그저 조금 긴장이 돼서요...",
  str_homestory_chat_12321008 = "그래도 다들 기대하고 있다면 저도 노력할게요.",
  str_homestory_chat_12321009 = "널 믿어! 너라면 문제없을 거야!",
  str_homestory_chat_12321010 = "한번 해 봐!",
  str_homestory_chat_12321011 = "알, 알겠어요. 당신의 부탁이니까...",
