  str_homestory_chat_12322002 = "커, 커피라도 좀 마실래요?",
  str_homestory_chat_12322003 = "마시고 싶지 않아도 괜찮아요...\n그냥 쏟아버리면 되니까...",
  str_homestory_chat_12322004 = "마시고 싶어!",
  str_homestory_chat_12322005 = "하지만... 맛이 없다면...",
  str_homestory_chat_12322006 = "왜 쏟아버리려는 거야?",
  str_homestory_chat_12322007 = "커피 내리는 법을 배운 지 얼마 안 돼서\n많이 내렸거든요...",
  str_homestory_chat_12322008 = "음... 아무래도 쏟아버리는 게 좋겠어요.\n맛이 없을 수도 있으니까...",
  str_homestory_chat_12322009 = "잠깐 기다려!",
  str_homestory_chat_12322010 = "난 커피 맛 잘 모르니까 걱정 안 해도 돼.",
  str_homestory_chat_12322011 = "그냥 정신만 번쩍 들게 해 주면 되거든.",
  str_homestory_chat_12322012 = "알겠어요...",
  str_homestory_chat_12323001 = "왜 그래?",
  str_homestory_chat_12323002 = "눈이 부셔요...",
  str_homestory_chat_12323003 = "이곳의 햇볕은 정말 눈이 부시네요...",
  str_homestory_chat_12323004 = "조금 그늘진 곳이 있었더라면... 좋았을 텐데요.",
  str_homestory_chat_12323005 = "나무 그늘에 있으면 조금 편해?",
  str_homestory_chat_12323006 = "아, 아마도요...",
  str_homestory_chat_12324001 = "지금 누구랑 이야기하는 거야?",
  str_homestory_chat_12324002 = "...알겠어, 알겠어. 알았다니까... 으, 미안해!",
