  str_homestory_chat_12324006 = "절 믿어 주세요. 안톤은 다 좋은 아이들이에요!",
  str_homestory_chat_12324007 = "좋아!",
  str_homestory_chat_12324008 = "그럼 아이들을 부를게요...",
  str_homestory_chat_12325001 = "뭐 하고 있어?",
  str_homestory_chat_12325002 = "아, PlayerName 씨였군요...",
  str_homestory_chat_12325003 = "저... 여기 온 지도 이제 시간이 꽤 지났네요.\n그동안 많은 사람들의 도움을 받았어요...",
  str_homestory_chat_12325004 = "그래서 여러분한테 커피를 만들어\n드리고 싶은데요... 근데...",
  str_homestory_chat_12325005 = "뭐 곤란한 일이라도 있어?",
  str_homestory_chat_12325006 = "네... 여, 여러분들이 커피를 좋아하실지\n모르겠어서...",
  str_homestory_chat_12325007 = "그래서... 고민하고 있어요...",
  str_homestory_chat_12325008 = "너무 긴장할 거 없어, 코놀리!",
