  str_homestory_chat_13601002 = "인사만?",
  str_homestory_chat_13601003 = "...역시 네 따분한 인사에 대답해 주겠다고\n기운 내는 게 아니었어.",
  str_homestory_chat_13621001 = "요즘은 어때?",
  str_homestory_chat_13621002 = "여기 음식은 너무 싱거워서 개도 안 먹겠어.",
  str_homestory_chat_13621003 = "뭐 먹고 싶은데?",
  str_homestory_chat_13621004 = "아무거나 상관없어.",
  str_homestory_chat_13621005 = "아까 여기 음식이 싫다고 했던 건 누구더라?",
