  str_homestory_chat_14951004 = "알겠어! 대장.\n그나저나 여기서도 저 큰 새우를 보게 될 줄이야.",
  str_homestory_chat_14951005 = "정말 크네! 움브라톤에 갖다 팔면 꽤 짭짤하겠어!",
  str_homestory_chat_14951006 = "진짜?",
  str_homestory_chat_14951007 = "그래, 새우는 싸움을 잘해서 관상용으로 좋거든.",
  str_homestory_chat_14951008 = "새우들이 서로 치고받는 걸 보면,\n꼭 내 쌍검 같단 말이지...",
  str_homestory_chat_14951009 = "손이 근질근질해서 나도 모르게\n끼어들고 싶어진다고...",
  str_homestory_chat_14951010 = "너랑 새우랑은 체격 차이가 너무 크지 않나...",
  str_homestory_chat_14951011 = "그렇지, 그러니까 그냥 눈으로 보는 수밖에.\n아무튼 움브라톤에는 나랑 생각이 같은 사람이 많아.",
  str_homestory_chat_14951012 = "때로는 싸움의 과정 자체가 사람을 설레게 한다고!",
  str_homestory_chat_14951013 = "움브라톤에서는 인기가 많은가 봐?",
  str_homestory_chat_14951014 = "(이거 왠지 돈이 좀 될 수도 있겠는데...)",
  str_homestory_chat_14951015 = "세르고 넌 새우에 대해 잘 아는 모양이네?",
  str_homestory_chat_14951016 = "당연하지!\n일단 녀석의 이름은 「킹프라운」이라고 해.",
  str_homestory_chat_14951017 = "그리고 난 이미 녀석이 여러 곳에서\n출몰한다는 사실을 알아냈지.",
  str_homestory_chat_14951018 = "여러 곳에 있다고?!",
  str_homestory_chat_14951019 = "게다가 다른 종류도 있지.",
  str_homestory_chat_14951020 = "종류가 많아?",
  str_homestory_chat_14951021 = "많은 건 아니야. 딱 두 종류 있어.\n상대적으로 흔히 보이는 게 저 남색 새우고 말이야.",
  str_homestory_chat_14951022 = "맞아, 내가 본 것도 저거였어.",
  str_homestory_chat_14951023 = "그렇겠지. 남색 말고 갈색도 있는데,\n그게 고급 품종이거든.",
  str_homestory_chat_14951024 = "발견하기가 더 어려운 게 문제지만...",
  str_homestory_chat_14951025 = "어떻게 잡을 수 있는데?",
  str_homestory_chat_14951026 = "먼저 저 파란색 킹프라운이 있어야 돼.\n학명은 「인디고킹프라운」이야.",
  str_homestory_chat_14951027 = "그걸 가지고 있다면, 더 큰 갈색 킹프라운의\n낚시 포인트와 교환할 수 있어.",
  str_homestory_chat_14951028 = "그게 다야?",
  str_homestory_chat_14951029 = "이젠 흥정도 배운 거야?\n그럼 헤븐즈 가든 대장에겐 추가 보수를 줄게.",
  str_homestory_chat_14951030 = "아무튼 손해는 없을 거라고!",
  str_homestory_chat_14951031 = "근데 그 인디고킹프라운은 어디서 잡을 수 있는데?",
  str_homestory_chat_14951032 = "아? 본 적 있다면서?",
  str_homestory_chat_14951033 = "만일을 대비해서 다른 낚시 포인트도 알고 있으면 더 좋잖아?",
  str_homestory_chat_14951034 = "그래! 몇 군데 더 있긴 해.\n거길 가면 인디고킹프라운을 찾을 수 있을걸.",
  str_homestory_chat_14951035 = "대장 실력이라면 문제없을 거야.\n그걸 구해 오면 「파르메킹프라운」의\n낚시 포인트와 교환할 수 있어!",
  str_homestory_chat_14951036 = "그게 그 갈색 새우의 이름이구나...",
  str_homestory_chat_14951037 = "이제 다 알았겠지?\n대장 능력이라면 큰돈을 벌 게 분명해! 그럼 나도...",
