  str_homestory_chat_11722005 = "저번에 뚫어 놓은 구멍도 아직 안 메웠잖아!",
  str_homestory_chat_11722006 = "내가 계획한 지하 퇴로가 마음에 안 들어?",
  str_homestory_chat_11722007 = "그, 그건 아니야. 다만 뚫기 전에 얘기라도 해줬으면 좋겠어.",
  str_homestory_chat_11722008 = "알겠어, 알겠어! 기억해 둘게!",
  str_homestory_chat_11751001 = "그 물고기는 어디 있어?",
  str_homestory_chat_11751002 = "으아아아! 철수해야 해! 철수!",
  str_homestory_chat_11751003 = "철수해야겠다고? 갑자기 무슨 소리야...?",
  str_homestory_chat_11751004 = "나, 나 잡으러 온 거 아니었어?",
  str_homestory_chat_11751005 = "널 잡으러 왔냐니? 뭘 했길래 그래?",
  str_homestory_chat_11751006 = "그게... 땅굴 판 거 때문에 그러는 줄 알았지.\n철수할 때 편할 것 같아서 파둔 거거든.",
  str_homestory_chat_11751007 = "나중에 진짜 못 버틸 상태가 되면 그 땅굴로\n스르륵 도망... 아니, 철수하는 거지~",
  str_homestory_chat_11751008 = "그래, 고생이 많네.",
  str_homestory_chat_11751009 = "어쨌든 땅굴을 파다가 그 물고기를 보게 된 거야.\n아! 그 물고기 때문에 날 찾아온 거구나? 맞지?",
  str_homestory_chat_11751010 = "응? 맞아. 근데 땅굴 말인데, 그거 별 소용 없을 거야.\n츄브들이 또 막아 버렸거든.",
  str_homestory_chat_11751011 = "막아 버렸다고?!",
  str_homestory_chat_11751012 = "막아 버리면 철수를 어떻게 하란 거야!\n진짜로 뭔 일이라도 생기면 어쩌려고!!",
  str_homestory_chat_11751013 = "아무 일도 없을 거야.\n그리고 그 땅굴은 다 나한테 말도 없이 만든 거잖아.",
  str_homestory_chat_11751014 = "그렇긴 하지만...",
  str_homestory_chat_11751015 = "아무튼 물고기에 대해 물어보고 싶은데,\n어디서 본 거야? 땅굴 근처였어?",
  str_homestory_chat_11751016 = "여기서 거리가 좀 돼. 근데 땅굴을 판다고 힘들어서\n지금은 별로 말하고 싶지 않아...",
  str_homestory_chat_11751017 = "설마 알려주는 대신 뭘 달라고 하려는 건 아니지?",
  str_homestory_chat_11751018 = "당연히 받을 생각이었거든!\n나한테 큰잎 쿤란나무 씨앗을 줘.\n그럼 이번 일은 없던 걸로 해 줄게!",
  str_homestory_chat_11751019 = "철수 노선은 내가 다시 찾아보면 되니까!",
  str_homestory_chat_11751020 = "그래, 알겠어. 어쩌다 내가 잘못한 것처럼 돼 버린 거야...",
  str_homestory_chat_14099999 = "빠직빠직 캔디 먹을래?",
  str_homestory_chat_14001001 = "빠직빠직 캔디?",
  str_homestory_chat_14001002 = "진짜 사탕이야? 폭탄 같은 거 아니지?",
  str_homestory_chat_14001003 = "내가 먹는 거 한번 볼래?",
  str_homestory_chat_14001004 = "근데 내가 한입에 다 먹어버릴 수도 있겠네.",
  str_homestory_chat_14021001 = "안녕, 무슨 일 있어?",
  str_homestory_chat_14021002 = "PlayerName, 쓰레기 분리수거를\n홍보하는 게 좋겠어.",
  str_homestory_chat_14021003 = "왜?",
  str_homestory_chat_14021004 = "쓰레기가 다 섞어 있으니까 불편하잖아.",
  str_homestory_chat_14021005 = "음, 좋은 생각이네.",
  str_homestory_chat_14021006 = "그럼 빨리 안 움직이고 뭐 해?",
  str_homestory_chat_14021007 = "나한테 도와달라고 해도 돼.",
  str_homestory_chat_14021008 = "이렇게 서둘러서 해야 할 일이야?",
  str_homestory_chat_14021009 = "쓰레기 속에 쓸만한 게 있을까 해서 뒤져 봤는데...\n손에 칠리소스만 잔뜩 묻었잖아.",
  str_homestory_chat_14021010 = "당연히 짜증 나지 않겠어?",
  str_homestory_chat_14022001 = "나 찾았어?",
  str_homestory_chat_14022002 = "PlayerName, 파티는 언제 열 거야?",
  str_homestory_chat_14022003 = "며칠 뒤에...",
  str_homestory_chat_14022004 = "불꽃놀이도 할 거야?",
  str_homestory_chat_14022005 = "빨리 「필요」하다고 말해!",
  str_homestory_chat_14022006 = "필... 잠깐, 내가 왜 필요한데?",
  str_homestory_chat_14022007 = "당연히 내가 새 폭죽을 실험해 보고 싶으니까!",
  str_homestory_chat_14022008 = "아직 그럴 계획은 없어.",
  str_homestory_chat_14022009 = "안 돼, 꼭 있어야 돼!",
  str_homestory_chat_14022010 = "그렇지 않으면 난 어디 가서 새 폭죽을\n실험하라는 거야?",
  str_homestory_chat_14022011 = "저기... 아무 공터나 찾아서 쏘면 되잖아!",
  str_homestory_chat_14022012 = "...그 말 무르기 없기야.",
  str_homestory_chat_14022013 = "...잠깐, 방금 그 말 취소해도 될까...?",
  str_homestory_chat_14023001 = "뭐 하고 있어?",
  str_homestory_chat_14023002 = "PlayerName, 내가 새로 만든 폭탄 좀 볼래?",
  str_homestory_chat_14023003 = "싫어.",
  str_homestory_chat_14023004 = "지난번에는 나무를 하나 날려 버렸고...",
  str_homestory_chat_14023005 = "또 저번에는 언덕을 반이나 날라 버렸잖아...",
  str_homestory_chat_14023006 = "이번에는 또 어딜 파괴하려고?",
  str_homestory_chat_14023007 = "...굳이 파괴하려고 했던 건 아니야!",
  str_homestory_chat_14023008 = "「굳이」는 아니지, 「고의」지!",
  str_homestory_chat_15199999 = "우리한테 인사하다니...\n보드게임이라도 하고 싶어진 거야?",
  str_homestory_chat_15121001 = "아니, 요즘 어떻게 지내?",
  str_homestory_chat_15121002 = "PlayerName, 편하게 지내길 바란다면\n최소한 먹을 거라도 준비해 줘야 하는 게 아닐까?",
  str_homestory_chat_15121003 = "먹을 게 아직도 부족해?",
  str_homestory_chat_15121004 = "부족한 게 아니라 먹을 게 없어.",
  str_homestory_chat_15121005 = "뭘 먹고 싶은데?",
  str_homestory_chat_15121006 = "일단 5년 정도 숙성된 빈티지 엔진오일 10캔이랑...",
  str_homestory_chat_15121007 = "트리거 기름때 5드럼 정도.",
  str_homestory_chat_15122001 = "아주 한가해 보이네.",
  str_homestory_chat_15122002 = "맞아. 여기 오래 머물렀더니 기관총이 다 녹슬었어.",
  str_homestory_chat_15122003 = "고쳐 달라고 하면 되잖아?",
  str_homestory_chat_15122004 = "수리는 가능한데 그게 근본적인\n처치 방법은 아니거든.",
  str_homestory_chat_15122005 = "사실 녹은 따분해서 생기는 거니까.",
  str_homestory_chat_15122006 = "내 생각에는 사격장을 세우는 게 좋을 것 같아.",
  str_homestory_chat_15122007 = "뭐 좋은 방법 있어?",
  str_homestory_chat_15122008 = "사격장을 세우면 어떨까?\nPlayerName, 한 번 고려해 봐.",
  str_homestory_chat_15122009 = "그래, 생각해 볼게.",
  str_homestory_chat_15123001 = "보드게임?",
  str_homestory_chat_15123002 = "내기도 할 수 있어!",
  str_homestory_chat_15123003 = "그 내기... 무시무시한 건 아니겠지...",
  str_homestory_chat_15123004 = "아니야. 이번에는 뭘 걸래? 먼저 선택해.",
  str_homestory_chat_15123005 = "손이나 발이나 뭐든 괜찮다고.",
  str_homestory_chat_15124001 = "여길 어떻게 생각해?",
  str_homestory_chat_15124002 = "다 좋지! 조금 조용한 것만 빼고 말이야.",
  str_homestory_chat_15124003 = "조용하다고?",
  str_homestory_chat_15124004 = "총소리랑 자동차 소리는 별로 안 들리고\n자연의 소리만 많이 들린다는 거다.",
  str_homestory_chat_15124005 = "아무래도 좀 어색하단 말이지...",
  str_homestory_chat_15124006 = "아무래도 감을 되찾으러 가끔 한 번씩 사막으로 돌아가 봐야 할 것 같네.",
  str_homestory_chat_15124007 = "음, 근데 막상 가려고 하면 또 너무 멀거든.",
  str_homestory_chat_15124008 = "여기서 총 몇 방만 쏠 수 있으면 될 것 같은데.",
  str_homestory_chat_15124009 = "안 돼!",
  str_homestory_chat_15399999 = "보스! 오늘은 뭐가 필요하세요?",
  str_homestory_chat_15321001 = "음...",
  str_homestory_chat_15321002 = "오늘은 새로운 토끼곰 인형,\n완벽한 형태의 샌드버그 뿔 그리고...",
  str_homestory_chat_15321003 = "잠깐만! 그냥 인사만 하려던 거였어.",
  str_homestory_chat_15321004 = "걱정 마세요.\n평범한 인사도 만족스러운 거래로 바뀔 수\n있는 거니까요!",
  str_homestory_chat_15322001 = "뭐 하고 있어?",
  str_homestory_chat_15322002 = "보스, 개 짖는 소리 못 들었어요?",
  str_homestory_chat_15322003 = "못 들었는데...",
  str_homestory_chat_15322004 = "환청이 들린 걸까요?",
  str_homestory_chat_15322005 = "아, 강아지가 없다면 어디서 위안받을 수 있을까요?",
  str_homestory_chat_15322006 = "보스가 저한테 다양한 물건을 사가시면\n위안이 안 될 것도 없지만 말이에요.",
  str_homestory_chat_15322007 = "강아지 말인데...",
  str_homestory_chat_15322008 = "들은 것 같아...",
  str_homestory_chat_15322009 = "역시 제가 잘못 들은 게 아니었네요!",
  str_homestory_chat_15322010 = "보스, 저는 강아지를 찾으러 가 볼 테니까\n필요한 게 있으면 꼭 절 찾아오세요!",
  str_homestory_chat_15322011 = "그래, 그래. 얼른 찾으러 가 봐.",
  str_homestory_chat_15323001 = "새로운 발견을 했다고?",
  str_homestory_chat_15323002 = "맞아요, 보스!\n헤븐즈 가든에 거대한 사업 기회가\n잠들어 있더라고요!",
  str_homestory_chat_15323003 = "사업 기회라니? 어디 한 번 얘기해 봐.",
  str_homestory_chat_15323004 = "이런, 보스는 발견하지 못했나 보네요.",
  str_homestory_chat_15323005 = "보스가 사업 기회를 포착했다면\n서로 교류하면 되겠지만...",
  str_homestory_chat_15323006 = "지금 알려드리면 제가 손해 보는 거잖아요?\n그건 제 원칙에 어긋나죠.",
  str_homestory_chat_15323007 = "대신 정보료를 주신다면...",
  str_homestory_chat_15323008 = "숨기는 거 없이 전부 알려드릴게요!",
  str_homestory_chat_15323009 = "...됐어.",
  str_homestory_chat_11399999 = "PlayerName 씨, 안녕! 나랑 같이 청소할래?",
  str_homestory_chat_11321001 = "우와, 엄청 부지런하네!",
  str_homestory_chat_11321002 = "헤븐즈 가든의 청결을 유지하려면 열심히 청소해야지!",
  str_homestory_chat_11322001 = "안녕! 파티를 열 거야!",
  str_homestory_chat_11322002 = "PlayerName 씨,\n생각해 둔 파티 테마는 있어?",
  str_homestory_chat_11322003 = "있어!",
  str_homestory_chat_11322004 = "내가 새 테마를 하나 제공해도 될까?",
  str_homestory_chat_11322005 = "예를 들면 「설경 속의 헤븐즈 가든」은 어때?",
  str_homestory_chat_11322006 = "아직 없어...",
  str_homestory_chat_11322007 = "내가 생각해 둔 테마가 있어...",
  str_homestory_chat_11322008 = "「설경 속의 헤븐즈 가든」!",
  str_homestory_chat_11322009 = "내가 하늘에 떠다니는 얼음 수정이랑 탭댄스 추는\n눈사람을 제공해 줄 수 있어!",
  str_homestory_chat_11322010 = "괜찮을 것 같은데? 한번 해 보자.",
  str_homestory_chat_11323001 = "뭐 보고 있어?",
  str_homestory_chat_11323002 = "저쪽에... 빛나는 물건이 있는 것 같아!",
  str_homestory_chat_11323003 = "그냥 풀잎 위의 이슬이야...",
  str_homestory_chat_11323004 = "그냥 이슬이라고 해도 무척 귀여워!",
  str_homestory_chat_11323005 = "얼려서 보관해 둘 거야!",
  str_homestory_chat_11323006 = "그냥 유리 조각인데...",
  str_homestory_chat_11323007 = "투명하고 반짝이는 유리 조각이구나!",
