  str_homestory_chat_11324001 = "뭐 하고 있었어?",
  str_homestory_chat_11324002 = "PlayerName 씨, 눈사람 장식을\n많이 만들었어!",
  str_homestory_chat_11324003 = "마음에 든다면 선물해 줄게!",
  str_homestory_chat_11324004 = "녹아버리진 않을까?",
  str_homestory_chat_11324005 = "당연히 안 녹지!\n눈사람들이 춤추길 바란다면 그렇게 해 줄 수 있어!",
  str_homestory_chat_11324006 = "그럼 이따가 눈사람들을 데려갈게!",
  str_homestory_chat_11325001 = "날씨가 참 좋네.",
  str_homestory_chat_11325002 = "그러게. 여긴 계속 눈이 오는 북방이랑은 전혀 달라!",
  str_homestory_chat_11325003 = "근데 눈사람 못 만드는 건 역시 좀 아쉽네!",
