  str_homestory_chat_11325005 = "낚시?",
  str_homestory_chat_11325006 = "눈처럼 반짝반짝 빛나는 물고기도 있을까?",
  str_homestory_chat_11325007 = "당장 보러 갈래!",
  str_homestory_chat_11325008 = "그럼 그네 타러 갈래?",
  str_homestory_chat_11325009 = "앉아서 두 다리를 흔들면 날아오를 수 있는\n의자 말이야?",
  str_homestory_chat_11325010 = "왠지 눈이 허공에서 춤출 것만 같아!",
  str_homestory_chat_11325011 = "나도 눈처럼 보송보송 반짝반짝 빛나고 싶어!",
