  str_homestory_chat_11021005 = "음... 좀 찾아볼게.\n주머니가 너무 커서 못 찾겠어.",
  str_homestory_chat_11022001 = "나한테 물어볼 게 있다고?",
  str_homestory_chat_11022002 = "PlayerName 씨는 요정이 되고 싶어?\n아니면 정령이 되고 싶어?",
  str_homestory_chat_11022003 = "그건 왜 물어보는 건데?",
  str_homestory_chat_11022004 = "새 이야기를 만들 준비를 하려고!",
  str_homestory_chat_11022005 = "내 이야기에 등장하고 싶어?",
  str_homestory_chat_11022006 = "안 될 것 없지.",
  str_homestory_chat_11022007 = "음, 생각 좀 해 볼게. 아무래도 정령이 되는 게 좋겠네.",
