  str_homestory_chat_15851012 = "얼마든지!",
  str_homestory_chat_15851013 = "힘내세요!",
  str_homestory_chat_17699999 = "만나서 기뻐...",
  str_homestory_chat_17601001 = "안녕, 클레이튼.",
  str_homestory_chat_17601002 = "맞혀 봐. 이번에 내가 했던 말은 진심일까? 아닐까?",
  str_homestory_chat_17601003 = "이런 거로도... 거짓말을 할 필요가 있어?",
  str_homestory_chat_17601004 = "그건 모르는 일이지.",
  str_homestory_chat_17621001 = "무슨 소식이 있다면서?",
  str_homestory_chat_17621002 = "맞아. 불행한 소식이 하나 있어.",
  str_homestory_chat_17621003 = "좋은 소식일 것 같은 느낌이 드는걸.",
  str_homestory_chat_17621004 = "내가 아는 너라면, 네가 말하는 나쁜 소식은\n종종 좋은 소식이었으니까.",
  str_homestory_chat_17621005 = "그럼 이제 말해 줄게...\n갑자기 강이 죽은 물고기들로 가득 찼어...",
  str_homestory_chat_17621006 = "아, 아니지?! 어떻게 그런 일이... 왜, 어째서...",
  str_homestory_chat_17621007 = "헤, 거짓말이야. 속았지?",
  str_homestory_chat_17621008 = "무슨 불행한 소식인데?",
  str_homestory_chat_17621009 = "내가 거짓말을 할까 걱정되진 않아?",
  str_homestory_chat_17621010 = "거짓말이면 더 좋은 거 아냐?\n그럼 「불행한 소식」은 없는 거니까.",
  str_homestory_chat_17621011 = "...정말 귀여운 용사님이라니까.",
  str_homestory_chat_17622001 = "무슨 말을 하려고?",
  str_homestory_chat_17622002 = "...음.",
  str_homestory_chat_17622003 = "잠깐, 일단 아무 말도 하지 말아 봐.",
  str_homestory_chat_17622004 = "입만 열면 또 거짓말하려고 할 테니까.",
