  str_homestory_chat_17721001 = "여왕 폐하, 무슨 생각 하세요?",
  str_homestory_chat_17721002 = "이곳에서 그대와 함께하는 자들을 여럿 보았다.\n그대가 참으로 대견하구나.",
  str_homestory_chat_17721003 = "아무래도 이 대륙에는 그대를 따르려는 이들이\n많은 모양이다.",
