  str_homestory_chat_17722001 = "여왕 폐하도 여기에 익숙해지셨나요?",
  str_homestory_chat_17722002 = "이곳의 풍경은 북방과는 사뭇 다르지만,\n마찬가지로 마음을 편안하게 만들어 주더구나.",
