  str_homestory_chat_17726009 = "적어도 경보는 울릴 수 있으니까요.",
  str_homestory_chat_17726010 = "그렇군. 내가 괜한 걱정을 했구나.",
  str_homestory_chat_17727001 = "츄브요?",
  str_homestory_chat_17727002 = "그대는 저들을 어떻게 생각하느냐.",
  str_homestory_chat_17727003 = "동료라고 생각해요.",
  str_homestory_chat_17727004 = "오로리안처럼 말인가.",
  str_homestory_chat_17727005 = "음... 조금은 달라요. 츄브는 헤븐즈 가든에만 주로 머물거든요.",
  str_homestory_chat_17727006 = "도우미요.",
  str_homestory_chat_17727007 = "그뿐인가?",
  str_homestory_chat_17727008 = "하나 더하자면...",
  str_homestory_chat_17727009 = "이곳의 관리자라고 할 수 있겠죠?",
  str_homestory_chat_17727010 = "그들에게 더 많은 직책을 맡길 생각은 해 보았느냐.",
  str_homestory_chat_17727011 = "예를 들어 콜로서스나 다른 마을로 가서,\n헤븐즈 가든과의 연락책 역할을 하는 것이다.",
  str_homestory_chat_17727012 = "그건... 너무 이른 것 같아요.",
  str_homestory_chat_16499999 = "PlayerName, 오늘도 한가해 보이는데?",
  str_homestory_chat_16421001 = "절 감시하시는 건가요?",
  str_homestory_chat_16421002 = "불편해?",
  str_homestory_chat_16421003 = "아, 아니에요...",
  str_homestory_chat_16421004 = "그럼 넌 앞으로 내 감독을 나아갈 동력으로\n삼는 게 좋을 거야.",
  str_homestory_chat_16422001 = "네, 쉬고 있었어요.",
  str_homestory_chat_16422002 = "...지금이 쉬는 시간이야?",
  str_homestory_chat_16422003 = "네.",
  str_homestory_chat_16422004 = "이런 시간에 휴식이라니... 일정이 너무 느슨하네.",
  str_homestory_chat_16422005 = "왠지 아닌 것 같네요...",
  str_homestory_chat_16422006 = "그럼 어서 대화를 마무리하고\n서둘러 업무로 복귀하도록 해.",
  str_homestory_chat_16422007 = "너도 나처럼 계속 바쁘게 움직이는 게 좋을 거야.",
  str_homestory_chat_16422008 = "하지만... 레이스 씨도 지금 한가해 보이시는데요?",
  str_homestory_chat_16422009 = "...겉보기엔 할 일이 없어 보여도,\n사실은 계속 집중하고 있어.",
  str_homestory_chat_16423001 = "뭐 하세요?",
  str_homestory_chat_16423002 = "명상.",
  str_homestory_chat_16423003 = "...날 그런 눈으로 보지 마.",
  str_homestory_chat_16423004 = "만약 너도 나처럼 스트레스를 받는다면\n심신의 안정을 위해 이런 방식을 선택하게\n될 테니까.",
  str_homestory_chat_16423005 = "좋아요, 그럼 방해하지 않을게요.",
  str_homestory_chat_16424001 = "절 찾으셨어요?",
  str_homestory_chat_16424002 = "네가 꼭 알아야 할 일이 있어.",
  str_homestory_chat_16424003 = "무슨 일인데요?",
  str_homestory_chat_16424004 = "붉은 남작의 힘을 해방할 만한 곳을 찾을 수가 없어.",
  str_homestory_chat_16424005 = "훈련장을 하나 짓는 게 좋겠어.",
  str_homestory_chat_16424006 = "거절해도 되나요?",
  str_homestory_chat_16424007 = "아무래도 무기들은 위험하니까 여기서는 되도록\n사용하지 않는 게 좋을 것 같아요.",
  str_homestory_chat_16424008 = "...그래? 근데 난 왠지 훈련장이 없는 게...\n더 안 좋을 것 같다는 예감이 들까?",
  str_homestory_chat_16424009 = "그러죠!",
  str_homestory_chat_16424010 = "훈련장을 짓는다면 모두에게 좋을 거야.",
  str_homestory_chat_16424011 = "네가 날 훈련장에 초대할 그날을 기대하고 있을게.",
  str_homestory_chat_15799999 = "안녕이다냥~ 무슨 일로 날 찾은 거냥~?",
  str_homestory_chat_15701001 = "안녕.",
  str_homestory_chat_15701002 = "별일 없어. 그냥 인사나 하려고.",
  str_homestory_chat_15701003 = "그랬구냥~ 그럼 필리시가 너한테\n인사를 많이 해줄게...",
  str_homestory_chat_15701004 = "안녕, 안녕이다냥~",
  str_homestory_chat_15721001 = "여기가 마음에 들어?",
  str_homestory_chat_15721002 = "응, 필리시는 여기가 정말 좋다냥~",
  str_homestory_chat_15721003 = "왜냐하면 실컷 잘 수 있기 때문이다냥~",
  str_homestory_chat_15721004 = "자주 조는 것 같던데?",
  str_homestory_chat_15721005 = "필리시는 조는 게 아니다냥~\n그냥 자는 걸 좋아하는 거다냥~",
  str_homestory_chat_15721006 = "부드러운 이불이 있다면 더 좋을 것 같다냥~",
  str_homestory_chat_15721007 = "알겠어. 네 요청 사항은 내가 잘 기억해 둘게.",
  str_homestory_chat_15722001 = "뭐 하고 있어?",
  str_homestory_chat_15722002 = "아무도 필리시한테 말린 생선을 주지 않아서...",
  str_homestory_chat_15722003 = "필리시가 직접 만들어 먹기로 했다냥!",
  str_homestory_chat_15722004 = "어떻게 만들 거야?",
  str_homestory_chat_15722005 = "당연히 일단 낚시하러 갈 거다냥~",
  str_homestory_chat_15722006 = "그렇지만... 낚시 중에 졸다가 강에 빠져 버리는 건\n아닐지 모르겠다냥...",
  str_homestory_chat_15722007 = "나한테 말린 생선 있어!",
  str_homestory_chat_15722008 = "어서 필리시한테 조금 나눠달라냥~",
  str_homestory_chat_15722009 = "나중에 필리시가 꼭 보답하겠다냥.",
