  str_homestory_chat_15723002 = "필리시의 털은 뻣뻣해 보이지만 만지면\n아주 부드럽다냥~",
  str_homestory_chat_15723003 = "나도 좀 만져 봐도 돼?",
  str_homestory_chat_15723004 = "근데 필리시가 방금 털을 핥아 버렸는데 말이다냥...",
