  str_homestory_chat_15724001 = "잘 잤어?",
  str_homestory_chat_15724002 = "오랫동안 푹 잤다냥.\n여기 잠시 머문 것뿐인데 유미는 너무 졸리다냥.",
  str_homestory_chat_15724003 = "유미였어?",
  str_homestory_chat_15724004 = "티가 팍팍 나지 않냥?",
