  str_homestory_chat_15724006 = "필리시는?",
  str_homestory_chat_15724007 = "필리시는 벌써 잠들었다냥.",
  str_homestory_chat_15724008 = "너무 오랫동안 깨어 있었다냥.\n이제는 필리시도 좀 쉬어야지.",
  str_homestory_chat_15724009 = "그러니까 필리시는 안 깨워 줄 거다냥.",
