  str_homestory_chat_18323004 = "알려드립니다. 리리암은 주인님에게 필요한 것이\n매우 많지만, 주인님이 자주 잊는다고 생각합니다.",
  str_homestory_chat_18323005 = "알려드립니다. 필요한 점을 정확히 이야기할 수\n있도록 사고력 훈련을 해야 합니다.",
