  str_homestory_chat_18323007 = "어디 보자...",
  str_homestory_chat_18323008 = "발언 미화, 리리암이 신속히 업무를\n진행할 수 있도록 주인님은 사전에 필요한 것을\n생각해 둘 필요가 있습니다.",
