  str_homestory_chat_18324001 = "조금 안 쉬어도 되겠어?",
  str_homestory_chat_18324002 = "번역 변환, 리리암에겐 동력이 남아 있습니다.\n다음 업무도 충분히 처리할 수 있습니다.",
  str_homestory_chat_18324003 = "주인님, 맡기실 새 업무가 있습니까?",
