  str_homestory_chat_18324005 = "그냥 리리암은 항상 청소나 다른 일을 하길래, 혹시 피곤하진 않을까 해서.",
  str_homestory_chat_18324006 = "헤븐즈 가든은 애초에 편하게 쉬라고 있는 곳이니까, 좀 쉬엄쉬엄해도 돼.",
