  str_homestory_chat_18325002 = "2호를 말씀하시는 겁니까?",
  str_homestory_chat_18325003 = "응.",
  str_homestory_chat_18325004 = "2호는 제 자매가 아닙니다.",
  str_homestory_chat_18325005 = "아니.",
  str_homestory_chat_18325006 = "그렇다면 누구를 지칭하시는 것입니까?",
  str_homestory_chat_18325007 = "그건... 아, 질문을 좀 더 정확하게 할걸.",
  str_homestory_chat_18325008 = "아무튼, 사실 리리암한테도 좀 친한 사람이 있냐고 물어보려고 했어.\n친구라든가 그런 거 있잖아.",
  str_homestory_chat_18325009 = "있으면 그 사람을 여기 초대해도 돼. 리리암은 볼 때마다 혼자 있으니까.",
  str_homestory_chat_18325010 = "번역 변환, 주인님은 리리암에게 파트너를\n찾아 주려는 것입니까?",
