  str_homestory_chat_18022005 = "있어!",
  str_homestory_chat_18022006 = "저, 정말인가요! 아... 죄송해요.\n방금... 소리가... 저, 너무 컸죠...?",
  str_homestory_chat_18022007 = "음, 제가 하려던 말은... 제 「운반 조수」가...\n점점 더 대단해지고 있다는 거였어요...",
  str_homestory_chat_18022008 = "그, 그러니까 무슨 일이 생기면\n저한테 도와달라고 하시면... 돼요!",
