  str_homestory_chat_18622003 = "사실 산책을 좋아한다기보다는 이곳의 풍경과\n가까워지는 걸 좋아해요.",
  str_homestory_chat_18622004 = "백야성에서는 이렇게 부드러운 풀밭을\n보기가 힘들거든요. 사이사이 피어 있는 작은 꽃들도 그렇고요.",
