  str_homestory_chat_18123002 = "PlayerName, 내 새 신발 좀 봐. 어때?",
  str_homestory_chat_18123003 = "뭐가 달라진 건지 모르겠는데...",
  str_homestory_chat_18123004 = "자세히 봐. 이 앞코랑 뒤축 그리고 배색까지...",
  str_homestory_chat_18123005 = "전부 다 최신 유행 스타일 아니냐고!",
  str_homestory_chat_18123006 = "어? 아? 그래? 새로운 걸 배웠네.",
  str_homestory_chat_18123007 = "멋진데?",
  str_homestory_chat_18123008 = "역시 이 몸의 형제야. 나랑 취향이 잘 맞잖아.",
  str_homestory_chat_18123009 = "어때? 내 신발 부럽지? 선물로 몇 켤레 줄까?",
  str_homestory_chat_18123010 = "좋지!",
  str_homestory_chat_18299999 = "헤헷, 안녕하세요!",
  str_homestory_chat_18201001 = "안녕! 오피나.",
  str_homestory_chat_18201002 = "오늘은 저도 새로운 모험을 떠나고 싶어요.\n같이 갈래요?",
  str_homestory_chat_18201003 = "모험? 어디 가려고? 여길 떠나려는 거야?",
  str_homestory_chat_18201004 = "안심하세요. 여길 떠나진 않을 거예요~",
  str_homestory_chat_18221001 = "왜 그래?",
  str_homestory_chat_18221002 = "후우... 후우... 힘드네요.",
  str_homestory_chat_18221003 = "이렇게 큰 뿔을 달고 걸어 다니니까...\n진짜 힘들어요...",
  str_homestory_chat_18221004 = "내가 뿔을 잠깐 맡아 줄까?",
  str_homestory_chat_18221005 = "뿌, 뿔은 건들지 마세요... 위험할 거예요!",
  str_homestory_chat_18222001 = "무슨 일이야?",
  str_homestory_chat_18222002 = "하고 싶은 말이 있어서요...",
  str_homestory_chat_18222003 = "저는 여기가 정말 좋아요! 탐험도 많이 할 수 있고,\n암귀한테 쫓길 걱정도 없으니까요.",
  str_homestory_chat_18222004 = "오늘 전 새로운 모험을 시작할 거예요.\n부디 제 여행을 축복해 주세요!",
  str_homestory_chat_18222005 = "그래, 즐거운 여행이 되길 바랄게!",
  str_homestory_chat_19299999 = "......",
  str_homestory_chat_19201001 = "안녕.",
  str_homestory_chat_19201002 = "나한테 인사해서 뭐 하게?",
  str_homestory_chat_19201003 = "네가 나한테 인사하면 나도 너한테 인사해야 해?",
  str_homestory_chat_19201004 = "으, 으음...",
  str_homestory_chat_19201005 = "좋아. 그럼 내가 「안녕」이라고 해 주면 만족할까?",
  str_homestory_chat_19221001 = "이야기나 좀 할래?",
  str_homestory_chat_19221002 = "이야기? 무슨 얘기가 하고 싶은데?",
  str_homestory_chat_19221003 = "아까도 말했지만, 내가 대답할지는 장담 못 해.",
  str_homestory_chat_19221004 = "이러면 벌써 대답한 거 아냐?",
  str_homestory_chat_19221005 = "...대답해 줄 수도 있고, 안 해 줄 수도\n있다는 거야. 알겠어?",
  str_homestory_chat_19221006 = "됐어. 너랑 얘기하는 거 포기할게.",
  str_homestory_chat_19221007 = "어떻게 이렇게 쉽게 포기하는 거야?",
  str_homestory_chat_19221008 = "몇 마디 들었다고 바로 포기해 버리다니...\n그러면 안 된다는 생각 안 들어?",
  str_homestory_chat_19221009 = "......",
  str_homestory_chat_19222001 = "지금 무슨 생각해?",
  str_homestory_chat_19222002 = "어제 저녁 식사 메뉴 맛있었어?",
  str_homestory_chat_19222003 = "맛있었어!",
  str_homestory_chat_19222004 = "그 입맛은 정말 이해할 수가 없어.\n어떻게 그게 맛있게 느껴질 수 있지?",
  str_homestory_chat_19222005 = "반찬으로 무가 나왔잖아!\n무는 모든 요리를 망쳐 버린다고. 그걸 몰라?",
  str_homestory_chat_19222006 = "그래? 진짜 몰랐네.",
  str_homestory_chat_19222007 = "맛없었어...",
  str_homestory_chat_19222008 = "왜 맛없다고 느꼈어?",
  str_homestory_chat_19222009 = "몇 명한테 물어봤는데, 다들 맛없었다고 하더라고.",
  str_homestory_chat_19222010 = "다들 참 특이해. 사실 뭐 보기 드문 요리들이\n좀 있었지. 도마뱀 구이 같은 거라든가...",
  str_homestory_chat_19222011 = "그래도 맛이 없는 수준은 아니었잖아?",
  str_homestory_chat_19222012 = "으엑, 그건...",
  str_homestory_chat_19223001 = "노트가 정말 많네...",
  str_homestory_chat_19223002 = "내가 좀 정리해 줄까?",
  str_homestory_chat_19223003 = "오늘은 조금 한가하거든.",
  str_homestory_chat_19223004 = "좋지!",
  str_homestory_chat_19223005 = "근데 일단 내 노트부터 찾아야 해...",
  str_homestory_chat_19223006 = "자기 노트도 제대로 못 챙겨 놓다니, 정말 정신없네.",
  str_homestory_chat_19223007 = "기다려. 나도 같이 정리해 줄 테니까.",
  str_homestory_chat_19223008 = "난 독서 노트 같은 건 없는데...",
  str_homestory_chat_19223009 = "책을 읽었는데 독서 노트를 안 적는다고?\n노트 작성법을 모르는 거야?",
  str_homestory_chat_19223010 = "모른다면 나한테 가르쳐 달라고 해.",
