  str_homestory_chat_14501001 = "안녕, 나일즈.",
  str_homestory_chat_14501002 = "이렇게 안부를 물어 주시니\n이 죄인은 참 당혹스럽습니다.",
  str_homestory_chat_14501003 = "그래도 저는 이 당혹감을 참아낼 것입니다.",
  str_homestory_chat_14501004 = "...인사만 좀 했을 뿐인데, 반응이 이렇게 심각하단 말이야?",
