  str_homestory_chat_14521002 = "함께하시겠습니까?",
  str_homestory_chat_14521003 = "아니...",
  str_homestory_chat_14521004 = "그렇군요. 빛 속에서 살아가는 분이라면 저처럼...",
  str_homestory_chat_14521005 = "참회로써 죄악으로 가득한 몸을 씻어낼 필요는\n없을 테니까요...",
  str_homestory_chat_14521006 = "음... 저기... 반성하는 건 좋은데...\n그래도 너무 과하면 안 좋아...",
  str_homestory_chat_14521007 = "그러자...",
  str_homestory_chat_14521008 = "자, 절 따라 진리를 마주하고 자신의 죄악을\n털어놓으세요.",
  str_homestory_chat_14521009 = "...죄악? 그 단어는 어감이 좀 그렇지 않아?",
  str_homestory_chat_14522001 = "왜 그래?",
  str_homestory_chat_14522002 = "...이곳의 햇빛은 너무나도 눈부시군요.",
  str_homestory_chat_14522003 = "햇빛을 싫어하는 거야?",
  str_homestory_chat_14522004 = "제가 어째서 햇빛을 싫어하겠습니까?",
  str_homestory_chat_14522005 = "아마도... 햇빛이 저라는 죄인을 비추는 것을\n원치 않는 것이겠지요.",
  str_homestory_chat_14522006 = "햇볕을 쬐면 안 되는 거야?",
  str_homestory_chat_14522007 = "동화책에서 봤는데, 어떤 생물들은 햇볕을 쬐면\n다친다고 하더라고.",
  str_homestory_chat_14522008 = "햇볕을 쬐면 다치는 건 맞습니다...\n다만 상처를 입는 것은 육체가 아닌...",
  str_homestory_chat_14522009 = "죄악을 품고 있는 제 마음입니다.",
