  str_homestory_chat_14523003 = "핏자국을 마르게 하는 건 제게 쉬운 일입니다.",
  str_homestory_chat_14523004 = "또 싸운 거야?",
  str_homestory_chat_14523005 = "요즘은 그런 종류의 죄악은 거의 범하지 않았습니다.",
  str_homestory_chat_14523006 = "그럼 다행인데... 아무래도 가서 지혈부터 하는 게 좋겠어.",
  str_homestory_chat_14523007 = "또 자길 찌른 거야?",
  str_homestory_chat_14523008 = "제 능력을 해방했을 뿐입니다...\n다만, 이 역시 일종의 속죄일지도 모르겠군요.",
