  str_homestory_chat_16899999 = "PlayerName, 안녕!",
  str_homestory_chat_16801001 = "안녕! 웬디!",
  str_homestory_chat_16801002 = "오늘은 너한테 온 편지가 없어!",
  str_homestory_chat_16801003 = "응, 알겠어.",
  str_homestory_chat_16801004 = "편지가 안 왔다고 슬퍼하지 마.\n내가 하나 써 줄 수 있으니까!",
  str_homestory_chat_16821001 = "나 찾았어?",
  str_homestory_chat_16821002 = "우와, 내 깃털에 무슨 더러운 게 묻지 않았어?",
  str_homestory_chat_16821003 = "확인 좀 해 줘!",
