  str_homestory_chat_16821005 = "진짜? 왜 이렇게 이상한 느낌이지...",
  str_homestory_chat_16821006 = "날개를 제대로 휙휙 털어 내고 싶어!",
  str_homestory_chat_16821007 = "이, 이따가 털어! 나 아직 여기 있다고!",
  str_homestory_chat_16821008 = "여기 있어!",
  str_homestory_chat_16821009 = "빠...빨리 떼어 줘!",
  str_homestory_chat_16821010 = "하하, 거짓말이었지롱!",
  str_homestory_chat_16821011 = "...짜증 나! 날개에 맞아서 날아가고 싶어?",
  str_homestory_chat_16822001 = "엄청 한가해 보이네.",
  str_homestory_chat_16822002 = "여기 오래 있었더니 조금 심심해졌어...",
  str_homestory_chat_16822003 = "왜?",
  str_homestory_chat_16822004 = "이곳의 땅은 모래가 아니라서\n차도 먼지가 안 날리잖아...",
  str_homestory_chat_16822005 = "레디젤 사막에서 플라잉 킥을 날리면 모래가\n막 날리니까 엄청 멋지고 대단해 보이거든.",
  str_homestory_chat_16822006 = "여기서는 플라잉 킥을 날려도 별로 대단해 보이지\n않는 것 같아...",
  str_homestory_chat_16822007 = "...알겠어. 그럼 모래밭을 찾아 줄게.",
  str_homestory_chat_16823001 = "가방에 대해 물어볼 게 있댔지?",
  str_homestory_chat_16823002 = "맞아!",
  str_homestory_chat_16823003 = "그럼... 뭐가 궁금한데?",
  str_homestory_chat_16823004 = "원단에 대해서 물어보고 싶어.\n여기 혹시 가볍고 질긴 재질의 원단은 없을까?",
  str_homestory_chat_16823005 = "난 아주 빠르게 날잖아. 게다가 모래폭풍이 있는\n지역을 비행하다 보니 마모가 심하거든!",
  str_homestory_chat_16823006 = "원단이면... 움브라톤에 가면 되는 거 아냐? 거긴 어떤 천이든 다 있잖아.",
  str_homestory_chat_16823007 = "움브라톤의 천은 너무 비싸니까 그렇지!\n그리고 거긴 악덕 상인이 너무 많아!",
  str_homestory_chat_16823008 = "근데 헤븐즈 가든은 달라.\n어쩌면 돈 없이도 좋은 원단을 찾을지도 모르잖아!",
  str_homestory_chat_16823009 = "그게 네 목적이었구나...",
  str_homestory_chat_16824001 = "뭐 보고 있어?",
  str_homestory_chat_16824002 = "나한테 물어보는 거야?\n아무것도 안 봤어, 그냥 바람을 느끼는 중이야.",
  str_homestory_chat_16824003 = "여긴 너무 잠잠하네, 바람도 한 점 없고.\n어디 바람이 강하게 부는 곳은 없어?",
  str_homestory_chat_16824004 = "없어.",
  str_homestory_chat_16824005 = "...역시 조용한 곳이라니까.\n조용해도 너무 심하게 조용하잖아.",
  str_homestory_chat_16824006 = "온몸이 근질근질해.\n혼자 돌면서 미니 허리케인이라도 일으키고 싶어.",
  str_homestory_chat_16824007 = "그건... 어디 넓은 데 가서 해.",
  str_homestory_chat_16824008 = "왜 강한 바람이 필요한데?",
  str_homestory_chat_16824009 = "강풍은 속도의 힘을 느끼게 해주고,\n이 제트팩도 시험할 수 있거든!",
  str_homestory_chat_16824010 = "사막 위를 날다 보면 강풍을 자주 만난다구!",
