  str_homestory_chat_19522003 = "언제든 와서 보실 수 있어요.",
  str_homestory_chat_19522004 = "동굴 안에서 지내는 게 더 좋아?",
  str_homestory_chat_19522005 = "네. 하지만 많은 오로리안이 동굴의\n습함과 어두움을 싫어하죠.",
  str_homestory_chat_19522006 = "당신은 신경 쓰지 않나요?",
  str_homestory_chat_16299999 = "안녕, PlayerName. 만나서 기뻐.",
  str_homestory_chat_16201001 = "오늘은 뭐 할 거야?",
  str_homestory_chat_16201002 = "어쩌면 숲에서 산책할지도 몰라.",
  str_homestory_chat_16221001 = "여기가 아주 마음에 든 모양이구나.",
  str_homestory_chat_16221002 = "초대해 줘서 고마워, PlayerName.",
  str_homestory_chat_16221003 = "여기서 친구도 많이 사귀었어.",
  str_homestory_chat_16221004 = "그럼 됐어.",
  str_homestory_chat_16221005 = "진정한 친구를 사귈 수만 있다면\n어디든 상관없다고 생각했지만.",
  str_homestory_chat_16221006 = "여기서 지내는 건 정말 굉장히 즐거워.",
  str_homestory_chat_16222001 = "나한테 볼일 있어?",
  str_homestory_chat_16222002 = "방에 덩굴을 많이 심어도 될까?",
  str_homestory_chat_16222003 = "심어도 돼.",
  str_homestory_chat_16222004 = "어떤 품종이 필요해? 내가 찾아줄게.",
  str_homestory_chat_16222005 = "고마워. 네가 허락해 준 것만으로도 충분해.",
  str_homestory_chat_16222006 = "그건 좀...",
  str_homestory_chat_16222007 = "아, 그렇구나...",
  str_homestory_chat_16222008 = "그럼 화분에 심도록 할게. 그래도 안 될까?",
  str_homestory_chat_16223001 = "뭔가 감성에 젖은 것 같은데?",
  str_homestory_chat_16223002 = "맞아. 난 매번 올 때마다 이곳의 지리적 환경에 감탄하게 돼.",
  str_homestory_chat_16223003 = "지리적 환경?",
  str_homestory_chat_16223004 = "쉽사리 눈에 띄지 않는 곳에 있어 안전하고, 날씨가 좋아.\n식물은 물론, 강과 폭포도 있어서 풍요롭고 아름다워,",
  str_homestory_chat_16223005 = "북방도 이랬다면... 얼마나 좋았을까.",
  str_homestory_chat_16223006 = "실바 네가 전에 숲지기로 있었다던 풍맥의 숲은 이렇지 않았어?",
  str_homestory_chat_16223007 = "내 기억엔 북방도 좋은 곳이었는데.",
  str_homestory_chat_16223008 = "북방과 비교했을 때 상대적으로 그렇단 얘기지.\n헤븐즈 가든과 비교하자면 풍맥의 숲보다 여기가 더 좋아.",
  str_homestory_chat_16223009 = "그래서 가끔은 터무니없는 상상을 하기도 했어...\n만약 내가 이 헤븐즈 가든의 수호자였다면 어땠을까 같은...",
  str_homestory_chat_16223010 = "그랬으면 지금 내 일보다 훨씬 수월했을 것 같아.\n자신에 대한 생각을 할 시간도 있었을 거고.",
  str_homestory_chat_16223011 = "여기 있을 땐 지킨다거나 그런 건 생각 안 해도 돼.",
  str_homestory_chat_16223012 = "그냥 마음 푹 놓고 생각 정리도 하고,\n재충전 시간을 가지면 되는 거야.",
  str_homestory_chat_16223013 = "그렇지. 헤븐즈 가든에 초대해 줘서 정말 고마워.",
  str_homestory_chat_16223014 = "에이, 천만에.",
  str_homestory_chat_16224001 = "물?",
  str_homestory_chat_16224002 = "그래. 조종사 넌 물에 대해 알아?",
  str_homestory_chat_16224003 = "알지.",
  str_homestory_chat_16224004 = "그렇다면 리아가 만든 저 물방울에 대해서도 알아?\n리아가 뭘 한 거야?",
  str_homestory_chat_16224005 = "그건... 모르겠는데.",
  str_homestory_chat_16224006 = "잘은 몰라.",
  str_homestory_chat_16224007 = "으음... 리아가 만든 물방울에 대해서는 아무래도\n다른 사람들한테 물어보는 수밖에 없겠네.",
  str_homestory_chat_16224008 = "근데 갑자기 웬 물방울인데?",
  str_homestory_chat_16224009 = "햇빛을 머금은 숲속의 이슬 같아서,\n재미있을 것 같단 느낌이 들었거든.",
  str_homestory_chat_16224010 = "그렇긴 하네.",
  str_homestory_chat_16224011 = "이슬 속에서 씨앗을 하나 발견했던 적이 있었어.\n아마 바람에 날려 온 씨앗이었겠지.",
  str_homestory_chat_16224012 = "평소에 보던 씨앗은 진한 초록색이나 갈색,\n심지어는 검은색뿐이었지만.",
  str_homestory_chat_16224013 = "아무튼 자연의 기운이 느껴지는 그런 거였어.\n무슨 느낌인지 이해할 수 있겠어?",
  str_homestory_chat_16224014 = "응.",
  str_homestory_chat_16224015 = "그렇지만 그 씨앗은, 이슬에 감싸인 것만으로도 햇빛 아래에서\n에메랄드만큼이나 특별한 자태를 뽐냈어.",
  str_homestory_chat_16224016 = "물은... 참 신기해. 리아처럼 말이야.",
  str_homestory_chat_16224017 = "그렇구나...",
  str_homestory_chat_16225001 = "검술 선생님을 소개해 달라고?",
  str_homestory_chat_16225002 = "정확히 말하면 같이 대련하며 연습해 줄 사람이 필요해.",
  str_homestory_chat_16225003 = "아버지께서 검술 실력을 갈고닦고 싶다면,\n대련 상태가 필요하다고 그러셨거든.",
  str_homestory_chat_16225004 = "어떤 덩굴은 성장하려면 다른 나무의 도움이 필요한데,\n그것과 같은 원리인 거지.",
  str_homestory_chat_16225005 = "그럼 실바 넌 어떤 대련 상대를 찾고 있는데?",
  str_homestory_chat_16225006 = "검술 실력은 나와 비슷한 정도면 돼.\n혹시 헤븐즈 가든에 이런 사람이 있을까?",
  str_homestory_chat_16225007 = "있어!",
  str_homestory_chat_16225008 = "꽤 많을걸. 백야성이나, 일루미나 사람 중에...",
  str_homestory_chat_16225009 = "없을걸.",
  str_homestory_chat_16225010 = "아니면 검술 실력 대신 전투 훈련 쪽으로 뛰어난 사람은?",
  str_homestory_chat_16225011 = "그래도 괜찮을 것 같아...",
  str_homestory_chat_16225012 = "근데 왜 갑자기 검술 실력을 단련하려는 거야?",
  str_homestory_chat_16225013 = "일상적인 훈련이라면 혼자서도 충분하지 않아?\n헤븐즈 가든에 있을 땐 더 느긋하게 쉬어 줬으면 좋겠는데.",
  str_homestory_chat_16225014 = "그 말도 맞긴 하네...",
  str_homestory_chat_20199999 = "안녕하세요, PlayerName 씨!",
  str_homestory_chat_20101001 = "안녕, 안시아.",
  str_homestory_chat_20101002 = "오늘은 어떤 메시지를 보낼 건가요?",
  str_homestory_chat_20101003 = "딱히 보낼 건 없어. 그냥 인사하려고 부른 거야.",
  str_homestory_chat_20101004 = "그런가요...",
  str_homestory_chat_20121001 = "오늘은 많이 한가하네.",
  str_homestory_chat_20121002 = "그러네요... 그러니까 PlayerName 씨,\n오늘은 조심해서 다녀야 해요.",
  str_homestory_chat_20121003 = "왜?",
  str_homestory_chat_20121004 = "왜냐하면... 아주 한가할 때는 저도 모르게\n장난치고 싶어지거든요.",
  str_homestory_chat_20121005 = "함정을 준비할 수도 있고,\n스티커를 붙일 수도 있어요...",
  str_homestory_chat_20121006 = "아무튼 조심하시면 돼요.",
  str_homestory_chat_20121007 = "...그렇게 말해 버리면 어디 가지를 못하겠잖아!",
  str_homestory_chat_20122001 = "오늘 보낼 메시지는...",
  str_homestory_chat_20122002 = "제가 다 정리해 뒀어요!",
  str_homestory_chat_20122003 = "지시를 내려 주세요!",
  str_homestory_chat_20122004 = "한번 들어볼게.",
  str_homestory_chat_20122005 = "읽어 드려야 하나요?",
  str_homestory_chat_20122006 = "아니, 내 통신기에 보내 주면 돼.",
  str_homestory_chat_20122007 = "잠깐만...",
  str_homestory_chat_20122008 = "아직 좀 바쁘거든. 그 메시지들 내 통신기로 좀 보내 줄래?",
