  str_homestory_chat_20123002 = "그럼요! 새로운 통신 방식이 떠올랐거든요!",
  str_homestory_chat_20123003 = "바로 비둘기를 활용하는 거예요!\n아마 지금까지 한 번도 본 적 없는 방법일걸요!",
  str_homestory_chat_20123004 = "어떻게 활용하는데?",
  str_homestory_chat_20123005 = "비둘기한테 말을 전하라고 하게?",
  str_homestory_chat_20123006 = "아뇨, 아뇨. 그렇게 간단한 게 아니에요.",
  str_homestory_chat_20123007 = "비둘기 몸에 스피커랑 무전기를 묶어 두면\n하늘에서 메시지를 재생할 수 있잖아요.",
  str_homestory_chat_20123008 = "효과가 아주 좋을 거예요!",
