  str_homestory_chat_20123010 = "그렇겠네요! 그럼 오로리안으로 바꾸면요?\n예를 들면 도브?",
  str_homestory_chat_20123011 = "아마 엄청 싫어할 거야.",
  str_homestory_chat_20299999 = "어이, 안녕.",
  str_homestory_chat_20201001 = "안녕, 테사.",
  str_homestory_chat_20201002 = "좋은 날씨네.",
  str_homestory_chat_20201003 = "그러게.",
  str_homestory_chat_20221001 = "같이 이야기나 좀 할래?",
  str_homestory_chat_20221002 = "얘기하다 보면 매번 결국 푸념으로 바뀐다고\n생각하지 않아?",
  str_homestory_chat_20221003 = "그런 것 같기도 하네...",
  str_homestory_chat_20221004 = "그래서 난 대화는 거의 안 해.",
  str_homestory_chat_20221005 = "다른 사람 푸념 듣는 거 별로 안 좋아하거든.",
  str_homestory_chat_20221006 = "내가 푸념을 늘어놓는 타입이 아니라서\n그럴지도 모르겠네.",
  str_homestory_chat_20221007 = "난 푸념도 나쁘지 않다고 생각해.",
  str_homestory_chat_20221008 = "대화는 서로의 감정을 나누는 거잖아.\n그 방식이 푸념이라도 말이야.",
  str_homestory_chat_20221009 = "네 생각이 맞을지도 몰라.",
  str_homestory_chat_20221010 = "하지만 그래도 난 푸념 듣는 건 싫어.",
  str_homestory_chat_20222001 = "뭐 먹어?",
  str_homestory_chat_20222002 = "바이스가 준 사탕. 나쁘지 않은 맛이야.",
