  str_homestory_chat_20222004 = "먹을래!",
  str_homestory_chat_20222005 = "음... 하지만 가지고 있던 사탕은\n이미 전부 먹어버렸는데.",
  str_homestory_chat_20222006 = "이따가 돌아가서 좀 갖다줄게.",
  str_homestory_chat_20222007 = "알겠어.",
  str_homestory_chat_20222008 = "아니...",
  str_homestory_chat_20222009 = "잘됐네. 마침 가지고 있던 사탕은 다 먹어 버렸거든.",
  str_homestory_chat_20222010 = "그럼 굳이 안 가져와도 되겠네.",
  str_homestory_chat_20223001 = "여기서 지내는 건 익숙해졌어?",
