  str_homestory_chat_20223004 = "마음에 들지. 여기서 꽤 자유롭게 지내고 있어.",
  str_homestory_chat_20223005 = "이렇게 자유롭게 지낼 수 있는 곳은\n대륙 전체를 뒤져 봐도 몇 군데 없을 거야.",
  str_homestory_chat_20223006 = "움브라톤이 싫어?",
