  str_homestory_chat_21722002 = "오늘은 감자를 많이 캤지... 먹고 싶은 메뉴가 있나?",
  str_homestory_chat_21722003 = "감자채볶음이요.",
  str_homestory_chat_21722004 = "문제없다. 대신 날이 잘 드는 식칼이 있는지\n찾아봐야겠군.",
  str_homestory_chat_21722005 = "감자튀김이요.",
  str_homestory_chat_21722006 = "튀긴 음식을 너무 많이 먹으면 좋지 않다만...",
  str_homestory_chat_21722007 = "그래도 가끔은 괜찮겠지.",
  str_homestory_chat_21722008 = "으깬 감자샐러드요.",
  str_homestory_chat_21722009 = "나쁘지 않은 제안이다. 그걸로 하지!",
  str_homestory_chat_21723001 = "잘 지내고 계신가요?",
  str_homestory_chat_21723002 = "꽤 자유롭게 지내고 있다.",
  str_homestory_chat_21723003 = "적응을 못 하실까 봐 걱정했어요.",
  str_homestory_chat_21723004 = "그렇게 이야기하시니까 이제 마음이 놓이네요.",
  str_homestory_chat_21723005 = "어째서지?\n내가 평온한 일상을 좋아하지 않을 것 같나?",
  str_homestory_chat_21723006 = "...하긴, 노병들 중에는 이런 생활에 적응을\n못 하는 녀석들도 있지.",
  str_homestory_chat_21723007 = "하지만 나는 다르다.",
  str_homestory_chat_21999999 = "PlayerName, 나한테 인사한 거야?",
  str_homestory_chat_21901001 = "맞아.",
  str_homestory_chat_21901002 = "그럼 다음에는 나도 너한테 인사할게.",
  str_homestory_chat_21921001 = "뭐 하고 있었어?",
  str_homestory_chat_21921002 = "부, 불맛 케이크 반 상자를 먹었더니...",
  str_homestory_chat_21921003 = "혀가 좀 부었나 봐.",
  str_homestory_chat_21921004 = "왜 한 번에 그렇게 많이 먹은 거야?",
  str_homestory_chat_21921005 = "그러려고 그랬던 건 아닌데... 너, 너무 맛있어서...",
  str_homestory_chat_21921006 = "후우... 하아...",
  str_homestory_chat_21922001 = "무슨 생각해?",
  str_homestory_chat_21922002 = "여기서는 비가 올 때까지 기다렸다가\n목욕할 필요가 없구나.",
  str_homestory_chat_21922003 = "그래?",
  str_homestory_chat_21922004 = "그냥 강에 뛰어들면 되잖아.\n빗물로 씻는 것보다 깨끗하기도 하고.",
  str_homestory_chat_21922005 = "이곳의 강물은... 아주 쓸모가 많아.",
  str_homestory_chat_21923001 = "엄청 심심해 보이네?",
  str_homestory_chat_21923002 = "맞아. 왜 여긴 베어 버릴 암귀가 없는 거야?\n내 대검이 다 녹슬겠어.",
  str_homestory_chat_21923003 = "그럼 나무 베는 걸 도와줄 수 있을까?",
  str_homestory_chat_21923004 = "나무 베기... 그것도 일이긴 하네.",
  str_homestory_chat_21923005 = "좋아. 일거리가 생기면 데려가 줘.",
  str_homestory_chat_21923006 = "그럼 돌 깨는 걸 도와 줄 수 있을까?",
  str_homestory_chat_21923007 = "돌이 딱딱한지, 내 대검이 딱딱한지 보고 싶은 거야?",
  str_homestory_chat_21923008 = "내 대검은 암귀도 반으로 가른다고.",
  str_homestory_chat_21923009 = "돌 따위는 살아남을 수 없어.",
  str_homestory_chat_22299999 = "PlayerName?",
  str_homestory_chat_22201001 = "안녕, 알루라.",
  str_homestory_chat_22201002 = "또 나한테 팔아줄 골동품이 생긴 거야?",
  str_homestory_chat_22201003 = "그건 아닌데...",
  str_homestory_chat_22201004 = "그럼... 나한테 뭘 사려는 거구나.",
  str_homestory_chat_22221001 = "혹시 화났어?",
  str_homestory_chat_22221002 = "...어디서 굴러온지도 모를 녀석이\n갑자기 내 회중시계를 사려고 하지 뭐야!",
  str_homestory_chat_22221003 = "이제부터는 회중시계에 「비매품」이라고\n붙여 둘 거야.",
  str_homestory_chat_22221004 = "좋은 생각이야.",
  str_homestory_chat_22221005 = "그럼 주제 파악도 못 하는 녀석들이\n매번 얼마냐고 물어보는 일은 없어지겠지.",
  str_homestory_chat_22221006 = "내가 상인이긴 하지만 뭐든 다 파는 건 아니라고.",
  str_homestory_chat_22221007 = "방법을 좀 바꿔 보면 어떨까?",
  str_homestory_chat_22221008 = "말해 봐.",
  str_homestory_chat_22221009 = "예를 들면 손님이 있을 때는 회중시계를 넣어 뒀다가...",
  str_homestory_chat_22221010 = "손님이 없을 때 다시 꺼내는 거지.",
  str_homestory_chat_22221011 = "그것도 방법이라면 방법이네.",
  str_homestory_chat_22222001 = "새 보고 있었어?",
  str_homestory_chat_22222002 = "여긴 다양한 새들이 있더라고.",
  str_homestory_chat_22222003 = "새들에 대해 연구라도 하는 거야?",
  str_homestory_chat_22222004 = "「연구」까지는 아니야.\n그래도... 여긴 총 23종류의 새가 있는 것 같은데...",
  str_homestory_chat_22222005 = "내가 맞게 센 거야?",
  str_homestory_chat_22222006 = "그건... 나도 모르는데...",
  str_homestory_chat_22223001 = "가게를 차리려고 하는 거야?",
  str_homestory_chat_22223002 = "맞아. 내가 골동품점을 떠날 날이\n얼마 남지 않은 것 같거든.",
  str_homestory_chat_22223003 = "그때가 되면 여기 가게를 하나 낼 생각이야.",
  str_homestory_chat_22223004 = "그럼 임대료는 안 받을게!",
  str_homestory_chat_22223005 = "그렇게 말하니 조금 미안해지잖아.",
  str_homestory_chat_22223006 = "그럼 가게를 차리고 나도 너한테 골동품 하나를\n선물로 줄게!",
  str_homestory_chat_22223007 = "그럼 임대료를 깎아 줄게!",
  str_homestory_chat_22223008 = "깎아 준다고? 그럼 지금 당상 논의해 보자.",
  str_homestory_chat_22199999 = "안녕, PlayerName.",
  str_homestory_chat_22101001 = "안녕, 파로마.",
  str_homestory_chat_22101002 = "내가 「안녕하지 않아」라고 한다면?",
  str_homestory_chat_22101003 = "어, 그럼...",
  str_homestory_chat_22101004 = "됐어. 안 괴롭힐게.",
  str_homestory_chat_22101005 = "너도 안녕, PlayerName.",
  str_homestory_chat_22121001 = "네 그 동전 말인데...",
  str_homestory_chat_22121002 = "내가 목에 걸고 있는 동전에 관심이 많나 봐?",
  str_homestory_chat_22121003 = "아, 아니야...",
  str_homestory_chat_22121004 = "궁금한 게 있으면 그냥 바로 얘기해.",
  str_homestory_chat_22121005 = "당신을 뭐 어떻게 할 생각도 없으니까.",
  str_homestory_chat_22121006 = "조금...",
  str_homestory_chat_22121007 = "난 다른 사람이 「관심 있어요」라고 했다고\n열심히 설명해 주는 타입은 아니야.",
  str_homestory_chat_22121008 = "동전을 당신한테 빌려주는 것도 딱히 상관은 없어.",
  str_homestory_chat_22122001 = "좀 어때?",
  str_homestory_chat_22122002 = "여기서 지내는 것도 괜찮은 것 같아.",
  str_homestory_chat_22122003 = "그럼 됐어.",
  str_homestory_chat_22122004 = "거짓 신조를 떠들어 대는 사람들도 딱히 없잖아.",
  str_homestory_chat_22122005 = "드디어 한동안 귀가 깨끗해지겠어.",
  str_homestory_chat_22122006 = "모두 당신 덕분이야.",
  str_homestory_chat_22123001 = "뭔가 새로운 일이라도 있어?",
  str_homestory_chat_22123002 = "나랑 얘기하러 온 거야?\n...만약 내가 말 상대를 안 해 준다면\n어떻게 할 거야?",
  str_homestory_chat_22123003 = "조용히 떠나야겠지?",
  str_homestory_chat_22123004 = "조용히 떠나는 당신 모습을 상상해 보니 좀 불쌍하네.",
  str_homestory_chat_22123005 = "그럼 최대한 어울려 줄게.",
  str_homestory_chat_22123006 = "계속 말을 걸어야겠지...",
  str_homestory_chat_22123007 = "대답해 줄 때까지... 아마 계속 이럴 거야.",
  str_homestory_chat_22123008 = "그러다가는 입술이 쩍쩍 갈라질 때까지 말해야 할걸.",
  str_homestory_chat_22124001 = "여기서 네 가시나무를 발견했다면서?",
  str_homestory_chat_22124002 = "맞아. 사실은 내 손으로 심은 거지만 말이야.",
  str_homestory_chat_22124003 = "왜 심은 건데?",
  str_homestory_chat_22124004 = "그 전에 하나 물어보고 싶어.\n당신은 가시나무를 어떤 식물이라고 생각해?",
  str_homestory_chat_22124005 = "평범한 식물이라고 생각해.",
  str_homestory_chat_22124006 = "특별한 식물이라고 생각해.",
  str_homestory_chat_22124007 = "사실 가시덤불은 일종의 「환경」이야.",
  str_homestory_chat_22124008 = "「환경」?",
  str_homestory_chat_22124009 = "가시를 지닌 식물은 아주 많아.\n그리고 그런 특징을 지닌 식물들이 모여\n무리를 이루면 「가시나무」가 되는 거지.",
  str_homestory_chat_22124010 = "그건 아니지 않아? 내 기억엔 따로 가시나무란 식물이 있었어.\n가시 돋친 줄기가 있는 그런 식물이었었나?",
  str_homestory_chat_22124011 = "보편적으로 그렇다는 얘기야!\n종류가 어떻게 됐든 가시가 돋쳐 있는 식물이\n잔뜩 있다면 「가시나무」라고 불러도 되는 거라고.",
  str_homestory_chat_22124012 = "특히 넓은 범위에 무성히 자라서 길까지 막고 있다면,\n흔히들 얘기하는 「가시나무 숲」이 되는 거라고.",
  str_homestory_chat_22124013 = "그, 그렇구나! 왠지 좀 이해가 되는 것 같아.",
  str_homestory_chat_22125001 = "츄브들한테 뭐 물어보고 있었어?",
  str_homestory_chat_22125002 = "맞아. 당신은 츄브들을 어떻게 생각해?",
  str_homestory_chat_22125003 = "원래부터 여기 살고 있던 토박이지.",
  str_homestory_chat_22125004 = "아주 특이한 생명체인 것 같아.",
  str_homestory_chat_22125005 = "왠지 모르게 지혜로운 면도 있는 존재들...?",
  str_homestory_chat_22125006 = "잠깐만, 근데 이거랑 파로마 네가 츄브들한테\n뭐 물어보고 있던 거랑은 별 상관없지 않아?",
  str_homestory_chat_22125007 = "파로마 넌 츄브들에 대해서 어떻게 생각하는데?",
  str_homestory_chat_22125008 = "아주 좋은 생명체들이지.\n세상에서 제일 훌륭한 녀석들일지도 몰라.",
  str_homestory_chat_22125009 = "왜 그렇게 생각해? 외모 때문에?\n츄브들처럼 네모난 머리가 꽤 인기란 얘길 듣긴 했는데.",
  str_homestory_chat_22125010 = "그 이유도 없진 않지만,\n가장 중요한 이유는 솔직하기 때문이야.",
  str_homestory_chat_22125011 = "솔직하다고?",
  str_homestory_chat_22125012 = "츄브들은 사람을 속이지 않잖아.\n필요한 게 있다면 바꿔달라 하면 돼.",
  str_homestory_chat_22125013 = "상대가 누구든 갑자기 값을 올려 부르거나,\n자꾸 말이 달라지거나, 나중에 가서 무르겠다거나\n하는 상도덕이 없는 짓은 안 하지.",
  str_homestory_chat_22125014 = "게다가 무슨 얘길 해도 참을성 있게\n잘 들어 주기까지 해.",
  str_homestory_chat_22125015 = "파로마 너... 요새 츄브들한테 찾아가서 대체 뭘 한 거야...?",
  str_homestory_chat_22126001 = "뭐 하고 있었어?",
  str_homestory_chat_22126002 = "날씨를 살펴보는 중이었어. 이건 아주 중요한 일이야.",
  str_homestory_chat_22126003 = "그런 거 치곤 아까 계속 눈 감고 있었던 것 같은데.",
  str_homestory_chat_22126004 = "내가 눈을 감고 있었다고?",
  str_homestory_chat_22126005 = "한참이나 감고 있었잖아... 진짜 날씨 살펴보던 거 맞아?",
  str_homestory_chat_22126006 = "가끔은 사색의 시간을 갖는 것도 중요한 거야.",
  str_homestory_chat_22126007 = "사색보단 그냥 짬을 내서 쉬고 있는 것 같았는데...",
  str_homestory_chat_22126008 = "안 그랬거든!",
  str_homestory_chat_22126009 = "사색은 아주 중요한 요소야.\n일과 중에선 특히 더 그렇지.",
  str_homestory_chat_22126010 = "기계의 톱니바퀴도 오래 작동하면 한 번씩\n멈춰 줄 때도 있어야 하는 거잖아.",
  str_homestory_chat_22126011 = "그게 쉬는 거 아냐...?",
  str_homestory_chat_22127001 = "오늘은 날씨가 꽤 좋네.",
  str_homestory_chat_22127002 = "그러게. 근데 여긴 평소에도 날씨가 이렇잖아.\n갑자기 날씨가 좋단 얘긴 왜 한 거야?",
  str_homestory_chat_22127003 = "그냥 말 걸려고 해본 소리야.",
  str_homestory_chat_22127004 = "그냥 날씨가 정말 좋으니까.",
  str_homestory_chat_22127005 = "휴, 당신 이젠 대화를 어떻게 시작하는지도\n잘 모르게 된 거야?",
  str_homestory_chat_22127006 = "그나마 연습 상대가 돼 줄 동료가 많아서 다행이겠네.",
  str_homestory_chat_22127007 = "그치만 동료는 대화 연습 상대가 아닌걸...",
  str_homestory_chat_22127008 = "그건 착각이야.",
  str_homestory_chat_22127009 = "으음...?",
  str_homestory_chat_22127010 = "당신 동료가 헤븐즈 가든까지 와 줬다는 건,\n적어도 그 사람은 당신과 소통하고 싶다는 뜻이니까.",
  str_homestory_chat_22127011 = "대화 주제가 일상적이든 엉뚱하든, 심지어는...",
  str_homestory_chat_22127012 = "으음, 조금 특이한 생각까지도.",
  str_homestory_chat_22127013 = "다들 당신 말을 받아주려고 할 거야.\n아무리 난감하더라도 말이지.",
  str_homestory_chat_22127014 = "예를 들면, 아까 당신은 말을 걸려고 「날씨가 좋다」고 했어.\n근데 마침 그날따라 날씨가 별로면 어떻게 할 거야?",
  str_homestory_chat_22127015 = "그럼 대화 주제를 「끔찍한 날씨」로 바꾸면 되지 않아?",
  str_homestory_chat_22127016 = "아, 드디어 이해한 모양이네.",
  str_homestory_chat_22127017 = "어? 그냥 그러면 되는 거라고? 그게 다야?",
  str_homestory_chat_22128001 = "암귀?",
  str_homestory_chat_22128002 = "이 문제에 대해 얘기할 필요가 있을 것 같거든.",
  str_homestory_chat_22128003 = "안전이 걱정돼서 그래? 그거라면 걱정 마.\n여긴 꽤 외진 곳이라 암귀들이 올 일은 없을 거야.",
  str_homestory_chat_22128004 = "안전 문제가 아니야.\n암귀들은 대체 왜 우릴 공격하는 걸까?\n이 부분에 대해서 생각해 본 적 있어?",
  str_homestory_chat_22128005 = "응.",
  str_homestory_chat_22128006 = "그래? 당신 생각엔 이유가 뭔데?",
  str_homestory_chat_22128007 = "일종의 본능인 것 같아.",
  str_homestory_chat_22128008 = "본능이라...",
  str_homestory_chat_22128009 = "아니.",
  str_homestory_chat_22128010 = "그치만... 굳이 하나 집어 보자면 녀석들의 본능이 아닐까?",
  str_homestory_chat_22128011 = "그럴 가능성도 있긴 해.",
  str_homestory_chat_21599999 = "안녕하신가요. PlayerName 님.",
  str_homestory_chat_21501001 = "안녕, 나로세르.",
  str_homestory_chat_21501002 = "오늘도 자연의 가호 아래 멋진 하루를\n보내시길 바랄게요.",
  str_homestory_chat_21501003 = "아, 그렇게 말해 줘서 고마워.",
  str_homestory_chat_21501004 = "이게 제 할 일인걸요.",
  str_homestory_chat_21521001 = "여기에 꽤 익숙해졌나 봐.",
  str_homestory_chat_21521002 = "네, 완벽하게 파악했어요.",
  str_homestory_chat_21521003 = "이 근처로 물건을 보내실 일이 있다면\n언제든 절 찾아 주세요.",
  str_homestory_chat_21521004 = "알겠어!",
  str_homestory_chat_21521005 = "이곳의 오로리안들에게 편지를 전하는 일이라면,\n저도 충분히 할 수 있어요.",
  str_homestory_chat_21521006 = "고마워!",
  str_homestory_chat_21521007 = "그래도 귀찮게 하고 싶진 않아...",
  str_homestory_chat_21521008 = "여기서 지내도록 초대해 주셨는데,\n아직 감사 인사도 제대로 못 했잖아요.",
  str_homestory_chat_21521009 = "그런 사소한 일은 제게 맡겨 주세요.\n답례라고 생각하시면 돼요.",
  str_homestory_chat_21522001 = "날씨 참 좋네.",
  str_homestory_chat_21522002 = "여긴 날씨에서부터 온화한 기운이 느껴져요.\n정말 마음이 편안해지는 것 같네요.",
  str_homestory_chat_21522003 = "기온이 떨어져도 그렇게 춥지도 않고요.",
  str_homestory_chat_21522004 = "추위를 잘 타는 편이야?",
  str_homestory_chat_21522005 = "제 몸은 너무 추운 날씨는 감당하지 못해요...",
  str_homestory_chat_21522006 = "따뜻한 곳이 좋아?",
  str_homestory_chat_21522007 = "사실 특별히 좋아하거나 싫어하는 온도는 없어요.\n그 어떤 기온이라도 모두 자연의 일부니까요.",
  str_homestory_chat_21522008 = "다만 추운 곳에서는 오랜 시간 머물기 힘들어요.",
  str_homestory_chat_21522009 = "그래서 이곳의 기후는 제가 활동하기\n가장 적합한 온도랍니다.",
  str_homestory_chat_21523001 = "여기서 평소에는 뭐 하면서 지냈어?",
  str_homestory_chat_21523002 = "...제게 물어보시는 건가요?",
  str_homestory_chat_21523003 = "맞아.",
  str_homestory_chat_21523004 = "평소에는 네 모습이 잘 안 보이더라고...",
  str_homestory_chat_21523005 = "아... 그건 아마 제가 숲속에서 산책하는 걸\n너무 좋아해서 그럴 거예요.",
  str_homestory_chat_21523006 = "긴장을 풀고 싶으시다면 저랑 같이 산책하러 가요.",
  str_homestory_chat_16599999 = "안녕하심니꺼!",
  str_homestory_chat_16501001 = "안녕, 트위티.",
  str_homestory_chat_16501002 = "오늘은 지가 오빠야의 쿠리어가 되어 드릴까예?",
  str_homestory_chat_16501003 = "고맙긴 한데, 당장은 괜찮아.",
  str_homestory_chat_16521001 = "뭘 찾고 있는 거야?",
  str_homestory_chat_16521002 = "하이고, 오빠야. 혹시 여도 눈꽃이 있심꺼?",
  str_homestory_chat_16521003 = "있지!",
  str_homestory_chat_16521004 = "여긴 눈꽃을 만들 수 있는 사람이 꽤 있거든.",
  str_homestory_chat_16521005 = "그라모 오데 가면 만날 수 있심꺼?\n만나러 가야겠심더!",
  str_homestory_chat_16521006 = "없을걸...",
  str_homestory_chat_16521007 = "우예 없심니꺼...",
  str_homestory_chat_16521008 = "그라모 지가 제빙기로 직접 맹글어야켔네예!",
  str_homestory_chat_16522001 = "나한테 하고 싶은 말 있어?",
  str_homestory_chat_16522002 = "오빠야, 지 말투가 그래 웃김미꺼?",
  str_homestory_chat_16522003 = "편지 가와가 지가 무슨 말만 카믄\n마카 다 웃다 디비진다 아입니꺼.",
  str_homestory_chat_16522004 = "난 괜찮은 것 같은데.",
  str_homestory_chat_16522005 = "사투리가 좀 섞여 있어서 그렇지.",
  str_homestory_chat_16522006 = "그리고 말은 알아듣기만 하면 그만이지.\n웃기고 안 웃기고가 어디 있어.",
  str_homestory_chat_16522007 = "히잉, 위로해 주셔서 고맙심더.",
  str_homestory_chat_16523001 = "오늘 엄청 덥네...",
  str_homestory_chat_16523002 = "하모요, 억수로 덥슴니더.",
  str_homestory_chat_16523003 = "오빠야, 으데가 좀 시원한지 아심미꺼?",
  str_homestory_chat_16523004 = "나무 아래는 아주 시원해.",
  str_homestory_chat_16523005 = "그라모 지는 나무 아래로 가 쉬겠슴니더.",
  str_homestory_chat_16523006 = "지한테 볼일 생기믄 나무 아래로 찾아오이소.",
  str_homestory_chat_16523007 = "아이스크림을 좀 먹어 봐.",
  str_homestory_chat_16523008 = "그라모 지는 아이스크림을 왕창 무야겠심더.",
  str_homestory_chat_22699999 = "안녕하세요, 조종사.",
  str_homestory_chat_22601001 = "안녕, 베델.",
  str_homestory_chat_22601002 = "사교 매너는 제대로 알고 계시네요.",
  str_homestory_chat_22601003 = "뭔가 조언해주고 싶은 게 있는 거야?",
  str_homestory_chat_22601004 = "조언해 드릴 건 없어요...\n그보다는, 만나서 정말 반가워요.",
  str_homestory_chat_22621001 = "뭐 새로운 일이라도 있어?",
  str_homestory_chat_22621002 = "대화를 하려는 건가요?\n저와 대화를 나누려면 일단 예약부터 하셔야 해요.",
  str_homestory_chat_22621003 = "이야기를 하는 것도 예약해야 해?",
  str_homestory_chat_22621004 = "제가 표현을 모호하게 했나요?",
  str_homestory_chat_22621005 = "뭐? 예약은 어떻게 하면 되는데?",
  str_homestory_chat_22621006 = "딱 한 번만 말할 테니까 잘 기억하세요...",
  str_homestory_chat_22621007 = "우선은 제 비서를 찾아가세요.\n그럼 비서가 시간을 예약해 줄 거예요.",
  str_homestory_chat_22621008 = "그, 그렇게 복잡해?",
  str_homestory_chat_22621009 = "그렇지만 지금은 한가하니 할 말이 있다면\n어서 하세요.",
  str_homestory_chat_22622001 = "난 왜 찾은 거야?",
  str_homestory_chat_22622002 = "여기 독서회를 만들려고 해요. 어떻게 생각하나요?",
  str_homestory_chat_22622003 = "좋지!",
  str_homestory_chat_22622004 = "근데 어떤 독서회를 만들고 싶은 거야?",
  str_homestory_chat_22622005 = "그건 영업 비밀이에요. 말할 수 없어요.",
  str_homestory_chat_22622006 = "만들 수 있겠어?",
  str_homestory_chat_22622007 = "당연하죠! 구체적인 계획도 준비해 뒀어요.",
  str_homestory_chat_22622008 = "독서 애호가를 찾으려고 정말 열심히 노력했답니다.",
  str_homestory_chat_22623001 = "이곳 생활에는 익숙해졌어?",
  str_homestory_chat_22623002 = "제가 적응을 못 하는 경우는 드물어요...",
  str_homestory_chat_22623003 = "이곳과 움브라톤에서 생활도 크게 다르진 않아요.",
  str_homestory_chat_22623004 = "유일한 차이점이라면 제가 더 조용히\n지낼 수 있다는 점이겠네요.",
  str_homestory_chat_22623005 = "그럼 심심하다고 느끼진 않아?",
  str_homestory_chat_22623006 = "일종의 휴가라고 생각하면 되죠.",
  str_homestory_chat_22999999 = "만나서 정말 기뻐.",
  str_homestory_chat_22901001 = "안녕, 나도 반가워.",
  str_homestory_chat_22901002 = "새로운 의뢰가 있는 거야?",
  str_homestory_chat_22901003 = "그렇진 않아...",
  str_homestory_chat_22901004 = "좋네. 그럼 이참에 좀 쉬면 되겠어.",
  str_homestory_chat_22921001 = "가면을 벗어줄 줄 수 있어?",
  str_homestory_chat_22921002 = "...가면을 쓴 사람하고 이야기하는 건 적응이 안 돼?",
  str_homestory_chat_22921003 = "조금...",
  str_homestory_chat_22921004 = "가면을 쓰면 거리감이 생긴다고 하는\n사람들이 있긴 했지.",
  str_homestory_chat_22921005 = "가면 말고 내 눈만 보려고 해 봐.\n기분이 좀 괜찮아질 거야.",
  str_homestory_chat_22921006 = "그래도 안 되겠으면 가면을 벗도록 할게.",
  str_homestory_chat_22921007 = "아니...",
  str_homestory_chat_22921008 = "그럼 그냥 궁금해서 가면을 벗어 달라고 했던 거야?",
  str_homestory_chat_22921009 = "궁금해서 그랬던 거라도 괜찮아.\n그런 걸로 기분이 상하지 않거든.",
  str_homestory_chat_22922001 = "지금 무슨 생각해?",
  str_homestory_chat_22922002 = "요즘 자기 옷에 그림을 그려 달라고\n부탁하는 사람들이 꽤 있더라고.",
  str_homestory_chat_22922003 = "무슨 그림인데?",
  str_homestory_chat_22922004 = "예를 들면, 「가장 좋아하는 헤븐즈 가든 모퉁이」\n이런 거...",
  str_homestory_chat_22922005 = "왜 그런 부탁을 하는 건데?",
  str_homestory_chat_22922006 = "옷에 헤븐즈 가든의 풍경을 그려 넣는 게\n요즘 유행이거든...",
  str_homestory_chat_22922007 = "누가 시작한 건지는 모르겠지만 말이야.",
  str_homestory_chat_22922008 = "너도 그런 옷을 가지고 싶으면\n무료로 하나 그려 줄게.",
  str_homestory_chat_22923001 = "기분이 무척 좋아 보이네...",
  str_homestory_chat_22923002 = "좋은 일이라도 있었어?",
  str_homestory_chat_22923003 = "좋은 일?",
  str_homestory_chat_22923004 = "아, 오늘 숲에서 어렸을 때 봤던\n곤충 몇 마리를 봤거든.",
  str_homestory_chat_22923005 = "그래서 기분이 좋아.",
  str_homestory_chat_22923006 = "곤충에 관심 있어?",
  str_homestory_chat_22923007 = "응!",
  str_homestory_chat_22923008 = "그럼 다음에는 같이 보러 가자.",
  str_homestory_chat_22923009 = "별로 관심 없어...",
  str_homestory_chat_22923010 = "자주 보다 보면 없던 흥미가 생겨날 때도 있어.",
  str_homestory_chat_22923011 = "다음번에 관찰하러 갈 때는 같이 가지 않을래?",
  str_homestory_chat_15599999 = "지금은 업무 시간입니다만... 아... 안녕하십니까.",
  str_homestory_chat_15501001 = "안녕하세요. 혹시 제가 방해한 건가요?",
  str_homestory_chat_15501002 = "이런, 죄송합니다. 제가 나쁜 습관이 들었나 보군요.",
  str_homestory_chat_15501003 = "만나서 반갑습니다. PlayerName 님.",
  str_homestory_chat_15501004 = "일하실 때마다 제가 자주 방해했었나요...?",
  str_homestory_chat_15501005 = "아닙니다. 이건 제 문제입니다.\n아무래도 일에 너무 오랫동안 집중해\n버린 모양입니다.",
  str_homestory_chat_15521001 = "이곳에 흥미가 많으신 모양이네요.",
  str_homestory_chat_15521002 = "그렇습니다.\n이곳에 오고 나서부터는 여행기를 꽤 많이 적었습니다.",
  str_homestory_chat_15521003 = "제게는 이곳의 많은 것들이 낯설고, 또 새롭습니다.",
  str_homestory_chat_15521004 = "그래서 자꾸 저도 모르게 본 것들을\n종이에 기록하게 되어 버립니다...",
  str_homestory_chat_15521005 = "이런 행동들 때문에 당신이 곤란해지는 일은\n없었으면 좋겠군요.",
  str_homestory_chat_15521006 = "전혀 곤란하지 않아요.\n기록하고 싶으신 만큼 기록하셔도 돼요.",
  str_homestory_chat_15522001 = "왜 절 보고 계세요?",
  str_homestory_chat_15522002 = "요즘 훈련은 열심히 하고 계십니까?",
  str_homestory_chat_15522003 = "네.",
  str_homestory_chat_15522004 = "좋습니다. 도주범 체포 자격을 갖추셨군요.",
  str_homestory_chat_15522005 = "아니요...",
  str_homestory_chat_15522006 = "아무래도... 도주범 체포는 저 혼자서 해야겠군요.",
  str_homestory_chat_15522007 = "여기 도주범이 나타난 건가요?!",
  str_homestory_chat_15522008 = "음, 「도주범」은 정확하지 않은 표현일지도\n모르겠군요...",
  str_homestory_chat_15522009 = "그럼 대체 뭐죠?!",
  str_homestory_chat_15522010 = "크흠, 토끼입니다.\n토끼가 꽃밭의 꽃을 잔뜩 먹어 치웠습니다...",
  str_homestory_chat_15523001 = "저한테 볼일이 있으시다면서요?",
  str_homestory_chat_15523002 = "PlayerName 님, 혹시 수업을 열어 볼\n생각은 없습니까?",
  str_homestory_chat_15523003 = "그게 무슨 말이죠?",
  str_homestory_chat_15523004 = "이곳의 유적에는 수많은 고대의 지식과 지혜가\n잠들어 있습니다...",
  str_homestory_chat_15523005 = "그 지식과 지혜들을 이어 나가고 싶지 않으십니까?",
  str_homestory_chat_15523006 = "일리 있는 얘기네요. 생각해 볼게요.",
  str_homestory_chat_22099999 = "또 만났네요. PlayerName 씨.",
  str_homestory_chat_22001001 = "안녕, 헤이디.",
  str_homestory_chat_22001002 = "아... 그렇지. 제가 얼마 전에 괜찮은 책을\n읽었거든요. 그래서 추천해 드리고 싶은데요...",
  str_homestory_chat_22001003 = "관심이 있으실지 모르겠네요.",
  str_homestory_chat_22001004 = "네 마음에 든 책이라면 엄청 재미있겠는걸.",
  str_homestory_chat_22021001 = "산책 중이야?",
  str_homestory_chat_22021002 = "네, 폼페이를 데리고 풀밭에서 산책했어요.",
  str_homestory_chat_22021003 = "여기라면 드디어 폼페이가 뭘 망가트리진 않을까\n걱정할 필요가 없겠네요.",
  str_homestory_chat_22021004 = "저희와 함께 산책하고 싶으시다면 언제든 환영해요.",
  str_homestory_chat_22021005 = "정말 같이 산책해도 돼?",
  str_homestory_chat_22021006 = "폼페이와 함께 산책하면 분명 멋질 거예요.",
  str_homestory_chat_22021007 = "마음은 굴뚝같지만...",
  str_homestory_chat_22021008 = "요즘 조금 바빠.",
  str_homestory_chat_22021009 = "걱정하지 마세요. 제 초대는 영원히 유효하답니다.",
  str_homestory_chat_22022001 = "얼마 뒤면 파티가 하나 열리는데...",
  str_homestory_chat_22022002 = "참가할래?",
  str_homestory_chat_22022003 = "초대해 주신 건 감사하지만...\n사람이 많으면 좀 거북해서요.",
  str_homestory_chat_22022004 = "그렇구나...",
  str_homestory_chat_22022005 = "그래도 파티 장소 근처의 높은 곳에서...",
  str_homestory_chat_22022006 = "파티를 구경하는 것도 어떻게 보면\n일종의 참여라고 할 수 있겠죠.",
  str_homestory_chat_22022007 = "하아?",
  str_homestory_chat_22023001 = "무슨 일로 날 찾은 거야?",
  str_homestory_chat_22023002 = "책 몇 권만 좀 찾아 주실 수 있나요?",
  str_homestory_chat_22023003 = "찾아 줄게.",
  str_homestory_chat_22023004 = "근데 며칠 전에 책을 엄청나게 많이 사지 않았어?",
  str_homestory_chat_22023005 = "벌써 다 읽은 거야?",
