  str_homestory_chat_22399999 = "안녕!",
  str_homestory_chat_22301001 = "안녕! 커디!",
  str_homestory_chat_22301002 = "오늘은 나도 열심히 이곳의 치안을 지키고 있어!",
  str_homestory_chat_22301003 = "이야, 고생이 많네.",
  str_homestory_chat_22301004 = "모두에게 안전한 환경을 만들어 줄 수만 있다면\n뭘 해도 힘들지 않아!",
  str_homestory_chat_22321001 = "벌써 가려고?",
  str_homestory_chat_22321002 = "으, 오늘은 아직 집 정리를 안 했다는 게\n생각났거든...",
  str_homestory_chat_22321003 = "우리 아직 두 마디도 안 했는데?",
  str_homestory_chat_22321004 = "나도 더 얘기하고 싶지만...",
  str_homestory_chat_22321005 = "집 정리를 안 했다는 생각 때문에 집중이 안 돼...",
  str_homestory_chat_22321006 = "으아아, 도저히 못 참겠어.\n빨리 가 봐야 할 것 같아. 진짜 미안!",
  str_homestory_chat_22322001 = "오늘은 뭔가 기분이 좋아 보이네?",
  str_homestory_chat_22322002 = "응, 새로 나눠 준 제복을 받았어!",
  str_homestory_chat_22322003 = "새 옷 입는 거 좋아해?",
  str_homestory_chat_22322004 = "새 옷이라고 다 좋아하는 건 아니야...",
  str_homestory_chat_22322005 = "이번에 나눠 준 새 제복은 세탁을 안 해도\n이상할 정도로 부드럽거든.",
  str_homestory_chat_22322006 = "이렇게 부드러운 옷을 입을 생각을 하니까...\n나도 모르게 웃음이 나온다니까...",
  str_homestory_chat_22322007 = "아, 놀리지는 말아줘.",
