  str_homestory_chat_22323005 = "스, 슬퍼서 운 게 아니야...",
  str_homestory_chat_22323006 = "치, 치안관을 하다 보면 놀라서 심장이\n떨어질 것 같은... 돌발 사건들이 생기곤 해...",
