  str_homestory_chat_11523003 = "누가 잘못 전달한 모양인데...",
  str_homestory_chat_11523004 = "실버가 그런 게 분명해.",
  str_homestory_chat_11523005 = "지금 바로 가서 물어볼게.",
  str_homestory_chat_11523006 = "아무래도... 평범한 파티인 것 같네.",
