  str_homestory_chat_23101002 = "여기서 산책 중이셨나요?",
  str_homestory_chat_23101003 = "네.",
  str_homestory_chat_23101004 = "함께 걸으시겠습니까?",
  str_homestory_chat_23121001 = "여기서 지내는 건 좀 어떠신가요?",
  str_homestory_chat_23121002 = "북방을 떠나 다른 곳에 갈 때마다 불편하다는\n느낌을 많이 받았습니다.",
  str_homestory_chat_23121003 = "하지만 이곳에서는 신기하게도\n그런 느낌이 들지 않습니다.",
  str_homestory_chat_23121004 = "잘 적응하고 계신 것 같네요.",
  str_homestory_chat_23121005 = "아마, 모두 조종사님 덕분일 겁니다.",
  str_homestory_chat_23122001 = "찾는 게 있나요?",
  str_homestory_chat_23122002 = "신선한 당근 있습니까?",
  str_homestory_chat_23122003 = "당근으로 뭐 하시려고요?",
  str_homestory_chat_23122004 = "저희 토끼 가족에게 새 식구가 생겼습니다.",
  str_homestory_chat_23122005 = "전에는 세 끼를 먹을 수 있던 분량을\n이제는 두 끼면 다 먹어 치웁니다.",
  str_homestory_chat_23122006 = "그래서 골치가 아프네요...",
  str_homestory_chat_23122007 = "아... 그랬군요. 제가 좀 물어봐 드릴게요.",
  str_homestory_chat_23123001 = "여왕 폐하를 찾고 계신가요?",
