  str_homestory_chat_23123003 = "알아요.",
  str_homestory_chat_23123004 = "바로 저기 계세요.",
  str_homestory_chat_23123005 = "잘됐군요. 방금 보석 브로치를 하나 만든\n참이었습니다...",
  str_homestory_chat_23123006 = "여왕 폐하께서 착용해 주시면 어떤 모습일지\n정말 기대되는군요.",
  str_homestory_chat_23123007 = "모르겠어요...",
  str_homestory_chat_23123008 = "방금 보석 브로치를 하나 만들어서\n여왕 폐하께 바치려 했었는데...",
  str_homestory_chat_23123009 = "그럼 이걸 누구에게 주어야 할까요...",
  str_homestory_chat_23123010 = "아아, 역시 제가 가지고 있는 편이 좋겠습니다.",
  str_homestory_chat_23124001 = "뭔가 듣고 계세요?",
  str_homestory_chat_23124002 = "네, 자연의 소리를 듣고 있습니다.\n가끔은 노래보다 더 듣기 좋거든요.",
  str_homestory_chat_23124003 = "조종사님은 음악을 좋아하십니까?",
