  str_homestory_chat_23125002 = "네. 며칠 동안 어떤 생각 때문에 답답해서,\n바람 좀 쐬러 나왔습니다.",
  str_homestory_chat_23125003 = "조종사님은 이럴 때 어떻게 하시는지요.",
  str_homestory_chat_23125004 = "산책을 해요.",
  str_homestory_chat_23125005 = "아무 생각 없이 그냥 걸어요.",
  str_homestory_chat_23125006 = "책을 읽어요.",
  str_homestory_chat_23125007 = "움브라톤에 연재되는 삼류 의적 이야기처럼 머리 안 써도 되는 책 위주로요.",
  str_homestory_chat_23125008 = "조종사님도 머리를 맑게 하려고\n많은 노력을 했던 모양이군요.",
  str_homestory_chat_23125009 = "아무래도 이곳을 지켜야 한다는 책임의\n부담감이 무척 크신 듯합니다.",
  str_homestory_chat_23125010 = "그건... 뭐 그렇게 힘들진 않아요.",
