  str_homestory_chat_23201001 = "그러게!",
  str_homestory_chat_23201002 = "벌꿀 케이크 한 조각 먹을래?",
  str_homestory_chat_23201003 = "로라의 특별 비법으로 만든 케이크라서\n먹어도 살이 안 쪄!",
  str_homestory_chat_23201004 = "그런 게 가능하단 말이야?",
  str_homestory_chat_23221001 = "뭐 찾아?",
