  str_homestory_chat_25501005 = "그렇게 말한 사람들이 누군지... 정말 궁금하네요.",
  str_homestory_chat_25521001 = "저한테 물어보신다는 게 뭐죠?",
  str_homestory_chat_25521002 = "너는 전투에 검을 쓰는 것이 좋다고 생각하나?\n아니면 총이 더 좋다고 생각하나?",
  str_homestory_chat_25521003 = "검이요.",
  str_homestory_chat_25521004 = "맞는 말이다! 검은 적에게 압박감을 줄 수 있지.",
  str_homestory_chat_25521005 = "게다가 근접 전투에서는 빠르게 연속 공격을\n가할 수도 있다.",
  str_homestory_chat_25521006 = "내가 무기로 검을 선택한 것도 바로 이런 이유에서다.",
  str_homestory_chat_25521007 = "총이요.",
  str_homestory_chat_25521008 = "음... 아이테르의 견해에 기반한 선택인가?",
  str_homestory_chat_25521009 = "너희는 감지 능력이 뛰어나니\n사격의 정확도도 아주 높겠지.",
  str_homestory_chat_25521010 = "하지만... 전...",
  str_homestory_chat_25521011 = "그건 네 훈련량이 부족해서 그런 거다.\n며칠 뒤에 특훈을 시켜 주마!",
  str_homestory_chat_25521012 = "내가 널 특급 사수로 만들어 주지!",
  str_homestory_chat_25521013 = "아, 알겠어요.",
  str_homestory_chat_25521014 = "잘 모르겠는데요...",
  str_homestory_chat_25521015 = "확실히 네가 전투에 익숙한 편은 아니지.",
  str_homestory_chat_25521016 = "다른 사람한테 물어봐야겠어. 바이스라든가...",
  str_homestory_chat_25521017 = "여기서는 매일 전투에 대해서만 생각하지 않으셨으면 좋겠어요...",
  str_homestory_chat_25522001 = "저한테 볼일이 있으시다면서요?",
  str_homestory_chat_25522002 = "검이 조금 무뎌진 것 같아서 말이지.\n여기 좋은 숫돌이 있나?",
  str_homestory_chat_25522003 = "있어요.",
  str_homestory_chat_25522004 = "아주 좋은 숫돌이어야 한다.\n윤기가 흐르면서 살짝 까칠까칠한 그런 돌 말이야.",
  str_homestory_chat_25522005 = "그런 돌이라면... 없을 것 같네요.",
  str_homestory_chat_25522006 = "없어요.",
  str_homestory_chat_25522007 = "이런... 역시 아이테르답군.",
  str_homestory_chat_25522008 = "평화를 사랑하는 사람들이라 이건가...",
  str_homestory_chat_25522009 = "무기도 제대로 관리할 줄 모르는 녀석들이라니.",
  str_homestory_chat_25523001 = "뭐 하고 계세요?",
  str_homestory_chat_25523002 = "...여긴 정말 조용한 곳이군.",
  str_homestory_chat_25523003 = "은퇴하고 나면 이곳에서 은거해도 되겠어.",
  str_homestory_chat_25523004 = "바튼 씨...",
  str_homestory_chat_25523005 = "아? 들었나? 방금 그건 혼잣말이었다!",
  str_homestory_chat_25523006 = "은퇴라니...",
  str_homestory_chat_25523007 = "아직 젊으시잖아요...",
  str_homestory_chat_25523008 = "아, 방금은 내가 잠깐 회까닥했던 모양이군.",
  str_homestory_chat_25523009 = "사실 가능만 하다면 난 은퇴는 하고 싶지 않거든.",
  str_homestory_chat_25523010 = "너무 늙어버린다면 큰 전투에서 총에 맞아\n세상을 떠났으면 좋겠군.",
  str_homestory_chat_25523011 = "그것이야말로 병사로서 맞이할 수 있는\n최고의 결말이니까.",
  str_homestory_chat_25523012 = "그, 근데 바튼 씨는 장군이잖아요...",
  str_homestory_chat_25699999 = "어머, PlayerName, 또 만났네.",
  str_homestory_chat_25601001 = "안녕, 니나.",
  str_homestory_chat_25601002 = "여기 올 때마다 자꾸 너한테 질문이\n하고 싶어진단 말이지.",
  str_homestory_chat_25601003 = "질문?",
  str_homestory_chat_25601004 = "아이테르의 심미감은 다들 이렇게 소박한 거야?",
  str_homestory_chat_25601005 = "음... 맞아.",
  str_homestory_chat_25601006 = "하지만 의외로 주변 환경과 멋지게 조화를\n이루고 있어. 생활하기에도 편안하고 말이야.",
  str_homestory_chat_25601007 = "앞으로도 이 상태를 유지했으면 좋겠어.\n움브라톤의 저속한 유행을 따르지 말고.",
  str_homestory_chat_25601008 = "칭찬 고마워.",
  str_homestory_chat_25621001 = "항상 우산을 가지고 다니네...",
  str_homestory_chat_25621002 = "아이테르, 내가 들고 있는 게 뭔지\n구체적으로 설명해 봐.",
  str_homestory_chat_25621003 = "항상 넌 뭔가 말을 피하고 있는 것 같단 말이야...",
  str_homestory_chat_25621004 = "양산이잖아?",
  str_homestory_chat_25621005 = "내 교육이 헛되진 않았나 보네. 안심했어.",
  str_homestory_chat_25621006 = "(후우... 겨우 넘어갔네.)",
  str_homestory_chat_25621007 = "뭐라고 중얼거리고 있는 걸까?",
  str_homestory_chat_25621008 = "아, 아무것도 아니야. 그럼 다음에 봐!",
  str_homestory_chat_25621009 = "우산이잖아?",
  str_homestory_chat_25621010 = "내가 몇 번이나 말했어?!\n이건 「양산」이지, 「우산」이 아니야!",
  str_homestory_chat_25621011 = "휴... 너한테 매번 이걸 강조하려니까\n정말 피곤하네.",
  str_homestory_chat_25621012 = "아, 알았어. 잘 기억해 둘게.",
  str_homestory_chat_25621013 = "지금 한 말을 잊어서는 안 될 거야.",
  str_homestory_chat_25622001 = "이제 뭐 할 거야?",
  str_homestory_chat_25622002 = "애프터눈 티를 마시고 싶어. 좋은 찻잎이 있을까?",
  str_homestory_chat_25622003 = "움브라톤에서 사서 상점에 뒀던 거로 기억하는데...",
  str_homestory_chat_25622004 = "그럼 애프터눈 티를 즐길 장소도 있을까?",
  str_homestory_chat_25622005 = "장소까지 따로 있단 말이야?",
  str_homestory_chat_25622006 = "애프터눈 티는 그냥 차를 즐기는 게 아니야.\n차를 마시는 그 시간을 즐기는 거지.",
  str_homestory_chat_25622007 = "장소도 아주 중요해. 조용하고 아늑해야 돼.\n자연의 소리가 들린다면 더 좋겠지.",
  str_homestory_chat_25622008 = "자연의 소리?",
  str_homestory_chat_25622009 = "예를 들면 가끔 들리는 벌레 소리,\n하늘을 지나는 새소리, 바람이 나뭇잎을\n사삭사삭 흔드는 소리 말이야.",
  str_homestory_chat_25622010 = "내가 열심히 찾아볼게.",
  str_homestory_chat_25623001 = "뭘 찾고 있어?",
  str_homestory_chat_25623002 = "여기 재미있는 소설은 없을까?",
  str_homestory_chat_25623003 = "어떤 장르가 좋아?",
  str_homestory_chat_25623004 = "좀 무서운 것도 있어?",
  str_homestory_chat_25623005 = "호러 소설 같은 거...",
  str_homestory_chat_25623006 = "어디 보자... 아, 있어!",
  str_homestory_chat_25623007 = "《움브라톤의 108가지 무서운 이야기》.",
  str_homestory_chat_25623008 = "정말 저속한 제목이네...\n근데 넌 좋아하는 모양이지?",
  str_homestory_chat_25623009 = "그럼 나도 억지로 참고 너랑 같이 읽어볼게.",
  str_homestory_chat_25799999 = "PlayerName 님, 음... 안녕하세요.",
  str_homestory_chat_25701001 = "안녕.",
  str_homestory_chat_25701002 = "저기... 지금 청소 중이에요. 열심히 하고 있어요,\n절대 게으름 피우거나 하지 않아요...",
  str_homestory_chat_25701003 = "그런 의미에서 인사한 게 아니야...",
  str_homestory_chat_25701004 = "봤으니까 그냥 인사한 거야.",
  str_homestory_chat_25701005 = "으아아아... 그럼... 제가 오해해 버렸네요.\n정말 죄송해요...",
  str_homestory_chat_25701006 = "그렇게 정중할 거 없어. 하던 일 해도 돼.",
  str_homestory_chat_25721001 = "네 일 말인데...",
  str_homestory_chat_25721002 = "앗! 뭔가 부족한 게 있었나요?",
  str_homestory_chat_25721003 = "아니.",
  str_homestory_chat_25721004 = "정말 많이 도와줬어. 정확히 말하자면 과할 정도야.",
  str_homestory_chat_25721005 = "그건... 메이드로서 당연한 일이에요.",
  str_homestory_chat_25721006 = "가끔은 너도 긴장을 좀 풀어줘.",
  str_homestory_chat_25721007 = "조금...",
  str_homestory_chat_25721008 = "으아아앗! 어디가 부족했던 건가요?",
  str_homestory_chat_25721009 = "너무 심하게 부지런한 것 같아.",
  str_homestory_chat_25721010 = "으엣... 「심하게 부지런」하다구요?",
  str_homestory_chat_25721011 = "아침부터 청소를 하면 시끄럽다고 생각하는 사람이 있을지도 몰라.",
  str_homestory_chat_25721012 = "그, 그건 앞으로 조심할게요.",
  str_homestory_chat_25722001 = "요즘 어떻게 지내?",
  str_homestory_chat_25722002 = "으아앗, PlayerName 님...",
  str_homestory_chat_25722003 = "며칠 전에 맛있는 걸 발견했는데요.\n아무래도 이곳의 특산품인 것 같아요!",
  str_homestory_chat_25722004 = "어떤 음식인데?",
  str_homestory_chat_25722005 = "여기 강에는 작은 물고기가 많이 있잖아요.\n좀처럼 낚기 어려운 작은 물고기들 말이에요.",
  str_homestory_chat_25722006 = "맞아. 그런 물고기는 작은 데다가 헤엄치는 것도 빨라서\n확실히 잡기가 힘들어.",
  str_homestory_chat_25722007 = "그래서 제가 그물로 떠서 잡았어요.\n그리고 깨끗이 씻어서...",
  str_homestory_chat_25722008 = "두들긴 다음에 소금을 치고 빵에 끼워 먹으면\n정말 맛있어요!",
  str_homestory_chat_25722009 = "뭐? 나, 날것으로 먹는 거야?",
  str_homestory_chat_25722010 = "다음에 먹을 때는 익히는 게 좋아. 탈이 날지도 몰라...",
  str_homestory_chat_25722011 = "그럴 일은 없을 거예요!\n다음엔 조종사님께도 만들어 드릴게요!",
  str_homestory_chat_25722012 = "고마워... 근데 난 됐어...",
  str_homestory_chat_25723001 = "사나에, 저기...",
  str_homestory_chat_25723002 = "으아아, 제가 또 무슨 사고를 쳤나요?",
  str_homestory_chat_25723003 = "전해들은 얘긴데...",
  str_homestory_chat_25723004 = "며칠 전 문을 닦다가 실수로 문을 팽개쳐 버렸다면서?",
  str_homestory_chat_25723005 = "근처에 있던 츄브가 깜짝 놀랐어.",
  str_homestory_chat_25723006 = "죄, 죄송해요! 힘 조절이 잘 안돼서요...",
  str_homestory_chat_25723007 = "문은 이미 수리해 뒀어요!",
  str_homestory_chat_25723008 = "아니, 사실 네 잘못이 아니야.\n그 문은 애초에 문제가 좀 있었거든.",
  str_homestory_chat_25723009 = "으아아, PlayerName 님!\n앞으로 조심할게요!",
  str_homestory_chat_25723010 = "그런 건 아닌데...",
  str_homestory_chat_25723011 = "아! 혹시 문이 떨어졌던 일 말씀하시려는 건가요?",
  str_homestory_chat_25723012 = "그건 이제 상관없어. 어차피 네가 제대로 수리도 해줬잖아.",
  str_homestory_chat_25723013 = "근데... 네 그 힘 말인데...",
  str_homestory_chat_25723014 = "메이드 일을 하기엔 아까운 게 아닐까?",
