  str_homestory_chat_25723016 = "더 열심히 할게요!\n더 세세한 부분까지 신경써서... 으아아...",
  str_homestory_chat_25723017 = "그런 뜻이 아니라니까...",
  str_homestory_chat_26499999 = "PlayerName, 또 만났네.",
  str_homestory_chat_26401001 = "어서 와.",
  str_homestory_chat_26401002 = "오늘은 무슨 일로 헤븐즈 가든에 온 거야?",
  str_homestory_chat_26401003 = "헤븐즈 가든에 있는 건물들을 답사할 예정이야.",
  str_homestory_chat_26401004 = "그리고 헤븐즈 가든과 백야성의 관계에 대해서도\n좀 생각해 보려고 해.",
  str_homestory_chat_26401005 = "엄청 근엄해 보이네.",
  str_homestory_chat_26401006 = "응? 확실히 이 옷만 입으면 조금 그런 것 같긴 해.",
  str_homestory_chat_26401007 = "계속 심오한 생각들만 하게 되는걸.",
  str_homestory_chat_26401008 = "그럼 여기 왔을 땐 너도 긴장을 좀 풀어주는 게 좋을 것 같아.",
  str_homestory_chat_26402001 = "오늘은 좀 덜 바쁜 것 같네?",
  str_homestory_chat_26402002 = "응. 헤븐즈 가든은 정말 여유로운 곳인 것 같아.",
  str_homestory_chat_26402003 = "가끔은 단련도 좀 하고 싶은데,\n뭔가 좋은 제안이 있을까?",
  str_homestory_chat_26402004 = "전투?",
  str_homestory_chat_26402005 = "좋은 제안이야. 그렇지만 여기 분위기랑은\n좀 안 어울릴 것 같아.",
  str_homestory_chat_26402006 = "헤븐즈 가든에서 무기를 휘두르면\n모두의 기분을 상하게 만들지도 몰라.",
  str_homestory_chat_26402007 = "하긴 그렇네. 그럼 강가에서 산책하는 건 어떨까?",
  str_homestory_chat_26402008 = "운동량은 얼마 안 돼도, 오래 걸으면 단련은 될 거라고 생각해.",
  str_homestory_chat_26402009 = "그렇네. 게다가 경치를 감상하면서\n생각에 잠길 수도 있겠어.",
  str_homestory_chat_26402010 = "체스?",
  str_homestory_chat_26402011 = "체스는 전투를 추상화한 놀이지.\n나쁘지 않은 제안이야.",
  str_homestory_chat_26402012 = "대국적인 시야와 집중력,\n전략을 세울 수 있는 능력을 기를 수 있으니까.",
  str_homestory_chat_26402013 = "밤이 되면 할 사람을 찾아서 몇 판 둬야겠어.",
  str_homestory_chat_26403001 = "지금 무슨 생각해?",
  str_homestory_chat_26403002 = "넌 헤븐즈 가든을 어떻게 생각하는지 묻고 싶어.",
  str_homestory_chat_26403003 = "고향.",
  str_homestory_chat_26403004 = "피난처.",
  str_homestory_chat_26403005 = "별로 차이는 없는 것 같은데,\n아무래도 네 마음속 답은 하나뿐인 것 같네.",
  str_homestory_chat_26403006 = "사실 내 생각도 너랑 거의 비슷해.\n여긴 어쨌든 네 집이잖아.",
  str_homestory_chat_26403007 = "하지만 백야성에 대해선 좀 다르게\n생각할지도 모르겠네.",
  str_homestory_chat_26403008 = "넌 어떻게 생각하는데?",
  str_homestory_chat_26403009 = "헤븐즈 가든은 이 대륙 어디에도\n존재할 리 없는 이상향 같아.",
  str_homestory_chat_26403010 = "어느 정도는 비현실적인 느낌이 든달까...",
  str_homestory_chat_26404001 = "나한테 볼일 있어?",
  str_homestory_chat_26404002 = "PlayerName, 헤븐즈 가든의 건설 문제에 대해\n진지하게 생각해 본 적 있어?",
  str_homestory_chat_26404003 = "아직 없는데...",
  str_homestory_chat_26404004 = "음, 미리미리 계획을 세워 놔야 해.",
