  str_homestory_chat_26404006 = "생각해 둔 게 조금 있는데,\n인력이랑 자본이 부족한 것 같아.",
  str_homestory_chat_26404007 = "예를 들면?",
  str_homestory_chat_26404008 = "우선 방어용 성벽을 하나 세우려면\n일손이 적잖이 필요할 거야.",
