  str_homestory_chat_26405001 = "나한테 뭐 물어볼 거 있어?",
  str_homestory_chat_26405002 = "지금 넌 헤븐즈 가든의 주인이야.\n따지고 보면 너도 어엿한 지도자라 할 수 있어.",
  str_homestory_chat_26405003 = "넌 지도력에 대해 어떻게 생각해?\n지도자에게 가장 중요한 건 뭘까?",
  str_homestory_chat_26405004 = "(친화력)",
  str_homestory_chat_26405005 = "모두가 네 곁에 모이게 만드는 친화력 말이지...",
  str_homestory_chat_26405006 = "그냥 내가 사람 사귀는 걸 좋아하는 것뿐이야.",
  str_homestory_chat_26405007 = "맞는 말이야. 내가 생각지도 못한 부분이었어.",
  str_homestory_chat_26405008 = "(결단력)",
  str_homestory_chat_26405009 = "맞아! 리더는 모든 일을 하나하나 따지기보다는\n결정적인 순간에 결단을 내릴 수 있어야 해.",
  str_homestory_chat_26405010 = "근데 그런 능력은 배운다고 느는 게 아니니까,\n타고난 재능이라고밖에 할 수 없겠지.",
  str_homestory_chat_26599999 = "PlayerName! 여기 있었구나!",
  str_homestory_chat_26501001 = "안녕! 뭐 하고 있어?",
  str_homestory_chat_26501002 = "며칠 전에 본 새 응용 공식에 대해 생각 중이었어.",
  str_homestory_chat_26501003 = "그런 「변환」을 현실에 응용하려면\n어떻게 해야 할까...",
  str_homestory_chat_26501004 = "재료를 만드는 거야? 아니면 구조 강화?",
