  str_homestory_chat_26502006 = "아무래도 내가 광석을 하나하나 조사하고\n토양 분석을 할 수밖에 없겠네...",
  str_homestory_chat_26502007 = "헤븐즈 가든이 얼마나 넓은데, 여길 다 돌아보겠단 말이야?",
