  str_homestory_chat_26503008 = "응. 해먹을 침대로 쓰면 엄청 편하잖아?",
  str_homestory_chat_26503009 = "누워 있으면 구름 위를 떠따니는 것 같고...",
  str_homestory_chat_26503010 = "잠도 잘 와.",
  str_homestory_chat_26503011 = "그런데 그거랑 아까 말한 각도, 방향 이런 거랑 무슨 관계가 있어?",
  str_homestory_chat_26503012 = "수면 환경이랑 상관이 있거든.\n날씨가 좋을 땐 편안한 환경에서\n낮잠을 푹 자고 싶어져.",
