  str_homestory_chat_26504001 = "나 찾았어?",
  str_homestory_chat_26504002 = "숙소를 좀 개조하고 싶은데, 해도 돼?",
  str_homestory_chat_26504003 = "그건 좀 곤란해.",
  str_homestory_chat_26504004 = "공사 때문에 그러는 거라면 걱정 안 해도 돼!",
  str_homestory_chat_26504005 = "다른 사람들이 불편해할 것 같아서 그래.\n공사가 시작되면 얼마 동안은 숙소에서 지낼 수 없게 되잖아.",
  str_homestory_chat_26504006 = "그렇구나. 그 문제는 생각 못 했어...",
  str_homestory_chat_26504007 = "그럼 사람들한테 잠깐만 헤븐즈 가든에\n오지 말라고 해 줄 순 없을까?",
  str_homestory_chat_26504008 = "그건 힘들 것 같은데...",
  str_homestory_chat_26504009 = "어떻게 개조할 생각인데?",
  str_homestory_chat_26504010 = "좌우 양쪽에 내력벽이랑 구조벽을 추가하고,\n방을 2개 더 만든 다음에,\n중간에 있는 방을 휴게실로 바꿀 거야.",
  str_homestory_chat_26504011 = "이러면 모두가 쉴 공간도 생기고, 머물 곳도 생겨.\n채광에도 문제가 없도록 다 생각해 뒀어.",
  str_homestory_chat_26504012 = "근데 그렇게 개조하려면 시간이 너무 많이 필요할 것 같아.\n게다가 일손도 부족할 거야...",
  str_homestory_chat_26504013 = "힘쓰는 일이라면 전부 나한테 맡겨!",
  str_homestory_chat_26504014 = "내 강화복은 기초공사부터 시작해서\n뼈대 건설이랑 담쌓기는 물론...",
  str_homestory_chat_26504015 = "대형 유적 발굴이랑 터널 굴착까지\n다 할 수 있으니까!",
  str_homestory_chat_26504016 = "진짜 대단하네!",
  str_homestory_chat_26504017 = "그래도 그 능력들은 일루미나 지하철 공사라든지...\n더 다양한 곳에 사용하는 편이 더 좋지 않을까?",
  str_homestory_chat_26504018 = "그게 네 본업이기도 하니까, 넌 헤븐즈 가든에선 푹 쉬면 돼.",
