  str_homestory_chat_26603002 = "혹시 반짝거리는 거 없어? 예를 들면...",
  str_homestory_chat_26603003 = "광석?",
  str_homestory_chat_26603004 = "물고기?",
  str_homestory_chat_26603005 = "둘 다 아니거든! 흥!",
