  str_homestory_chat_26702007 = "적어도 이곳에서의 일은 그렇습니다.\n끝없이 노력만 한다면 수확이 있을 겁니다.",
  str_homestory_chat_26702008 = "그거 고맙네.",
  str_homestory_chat_26702009 = "음, 그건 아마 이곳이 무척 평화롭기 때문일 겁니다.",
  str_homestory_chat_26702010 = "재물.",
  str_homestory_chat_26702011 = "미래의 당신은 계속 빈털터리일 겁니다.\n하지만 그건 다 앞으로의 행복을 위해서지요.",
  str_homestory_chat_26702012 = "행복?",
  str_homestory_chat_26702013 = "아마 이곳의 건설 자금이 아닐까 싶습니다.",
