  str_homestory_chat_26703005 = "루미나틱스 같아.",
  str_homestory_chat_26703006 = "둘 다 맞기도, 틀리기도 합니다.",
  str_homestory_chat_26703007 = "이해가 잘 안돼.",
  str_homestory_chat_26703008 = "어떤 관점에서 생각하느냐에 따라\n달라진다는 것이지요.",
