  str_homestory_chat_26703011 = "그러니까 더 모르겠어...",
  str_homestory_chat_26704001 = "무슨 생각 하고 있었어?",
  str_homestory_chat_26704002 = "마술의 원리를 생각하고 있었습니다.\n가끔은 반대여야 할 것 같아서요.",
  str_homestory_chat_26704003 = "반대라니?",
  str_homestory_chat_26704004 = "예를 들면 가끔 카드 마술을 선보일 때\n관객을 무대 위로 모셔야 할 때가 있습니다.",
  str_homestory_chat_26704005 = "많은 사람들은 그 관객이 그렇게 가까이에서\n보고도 왜 트릭을 알아채지 못할까 궁금해하지요.",
  str_homestory_chat_26704006 = "그렇지.",
  str_homestory_chat_26704007 = "하지만 만약 그 관객이 처음부터 마술사와\n말을 맞춰 둔 상태라면 어떨까요?",
  str_homestory_chat_26704008 = "그렇구나! 발상의 전환이었어!",
  str_homestory_chat_26705001 = "어떤 음료를 좋아해?",
  str_homestory_chat_26705002 = "당연히 블랙커피입니다.\n설탕과 우유는 넣지 않습니다.",
  str_homestory_chat_26705003 = "그러면 너무 쓸 텐데.",
  str_homestory_chat_26705004 = "쓴맛이 다하면 달콤함이 찾아오는 법이지요.",
  str_homestory_chat_26705005 = "게다가 가장 중요한 건,\n블랙커피는 마셔도 살이 찌지 않습니다.",
  str_homestory_chat_26705006 = "그래서 마시는 거였구나.",
  str_homestory_chat_26705007 = "마술사로서 언제나 맑은 정신을\n유지해야 하기 때문입니다.",
