  str_homestory_chat_26801001 = "뭐 하고 있어?",
  str_homestory_chat_26801002 = "물총을 테스트해 보고 있었어.\n모두를 시원하게 해 주려구!",
  str_homestory_chat_26801003 = "시원하게 해 준다고?",
  str_homestory_chat_26801004 = "물을 뿌려 주는 거야. 이슬비를 내리게 하는 거지!\n겸사겸사 식물들한테도 물을 줄 수 있어!",
  str_homestory_chat_26801005 = "물을 주는 건 좋은데, 비를 내리게 하는 건 그만두자. 우산을 써야 하니까 귀찮잖아.",
  str_homestory_chat_26802001 = "혹시 수영하고 싶어?",
  str_homestory_chat_26802002 = "응. 마침 이 근처에 강도 하나 있던데?",
  str_homestory_chat_26802003 = "물살도 빠르지 않고 깊이도 적당한 것 같았어!",
  str_homestory_chat_26802004 = "넌 수영을 정말 좋아하는구나.",
  str_homestory_chat_26802005 = "왜냐면 난 바닷가, 아니, 바다 위에서 자랐는걸.",
  str_homestory_chat_26802006 = "나한테 바다는 가족 같은 존재야.",
  str_homestory_chat_26802007 = "근데 레인보우, 그 강에 흐르는 건 바닷물이 아닌데 괜찮겠어?",
  str_homestory_chat_26802008 = "에이, 무슨 소리를 하는 거야. 난 바닷물고기가 아니라구.",
  str_homestory_chat_26802009 = "아... 내가 너무 오버했나 봐. 미안해.",
  str_homestory_chat_26802010 = "헤헤, 괜찮아.\n그럼 나중에 시간 날 때 같이 수영하러 가자!",
  str_homestory_chat_26803001 = "뭐 하려는 거야?",
  str_homestory_chat_26803002 = "동체시력이랑 손이 빨라지도록\n연습을 하려던 참이었어.",
  str_homestory_chat_26803003 = "왜?",
  str_homestory_chat_26803004 = "강에 있는 물고기가 잘 안 잡혀서 그러지.",
  str_homestory_chat_26803005 = "물고기가 빠르고, 물속이 좀 복잡한 탓도 있지만,\n제일 중요한 건...",
  str_homestory_chat_26803006 = "물 밖에서 보이는 물고기의 위치가\n실제 위치보다 조금 쏠려 있더라구!",
  str_homestory_chat_26803007 = "빛이 물속을 지나면서... 굴절이 일어나서 그런 거겠지?",
  str_homestory_chat_26803008 = "잠깐만! 레인보우, 너 바다 위에서 자랐다고 하지 않았어?\n그럼 물고기를 많이 잡아 봤을 거 아냐?",
  str_homestory_chat_26803009 = "맞아. 근데 그때는 잠수해서 잡았으니까\n빛의 굴절 때문에 영향을 받진 않았어.",
  str_homestory_chat_26803010 = "게다가 바닷속에는 물고기가 아주 많은 데다가,\n무리를 지어 몰려 다니니까 잡기 엄청 쉽거든.",
  str_homestory_chat_26803011 = "그랬구나. 그럼 계속 연습하는 수밖에 없겠네.",
  str_homestory_chat_26804001 = "나 찾았어?",
  str_homestory_chat_26804002 = "응, 목재 좀 찾아 줄 수 있을까?",
  str_homestory_chat_26804003 = "뭐에다 쓸 건데?",
  str_homestory_chat_26804004 = "수상함대를 만들 거야!",
  str_homestory_chat_26804005 = "수, 수상함대? 어디에?",
  str_homestory_chat_26804006 = "저 강에다 만들 거야.\n그럼 헤븐즈 가든을 지키기에도 좋잖아?",
  str_homestory_chat_26804007 = "그럼 강이 가득 차 버릴 거야. 강폭이 그렇게 넓지도 않으니까.",
  str_homestory_chat_26804008 = "소형, 아니지, 초소형 함대를 만들면 되지!",
  str_homestory_chat_26804009 = "작은 배를 몇 척 찾아서\n순찰용 함대를 만드는 거야~",
  str_homestory_chat_26804010 = "그럼 조종은 누가 해?",
  str_homestory_chat_26804011 = "좋은 질문이야! 아마... 츄브?",
  str_homestory_chat_26804012 = "츄브들은 땅딸막하니까,\n선실은 좀 작게 만들어야겠네.",
  str_homestory_chat_26804013 = "혹시 적이라도 마주치면? 어떻게 방어할 생각이야?",
  str_homestory_chat_26804014 = "그것도 그렇네... 화력이 문제였네.\n뭐하면... 새총을 쏠까? 돌을 던지는 게 나으려나?",
  str_homestory_chat_26804015 = "난 그냥 여기가 앞으로도 쭉 안전했으면 좋겠어.",
  str_homestory_chat_27099999 = "PlayerName, 요즘 컨디션은 어떠니?",
  str_homestory_chat_27001001 = "나쁘지 않아요. 폴룩스 씨는요?",
  str_homestory_chat_27001002 = "솔직히 말하자면 조금 실망스러워.",
  str_homestory_chat_27001003 = "실망이요?",
  str_homestory_chat_27001004 = "여긴 비가 너무 안 와! 오더라도 너무 적게 내려!",
  str_homestory_chat_27001005 = "폴룩스 씨는 비를 좋아했던 거군요...",
  str_homestory_chat_27021001 = "절 찾았다면서요?",
  str_homestory_chat_27021002 = "맞아! 난 아주 큰 어린이 놀이공원을 만들고 싶어.",
  str_homestory_chat_27021003 = "미끄럼틀, 회전목마, 그리고 시소 같은 걸 둬서,\n아이들이 하루 종일 놀아도 질리지 않게 할 거야.",
  str_homestory_chat_27021004 = "왜 갑자기 그런 생각을 하는데요?",
  str_homestory_chat_27021005 = "방금 말한 그런 것들은 아이들만이 아니라,\n좋아하는 어른도 많아.",
  str_homestory_chat_27021006 = "특히 이곳 동료 중에는 아직 동심을 간직하고\n있는 사람이 많잖아.",
  str_homestory_chat_27021007 = "그러고 보니까... 확실히 일리가 있네요. 생각해 볼게요.",
  str_homestory_chat_27022001 = "물어볼 게 있다면서요?",
  str_homestory_chat_27022002 = "여기 총을 잘 아는 정비사는 없을까?",
  str_homestory_chat_27022003 = "없어요.",
  str_homestory_chat_27022004 = "있어요.",
  str_homestory_chat_27022005 = "근데 좀 찾아봐야 돼요.",
  str_homestory_chat_27022006 = "혹시 폴룩스 씨 총이 망가진 건가요?",
  str_homestory_chat_27022007 = "교정이 필요해. 총도 사람처럼 가끔 병에 걸리거든.",
  str_homestory_chat_27022008 = "그럴 땐 정비사가 필요해.\n총한테는 그 사람들이 의사인 거야.",
  str_homestory_chat_27022009 = "근데 왜 움브라톤에서 안 찾는 거죠?",
  str_homestory_chat_27022010 = "멀잖아. 게다가 헤븐즈 가든에 상주하는 정비사가\n있는 것도 나쁘지 않고 말이야.",
  str_homestory_chat_27022011 = "네 동료 중에도 그런 도움이 필요한 사람이 많잖아.\n한 명 정도 초대해 보는 게 어때?",
  str_homestory_chat_27022012 = "내가 소개해 줄 수도 있어. 가격도 적당해.",
  str_homestory_chat_27022013 = "왜 이야기가 그런 쪽으로 새는 거죠...",
  str_homestory_chat_27023001 = "뭘 보고 있어요?",
  str_homestory_chat_27023002 = "헤븐즈 가든은 모든 게 멋져.\n다만 조금 외진 곳에 있어서 그렇지.",
  str_homestory_chat_27023003 = "움브라톤의 유행을 알고 싶어도 따라잡을 수 없어.",
  str_homestory_chat_27023004 = "너 요즘 움브라톤에는 갔었니?\n최신 스타일 같은 거 못 봤어?",
  str_homestory_chat_27023005 = "갔어요.",
  str_homestory_chat_27023006 = "어머, 그럼 요즘 어떤 스타일이 유행이니? 코디는?",
  str_homestory_chat_27023007 = "저, 전 그런 건 잘 신경 안 써서요...",
  str_homestory_chat_27023008 = "안 갔어요.",
  str_homestory_chat_27023009 = "휴, 너한테 기대한 내가 바보네.",
  str_homestory_chat_27023010 = "차라리 돈을 좀 더 벌고 츄브랑 이야기해서\n옷 가게를 하나 차려 보는 건 어때?",
  str_homestory_chat_27023011 = "아니면 쿠리어들한테 패션 잡지라도\n좀 받아서 보거나...",
  str_homestory_chat_27024001 = "뭐 하고 있었어요?",
  str_homestory_chat_27024002 = "아무것도 안 했어.\n이렇게 느긋하게 지내는 것도 꽤 오랜만인 것 같아.",
  str_homestory_chat_27024003 = "여긴 정말 평화롭네. 가끔은 무서울 정도야.",
  str_homestory_chat_27024004 = "왜요?",
  str_homestory_chat_27024005 = "평화는 위협을 잊게 만들거든.\n때로는 단련도 필요해.",
  str_homestory_chat_27024006 = "여긴 안전하니까 하루 종일 신경을 곤두세우는 건 좋지 않아요.",
  str_homestory_chat_27024007 = "음... 그래.",
  str_homestory_chat_27024008 = "무서워할 거 없어요.",
  str_homestory_chat_27024009 = "평화는 좋은 거 아닌가요? 매일 싸움만 할 순 없잖아요.",
  str_homestory_chat_27024010 = "평화 속에서도 위험을 항상 대비해야 해...",
  str_homestory_chat_27199999 = "무슨 일 있어?",
  str_homestory_chat_27101001 = "특별히 용건이 있는 건 아니야.",
  str_homestory_chat_27101002 = "그래, 그럼 안녕.",
  str_homestory_chat_27101003 = "아... 저기, 카스타.",
  str_homestory_chat_27101004 = "왜?",
  str_homestory_chat_27101005 = "아무것도 아니야. 그냥 이렇게 대화를 끝내는 건 좀 아닌 것 같아서...",
  str_homestory_chat_27101006 = "우리 대화 중인 거야?",
  str_homestory_chat_27101007 = "그것도 그렇네. 그럼 다음에 시간 날 때 얘기하자.",
  str_homestory_chat_27121001 = "요즘 무슨 계획 있어?",
  str_homestory_chat_27121002 = "높은 곳을 찾고 싶어. 키가 큰 나무라든지 말이야.\n여기 그런 거 있어?",
  str_homestory_chat_27121003 = "있어.",
  str_homestory_chat_27121004 = "헤븐즈 가든의 숙소라든지...",
  str_homestory_chat_27121005 = "그거 가지곤 안 돼. 별로 안 높잖아.\n그래, 바람의 탑 정도면 좋겠네.",
  str_homestory_chat_27121006 = "아마 없을걸.",
  str_homestory_chat_27121007 = "진짜? 그럴 리가 없잖아.\n저 바람의 탑 정도면 괜찮아 보이는데.",
  str_homestory_chat_27121008 = "츄브들이 동의할지는 모르겠는데...",
  str_homestory_chat_27121009 = "거기서 뭘 할 건데?",
  str_homestory_chat_27121010 = "높은 곳을 망루로 개조하는 거야.\n적을 저격할 수도 있게.",
  str_homestory_chat_27121011 = "그건 가장 기본적인 방어 체계야.",
  str_homestory_chat_27121012 = "그런 건... 여긴 필요 없을 것 같아.",
  str_homestory_chat_27122001 = "커피를 좋아한다면서?",
  str_homestory_chat_27122002 = "맞아, 특히 설탕도 우유도 안 넣는\n블랙커피를 좋아해. 넌?",
  str_homestory_chat_27122003 = "나도 좋아해.",
  str_homestory_chat_27122004 = "역시 너도 그 맛에 매료된 거구나.",
  str_homestory_chat_27122005 = "특히 블랙커피를 마시면 생각이 많아지거든...",
  str_homestory_chat_27122006 = "나...난 그냥 단순히 커피가 좋을 뿐이야.",
  str_homestory_chat_27122007 = "아쉽네. 하지만 너도 앞으로 서서히\n그 맛을 알게 될 거야.",
  str_homestory_chat_27122008 = "난 별로.",
  str_homestory_chat_27122009 = "아무것도 안 넣으면 너무 쓰잖아.\n그래서 난 최소한 뭐라도 좀 넣어서 맛을 맞추는 편이야.",
  str_homestory_chat_27122010 = "그게 대부분 사람들의 취향이긴 하지.\n그런 점에서 난 무리에서 벗어난 사람이야.",
  str_homestory_chat_27122011 = "그렇지 않아. 맛의 취향은 사람마다 다르잖아.",
  str_homestory_chat_27123001 = "무슨 고민 있어?",
  str_homestory_chat_27123002 = "누가 그러더라고. 내 사고방식이 너무 곧아서\n다른 사람의 기분을 상하게 한대. 정말 그래?",
  str_homestory_chat_27123003 = "그렇지 않아.",
  str_homestory_chat_27123004 = "음... 그럼 다행이고.",
  str_homestory_chat_27123005 = "살짝 그런가...",
  str_homestory_chat_27123006 = "근데 난 상관없다고 생각해.",
  str_homestory_chat_27123007 = "왜냐하면 그게 네 성격이고 네가 카스타인 이유잖아.",
  str_homestory_chat_27123008 = "그러니까 지금 스타일을 유지하면 될 것 같아.",
  str_homestory_chat_23099999 = "오늘은 법을 어기는 일이 있었나?",
  str_homestory_chat_23001001 = "음...",
  str_homestory_chat_23001002 = "아무래도 있었던 모양이군.\n그럼 지금 바로 개정하도록 하지.",
  str_homestory_chat_23001003 = "우선 심판관은 당연히 나다.\n그리고 법정 질서 유지를 맡는 호위병은...",
  str_homestory_chat_23001004 = "잠깐만, 전 그런 일이 있다고 한 적 없는데요...\n그냥 어떻게 대답할까 망설이고 있었을 뿐이라구요.",
  str_homestory_chat_23001005 = "휴, 그렇군. 너무 지루하잖아.",
  str_homestory_chat_23021001 = "요즘 뭐 하고 지내요?",
  str_homestory_chat_23021002 = "아, 마침 그대와 논의할 일이 있다.\n츄브를 몇 마리 빌려줄 수 있겠나?",
  str_homestory_chat_23021003 = "뭘 하려는 건데요?",
  str_homestory_chat_23021004 = "츄브의 직육면체 구조를 봐라.\n참으로 훌륭한 재료다.",
  str_homestory_chat_23021005 = "츄브한테 뭔가 할 생각인 것처럼 들리는데... 츄브를 해치면 안 돼요.",
  str_homestory_chat_23021006 = "안 되는 것이냐?\n츄브로 조각상을 만들 생각이었다만...",
  str_homestory_chat_23021007 = "그렇다면 이곳에서 움직이는 다양한 조각상들을\n감상할 수 있을 텐데 말이야.",
  str_homestory_chat_23021008 = "한 번 더 당부하는데, 츄브를 해치지 마세요!",
  str_homestory_chat_23021009 = "화난 거냐? 뭐, 알았다.",
  str_homestory_chat_23022001 = "제 도움이 필요한가요?",
  str_homestory_chat_23022002 = "그렇다, 조만간 움브라톤에 갈 일이 있나?\n가서 잡지를 좀 사다 줬으면 좋겠군.",
  str_homestory_chat_23022003 = "그럴 시간은 없어요.",
  str_homestory_chat_23022004 = "여기서 무척 바쁜 것이냐?\n매일 빈둥대는 것처럼 보인다만...",
  str_homestory_chat_23022005 = "사람 돕는다 생각하고 놀러 갔다 오도록 해라.",
  str_homestory_chat_23022006 = "여기서도 할 일이 많고, 움브라톤까지도 멀다고요.",
  str_homestory_chat_23022007 = "뭐, 됐다. 게으른 녀석...",
  str_homestory_chat_23022008 = "어떤 잡지요?",
  str_homestory_chat_23022009 = "표지가 아름답고, 내용도 흥미롭고,\n인쇄도 정교한 잡지다.",
  str_homestory_chat_23022010 = "왠지 재미있을 것 같네요.",
  str_homestory_chat_23022011 = "그렇지? 그대라면 알 수 있을 것이다, 후후후.",
  str_homestory_chat_23022012 = "《조소 예술 대백과》 맞죠? 저도 본 적 있어요.",
  str_homestory_chat_23022013 = "뭐?! 그건! 휴...",
  str_homestory_chat_23023001 = "뭘 찾고 있죠?",
  str_homestory_chat_23023002 = "종이를 사고 싶다만.\n대량의 종이와 잉크가 필요하다...",
  str_homestory_chat_23023003 = "어디 쓸 건데요? 책이라도 쓰는 건가요?",
  str_homestory_chat_23023004 = "그렇다, 재판관으로서 난 이곳에 법이 없다는\n사실에 항상 마음 아파하고 있다.",
  str_homestory_chat_23023005 = "여긴 딱히 법 같은 건 필요 없다고 생각하는데요...",
  str_homestory_chat_23023006 = "구두 약속은 언제나 서면 기록보다 못한 법이다!",
  str_homestory_chat_23023007 = "사실은 그저 재판관 씨한테만 좋은 법을 만들 생각일 뿐이잖아요.",
  str_homestory_chat_23023008 = "그, 그럴 리가!\n이 몸이 제정하는 법은 모두 공정하다!",
  str_homestory_chat_23023009 = "예를 들면, 백야성 심판관의 명령은 반드시\n따라야 한다...라거나...",
  str_homestory_chat_23023010 = "그것부터 벌써 이상하잖아요!",
  str_homestory_chat_27299999 = "PlayerName, 뭐 찍을 만한 거 있어?",
  str_homestory_chat_27221001 = "없지.",
  str_homestory_chat_27221002 = "정말 항상 촬영만 생각하는구나...",
  str_homestory_chat_27221003 = "이곳의 풍경이 너무 예뻐서 그래.\n하지만 좋은 시나리오가 떠오르지는 않네.",
  str_homestory_chat_27221004 = "으으, 너무 괴로워. 극본까지 짜야 한다니...",
  str_homestory_chat_27221005 = "정말 뭐 재미있는 거 없어? 예를 들면...\n「헤븐즈 가든의 9대 불가사의」 같은 거?",
  str_homestory_chat_27221006 = "정말 없어...",
  str_homestory_chat_27222001 = "뭐 살 거야?",
  str_homestory_chat_27222002 = "스탠드 있어? 바퀴가 달려 있어서\n이동할 수 있는 거면 더 좋고!",
  str_homestory_chat_27222003 = "그걸로 뭐 하게?",
  str_homestory_chat_27222004 = "촬영해야지.\n항상 세로로한테 기계를 들게 하는 것도 안 좋으니까.\n세로로가 힘들 거야.",
  str_homestory_chat_27222005 = "그렇다고 전문 카메라맨을 고용할 만큼\n예산이 풍족한 것도 아니고...",
  str_homestory_chat_27222006 = "그랬구나. 근데 그런 건 움브라톤에나 있지 않을까?",
  str_homestory_chat_27222007 = "하지만 그쪽은 너무 비싸.",
  str_homestory_chat_27223001 = "한가한 모양이네?",
  str_homestory_chat_27223002 = "맞아. 딱히 재미있는 이야기도 없거든.\n넌 뭐 좋아하는 거 있어?",
  str_homestory_chat_27223003 = "없어.",
  str_homestory_chat_27223004 = "있긴 있지...",
  str_homestory_chat_27223005 = "가끔은 바이스 쪽에서 보내준 책을 읽곤 해.",
  str_homestory_chat_27223006 = "휴, 너한테서는 딱히 발견할만한 게\n없을 것 같네.",
  str_homestory_chat_27223007 = "단편 스토리를 추천해달라고 말할\n생각이었는데... 무서운 걸로 말이지...",
  str_homestory_chat_27223008 = "넌 그런 이야기를 좋아하는 것 같네. 안 무서워?",
  str_homestory_chat_27223009 = "흥! 가난한 생활보다 무서운 건 없어!",
  str_homestory_chat_27223010 = "게다가 만약에 이런 이야기로 영화를 찍으면\n내가 여주인공이 될 수 있을지도 모르잖아?",
  str_homestory_chat_27223011 = "진정한 대스타가 되는 거지... 후후...",
  str_homestory_chat_27223012 = "크흠, 난 먼저 갈게.",
  str_homestory_chat_27224001 = "팬?",
  str_homestory_chat_27224002 = "너도 이제 조금 유명해졌잖아. 팬 없어?",
  str_homestory_chat_27224003 = "있을걸.",
  str_homestory_chat_27224004 = "오! 누구?",
  str_homestory_chat_27224005 = "사실... 나도 잘 몰라.",
  str_homestory_chat_27224006 = "없어.",
  str_homestory_chat_27224007 = "아깝네.",
  str_homestory_chat_27224008 = "뭐... 팬이 있든 없든 계속 열심히 노력하라고!",
  str_homestory_chat_27224009 = "그거야 당연하지.",
  str_homestory_chat_27224010 = "그러니까 가끔은 나 자신을 응원해주기도 해야겠지?",
  str_homestory_chat_27224011 = "맞아. 근데 왜 갑자기... 무슨 일 있어?",
  str_homestory_chat_27224012 = "그냥... 가끔 좀 힘들어서.",
  str_homestory_chat_27225001 = "뭐 살 거야?",
  str_homestory_chat_27225002 = "생선 먹고 싶어...",
  str_homestory_chat_27225003 = "강에 많잖아?\n세로로한테 몇 마리 잡아 오라고 하자.",
  str_homestory_chat_27225004 = "하지만 내가 먹고 싶은 건 민물고기가\n아니라 해산물이야...",
  str_homestory_chat_27225005 = "특히 굴국이랑 해산물 리소토...",
  str_homestory_chat_27225006 = "민물고기로도 충분히 만들 수 있을 것 같은데.",
  str_homestory_chat_27225007 = "전! 혀! 달! 라!",
  str_homestory_chat_27225008 = "해산물만의 독특한 맛이 있다고.\n딱 먹으면 바다의 기운을 가득 느낄 수 있어.",
  str_homestory_chat_27225009 = "뭐든 할 수 있고, 모든 걸 정복해서 꿈을 이룰 수\n있을 것만 같은 기분이 든다니까.",
  str_homestory_chat_27225010 = "그 설명... 밥에 대한 거 맞지...?",
  str_homestory_chat_27399999 = "존경하는 PlayerName 님.\n이 미노스는 언제든 당신을 위해 일할 것입니다.",
  str_homestory_chat_27301001 = "안녕, 미노스.",
  str_homestory_chat_27301002 = "항상 깍듯하네. 헤븐즈 가든에서는 좀 더 풀어져도 된다니까.",
  str_homestory_chat_27301003 = "안 됩니다. 집사는 언제든 주인님을 위해\n일할 준비를 하고 있어야 하죠.",
  str_homestory_chat_27301004 = "주인님이 곁에 없더라도?",
  str_homestory_chat_27301005 = "그렇다고 해도 주인님이 오실 것을\n대비해서 준비해둬야 합니다.",
  str_homestory_chat_27321001 = "네 무기...",
  str_homestory_chat_27321002 = "마침 찾아가려던 참이었습니다.\n헤븐즈 가든에 무기를 수리할 수 있는\n인재가 있습니까?",
  str_homestory_chat_27321003 = "있어.",
  str_homestory_chat_27321004 = "어느 츄브죠?",
  str_homestory_chat_27321005 = "크흠... 걔들은 아니야.\n다른 동료가 수리할 수 있을 거야.",
  str_homestory_chat_27321006 = "아니.",
  str_homestory_chat_27321007 = "아, 정말 유감이군요.",
  str_homestory_chat_27321008 = "총이 망가진 거야?",
  str_homestory_chat_27321009 = "아닙니다. 집사라면 언제든 무기가 잘\n작동하도록 관리해둬야 하죠.\n이것 또한 마땅히 해야 할 일입니다.",
  str_homestory_chat_27321010 = "주인님에게 언제 위험이 닥칠지 모르니까요.",
  str_homestory_chat_27321011 = "정말 책임감이 넘치네...",
  str_homestory_chat_27322001 = "무슨 일로 날 찾은 거야?",
  str_homestory_chat_27322002 = "존경하는 PlayerName 님.\n정확한 시간을 알려주셨으면 합니다.",
  str_homestory_chat_27322003 = "시계가... 고장 난 거야?",
  str_homestory_chat_27322004 = "아무리 정밀한 도구라 해도 착오가\n생길 때가 있는 법이죠. 오늘 아침에...",
  str_homestory_chat_27322005 = "평소보다 조금 느리게 가는 것 같은\n느낌을 받았습니다.",
  str_homestory_chat_27322006 = "그런 것도 알아?",
  str_homestory_chat_27322007 = "집사라면 필요한 감각입니다.\n언제든 시간을 신경 써야 하니까요.",
  str_homestory_chat_27322008 = "아니면 주인님의 일정에 문제가 생길 테니까요.\n심지어 주인님의 계획을 망쳐버릴지도 모르죠.",
  str_homestory_chat_27322009 = "저기... 나... 네 주인님을 부러워해도 될까?",
  str_homestory_chat_27322010 = "미노스 같은 조력자가 있다면 얼마나 좋을까...",
  str_homestory_chat_27323001 = "뭔가 생각하는 중인 것 같네.",
  str_homestory_chat_27323002 = "그렇습니다. 집사는 주인님을 어떻게 대해야\n한다고 생각하십니까?",
  str_homestory_chat_27323003 = "복종해야지.",
  str_homestory_chat_27323004 = "완전한 복종 말입니까...",
  str_homestory_chat_27323005 = "외람되지만 전 동의하지 않습니다.",
  str_homestory_chat_27323006 = "보좌해야지.",
  str_homestory_chat_27323007 = "그 말이 맞습니다!",
  str_homestory_chat_27323008 = "집사면 오직 복종만을 해서는 안 됩니다.\n오히려 주인님이 자기 잘못을 깨달을 수\n있도록 옆에서 알려드려야 하죠.",
  str_homestory_chat_27323009 = "그렇기에 집사와 주인님은 인격적으로 평등합니다.",
  str_homestory_chat_27323010 = "확실히 그래야겠네.",
  str_homestory_chat_27324001 = "여기가 어떤 것 같아?",
  str_homestory_chat_27324002 = "정말 아름다운 곳입니다.\n매우 거대하지만 깨끗하죠.",
  str_homestory_chat_27324003 = "츄브들이 이곳을 깨끗하게 청소하나 보군요.",
  str_homestory_chat_27324004 = "아니야. 모두가 열심히 노력한 결과야.",
  str_homestory_chat_27324005 = "존경하는 PlayerName님,\n역시 정말 겸손하시군요.",
  str_homestory_chat_27324006 = "굳이 말하자면 이곳은 감탄스러울 정도로\n살기 좋은 곳입니다.",
  str_homestory_chat_27324007 = "환경, 기후, 일조량까지도 매우 훌륭하죠.",
  str_homestory_chat_27324008 = "가장 중요한 건 해충이 매우 적다는 것입니다.\n덕분에 부담이 훨씬 줄었군요.",
  str_homestory_chat_27324009 = "이곳이 마음에 들면 됐어.",
  str_homestory_chat_26999999 = "666, 또 멋대로 돌아다니고 있구나.",
