  str_homestory_chat_26901002 = "안녕안녕안녕, 너도 멋대로 돌아다니고 있네.",
  str_homestory_chat_26901003 = "왜 나 따라 해?",
  str_homestory_chat_26901004 = "너만 보면 나도 모르게 이렇게 말하게 되거든.",
  str_homestory_chat_26901005 = "666, 아무래도 너도 반해버린 모양이네~",
  str_homestory_chat_26921001 = "뭐 보고 있어?",
  str_homestory_chat_26921002 = "《연간 의적 도감 에디션》이야.\n움브라톤에서 막 나온 거지.",
  str_homestory_chat_26921003 = "마침 헤븐즈 가든에 와서 세 번 정도\n다시 읽고 싶었거든.",
  str_homestory_chat_26921004 = "세 번을 다시 읽는다고?",
  str_homestory_chat_26921005 = "백 번을 봐도 안 질려!",
  str_homestory_chat_26921006 = "지금 네 상태를 보니...\n벌써 삼백 번은 읽은 것 같은데?",
  str_homestory_chat_26921007 = "아니야. 666번 읽었어.",
  str_homestory_chat_26921008 = "으악!",
  str_homestory_chat_26922001 = "너 지금 웃는 거야?",
  str_homestory_chat_26922002 = "즐거운 일이 떠올랐거든.\n네가 헤븐즈 가든에 있을 때처럼 말이지.",
  str_homestory_chat_26922003 = "즐거운 일?",
  str_homestory_chat_26922004 = "의적을 떠올리기만 하면 웃음이 나와.",
  str_homestory_chat_26922005 = "특히 의적이 악당의 음모를 박살 낼 때!",
  str_homestory_chat_26922006 = "헤븐즈 가든?",
  str_homestory_chat_26922007 = "그래. 널 오랫동안 관찰했는데,\n헤븐즈 가든에 있을 때면 항상 웃고 있더라고.",
  str_homestory_chat_26922008 = "자기도 모르게 말이야.",
  str_homestory_chat_26922009 = "그래서... 왜 웃고 있는 거야?",
  str_homestory_chat_26922010 = "왜냐하면 의적이 웃고 악당이 울고 있으니까!",
  str_homestory_chat_26922011 = "이 부분만 떠올리면 몇 마디 하지 않을\n수가 없다니까.",
  str_homestory_chat_26922012 = "의적 의적, 악당의 천적\n마주치면 무릎 꿇고 빌어.",
  str_homestory_chat_26922013 = "헤이! 시끌벅적하네!",
  str_homestory_chat_26923001 = "야구 좋아해?",
  str_homestory_chat_26923002 = "막 좋아하는 건 아니야. 그건 왜?",
  str_homestory_chat_26923003 = "항상 야구 모자를 쓰고 야구 배트를 들고 다니길래.",
  str_homestory_chat_26923004 = "그냥 이 차림을 좋아할 뿐이야.\n생동감이 넘치지 않아?",
  str_homestory_chat_26923005 = "생동감?",
  str_homestory_chat_26923006 = "역동적이고 리듬감 있는 느낌 말이야...",
  str_homestory_chat_26923007 = "나는~ 야구를~ 못하지만~\n나는~ 힙합을~ 잘하지~",
  str_homestory_chat_26923008 = "666, 야구 배트, 666, 휘두르지.",
  str_homestory_chat_26923009 = "주 용도는 무기였구나.",
  str_homestory_chat_26923010 = "666, 야구 모자, 666, 스피릿이 넘치지.",
  str_homestory_chat_26923011 = "알겠어. 그러니까 제대로 좀 얘기해 줄래...",
  str_homestory_chat_27599999 = "하암~ 조종사는 오늘도 빈둥거리고 있네요.",
  str_homestory_chat_27521001 = "또 만났네.",
  str_homestory_chat_27521002 = "방금 하품한 거지? 피곤해?",
  str_homestory_chat_27521003 = "아니요, 악셀리아는 자주 이렇습니다.",
  str_homestory_chat_27521004 = "하긴, 별로 피곤해 보이진 않네...",
  str_homestory_chat_27521005 = "다들 악셀리아에게 그렇게 말합니다.",
  str_homestory_chat_27521006 = "그게 바로 악셀리아의 개성인 거지.",
  str_homestory_chat_27522001 = "넌 항상 그 옷을 입고 다녀?",
  str_homestory_chat_27522002 = "네, PlayerName 눈에는 뭐가 이상한가요?",
  str_homestory_chat_27522003 = "크기가 좀 안 맞는 거 같아서.",
  str_homestory_chat_27522004 = "너무 딱 맞는 옷을 입으면 불편하기도 하지만,\n숨을 쉬기 힘들어질 때도 있어요.",
  str_homestory_chat_27522005 = "전에 몇 번 입어 보려고 해 봤는데,\n도저히 참을 수가 없었습니다.",
  str_homestory_chat_27522006 = "아버지께서 한 치수 큰 옷으로 입으면 된다고\n알려 주시기 전까진 정말 힘들었습니다.",
  str_homestory_chat_27522007 = "그 뒤부터는 옷 때문에 머리 아픈\n일은 없었습니다.",
  str_homestory_chat_27522008 = "그랬구나.",
  str_homestory_chat_27522009 = "볼 때마다 그 옷인거 같아서...",
  str_homestory_chat_27522010 = "똑같은 옷을 여러 벌 준비해서 돌려 입는 거예요.",
  str_homestory_chat_27522011 = "아니, 중요한 건 그게 아니라, 다른 옷을 입어 보려고는 안 해 봤어?",
  str_homestory_chat_27522012 = "안 해 봤어요. 악셀리아는 이런 옷을 좋아해요.\n입으면 엄청 편합니다.",
  str_homestory_chat_27522013 = "그건 그렇겠네...",
  str_homestory_chat_27523001 = "조명?",
  str_homestory_chat_27523002 = "네. 헤븐즈 가든의 가로등을 바꾸고 싶습니다.",
  str_homestory_chat_27523003 = "어떻게 바꾸고 싶은데?",
  str_homestory_chat_27523004 = "전부 네온사인으로 바꾸는 거예요.\n알록달록해서 엄청 예쁠 게 분명해요.",
  str_homestory_chat_27523005 = "「츄브」들도 좋아할 거예요.",
  str_homestory_chat_27523006 = "아무리 생각해도 꽤 대작업이 될 거 같은데.",
  str_homestory_chat_27523007 = "그럼 PlayerName도 동의한 거죠?",
  str_homestory_chat_27523008 = "필요한 자재 수량이랑 비용이 어느 정도가 될 지\n한 번 계산해 보지 않을래요?",
  str_homestory_chat_27523009 = "음, 그냥 바꾸지 말자...",
  str_homestory_chat_27524001 = "말할 때 좀 크게 얘기해 줄 수 있어?",
  str_homestory_chat_27524002 = "악셀리아의 목소리가 너무 작나요?\n대화가 제대로 안 될 정도인가요?",
  str_homestory_chat_27524003 = "가끔 잘 안 들리긴 해...",
  str_homestory_chat_27524004 = "그럼 조금 더 가까이 붙어서 대화하세요.",
  str_homestory_chat_27524005 = "악셀리아는 문제가 있습니다.\n그래서 이게 제일 큰 목소리예요.",
  str_homestory_chat_27524006 = "그치만 너무 가까이 붙어 있으면 좀 불편할 때도 있는데...",
  str_homestory_chat_27524007 = "왜 불편한가요?",
  str_homestory_chat_27524008 = "거리가 가까우면 서로 소통하기 더 좋은 거 아닌가요?",
  str_homestory_chat_27524009 = "음... 일단은 그냥 이대로 하자.",
  str_homestory_chat_27525001 = "사탕?",
  str_homestory_chat_27525002 = "네, 조종사는 사탕을 좋아하나요?",
  str_homestory_chat_27525003 = "좋아하지.",
  str_homestory_chat_27525004 = "전에 움브라톤에서 어떤 젤리를 먹은 적이 있었는데,\n너무 달지도 않고 이에 달라붙지도 않았었어...",
  str_homestory_chat_27525005 = "나중에 악셀리아도 데려가서 그 젤리를 주세요.\n그럼 PlayerName에게 정말 고마울 거예요.",
  str_homestory_chat_27525006 = "알겠어. 그런데 그렇게 말하는 거 치곤 별로 기대하는 것처럼 안 보이는데.",
  str_homestory_chat_27525007 = "아니요, 악셀리아는 엄청 기대하고 있어요.",
  str_homestory_chat_27525008 = "별로 안 좋아해.",
  str_homestory_chat_27525009 = "아깝네요. 악셀리아가 여러 가지 사탕을\n추천해 주려고 했는데 말이에요.",
  str_homestory_chat_27525010 = "특히 빠직빠직 캔디요...",
  str_homestory_chat_27699999 = "안녕! 나 오늘은 기분이 좀 좋아!",
  str_homestory_chat_27601001 = "안녕!",
  str_homestory_chat_27601002 = "베르타는 스스로 부지런히 일을 찾아서 하는 타입이라면서?",
  str_homestory_chat_27601003 = "맞아. 여기가 백야성은 아니지만,\n그래도 여기 온 뒤로 계속...",
  str_homestory_chat_27601004 = "여길 더 좋은 곳으로 만들어야 한다는 의무감이\n들어서 자꾸 뭐라도 좀 하고 싶어져.",
  str_homestory_chat_27601005 = "너무 조급해하진 마. 헤븐즈 가든을 가꾸는 일은\n하루아침에 되는 일이 아니거든.",
  str_homestory_chat_27601006 = "라파엘 님도 그렇게 얘기하셨었는데... 알겠어.",
  str_homestory_chat_27621001 = "꽃을 기르고 싶어?",
  str_homestory_chat_27621002 = "응, 여긴 재미있게 생긴 꽃들이 많더라고.\n그중에서도 특히 엄청 키가 큰 꽃들!",
  str_homestory_chat_27621003 = "그건... 꽃이 아니라... 환상수야...",
  str_homestory_chat_27621004 = "응? 진짜 신기하네. 어떤 것들은 꽃이랑 똑같던데?\n특히 화관 쪽 말이야. 다 네가 심은 거야?",
  str_homestory_chat_27621005 = "응.",
  str_homestory_chat_27621006 = "대부분 츄브들이 심은 거야.",
  str_homestory_chat_27621007 = "나도 같이 해도 돼?\n나 식물 돌보는 거 엄청 잘하거든!",
  str_homestory_chat_27621008 = "음... 생각 좀 해 볼게.",
  str_homestory_chat_27622001 = "네가 말한 새 말인데...",
  str_homestory_chat_27622002 = "응, 헤븐즈 가든은 굉장히 넓잖아.\n그래서 여러 새들이 많이 날아올 거 같거든.",
  str_homestory_chat_27622003 = "난 그 새들이 편히 쉴 수 있게 둥지를 만들고 싶어.",
  str_homestory_chat_27622004 = "좋은 생각이야! 새들을 그렇게 주의 깊게 관찰한 걸 보면,\n넌 새를 아주 좋아하는구나?",
  str_homestory_chat_27622005 = "사실... 새들을 관찰해 보라고 한 건\n라파엘 님의 제안이었어.",
  str_homestory_chat_27622006 = "인내심을 기르면 마음이 조금은\n덜 조급해진다고 하셨거든.",
  str_homestory_chat_27622007 = "근데 여기 오고 나서는 할 일이 없어서 그런지\n걸핏하면 본성이 되돌아오는 느낌이야.",
  str_homestory_chat_27622008 = "그러니까 어디에 가면 새가 있는지 알려 줄래?\n새가 있다면 지금 바로 가 보려고!",
  str_homestory_chat_27622009 = "역시 마음이 급해졌구나...",
  str_homestory_chat_27622010 = "방금 뭐라고? 새가 어디 있다고?",
  str_homestory_chat_27622011 = "아, 내 말은 서두르지 말고 천천히 찾아봐야 한다는 거였어.",
  str_homestory_chat_27622012 = "그것도 인내심을 기르는 하나의 과정이잖아. 그렇지?",
  str_homestory_chat_27622013 = "그렇네.",
  str_homestory_chat_27623001 = "의료 훈련?",
  str_homestory_chat_27623002 = "응, 헤븐즈 가든이 평화롭긴 하지만,\n그래도 이런 훈련은 해야 한다고 봐.",
  str_homestory_chat_27623003 = "적의 침입이 없어도, 응급 상황에 대처하는\n방법은 알아야지.",
  str_homestory_chat_27623004 = "예를 들면 갑자기 물에 빠진다거나,\n지붕에서 떨어진다거나...",
  str_homestory_chat_27623005 = "확실히 그렇네.",
  str_homestory_chat_27623006 = "근데 의료 훈련을 어떻게 시작해야 하지?\n도와 줄 사람들도 좀 찾아야 되나?",
  str_homestory_chat_27623007 = "그럴 필요 없어! 츄브들이 이렇게나 많은걸!",
  str_homestory_chat_27623008 = "잠깐만! 츄브들은 오로리안이랑 다르잖아...",
  str_homestory_chat_27623009 = "츄브들이랑 하는 의료 훈련이 정말 효과가 있을까?",
  str_homestory_chat_27623010 = "내 기술이 녹슬지 말라고 하는 거니까,\n아무 문제 없어!",
  str_homestory_chat_27623011 = "아, 알았어.",
  str_homestory_chat_27799999 = "하이, 오늘도 건강해 보이네!",
  str_homestory_chat_27721001 = "넌 항상 밝구나.",
  str_homestory_chat_27721002 = "그 텐션을 어떻게 항상 유지하는 거야? 무슨 비결이라도 있어?",
  str_homestory_chat_27721003 = "왜냐하면 아이돌은 그런 거잖아.\n비록 마음이 울적할 때라도...",
  str_homestory_chat_27721004 = "항상 열정을 잃지 말고 모두에게\n최고의 모습을 보여줘야 해!",
  str_homestory_chat_27721005 = "그래야 온 대륙을 사랑과 치유로 채울 수 있거든.",
  str_homestory_chat_27721006 = "어떻게 보면 넌 정말 대단하네...",
  str_homestory_chat_27722001 = "나 찾았어?",
  str_homestory_chat_27722002 = "PlayerName 씨, 나 굉장히 심각한 질문이 있어.\n진지하게 대답해 줘.",
  str_homestory_chat_27722003 = "어, 왜 그래? 무슨 일 있었어?",
  str_homestory_chat_27722004 = "요즘 나... 혹시... 몸무게가...",
  str_homestory_chat_27722005 = "(살이 쪘을까 걱정하는 것 같네. 뭐라고 대답하면 좋을까?)",
  str_homestory_chat_27722006 = "조금 통통해진 것 같아.",
  str_homestory_chat_27722007 = "역시! 분명히 저번에 너무 많이 먹은 탓이야.",
  str_homestory_chat_27722008 = "게다가 여기 분위기가 너무 편안해서...\n이대로는 안 돼!",
  str_homestory_chat_27722009 = "오늘 밤은 아무것도 먹으면 안 되겠어.\n그리고 50바퀴 뛰어야 해!",
  str_homestory_chat_27722010 = "아닌데?",
  str_homestory_chat_27722011 = "진짜? 너 사실대로 말 안 하면 앞으로 다시는\n너한테 하트를 안 날릴 거야!",
  str_homestory_chat_27722012 = "음... 조금 늘어난 것 같긴 해.",
  str_homestory_chat_27722013 = "아무래도 요즘 너무 긴장을 풀었던 것 같아.\n지금부터 나한테 엄격해져야겠어!",
  str_homestory_chat_27722014 = "아니, 그...그렇게까지 반응할 건 없어. 그냥 아주 살짝일 뿐이니까.",
  str_homestory_chat_27722015 = "살짝이라도 안 돼. 이건 아이돌이 된 대가야.",
  str_homestory_chat_27722016 = "넌 진짜 자기한테 엄격하구나.",
  str_homestory_chat_27723001 = "운동하고 싶다고?",
  str_homestory_chat_27723002 = "사실은 공연을 위한 훈련이야!\n여기 혹시 전용 트레이닝 룸 있어?",
  str_homestory_chat_27723003 = "저기...",
  str_homestory_chat_27723004 = "휴, 여긴 역시 쉬기 좋은 장소구나.",
  str_homestory_chat_27723005 = "근데 트레이닝을 빠트릴 순 없어...\n아이돌은 항상 베스트 컨디션을 유지해야 하니까.",
  str_homestory_chat_27723006 = "전문적인 기구가 필요 없는 트레이닝이라면 할 수 있지 않을까?",
  str_homestory_chat_27723007 = "좋지! 음, 어떤 종목이 있나 볼까...",
  str_homestory_chat_27723008 = "달리기, 수영, 등산, 춤... 확실히 많이 있네!",
  str_homestory_chat_27723009 = "그럼 힘내.",
  str_homestory_chat_27724001 = "방?",
  str_homestory_chat_27724002 = "맞아. 마시멜로 전용 방을 구해주고 싶어.",
  str_homestory_chat_27724003 = "너 옆에 있는 그 강아지 말하는 거지?",
  str_homestory_chat_27724004 = "맞아. 항상 밖에서 재워두는 것도 안 좋고.\n여긴 가끔 비가 오니까.",
  str_homestory_chat_27724005 = "확실히 좀 그렇네...",
  str_homestory_chat_27724006 = "그럼 이렇게 하자! 내 침대 밑에 집을 만들어 줄래.\n담요 하나만 있으면 되니까.",
  str_homestory_chat_27724007 = "그거 좋은 생각이네!",
  str_homestory_chat_27724008 = "그럼 지금 바로 츄브들을 불러올게.",
  str_homestory_chat_27724009 = "아무래도... 진작에 그럴 생각이었던 모양이네.",
  str_homestory_chat_27725001 = "너도 컨디션이 좋아 보이네.",
  str_homestory_chat_27725002 = "맞아! 여기 쏜 오이가 없어서 그런 것도 있어.",
  str_homestory_chat_27725003 = "쏜 오이? 그게 싫은 거야?",
  str_homestory_chat_27725004 = "PlayerName 씨는 안 싫어?!",
  str_homestory_chat_27725005 = "딱히 싫진 않은데.",
  str_homestory_chat_27725006 = "진짜?! 믿을 수 없어! 그 맛은 정말...",
  str_homestory_chat_27725007 = "아, 이해했어. 다이어트 때문에 먹는 거지?",
  str_homestory_chat_27725008 = "저기... 난 그런 게...",
  str_homestory_chat_27725009 = "휴, 역시 너도 체중을 중요하게 생각하는구나.\n고생이 많아.",
  str_homestory_chat_27725010 = "아니, 난 진짜로...",
  str_homestory_chat_27725011 = "싫어해.",
  str_homestory_chat_27725012 = "그치? 그러니까 절대 오이를 여기 가져오면 안 돼!\n절대 잊지 마!",
  str_homestory_chat_27725013 = "알겠어.",
  str_homestory_chat_27899999 = "음~ 무슨 일이야?",
  str_homestory_chat_27821001 = "뭐 해?",
  str_homestory_chat_27821002 = "흔들의자를 만들까, 해먹을 만들까 생각 중이었어...",
  str_homestory_chat_27821003 = "그걸로 뭘 하게?",
  str_homestory_chat_27821004 = "당연히 쉬는 거지. 설마 균형감각이라도 단련하게?",
  str_homestory_chat_27821005 = "상상해 봐. 거기 누워서 햇볕도 쬐고\n산들바람도 쐬고, 으음~",
  str_homestory_chat_27821006 = "확실히 편하겠네...",
  str_homestory_chat_27822001 = "정말 한가해 보이네.",
  str_homestory_chat_27822002 = "그러게. 여긴 사람이 완전히 긴장을 풀 수 있는\n드문 곳이니까.",
  str_homestory_chat_27822003 = "설마 PlayerName 넌 이런 느낌이 싫어?",
  str_homestory_chat_27822004 = "좋아해.",
  str_homestory_chat_27822005 = "그렇지! 역시 PlayerName 넌 날 가장\n잘 알고 있다니까!",
  str_homestory_chat_27822006 = "분명히 너도 나처럼 이런 느긋한 느낌을 좋아하겠지.",
  str_homestory_chat_27822007 = "아무것도 하지 않고 바람에 날리는\n구름을 바라보고 있거나...",
  str_homestory_chat_27822008 = "나뭇잎의 웅성거림을 들으면서\n머리를 완전히 비우면...",
  str_homestory_chat_27822009 = "금방 기운을 되찾을 수 있어.",
  str_homestory_chat_27822010 = "그거 괜찮네. 나도 나중에 해봐야겠어.",
  str_homestory_chat_27822011 = "싫지는 않지만...",
  str_homestory_chat_27822012 = "너무 느긋한 것도 좋진 않으니까, 적당히 뭔가 하고 싶어.",
  str_homestory_chat_27822013 = "예를 들면 집을 짓는다든지?\n근데 그런 건 츄브들한테 해달라고 하면 되잖아.",
  str_homestory_chat_27822014 = "넌 이 느긋한 시간을 좀 더 즐겨도 돼.",
  str_homestory_chat_27822015 = "그건... 아무래도 좀 다른 것 같아.",
  str_homestory_chat_27823001 = "뭐가 필요해?",
  str_homestory_chat_27823002 = "여기 이상한 동물들이 있다고 들었는데?",
  str_homestory_chat_27823003 = "본 적 없어.",
  str_homestory_chat_27823004 = "그거 아깝네.\n여기서 뭔가 발견할 수 있을 줄 알았는데.",
  str_homestory_chat_27823005 = "그래도 휴가라고 생각하는 것도 괜찮을 것 같네...",
  str_homestory_chat_27823006 = "아... 있어.",
  str_homestory_chat_27823007 = "역시 여기 오길 잘했다니까!\n쉴 수도 있고, 환상동물도 찾을 수 있잖아.",
  str_homestory_chat_27823008 = "일거양득이네!",
  str_homestory_chat_27823009 = "땡땡이치는 게 목적이었나...",
  str_homestory_chat_27824001 = "낚시?",
  str_homestory_chat_27824002 = "그래, 근처 강에서 물고기를 많이 봤거든.\n낚시하러 가는 사람도 많겠지.",
  str_homestory_chat_27824003 = "맞아.",
  str_homestory_chat_27824004 = "낚시 좋아해?",
  str_homestory_chat_27824005 = "좋아.",
  str_homestory_chat_27824006 = "그런대로.",
  str_homestory_chat_27824007 = "그렇구나... 뭐, 난 낚시보다 관상이 더 좋거든.",
  str_homestory_chat_27824008 = "물속에서 움직이는 모습을 보고 있으면\n마음이 편안해지니까.",
  str_homestory_chat_27824009 = "그럼 희망의 연못에 보러 가 봐.",
  str_homestory_chat_27824010 = "음, 그거랑은 달라.\n소원의 연못에 갇혀 있는 건 전혀 다른 느낌이거든.",
  str_homestory_chat_27824011 = "그것도 맞는 말이네...",
  str_homestory_chat_27825001 = "마실 거 찾는 중이야?",
  str_homestory_chat_27825002 = "맞아, 여긴 참 멋지긴 한데...\n뭔가 부족하단 말이지..",
  str_homestory_chat_27825003 = "역시 맛있는 술이 빠지면 안 되지~",
  str_homestory_chat_27825004 = "대낮부터 마시는 거야...?",
  str_homestory_chat_27825005 = "그냥 살짝 한잔할 뿐이야. 산들바람도 맞으면서.\n만약 여기 흔들의자도 하나 있으면...",
  str_homestory_chat_27825006 = "정말 최고겠지!",
  str_homestory_chat_27825007 = "그래서 환상동물은 찾으러 안 가?",
  str_homestory_chat_27825008 = "여긴 쉬러 온 거야! 휴, 술이 없다면...",
  str_homestory_chat_27825009 = "저쪽의 계곡물도 괜찮겠지? 으음~",
  str_homestory_chat_27825010 = "그건... 비크 씨가 알아서 해.",
  str_homestory_chat_28099999 = "뭔가 가십거리가 있을 것 같군요!",
  str_homestory_chat_28001001 = "어? 딱히 없는데...",
  str_homestory_chat_28001002 = "넌 왜 그렇게 가십거리를 좋아해?",
  str_homestory_chat_28001003 = "재밌잖아요!",
  str_homestory_chat_28001004 = "예를 들면 어떤 대상회의 중요한 인물은\n사실 소설가가 꿈이라든가...",
  str_homestory_chat_28001005 = "그런 거 재미있지 않나요?",
  str_homestory_chat_28001006 = "그건... 사람마다 다르지 않을까.",
  str_homestory_chat_28001007 = "그러니까 부지런히 기삿거리를 모아서\n다양한 독자들의 요구에 부응해야죠!",
  str_homestory_chat_28001008 = "그럼 힘내.",
  str_homestory_chat_28021001 = "그 기계...",
  str_homestory_chat_28021002 = "항상 가지고 다니는 것 같은데, 언제 어디서든 사진을 찍기 위해서지?",
  str_homestory_chat_28021003 = "맞아요! 왜냐면 가십의 기본은 진실이니까요!",
  str_homestory_chat_28021004 = "뭐? 그건 아니지 않아?",
  str_homestory_chat_28021005 = "그럼 PlayerName 씨는 어떻게 생각하는데요?",
  str_homestory_chat_28021006 = "거리의 소문은 진실일 거야.",
  str_homestory_chat_28021007 = "맞아요!",
  str_homestory_chat_28021008 = "가끔은 조작도 있잖아...",
  str_homestory_chat_28021009 = "그래도 괜찮지 않을까? 어차피 사소한 일인데 그렇게 중요하지 않잖아.",
  str_homestory_chat_28021010 = "안 돼요!",
  str_homestory_chat_28021011 = "절대 안 돼요. 가십이라도 사실이어야만 해요.\n안 그러면 독자는 결국 흥미를 잃게 되거든요.",
  str_homestory_chat_28021012 = "가십에도 어느 정도 진실성이 있어야만\n독자를 끌어들일 수 있어요!",
  str_homestory_chat_28021013 = "가십도 마음대로 쓸 수 있는 게 아니었구나.",
  str_homestory_chat_28022001 = "네 그 가방...",
  str_homestory_chat_28022002 = "왜 그렇게 큰 거야? 게다가 맨날 들고 다니던데.",
  str_homestory_chat_28022003 = "여러 가지 자료가 들어있기 때문이겠죠.\n노트, 사진, 신문, 그리고 전단지까지...",
  str_homestory_chat_28022004 = "다 가지고 다니는 거야? 사무실에 두면 안 돼?",
  str_homestory_chat_28022005 = "안 돼요! 많은 정보들은 서로 관련이 있거든요!",
  str_homestory_chat_28022006 = "때로는 무심한 정보 속에 특종이 숨어 있기도 해요.",
  str_homestory_chat_28022007 = "특종이 될 것 같은 사람이나 사물을 만났을 때,\n그것들이 필요할지도 모른다구요!",
  str_homestory_chat_28022008 = "근데 그런 정보는 금방 뒤처지지 않을까?",
  str_homestory_chat_28022009 = "그러니까 항상 가지고 다녀야 하는 거죠.\n이 가방은 제가 주문제작한 거예요!",
  str_homestory_chat_28022010 = "대용량일 뿐만 아니라 입구도 넓어서\n자료 찾기가 편리해요!",
  str_homestory_chat_28022011 = "자료의 자세한 위치는 전부 잘 기억하고 있거든요!",
  str_homestory_chat_28022012 = "그렇게 기억력이 좋다면 차라리 그 자료를 암기하는 게 더 빠르지 않을까...",
  str_homestory_chat_28023001 = "무슨 소식 있어?",
  str_homestory_chat_28023002 = "아니요... 전혀요. 여기 생활은 정말 지루하네요.",
  str_homestory_chat_28023003 = "어딜 봐도 츄브, 츄브, 츄브 투성이잖아요.",
  str_homestory_chat_28023004 = "소식을 접할 만한 카페나 신문 가판대조차 없어요.",
  str_homestory_chat_28023005 = "여기서 좀 쉬는 것도 좋잖아.",
  str_homestory_chat_28023006 = "그럴 순 없어요. 특종을 놓쳐버릴 거라구요!",
  str_homestory_chat_28023007 = "하지만 여기 생활은 확실히 평온해.\n다른 할 일을 찾아보는 건 어때?",
  str_homestory_chat_28023008 = "다른 할 일이라... 아, 있어요!",
  str_homestory_chat_28023009 = "츄브를 훈련시킨 다음에 가서 특종을\n찾아오라고 해야겠어요!",
  str_homestory_chat_28023010 = "그렇게 된다면... 헤헤헤...",
  str_homestory_chat_28023011 = "하지 마!",
  str_homestory_chat_28199999 = "귀공은 근래에 무엇을 하고 있었소?",
  str_homestory_chat_28121001 = "종서 씨는 취미가 있나요?",
  str_homestory_chat_28121002 = "종 모는 나무 조각을 만드는 취미가 있소.",
  str_homestory_chat_28121003 = "나무 조각이요?",
  str_homestory_chat_28121004 = "그렇소. 평평한 나무토막을 날카로운 칼로...",
  str_homestory_chat_28121005 = "점차 모양을 잡으면 조각 작품이 탄생하는 것이오.",
  str_homestory_chat_28121006 = "조각을 만들면 때로는 전쟁에서 이겼을 때보다\n더 기쁨을 주기도 한다네.",
  str_homestory_chat_28121007 = "나무 조각을 정말 좋아하시는군요...",
  str_homestory_chat_28122001 = "환상수요?",
  str_homestory_chat_28122002 = "여기서 저 기묘한 나무들을 보다가\n새로운 생각이 들었소.",
  str_homestory_chat_28122003 = "저 나무들로 조각 공예를 하고 싶으신 거죠?",
  str_homestory_chat_28122004 = "그렇소. 귀공은 승낙해줄 것이오?",
  str_homestory_chat_28122005 = "안 돼요.",
  str_homestory_chat_28122006 = "그토록 단호한 것을 보니,\n귀공이 소중히 여기는 나무인가 보오.",
  str_homestory_chat_28122007 = "그야... 키우는 게 쉽지 않은 건 사실이니까요...",
  str_homestory_chat_28122008 = "생각해 볼게요...",
  str_homestory_chat_28122009 = "나무 조각을 하는 데 재료가 많이 필요한가요?",
  str_homestory_chat_28122010 = "그렇소. 사용해 본 적이 없는 수종이니,\n버려지는 게 많을지도 모르오.",
  str_homestory_chat_28122011 = "이 환상수는 목재의 결이 조금 다를 수도\n있기 때문이오.",
  str_homestory_chat_28122012 = "그럼... 좀 곤란할 것 같아요.",
  str_homestory_chat_28122013 = "허면... 여기서 질 좋은 목재를 찾을 수 있는\n것으로 만족해야겠구려.",
  str_homestory_chat_28122014 = "아니면 외부에서 사들이는 것도 하나의 방도겠지...",
  str_homestory_chat_28123001 = "고양이를 좋아하나요?",
  str_homestory_chat_28123002 = "그렇소. 그래서 세 마리나 키우고 있소.",
  str_homestory_chat_28123003 = "세 마리나!",
  str_homestory_chat_28123004 = "하지만 평소엔 한 마리만 보이던데요.",
  str_homestory_chat_28123005 = "저들의 역할이 모두 다르기 때문이오...",
  str_homestory_chat_28123006 = "각자 역할도 있는 건가요... 대단하네요.",
  str_homestory_chat_28123007 = "일심은 전투를 맡고, 일몽은 종 모 곁을 지키지.\n그리고 일낙은...",
  str_homestory_chat_28123008 = "신출귀몰해서 종 모도 녀석이 어딜 가는지 모르오.",
  str_homestory_chat_28123009 = "그럼 그걸 키운다고 할 수 있나요...",
  str_homestory_chat_28124001 = "뭐 사려고요?",
  str_homestory_chat_28124002 = "기물을 살까 하오. 방에 두면 쌍사성에 있는\n느낌이 들 것 같소.",
  str_homestory_chat_28124003 = "기물이라면... 골동품 말인가요?\n용주의 골동품은 구하기 힘들 것 같은데요.",
  str_homestory_chat_28124004 = "용주의 것이 아니어도 괜찮소.\n사실 종 모는 아스트라 대륙의 골동품을 원하오.",
  str_homestory_chat_28124005 = "백야성의 보검, 움브라톤의 명주,\n북방의 뼈 조각 같은 것들 말이오...",
  str_homestory_chat_28124006 = "꽤 잘 알고 계시는 것 같네요.",
  str_homestory_chat_28124007 = "과찬이오. 기왕 이곳에 왔으니,\n다양한 문예를 감상해야 하지 않겠소.",
  str_homestory_chat_28124008 = "아스트라 대륙을 이해할 기회이기도 하고 말이오.",
  str_homestory_chat_28124009 = "저도 염두해 둘게요.",
  str_homestory_chat_28125001 = "다른 조각 공예요?",
  str_homestory_chat_28125002 = "그렇소. 귀공이 조각 공예에 대해 아는지 모르겠군.",
  str_homestory_chat_28125003 = "조금이요.",
  str_homestory_chat_28125004 = "호오? 이 대륙에는 어떤 공예들이 있소?",
  str_homestory_chat_28125005 = "대부분은 석조나 목조고, 북방에는 골조도 있어요.",
  str_homestory_chat_28125006 = "일루미나와 레디젤 렌치에는 가끔 철 공예도 볼 수 있다고 해요!",
  str_homestory_chat_28125007 = "종류가 그리 많았다니...\n허나 뿌리 조각은 없는 듯하오.",
  str_homestory_chat_28125008 = "그게 뭐죠?",
  str_homestory_chat_28125009 = "용주에만 있는 독특한 조각이오.\n기회가 되면 상세히 설명해 주리다.",
  str_homestory_chat_28125010 = "왠지... 궁금하네요...",
  str_homestory_chat_28125011 = "전혀 모르겠네요...",
  str_homestory_chat_28125012 = "아쉽게 되었소. 하면 이쯤에서 이야기를 마치겠소.",
  str_homestory_chat_28125013 = "아, 뭔가 더 말해야 할 것 같은 느낌인데요...",
  str_homestory_chat_28299999 = "무슨 일이야?",
  str_homestory_chat_28221001 = "수영할 수 있는 곳이 어디냐고 물었죠?",
  str_homestory_chat_28221002 = "맞아. 육지에만 있다 보니 수영 실력이\n떨어지는 것 같거든.",
  str_homestory_chat_28221003 = "강은 어때요?",
  str_homestory_chat_28221004 = "조금 얕은 것 같아.\n좀 더 깊고 파도가 있는 게 좋겠어.",
  str_homestory_chat_28221005 = "기복이 좀 있어야 해, 바다처럼 말이야.",
  str_homestory_chat_28221006 = "그럼 해변에 가는 게 낫겠네요...",
  str_homestory_chat_28222001 = "어떤 음식 좋아해요?",
  str_homestory_chat_28222002 = "내가 좋아하는 건 받아들이기 힘들 거야.\n우렁쌀국수라든지 말이야.",
  str_homestory_chat_28222003 = "괜찮을 것 같은데요...",
  str_homestory_chat_28222004 = "당신도 좋아하는 거야?! 신기하네!",
  str_homestory_chat_28222005 = "그게... 그냥 받아들일 수 있는 정도예요. 대신 먹을 땐 사람들을 피해야겠죠.",
  str_homestory_chat_28222006 = "알아, 잘 알아.",
  str_homestory_chat_28222007 = "먹을 수 있다는 것만으로 대단한 거야.\n아스트라 대륙의 용사라고 불릴만 해.",
  str_homestory_chat_28222008 = "그, 그 정도는 아니에요.",
  str_homestory_chat_28222009 = "역시...",
  str_homestory_chat_28222010 = "역시 그건 향이 너무 진하단 말이지.",
  str_homestory_chat_28222011 = "만약 먹게 된다면 사람들을 피해서 먹을 거야.",
  str_homestory_chat_28222012 = "고마워요!",
  str_homestory_chat_28223001 = "약을 찾고 있나요?",
  str_homestory_chat_28223002 = "응. 멀미약 있어?",
  str_homestory_chat_28223003 = "아니요.",
  str_homestory_chat_28223004 = "아마 있을 거예요...",
  str_homestory_chat_28223005 = "근데 잠깐만요! 그건 왜 찾죠?",
  str_homestory_chat_28223006 = "월백 씨는 숙련된 선장이잖아요!",
  str_homestory_chat_28223007 = "당연히 다른 사람에게 주려는 거지.\n대부분 멀미가 있으니까.",
  str_homestory_chat_28223008 = "일부 숙련된 선원들도 힘들 때가 있고 말이야.",
  str_homestory_chat_28223009 = "그렇군요. 가서 찾아볼게요.",
  str_homestory_chat_28224001 = "배를 찾는다면서요?",
  str_homestory_chat_28224002 = "맞아. 강을 보다가 생각났어.",
  str_homestory_chat_28224003 = "헤븐즈 가든은 외부와의 길은 막았지만,\n수로는 아직 그런대로 원활한 것 같아.",
  str_homestory_chat_28224004 = "그래서 이 수로로 무역을 좀 할 수 있을까 해서.",
  str_homestory_chat_28224005 = "안 그러는 게 좋겠어요.",
  str_homestory_chat_28224006 = "왜지?",
  str_homestory_chat_28224007 = "수로는 매끄럽지만, 역류가 많다고 츄브들이 그랬어요.",
  str_homestory_chat_28224008 = "그리고 암초도 많고 흘수가 얕아서 배가 쉽게 뒤집힐 수 있어요.",
  str_homestory_chat_28224009 = "생각해 볼게요.",
  str_homestory_chat_28224010 = "정말? 다른 문제는 없을까?",
  str_homestory_chat_28224011 = "츄브 말로는 수로 상황이 복잡하다고는 하는데...",
  str_homestory_chat_28224012 = "자세히는 저도 잘 모르겠어요.",
  str_homestory_chat_28224013 = "수로가 복잡하다고? 그렇다면 확인해봐야겠어.",
  str_homestory_chat_28224014 = "아무래도... 내가 섣불렀던 것 같네.",
  str_homestory_chat_28225001 = "당신 칼 말인데요...",
  str_homestory_chat_28225002 = "왜?",
  str_homestory_chat_28225003 = "누군가 불만을 제기했어요...",
  str_homestory_chat_28225004 = "응? 누가? 뭐 때문에?",
  str_homestory_chat_28225005 = "츄브들이요. 당신이 그 칼을 가지고 노는 걸 봤대요.",
  str_homestory_chat_28225006 = "왠지 자기들을 어떻게 할 것 같나 봐요.",
  str_homestory_chat_28225007 = "맞아...",
  str_homestory_chat_28225008 = "내가 헤븐즈 가든에 온 목적은 바로\n츄브를 사냥하는 거니까.",
  str_homestory_chat_28225009 = "진짜요?!",
  str_homestory_chat_28225010 = "그걸 믿어?",
  str_homestory_chat_28225011 = "당연히 아니겠죠...",
  str_homestory_chat_28225012 = "그래서 뭘 걱정하는데? 가서 츄브에게 말해야지.",
  str_homestory_chat_28225013 = "쓸데없는 두려움이야.\n난 습관적으로 칼을 만지작거렸을 뿐인걸.",
  str_homestory_chat_28225014 = "아, 알았어요.",
  str_homestory_chat_28399999 = "안녕, PlayerName, 약초 맛 좀 볼래?",
  str_homestory_chat_28301001 = "안녕! 많이 찾은 모양이네!",
  str_homestory_chat_28301002 = "응! 여기 기후는 각종 약초가 자라기 아주 좋거든!",
  str_homestory_chat_28301003 = "자연의 식물들일 뿐이지만 약효는 아주 다양해.",
  str_homestory_chat_28301004 = "저 기묘한 나무들은 말할 것도 없고...",
  str_homestory_chat_28301005 = "서, 설마 지금 환상수를 노리는 거야?",
  str_homestory_chat_28301006 = "아직은 아니야. 츄브들이 꽤나 엄격한 것 같거든.",
  str_homestory_chat_28301007 = "그래서 용주의 약초를 여기에 심어볼 생각이야.",
  str_homestory_chat_28301008 = "아, 그건 좋은 것 같네.",
  str_homestory_chat_28321001 = "간식?",
  str_homestory_chat_28321002 = "여긴 어떤 간식이 있어? 요즘 죽만 먹었더니...",
  str_homestory_chat_28321003 = "츄브 상인한테 물어도 아무 대답도 안 해주고!",
  str_homestory_chat_28321004 = "설마 아스트라 대륙에는 맛있는 간식이 없는 거야?",
  str_homestory_chat_28321005 = "아니야, 있어!",
  str_homestory_chat_28321006 = "그럼 알려줘!",
  str_homestory_chat_28321007 = "북방의 젤리.",
  str_homestory_chat_28321008 = "너무 달지 않으면서 부드럽고, 쫀득한 게 이에 붙지도 않아.",
  str_homestory_chat_28321009 = "움브라톤의 초콜릿.",
  str_homestory_chat_28321010 = "순초콜릿은 쓴맛이 나서 대부분은 우유, 설탕이나 견과류를 넣곤 해.",
  str_homestory_chat_28321011 = "이를테면 헤이즐넛, 아몬드, 땅콩 같은...",
  str_homestory_chat_28321012 = "그만 말해...",
  str_homestory_chat_28321013 = "너 침이...",
  str_homestory_chat_28321014 = "아앗! 언젠가 먹을 수 있을 테니까... 그때까진...",
  str_homestory_chat_28321015 = "상상하면서 버텨야겠어.",
  str_homestory_chat_28321016 = "어떻게 보면 너도 참 대단하네.",
  str_homestory_chat_28322001 = "저울?",
  str_homestory_chat_28322002 = "맞아, 이 녀석 좀 봐.",
  str_homestory_chat_28322003 = "아스트라 대륙에 와서 안 건데,\n여기 저울은 내가 살던 데랑 달라!",
  str_homestory_chat_28322004 = "바닥에 놓고 쓰는 데다가,\n양쪽에 그릇이 하나씩 있더라고.",
  str_homestory_chat_28322005 = "응, 그게 이곳의 저울이야.",
  str_homestory_chat_28322006 = "맞아. 대신 휴대도 불편하고 평평한 바닥도 필요해.",
  str_homestory_chat_28322007 = "내 저울이 더 쓰기 편하다구.\n아스트라 대륙 사람들은 다 이렇게 답답한 거야?",
  str_homestory_chat_28322008 = "저기... 사실 움브라톤에서도 저울을 쓰고 있어.",
  str_homestory_chat_28322009 = "아?",
  str_homestory_chat_28322010 = "당장 린 가문 상회에 가도 있고, 여기 저울도 아주 정확해.",
  str_homestory_chat_28322011 = "저울은... 사용하는 사람에 따라 다를 수 있는 거야.",
  str_homestory_chat_28322012 = "이해했어. 복자께서 가라사대, 「인지제의」라!\n지역마다 방법도 달라야지. 역시 옛말이 맞다니까!",
  str_homestory_chat_28322013 = "이럴 땐 「저마다 자기 장점이 있다」가 더 맞지 않을까?",
  str_homestory_chat_28323001 = "고양이 찾는 거야?",
  str_homestory_chat_28323002 = "응. 정확히 말하자면 형한테 친구가 필요하거든.",
  str_homestory_chat_28323003 = "형?",
  str_homestory_chat_28323004 = "작은꼬리 말이야. 그래서 진짜로 고양이가 있어?",
  str_homestory_chat_28323005 = "여긴 없네... 근데 여기 지내러 오는 사람들이 한두 마리 데리고 왔을 순 있어.",
  str_homestory_chat_28323006 = "그 사람들한테 물어보는 게 나을걸.",
  str_homestory_chat_28323007 = "하지만 다들 아스트라 대륙 사람들이잖아.\n난 아직 잘 모른단 말이야.",
  str_homestory_chat_28323008 = "다들 여기까지 왔는데 잘 모르긴! 괜찮을 거야!",
  str_homestory_chat_28323009 = "지, 진짜?!",
  str_homestory_chat_28323010 = "넌 활발하니까 문제없을 거야.",
  str_homestory_chat_28323011 = "역시! 나도 자신감을 가져야겠어.\n그럼 며칠 뒤에 가서 물어볼게~",
  str_homestory_chat_28499999 = "아이테르 군, 오늘은 한가한 모양이구나.",
  str_homestory_chat_28421001 = "예리아 씨도 그런 것 같은데요.",
  str_homestory_chat_28421002 = "난 산책하는 중이었어.",
  str_homestory_chat_28421003 = "산책?",
  str_homestory_chat_28421004 = "특별히 할 일이 없거든.\n게다가 이 헤븐즈 가든은 애초에 일도 별로 없잖아.",
  str_homestory_chat_28421005 = "그렇다고 내 흥미를 자극하는 것도 없으니까,\n산책이나 해야지.",
  str_homestory_chat_28421006 = "그렇군요.",
  str_homestory_chat_28422001 = "그럼 음식 얘기나 할까요?",
  str_homestory_chat_28422002 = "좋아, 아이테르 군은 무슨 음식을 좋아할까?",
  str_homestory_chat_28422003 = "디저트요.",
  str_homestory_chat_28422004 = "단 걸 좋아하는구나... 평범하네.",
  str_homestory_chat_28422005 = "다들 좋아하지 않나요? 초콜릿 같은 거요.",
  str_homestory_chat_28422006 = "엄밀히 말하면 초콜릿은 쓴 거야.\n단맛은 설탕을 첨가한 거란다.",
  str_homestory_chat_28422007 = "그럼... 설마 넌 쓴맛을 좋아하는 거였니?",
  str_homestory_chat_28422008 = "그건 아니에요...",
  str_homestory_chat_28422009 = "고기요.",
  str_homestory_chat_28422010 = "뭘 좀 아네! 그럼 간은 어때?\n특히 간으로 만든 간식들 말이야.",
  str_homestory_chat_28422011 = "그건... 저한테 좀 힘들 것 같은데요.",
  str_homestory_chat_28422012 = "아, 그거 참 아쉽네.",
  str_homestory_chat_28423001 = "목재를 찾으시나요?",
  str_homestory_chat_28423002 = "응. 방에 작은 둥지를 하나 만들까 하는데 괜찮을까?",
  str_homestory_chat_28423003 = "그럼요.",
  str_homestory_chat_28423004 = "안 하는 게... 낫겠어요.",
  str_homestory_chat_28423005 = "근데 둥지는 왜요?",
  str_homestory_chat_28423006 = "집을 좀 만들어주려고.\n요즘 통 잠을 못 자더라고...",
  str_homestory_chat_28423007 = "누구한테요?",
  str_homestory_chat_28423008 = "파이선 말이야.\n계속 남의 침대에서 자게 할 수는 없으니까...",
  str_homestory_chat_28423009 = "다, 당연히 안 되죠! 다른 사람들이 놀랄 거예요.",
  str_homestory_chat_28423010 = "그럼 넌 된다는 뜻인가 보네?",
  str_homestory_chat_28423011 = "아니면... 예리아 씨 침대 밑에 하나 만드세요.",
  str_homestory_chat_28424001 = "책?",
  str_homestory_chat_28424002 = "응. 아이테르 군은 무슨 책 읽는 거 좋아하니?",
  str_homestory_chat_28424003 = "소설이요.",
  str_homestory_chat_28424004 = "평범한 장르네...",
  str_homestory_chat_28424005 = "소설도 재밌는 게 많아요. 특히 움브라톤의 추리 소설들이요...",
  str_homestory_chat_28424006 = "확실히 대중적인 취향이구나...",
  str_homestory_chat_28424007 = "인물 전기요.",
  str_homestory_chat_28424008 = "오? 재밌네, 역사에 관심이 있나 봐?",
  str_homestory_chat_28424009 = "아스트라 대륙의 과거에 대해 더 알고 싶어서요.",
  str_homestory_chat_28424010 = "그럼 예리아 씨는 무슨 책을 좋아하는데요?",
  str_homestory_chat_28424011 = "철학.",
  str_homestory_chat_28424012 = "철학이라니!",
  str_homestory_chat_28424013 = "놀란 것 같네, 사실 철학은 정말 재미있어.\n시간 날 때 몇 권 추천해줄게.",
  str_homestory_chat_28424014 = "아, 알겠어요.",
  str_homestory_chat_28425001 = "츄브?",
  str_homestory_chat_28425002 = "맞아. 내가 보기에 저 츄브는 정말 똑똑한 것 같아.",
  str_homestory_chat_28425003 = "어느 츄브요?",
  str_homestory_chat_28425004 = "저 바람의 탑 광장에 있는 수염 난 츄브 있잖아.",
  str_homestory_chat_28425005 = "츄브 장로요?",
  str_homestory_chat_28425006 = "맞아. 「장로」라고 불리는 걸 보니\n역시 똑똑한 모양이네.",
  str_homestory_chat_28425007 = "정말 그거 때문인가요...",
  str_homestory_chat_28425008 = "사실 「장로」도 그냥 별명일 뿐이에요. 그 수염은...",
  str_homestory_chat_28425009 = "수염은?",
  str_homestory_chat_28425010 = "그냥 자기가 찬 가짜 수염이에요.",
  str_homestory_chat_28425011 = "아... 그렇구나.",
  str_homestory_chat_28425012 = "민망하네...",
  str_homestory_chat_28425013 = "그럼... 전 이만 가볼게요.",
  str_homestory_chat_28599999 = "안녕하세요, PlayerName. 오늘은 별일 없나요?",
  str_homestory_chat_28501001 = "별일 없어, 넌?",
  str_homestory_chat_28501002 = "전 헤븐즈 가든에서 부업을 찾는 중이에요.",
  str_homestory_chat_28501003 = "부업?",
  str_homestory_chat_28501004 = "근데 벌써 츄브 장로랑 츄브 상인한테 물어봤는데,\n일거리가 별로 없나 봐요.",
  str_homestory_chat_28501005 = "맞아, 여긴 원래 일이 별로 없어. 다들 자기들끼리 하는 거야.",
  str_homestory_chat_28501006 = "택배 일 같은 건 없나요?\n메시지를 보내는 것도 좋아요.",
  str_homestory_chat_28501007 = "여긴 땅이 크지도 않아서 잘 없어. 다들 쉬려고 오는 곳이지.",
  str_homestory_chat_28501008 = "아... 그렇군요.",
  str_homestory_chat_28521001 = "싫어하는 게 뭐냐고?",
  str_homestory_chat_28521002 = "네, 한순간도 참을 수 없는 그런 거요.",
  str_homestory_chat_28521003 = "음... 암귀?",
  str_homestory_chat_28521004 = "암귀는 누구나 싫어하죠...",
  str_homestory_chat_28521005 = "악당?",
  str_homestory_chat_28521006 = "구체적으로 어떤 거죠?",
  str_homestory_chat_28521007 = "동료를 해치는 녀석들.",
  str_homestory_chat_28521008 = "그렇군요.",
  str_homestory_chat_28521009 = "그럼 키아는 뭘 싫어해?",
  str_homestory_chat_28521010 = "지각하는 사람이요!",
  str_homestory_chat_28521011 = "어떻게 시간을 안 지킬 수가 있는 거죠...\n대부분은 미리 약속한 건데 말이에요.",
  str_homestory_chat_28521012 = "조금 늦어도 괜찮다는 녀석들은...\n혼이 좀 나야 해요!",
  str_homestory_chat_28521013 = "그건 그래...",
  str_homestory_chat_28522001 = "사고 싶은 게 있다면서?",
  str_homestory_chat_28522002 = "네, 손목시계가 사고 싶어요.",
  str_homestory_chat_28522003 = "하지만 헤븐즈 가든엔 손목시계가 없는데,\n사람 잘못 찾아온 거 아냐?",
  str_homestory_chat_28522004 = "아니에요. 당신한테 특별한 거래처가\n있다고 들었어요.",
  str_homestory_chat_28522005 = "특별한 거래처?",
  str_homestory_chat_28522006 = "네, 「지인 할인」 그런 거 있잖아요.",
  str_homestory_chat_28522007 = "그것도 아주 큰 할인이요.\n평소 가격의 25%라고 하던데요!",
  str_homestory_chat_28522008 = "그건 너무 과하잖아! 누구한테 들은 거야?",
  str_homestory_chat_28522009 = "네? 안 되는 건가요...",
  str_homestory_chat_28522010 = "아쉽네요, 전에 움브라톤에서 본 손목시계가\n정말 마음에 들었는데...",
  str_homestory_chat_28522011 = "너무 비싸더라고요. 십 년은 일해야 할 거예요.\n할인하면 2년 반이면 될 텐데...",
  str_homestory_chat_28522012 = "저기... 너희 월급이 그렇게 적은 거야...?",
  str_homestory_chat_28522013 = "그게 다 움브라톤에서 너무 비싸게 팔아서 그래요!\n악덕 상인들!",
  str_homestory_chat_28522014 = "그것도 그래!",
  str_homestory_chat_28523001 = "음식?",
  str_homestory_chat_28523002 = "네, PlayerName 씨는 평소에 뭘 먹나요?",
  str_homestory_chat_28523003 = "음... 있는 대로 먹지 뭐.",
  str_homestory_chat_28523004 = "그게 다예요?",
  str_homestory_chat_28523005 = "난 콜로서스에서 만든 영양액을 계속 마셨어.",
  str_homestory_chat_28523006 = "에... 그렇게 먹는 즐거움을 안 따지는 건가요...\n근데 사실 저도 비슷해요.",
  str_homestory_chat_28523007 = "어? 비슷하다고?",
  str_homestory_chat_28523008 = "가끔 시간 아끼려고 딱딱한 빵이나 육포를\n먹을 때도 있거든요.",
  str_homestory_chat_28523009 = "일이 끝나야만 먹고 싶은 걸 먹을 수 있어요.\n매운 짬뽕 같은 거 말이에요.",
  str_homestory_chat_28523010 = "PlayerName 씨도 노력을 많이 하는군요.\n하긴, 그 덕에 지금의 성과를 이룬 거겠죠.",
  str_homestory_chat_28523011 = "저기... 완전히 잘못 이해한 것 같아.",
  str_homestory_chat_28699999 = "정말 여유롭군요, PlayerName.",
  str_homestory_chat_28621001 = "너도네.",
  str_homestory_chat_28621002 = "맞아요. 정말 사람을 편하게 만드는 분위기예요.\n낮잠 자고 싶을 정도로... 하암~",
  str_homestory_chat_28621003 = "하아암~",
  str_homestory_chat_28621004 = "앗, 당신도 그런가요?",
  str_homestory_chat_28621005 = "왠지 하품도 전염되는 것 같은데?",
  str_homestory_chat_28621006 = "그거 꽤 재미있는 생각이네요...\n그럼 이제 자러 갈 건가요?",
  str_homestory_chat_28621007 = "아니, 가 볼 데가 있어서 안 돼.",
  str_homestory_chat_28621008 = "그럼 힘내세요~",
  str_homestory_chat_28622001 = "너 그 손...",
  str_homestory_chat_28622002 = "제 「신의 손」 말인가요?",
  str_homestory_chat_28622003 = "응.",
  str_homestory_chat_28622004 = "이건, 말하자면 긴데요...\n아주 강력한 루미나틱스가 있단 것만 알면 돼요.",
  str_homestory_chat_28622005 = "응...",
  str_homestory_chat_28622006 = "아니.",
  str_homestory_chat_28622007 = "너 왼손 말이야.",
  str_homestory_chat_28622008 = "왼손? 그래요.\n그것도 사실 사람들이 자주 물어보곤 해요.",
  str_homestory_chat_28622009 = "응... 왼손 힘이 센 것도 「신의 손」 때문이야?",
  str_homestory_chat_28622010 = "아... 그건 전혀 아니에요.\n그냥 제가 평소에 왼손을 많이 써서 그런가 봐요.",
  str_homestory_chat_28622011 = "그래서 저도 모르게 힘이 세졌어요...",
  str_homestory_chat_28622012 = "일종의 간접 훈련인 셈이겠네.",
  str_homestory_chat_28623001 = "암귀?",
  str_homestory_chat_28623002 = "왠지 암귀가 여기 온 적은 한 번도 없는 것 같네요.",
  str_homestory_chat_28623003 = "응.",
  str_homestory_chat_28623004 = "진짜 들어온다면 엄청난 일이겠지.",
  str_homestory_chat_28623005 = "앗... 그럼 녀석을 어떻게 찾죠...",
  str_homestory_chat_28623006 = "녀석?",
  str_homestory_chat_28623007 = "아, 아니에요!\n암귀가 없다면 암귀의 흔적이 있는 곳도 괜찮아요.",
  str_homestory_chat_28623008 = "혹시 아는 게 있나요?",
  str_homestory_chat_28623009 = "여쨌든 여긴 없어. 포기하는 게 좋을 거야.",
  str_homestory_chat_28623010 = "역시 츄브들에게 물어봐야겠네요.",
  str_homestory_chat_28623011 = "걔네도 모를 거라고!",
  str_homestory_chat_28624001 = "장사를 하려고?",
  str_homestory_chat_28624002 = "사실 그냥 뭔가 좀 사고 싶거든요. 서적 같은 거요.",
  str_homestory_chat_28624003 = "헤븐즈 가든에서는 구하기 힘든데, 움브라톤에 가보지 그래?",
  str_homestory_chat_28624004 = "너무 멀잖아요. 그냥 근처에 서점이 있으면\n하나 사서 시간 때우려던 거예요.",
  str_homestory_chat_28624005 = "백야성에서 움브라톤까진 가깝지 않나...",
  str_homestory_chat_28624006 = "전 이미 여기 있으니까요.\n그럼 츄브 상인도 책은 없는 건가요?",
  str_homestory_chat_28624007 = "내가 알기론 없어.",
  str_homestory_chat_28624008 = "하아, 어쩔 수 없네요... 하암...",
  str_homestory_chat_28624009 = "낮잠 좀 자는 건 어때? 그것도 시간 보내기 좋은 방법이야.",
  str_homestory_chat_28625001 = "간식?",
  str_homestory_chat_28625002 = "네, PlayerName 당신은 어떤 간식을 좋아하나요?",
  str_homestory_chat_28625003 = "케이크.",
  str_homestory_chat_28625004 = "단 걸 좋아했군요... 먹고 나면 불편하지 않나요?",
  str_homestory_chat_28625005 = "그렇진 않은 것 같아. 티나 넌 단 거 안 좋아해?",
  str_homestory_chat_28625006 = "과자.",
  str_homestory_chat_28625007 = "특히 짭짤한 거? 따뜻한 물이랑 먹으면 아주 맛있거든.",
  str_homestory_chat_28625008 = "탁월한 선택이네요. 간식은 단 것만 있는 게 아니라...",
  str_homestory_chat_28625009 = "여러 가지 맛이 있어야 해요!",
  str_homestory_chat_28625010 = "넌 단 걸 안 좋아하는 모양이구나...",
  str_homestory_chat_28625011 = "안 좋아해요.\n먹으면 왠지 초조해서 잠이 안 오거든요.",
  str_homestory_chat_28625012 = "이리저리 뒤척이는 그 괴로운 느낌을\n당신도 알지 모르겠네요.",
  str_homestory_chat_28625013 = "알 것 같아. 다음날도 피곤하고 말이야.",
  str_homestory_chat_28625014 = "맞아요. 그게 제가 낮에도 잠을 자야 하는 이유예요.",
  str_homestory_chat_28625015 = "근데 넌 단 걸 안 먹어도 잠은 자잖아...",
  str_homestory_chat_28999999 = "PlayerName, 제가 뭘 하면 됩니까?",
  str_homestory_chat_28921001 = "응? 그냥 얘기나 하려는 건데?",
  str_homestory_chat_28921002 = "여유 시간인가 보군요.\n취미를 하나 만들고 싶진 않습니까?",
  str_homestory_chat_28921003 = "예를 들면?",
  str_homestory_chat_28921004 = "꽃을 심는 것도 아주 좋습니다.",
  str_homestory_chat_28921005 = "씨를 심은 후에 싹이 터서 마침내\n아름다운 꽃이 피는 걸 보면...",
  str_homestory_chat_28921006 = "자연의 아름다움에 감탄하지 않을 수 없을 겁니다.",
  str_homestory_chat_28921007 = "난 이미 나무도 심어 봤는데...",
  str_homestory_chat_28921008 = "그것도 좋습니다.\n꾸준히 하다 보면 깨달음을 얻게 될 겁니다.",
  str_homestory_chat_28922001 = "그 무기...",
  str_homestory_chat_28922002 = "왜 그러십니까?",
  str_homestory_chat_28922003 = "가끔 보면 왠지 무기 같지가 않은 것 같아서. 특히 그 드릴.",
  str_homestory_chat_28922004 = "이해합니다. 백야성 기사들이 쓰는 일반적인\n무기와는 다르게 보이겠지요.",
  str_homestory_chat_28922005 = "맞아, 기사들은 보통 검이나 창 뭐 그런 걸 쓰니까...",
  str_homestory_chat_28922006 = "그래서 무슨 이유라도 있는 거야?",
  str_homestory_chat_28922007 = "이유는 중요하지 않습니다.\n기사에게 무기가 중요하지 않은 것처럼 말이죠.",
  str_homestory_chat_28922008 = "중요하지 않다니?",
  str_homestory_chat_28922009 = "기사를 결정하는 것은 그의 기사도 정신이니까요.",
  str_homestory_chat_28922010 = "알겠어! 겸손, 관용 같은 「기사의 미덕」 그런 거 말이지...",
  str_homestory_chat_28922011 = "맞습니다. 그런 정신이 있어야만 기사인 것이지,\n무기는 중요한 것이 아닙니다.",
  str_homestory_chat_28922012 = "이해했어.",
  str_homestory_chat_28923001 = "뭐 사려고?",
  str_homestory_chat_28923002 = "기름을 사려고 합니다.",
  str_homestory_chat_28923003 = "무슨 기름?",
  str_homestory_chat_28923004 = "식용유라면 아마 있을걸.",
  str_homestory_chat_28923005 = "부품 윤활에 쓸 겁니다.\n보통 움브라톤에선 살 수 있었는데 말이죠.",
  str_homestory_chat_28923006 = "그건...",
  str_homestory_chat_28923007 = "구하기 어렵겠죠?\n여긴 자연의 분위기가 가득한 곳이니까요.",
  str_homestory_chat_28923008 = "응... 확실히 여기선 찾기 힘든 물건이겠네.",
  str_homestory_chat_28923009 = "요즘 무기가 시원치 않아서 수리를 좀\n하려던 참이었거든요.",
  str_homestory_chat_28923010 = "힘을 줘서 휘두르기만 하면 거슬리는\n「딸깍」소리가 나더군요.",
  str_homestory_chat_28923011 = "그럼... 아무래도 움브라톤에 가 봐야 하지 않을까.",
