  str_homestory_chat_28924002 = "매우 중요한 일을 생각하고 있습니다만,\n답이 나오질 않는군요.",
  str_homestory_chat_28924003 = "뭔지 말해줄 수 있어?",
  str_homestory_chat_28924004 = "당신은 공정과 평등 중 어느 쪽이\n더 중요하다고 생각하십니까?",
  str_homestory_chat_28924005 = "공정.",
  str_homestory_chat_28924006 = "그렇다면 일부 약자가 더 많은 권리를\n갖는 것에 동의하십니까?",
  str_homestory_chat_28924007 = "예를 들어 경범죄를 저질러도 면제를\n해주거나 한다든지 말입니다.",
  str_homestory_chat_28924008 = "음... 생각 좀 해 볼게...",
  str_homestory_chat_28924009 = "평등.",
