  str_homestory_chat_28924011 = "한 사람은 단거리 달리기를 자주 연습했고,\n다른 한 사람은 한쪽 다리가 부러진 병사였습니다.",
  str_homestory_chat_28924012 = "말씀하신 대로라면 우승 기준에 두 사람의\n신체를 고려해서는 안 됩니다.",
