  str_homestory_chat_28925002 = "당신은 아주 많은 곳을 다녔다고 들었는데,\n거기도 가봤습니까?",
  str_homestory_chat_28925003 = "딱히 기억에 남진 않았어.",
  str_homestory_chat_28925004 = "음... 아쉽군요.",
  str_homestory_chat_28925005 = "레인 씨는 가 봤어?",
  str_homestory_chat_28925006 = "운 좋게 몇 번 가봤습니다.\n확실히 백야성과는 다른 곳입니다.",
  str_homestory_chat_28925007 = "그곳 사람들의 관념도 백야성과 달랐죠.\n삶은 고달파도, 많은 용감한 사람들이 있었습니다.",
