  str_homestory_chat_28925010 = "가봤어.",
  str_homestory_chat_28925011 = "그곳의 풍토에 대해 어떻게 생각하십니까?",
  str_homestory_chat_28925012 = "열정적이고, 역동적이야... 마치 사막처럼.",
  str_homestory_chat_28925013 = "맞습니다. 비록 적응이 쉽진 않겠지만,\n이 대륙에서 꼭 필요한 곳이기도 합니다.",
  str_homestory_chat_28925014 = "세상의 많은 일이 다 그런 것 같네.",
  str_homestory_chat_29099999 = "PlayerName, 오늘은 산책하기 좋은 날이군.",
  str_homestory_chat_29001001 = "안녕, 마티외 씨.",
  str_homestory_chat_29001002 = "오늘도 무척 한가해 보이는군그래.\n이곳의 서민은 참 해이하단 말이지.",
