  str_homestory_chat_29001005 = "츄브 말이야?",
  str_homestory_chat_29001006 = "그래, 언제 어디서든 일하는 것 같던데.",
  str_homestory_chat_29001007 = "바람의 탑 앞에서 안내하는 녀석, 물 주는 녀석,\n또 온종일 돈 계산하는 녀석.",
  str_homestory_chat_29001008 = "아마... 좋아서 하는 거일걸.",
