  str_homestory_chat_29021006 = "뭔데?",
  str_homestory_chat_29021007 = "비 오는 날 생기는 웅덩이.\n이 산골짜기에 지붕을 하나 만들어야겠어.",
  str_homestory_chat_29021008 = "하늘 전체를 다 가릴 수 있는 크기로.",
  str_homestory_chat_29021009 = "그렇게 크게?!",
  str_homestory_chat_29021010 = "그럼 평소 햇빛은 어떡해!",
  str_homestory_chat_29021011 = "걱정하지 말라고. 장치만 있으면 맑은 날엔 열고,\n비가 오면 닫을 수 있다고 들었거든.",
  str_homestory_chat_29021012 = "여기 있는 일루미나 사람이 그러더군.\n몇몇 지하성도 그런 식이라고 말이야.",
  str_homestory_chat_29021013 = "뭔가 이상한 지식을 배워온 거 같은데...",
  str_homestory_chat_29021014 = "허락한 것 같으니 그럼 비용 계산은\n네게 맡기도록 하지.",
