  str_homestory_chat_29022001 = "식기?",
  str_homestory_chat_29022002 = "이곳 식기는 너무 투박해.\n보고 있으면 있던 입맛도 사라진단 말이지.",
  str_homestory_chat_29022003 = "그 정도로 심할 리가 없잖아!",
  str_homestory_chat_29022004 = "정말이다. 못 믿겠으면 한 번 봐라!\n죄다 나무 아니면 도자기잖아.",
  str_homestory_chat_29022005 = "은 나이프 한 자루도 없어서 빵도 못 자른다고.",
  str_homestory_chat_29022006 = "설마 요 며칠 내내 굶은 건 아니지...?",
  str_homestory_chat_29022007 = "그러니 은식기 한 세트만 좀 구해다 줬으면 좋겠군.",
  str_homestory_chat_29022008 = "가능하면 애프터눈 티를 마실 수 있는\n백자다기 세트도 준비해주면 더 좋고.",
  str_homestory_chat_29022009 = "듣기만 해도 아주 비쌀 것 같은데... 대충 가격이 얼마나 하는지 알아?",
  str_homestory_chat_29022010 = "가격? 나야 모르지.",
  str_homestory_chat_29022011 = "가격도 모르면서 사달라니... 그럼 돈도 내가 대신 내라는 거야?",
  str_homestory_chat_29022012 = "당연하지, 사 온 다음에 내 집사에게 청구하라고.",
  str_homestory_chat_29022013 = "잠깐만! 나 아직 대답 안 했어!",
  str_homestory_chat_29023001 = "하인을 고용하겠다고?",
  str_homestory_chat_29023002 = "그래, 후하게 대우해 줄 테니 말이야.",
  str_homestory_chat_29023003 = "하인은 왜 고용하려는 건데?",
  str_homestory_chat_29023004 = "여긴 하인이 없어.",
  str_homestory_chat_29023005 = "근데 왜 이렇게 갑자기?",
  str_homestory_chat_29023006 = "잡일은 하인에게 맡겨야지.",
  str_homestory_chat_29023007 = "귀족으로서 난 내 시간을 중요한 일에 써야 하거든.",
