  str_homestory_chat_29023012 = "정확해.",
  str_homestory_chat_29023013 = "안 돼!",
  str_homestory_chat_29199999 = "헤븐즈 가든 순찰 중인가?\n아니면 그냥 빈둥빈둥 돌아다니는 건가?",
  str_homestory_chat_29101001 = "하티 넌 뭐 하고 있었는데?",
