  str_homestory_chat_29121002 = "그래, 여긴 아이들이 별로 없어서인지,\n뭐랄까... 너무 조용해.",
  str_homestory_chat_29121003 = "있는데?",
  str_homestory_chat_29121004 = "어디?",
  str_homestory_chat_29121005 = "여기저기서 온 동료들이 있어. 백야성이랑 레디젤 렌치랑 또...",
  str_homestory_chat_29121006 = "며칠 있으면 헤븐즈 가든에 와서 한동안 묵다 갈 거야.",
