  str_homestory_chat_29121010 = "그건 그렇네.",
  str_homestory_chat_29121011 = "그렇진 않은 거 같은데.",
  str_homestory_chat_29121012 = "하아... 츄브한테 가서 기분 전환이나 좀 해야겠어.",
  str_homestory_chat_29121013 = "기분 전환? 뭐 할 건데?",
  str_homestory_chat_29121014 = "겁먹을 필요 없어. 그냥 멀리서 츄브들을 보다가\n무슨 일이 생긴 거 같으면 가서 도와주는 것뿐이야.",
  str_homestory_chat_29121015 = "넘어지면 가서 부축해 준다든지, 뭐 그런 거.",
  str_homestory_chat_29121016 = "너 정말... 마음씨가 착하구나?",
  str_homestory_chat_29121017 = "뭐라고?",
  str_homestory_chat_29121018 = "아무것도 아니야! 아무튼 고마워!",
  str_homestory_chat_29122001 = "낱말 퍼즐?",
  str_homestory_chat_29122002 = "낱말 퍼즐 좋아해?",
  str_homestory_chat_29122003 = "좋아해.",
  str_homestory_chat_29122004 = "별로 안 좋아해.",
  str_homestory_chat_29122005 = "근데 갑자기 그건 왜 물어보는 거야?",
  str_homestory_chat_29122006 = "따분해 죽겠어.\n여긴 낱말 퍼즐이 실린 신문도 없어.",
  str_homestory_chat_29122007 = "저기 안경 낀 츄브라면 그걸 좋아할 줄 알았는데,\n머리에 온통 숫자밖에 안 들었더라고.",
  str_homestory_chat_29122008 = "저기 저쪽에 있는 수염 난 어르신 츄브는\n온종일 한가하게 돌아다니기만 해. 너처럼...",
  str_homestory_chat_29122009 = "크, 크흠. 난 한가하게 돌아다니는 게 아니라... 헤븐즈 가든을 순찰하는 거야.",
  str_homestory_chat_29122010 = "그나저나 하티 넌 쉴 때 낱말 퍼즐 말고 다른 건 안 해?",
  str_homestory_chat_29122011 = "낱말 퍼즐은 아주 재미있어.\n특히 굉장히 어려운 단어를 맞혔을 때...",
  str_homestory_chat_29122012 = "그 짜릿함은 말론 다 표현할 수 없을 정도라고!",
  str_homestory_chat_29122013 = "머리도 좀 쉬어 주는 편이 좋을 거 같아...",
  str_homestory_chat_29123001 = "뭐 살 거야?",
  str_homestory_chat_29123002 = "침이랑 바늘.",
  str_homestory_chat_29123003 = "뭐 꿰매려고 그러는 거지? 혹시 옷이 찢어졌어?",
  str_homestory_chat_29123004 = "넌 감응 능력은 아주 강하지만, 눈썰미는 없네.",
  str_homestory_chat_29123005 = "엥?",
  str_homestory_chat_29123006 = "인형이 찢어진 거야. 난 그걸 고치려는 거고.",
  str_homestory_chat_29123007 = "인형을 고칠 줄도 아는구나...",
  str_homestory_chat_29123008 = "이상한가? 고치는 거 말고 만들 줄도 안다고.\n자투리 천이랑 실 그리고 바늘만 있으면 돼.",
  str_homestory_chat_29123009 = "겉보기랑 참 다르네...",
  str_homestory_chat_29123010 = "PlayerName 네 눈엔 내가 이런 일하곤 거리가\n멀어 보이는 사람인가?",
  str_homestory_chat_29123011 = "하티 넌 평소에 좀 쿨한 이미지잖아.\n말할 때도, 뭘 할 때도 항상 시원시원하고.",
  str_homestory_chat_29123012 = "그건 네가 가진 고정관념이야.",
  str_homestory_chat_29123013 = "일을 시원시원하게 하는 거랑 천 인형을 만드는 일\n사이엔 필연적인 관계가 없어.",
  str_homestory_chat_29123014 = "그건 맞아.",
  str_homestory_chat_29124001 = "향신료?",
  str_homestory_chat_29124002 = "향신료가 좀 필요해. 요리용으로.",
  str_homestory_chat_29124003 = "맛있는 걸 만들려고 하는구나?",
  str_homestory_chat_29124004 = "맞아! 고기찜을 만들 거야!",
  str_homestory_chat_29124005 = "우와! 고기찜이라니!",
  str_homestory_chat_29124006 = "그럼 요리에 쓰려고 특별히 좋은 고기를 가져왔겠네?",
  str_homestory_chat_29124007 = "좋은 고기? 그런 건 안 가져왔는데.",
  str_homestory_chat_29124008 = "엥?",
  str_homestory_chat_29124009 = "가져오기엔 번거롭기도 하고 상할 수도 있으니까.\n여긴 고기 안 파냐?",
  str_homestory_chat_29124010 = "고기는... 안 팔아.",
  str_homestory_chat_29124011 = "그거 곤란하네.\n여긴 사냥감도 딱히 없는 것 같은데 말이야.",
  str_homestory_chat_29124012 = "낚시를 해서 생선으로 대체하는 수밖에 없나?",
  str_homestory_chat_29124013 = "그러면 고기찜이 아니라 생선국이 돼 버릴 텐데...",
  str_homestory_chat_29124014 = "생선찜도 나쁘지 않아.\n가끔은 그거대로 맛있고, 조미료도 별로 안 쓰고.",
  str_homestory_chat_29124015 = "이제 고기는 아무래도 상관없어진 모양이네.",
  str_homestory_chat_29399999 = "무슨 일이신가요?",
  str_homestory_chat_29321001 = "창술 훈련?",
  str_homestory_chat_29321002 = "혹시 헤븐즈 가든에 창술 선생님이 계신가요?",
  str_homestory_chat_29321003 = "여긴... 평화로운 곳이야.",
  str_homestory_chat_29321004 = "일상적인 훈련 정도만 할 생각이에요.\n그렇지 않으면 이 장창이 무뎌져 버릴 거예요.",
  str_homestory_chat_29321005 = "그렇게까진 안 되지 않을까?\n너도 여기 묵은지 며칠밖에 안 됐으니까 좀 쉬어도 될 거 같은데.",
  str_homestory_chat_29321006 = "어떻게 쉴 수 있겠어요!\n전 백야성의 귀족으로서 언제나 바른 생활\n습관을 유지해야 해요!",
  str_homestory_chat_29321007 = "그럼... 일단은 혼자서 연습해 보도록 해.",
  str_homestory_chat_29322001 = "누가 너한테 불만이 있다던데?",
  str_homestory_chat_29322002 = "네? 누가요?",
  str_homestory_chat_29322003 = "크리스틴이랑 같은 방 쓰는 사람.",
  str_homestory_chat_29322004 = "설마 제가 매일 장창 연습을 하려고 해서\n다들 놀라 버린 건가요?",
  str_homestory_chat_29322005 = "맞아.",
  str_homestory_chat_29322006 = "그리고... 다른 이유도 있어.",
  str_homestory_chat_29322007 = "매일 아침... 너무 일찍 일어나는 거요?",
  str_homestory_chat_29322008 = "그 이유도 있긴 했어...",
  str_homestory_chat_29322009 = "그 말은... 그럼 다른 이유가 또 있단 건가요?",
  str_homestory_chat_29322010 = "응. 가장 불만인 점은 크리스틴이 이불을 항상\n네모반듯하게 정리해 놓으려고 한다는 점 같아.",
  str_homestory_chat_29322011 = "그건 당연한 거 아닌가요?\n침대 위에 대충 뭉쳐 있으면 얼마나 거북한데요!",
  str_homestory_chat_29322012 = "문제는... 다른 사람한테도 그렇게 하라고 강요하면 안 된다는 거야.",
  str_homestory_chat_29322013 = "하지만...",
  str_homestory_chat_29322014 = "아무튼, 너도 다른 사람들한텐 좀 너그러워지는 게 좋겠어.",
  str_homestory_chat_29323001 = "츄브 일로 물어보고 싶은 게 있다고?",
  str_homestory_chat_29323002 = "츄브들을 제 수행원으로 삼아도 될까요?",
  str_homestory_chat_29323003 = "헤븐즈 가든에서 그런 부탁은 처음 받아 봤는걸.\n그리고 백야성에서 그걸 허락할까?",
  str_homestory_chat_29323004 = "전 기사고, 물론 수행원을 모집할 권리가 있어요.\n그리고 당신은 헤븐즈 가든의 주인이잖아요?\n허락해 줄 수 있나요?",
  str_homestory_chat_29323005 = "좋아.",
  str_homestory_chat_29323006 = "생각 좀 해 봐야 할 거 같아.",
  str_homestory_chat_29323007 = "잠깐만! 근데 왜 갑자기 츄브들을 수행원으로 삼으려는 거야?",
  str_homestory_chat_29323008 = "아주 잘 어울릴 거 같아서요!",
  str_homestory_chat_29323009 = "머리도 반듯하고 몸도 반듯하니까...",
  str_homestory_chat_29323010 = "기사의 미덕을 잘 지키는 좋은 수행원이\n될 수 있을 거예요!",
  str_homestory_chat_29323011 = "완전히 잘못 생각하고 있단 느낌이 드는데...",
  str_homestory_chat_29323012 = "그렇지 않아요!\n「건강한 신체에 건강한 정신이 깃든다」라는 말도\n있듯이 분명히 좋은 수행원이 될 거예요!",
  str_homestory_chat_29323013 = "그렇다면 미안하지만 허락은 못 해 주겠어. 그건 진짜 불가능한 일이거든...",
  str_homestory_chat_29324001 = "오페라?",
  str_homestory_chat_29324002 = "오페라를 어떻게 생각하시나요?",
  str_homestory_chat_29324003 = "나쁘지 않지.",
  str_homestory_chat_29324004 = "그럼 괜찮겠네요!",
  str_homestory_chat_29324005 = "별생각 없는데...",
  str_homestory_chat_29324006 = "으음, 그렇다면 안 되겠네요.",
  str_homestory_chat_29324007 = "무슨 일 때문에 그래?",
  str_homestory_chat_29324008 = "헤븐즈 가든에 무대를 하나 세우고 싶어서요.\n무대가 있으면 오페라 극단을 초청해서\n공연을 할 수 있잖아요.",
  str_homestory_chat_29324009 = "여력이 된다면...\n오페라 극장을 하나 세워도 좋을 거 같아요.\n상주하는 오페라 극단도 하나 두고요.",
  str_homestory_chat_29324010 = "그럼 언제든 최신 오페라 공연을\n즐길 수 있을 거예요.",
  str_homestory_chat_29324011 = "그거... 아무래도 무리 아닐까.",
  str_homestory_chat_29999999 = "안녕하세요, 요즘 좀 어떤가요?",
  str_homestory_chat_29901001 = "나야 잘 지냈지. 잉겔 넌?",
  str_homestory_chat_29901002 = "헤븐즈 가든 생활에도 익숙해졌어요.\n다만 여긴 생활의 템포가 약간 느릿한 감이 있네요.",
  str_homestory_chat_29901003 = "템포가 느릿해?",
  str_homestory_chat_29901004 = "도전 정신을 불러일으킬 이벤트를 열어도 좋을 것 같네요.\n벌목 대회 같은 건 어떨까요?",
  str_homestory_chat_29901005 = "역시 그냥 느긋한 시간을 즐기는 편이 더 좋을 것 같아...",
  str_homestory_chat_29921001 = "갑자기 음료는 왜?",
  str_homestory_chat_29921002 = "당신은 어떤 음료를 좋아하죠?",
  str_homestory_chat_29921003 = "커피.",
  str_homestory_chat_29921004 = "대중적인 취향이군요. 동료들에게서 영향을 받은 건가요?",
  str_homestory_chat_29921005 = "맞아. 근데 커피가 맛있어서라기보단,\n휴식법이란 느낌으로 직접 커피를 내린다거나 마시는 거라...",
  str_homestory_chat_29921006 = "카페에 가면 커피 한잔하면서 친구들이랑\n얘기도 할 수 있고 그러잖아.",
  str_homestory_chat_29921007 = "맞는 말이군요.",
  str_homestory_chat_29921008 = "차.",
  str_homestory_chat_29921009 = "특별히 좋아하는 차는 뭐죠?\n몇몇 차 종류는 굉장히 쓰다고 들었어요.",
  str_homestory_chat_29921010 = "설탕이나 우유 같은 걸 적당히 넣으면 훨씬 더 맛있어져.\n그치만 찻잎만 넣어서 우려도...",
  str_homestory_chat_29921011 = "첫 모금엔 쓴맛이 느껴지겠지만, 조금만 지나면\n입이랑 목에 묘하게 향긋함이 퍼질 거야.",
  str_homestory_chat_29921012 = "정신을 맑게 해 주기도 한다는 얘길 들었어요.",
  str_homestory_chat_29921013 = "맞아. 한번 마셔 보는 걸 추천할게.",
  str_homestory_chat_29921014 = "주스.",
  str_homestory_chat_29921015 = "자연의 맛을 즐기는 건가요... 역시 아이테르답네요.",
  str_homestory_chat_29921016 = "적당히 섞어서 만든 주스도 나쁘지 않아...\n난 그냥 신선하고 상큼한 느낌이 좋은 것 같아.",
  str_homestory_chat_29921017 = "여러 영양소를 보충할 수도 있으니 몸에도 좋겠군요.\n나중에 한번 잘 생각해 봐야겠어요.",
  str_homestory_chat_29921018 = "그렇지, 진짜 괜찮은 음료라니까!",
  str_homestory_chat_29921019 = "소다.",
  str_homestory_chat_29921020 = "마시면 트림이 나오는 그런 음료를 좋아하다니!\n정말 이해할 수가 없네요!",
  str_homestory_chat_29921021 = "그렇게 격하게 반응할 것까진 없잖아...",
  str_homestory_chat_29922001 = "뭘 심고 싶다고?",
  str_homestory_chat_29922002 = "헤븐즈 가든에 밭을 하나 일구고 싶어요.\n콩 농사 전용으로요.",
  str_homestory_chat_29922003 = "얼마든지.",
  str_homestory_chat_29922004 = "아직은 공터가 많을 테니까... 그래도 일단 츄브들한테 물어는 봐.",
  str_homestory_chat_29922005 = "그건 안 돼.",
  str_homestory_chat_29922006 = "잠깐만, 왜 콩을 심는 건데?",
  str_homestory_chat_29922007 = "일루미나의 연구에 따르면, 콩은 대규모 재배가 가능하고,\n영양가도 높은 편에 속하는 작물이에요.",
  str_homestory_chat_29922008 = "그럼 맛은?",
  str_homestory_chat_29922009 = "변화무쌍하다고 해도 과언이 아니에요!\n특히 다양한 콩 제품 말이죠!",
  str_homestory_chat_29922010 = "움브라톤에서도 콩 제품을 많이 팔고 있던 걸로 기억해...\n뭐라더라, 「두부」라는 것 같던데?",
  str_homestory_chat_29922011 = "저도 들어 봤어요! 동방에서 온 음식인데, 콩에 새 생명을\n불어넣었다고 할 수 있을 정도로 대단한 음식이라더군요!",
  str_homestory_chat_29922012 = "식감은 아주 부드럽고, 아무것도 곁들이지 않고 먹으면\n콩의 담백한 맛이 느껴질 뿐만 아니라...",
  str_homestory_chat_29922013 = "단맛, 짠맛, 새콤한 맛, 매운맛... 어떤 맛이든 잘 어울린대요!\n정말 다재다능한 식품이죠!",
  str_homestory_chat_29922014 = "확실히 대단하긴 하네...",
  str_homestory_chat_29923001 = "움브라톤에 가고 싶다고?",
  str_homestory_chat_29923002 = "헤븐즈 가든에 온 지 꽤 됐는데, 갑자기 여긴 움브라톤과\n교류가 그다지 많지는 않다는 걸 발견했어요.",
  str_homestory_chat_29923003 = "그렇긴 해. 아무래도 헤븐즈 가든은 좀 외진 곳이니까.",
  str_homestory_chat_29923004 = "나름 여기 특색이야. 좀 외진 곳이란 건,\n바꿔 말하면 딱히 간섭받을 일 없는 조용한 곳이란 거잖아.",
  str_homestory_chat_29923005 = "아무튼 여기서 움브라톤에 가는 건 그렇게 힘든 일이 아니긴 한데...",
  str_homestory_chat_29923006 = "전 정기적으로 가서 우유를 구매할 생각이에요.",
  str_homestory_chat_29923007 = "우유?",
  str_homestory_chat_29923008 = "일루미나에선 우유를 배급해 줘요.\n하지만 여긴 우유가 없는 것 같고, 상점에도 팔질 않아서요.",
  str_homestory_chat_29923009 = "그러네. 우유를 마시고 싶다면 다른 데서 사 오는 수밖에 없어.",
  str_homestory_chat_29923010 = "혹시 마시고 싶다면, 다음에 움브라톤에 갔을 때 몇 상자 사 올게.",
  str_homestory_chat_29923011 = "하지만 움브라톤과 여긴 거리가 가까운 편은 아니니까,\n신선한 우유는 기대하기 어렵겠죠...",
  str_homestory_chat_29923012 = "그럼... 요거트는 어때?",
  str_homestory_chat_29923013 = "좋죠! 요거트도 괜찮아요.",
  str_homestory_chat_29923014 = "그럼 그걸로 사 올게.",
  str_homestory_chat_29924001 = "새집?",
  str_homestory_chat_29924002 = "네. 창문에 걸어 두거나 지붕 위에 둘 수 있는 그런 종류요.",
  str_homestory_chat_29924003 = "아니... 내가 궁금한 건, 갑자기 왜 새집을 만들겠단 거야?",
  str_homestory_chat_29924004 = "아오하를 위해서예요.\n계속 제 손가락 위에서 지내게 할 수는 없으니까요.",
  str_homestory_chat_29924005 = "특히 제가 자고 있을 땐...\n아오하가 갈 수 있는 곳이 마땅히 없는 것 같거든요.",
  str_homestory_chat_29924006 = "그렇다고 하니까 뭔가 조금 딱한걸.",
  str_homestory_chat_29924007 = "그래서 아오하에게도 집을 하나 주려는 거예요.\n아주 커다랄 필요까진 없어요.",
  str_homestory_chat_29924008 = "움브라톤에서 새집을 본 적은 있어.\n크기도 작으니까 만드는 거 자체는 쉬울 거야. 문제는 목재가...",
  str_homestory_chat_29924009 = "이미 츄브에게 사 와 달라고 부탁해 뒀어요.",
  str_homestory_chat_29924010 = "역시 잉겔이라니까.",
  str_homestory_chat_29924011 = "그럼 새집 제작에 동의하는 거죠?",
  str_homestory_chat_29924012 = "딱히 반대할 이유가 없는걸...\n대신 다른 사람의 공간만 안 차지하면 돼.",
  str_homestory_chat_29924013 = "그럼 이제부터 목수를 찾아야겠네요...",
  str_homestory_chat_29924014 = "아무래도... 완성까진 시간이 꽤 걸리겠네.",
  str_homestory_chat_29299999 = "만나서 반가워.",
  str_homestory_chat_29201001 = "그동안 잘 지냈어?",
  str_homestory_chat_29201002 = "평화, 풍족, 헤븐즈 가든은 정말 꿈속의 이상향 같은 곳이네.\n이런 곳에서 쉴 수 있어서 정말 영광이야.",
  str_homestory_chat_29201003 = "마음에 든다니 다행이야. 편하게 쉬어.",
  str_homestory_chat_29201004 = "여기 오고 난 뒤로 자주 이런 생각을 하곤 해.\n이 꿈속의 이상향을 지키려면 난 지금보다\n훨씬 더 노력해야겠다고 말이야.",
  str_homestory_chat_29201005 = "이곳이 더러움에 물들고, 바깥세상의 악독한 자들이\n이곳에 발을 들이게 만들 순 없어.",
  str_homestory_chat_29201006 = "그렇게 생각해 줘서 고마워.",
  str_homestory_chat_29221001 = "레오 씨는 좋아하는 과일이 뭐야?",
  str_homestory_chat_29221002 = "갑자기 그건 왜 묻는 거지?",
  str_homestory_chat_29221003 = "그냥, 갑자기 궁금해졌거든.",
  str_homestory_chat_29221004 = "난 남쪽 지방에서 나는 과일을 좋아해.\n과즙과 영양가도 풍부하고, 종류도 다양하거든.",
  str_homestory_chat_29221005 = "넌?",
  str_homestory_chat_29221006 = "난 사과.",
  str_homestory_chat_29221007 = "흔한 과일인데, 어떤 점이 그렇게 마음에 든 거지?",
  str_homestory_chat_29221008 = "바로 어디서든 흔히 볼 수 있단 점?\n그리고 사과는 아삭아삭하고 달기도 꽤 달잖아.",
  str_homestory_chat_29221009 = "그렇지. 자주 접할 수 있는 과일인 만큼, 활용법도 다양해.",
  str_homestory_chat_29221010 = "게다가 요리 맛을 돋울 때 사용할 수도 있다고 들었어.\n확실히 사과는 여러모로 유용한 모두의 과일이네.",
  str_homestory_chat_29221011 = "확실히 그렇지.",
  str_homestory_chat_29221012 = "난 포도.",
  str_homestory_chat_29221013 = "포도도 자주 접할 수 있는 과일이지.\n게다가 수많은 음료의 원료이기도 해.",
  str_homestory_chat_29221014 = "음료의 원료? 예를 들면?",
  str_homestory_chat_29221015 = "백야성에서 식사에 곁들여 마시는 와인이 그렇지.\n일루미나 연방의 탄산음료 중에도 포도즙을 첨가한 것들이 있고.",
  str_homestory_chat_29221016 = "듣기론 레디젤 사막에선 포도를 말려서 간식으로\n먹는 사람들도 있다더군.",
  str_homestory_chat_29221017 = "말려서 먹는 거면 음료는 아니잖아?",
  str_homestory_chat_29221018 = "그렇지. 대신 말린 포도는 빵을 만들 때 풍미를 더하는\n재료로 사용할 수도 있어.",
  str_homestory_chat_29221019 = "그렇게 쓸 수도 있었구나... 대단하네.",
  str_homestory_chat_29222001 = "레오 씨는 어떤 음식을 좋아해?",
  str_homestory_chat_29222002 = "난 뜨거운 음식을 좋아해.\n특히 조리법이 복잡하지 않은 고기 요리.",
  str_homestory_chat_29222003 = "그게 뭔데?",
  str_homestory_chat_29222004 = "쉽게 말하면 맹물에 고기를 넣고 끓인 다음 꺼내서,\n내가 좋아하는 소스를 곁들여 먹는 거야.",
  str_homestory_chat_29222005 = "간편하게 만들어 먹을 수 있는 음식 같네.",
  str_homestory_chat_29222006 = "병사들에겐 만들기도 쉽고 맛도 훌륭한 음식이지.\n게다가 체력도 순식간에 보충할 수 있어.",
  str_homestory_chat_29222007 = "그래서 언제든 고기를 먹을 수 있도록 신경 써야 해.\n보급은 전쟁에 아주 중요한 부분이니까.",
  str_homestory_chat_29222008 = "반면에 무척 복잡한 문제이기도 해...",
  str_homestory_chat_29222009 = "복잡하다고?",
  str_homestory_chat_29222010 = "고려해야 할 부분이 한두 개가 아니거든.\n일단 불을 피우는 연료가 필요해.",
  str_homestory_chat_29222011 = "그리고 육류의 신선도는 물론이고, 병사 개개인의\n취향을 만족시켜야 할 필요도 있어.",
  str_homestory_chat_29222012 = "그중 하나라도 문제가 생긴다면, 병사들의 사기가 떨어지지.\n단장으로서 반드시 신경 써야 하는 부분이야.",
  str_homestory_chat_29222013 = "진짜... 고생이 많네.",
  str_homestory_chat_29223001 = "지도를 그리겠다고?",
  str_homestory_chat_29223002 = "맞아. 혹시 지도 제작법에 대해 알고 있어?",
  str_homestory_chat_29223003 = "대충은...?",
  str_homestory_chat_29223004 = "잘됐네. 마침 도움이 되겠어.",
  str_homestory_chat_29223005 = "잘 몰라...",
  str_homestory_chat_29223006 = "근데 지도 그려서 뭐 하려고?",
  str_homestory_chat_29223007 = "헤븐즈 가든에 온 지도 한참이 지났지만,\n아직도 마음이 완전히 놓이질 않아서 말이야.",
  str_homestory_chat_29223008 = "왜 그런 건데?",
  str_homestory_chat_29223009 = "생각해 보니 헤븐즈 가든이란 곳이 나한텐 아직\n낯설게 느껴지기 때문인 것 같아.",
  str_homestory_chat_29223010 = "바꿔 말하면 내가 아직 이곳에 익숙하지 않다는 거겠지.\n난 익숙하지 않은 곳에선 항상 어느 정도 불안함을 느끼거든.",
  str_homestory_chat_29223011 = "여긴 외부인이 올 일은 없으니까 마음 푹 놓고 있어도 돼.",
  str_homestory_chat_29223012 = "그렇다곤 해도... 지도를 그리면서 지형을 파악해 둬야만\n안심할 수 있을 것 같아.",
  str_homestory_chat_29223013 = "그렇구나... 그럼 힘내!",
  str_homestory_chat_29224001 = "무기를 사고 싶다고?",
  str_homestory_chat_29224002 = "아, 잘못 들은 모양이네.\n그게 아니라 박물관을 하나 지어 달라고 하려던 거야.",
  str_homestory_chat_29224003 = "박물관?",
  str_homestory_chat_29224004 = "백야성의 장창, 일루미나의 지휘용 칼 같은\n다양한 무기를 전시하자는 거지...",
  str_homestory_chat_29224005 = "굳이 박물관을 지을 정돈 아니지 않아?\n몇 가지 안 되는 것 같은데, 그럼 전시실 정도면 충분하잖아?",
  str_homestory_chat_29224006 = "그럴 리가! 대량 생산을 좋아하는 일루미나 연방이라 해도,\n종류는 아주 다양해!",
  str_homestory_chat_29224007 = "장창, 머스킷 단총, 군도, 단검, 근접전 무기, 원거리 무기,\n냉병기, 화기 등 수십 가지는 될 거야.",
  str_homestory_chat_29224008 = "더군다나 백야성의 귀족들은 저마다 다른\n양식과 문양을 지닌 무기를 사용해.",
  str_homestory_chat_29224009 = "자세히 설명하려면 3일 밤낮을 꼬박 써도 모자랄 정도라서,\n전시실 하나론 부족할 게 분명해.",
  str_homestory_chat_29224010 = "무기도 종류가 엄청 많구나... 잠깐만!\n그럼 레오 씨는 그 무기들을 다 가지고 있단 거야?!",
  str_homestory_chat_29224011 = "난 그중 아주 일부만 가지고 있어.\n하지만 차차 수집해 나가면 되겠지.",
  str_homestory_chat_29224012 = "그렇게 많이 가지고 있는 건 아니었구나...\n이제 좀 안심이 되네.",
  str_homestory_chat_29224013 = "이곳은 무척 안전하니 내 소장품을 둬도 괜찮을 것 같거든.\n무기 박물관을 세우자는 얘기를 꺼낸 이유도 그래서고.",
  str_homestory_chat_29224014 = "생각할 시간을 좀 줘...",
  str_homestory_chat_30099999 = "오늘은 어떤 새 소식이 있습니까?",
  str_homestory_chat_30021001 = "저기, 아나톨리 씨는 취미가 뭐야?",
  str_homestory_chat_30021002 = "제 취미 말입니까...\n왜 그런 질문을 하는 건지 물어봐도 되겠습니까?",
  str_homestory_chat_30021003 = "그냥 궁금해서 물어보는 거야.",
  str_homestory_chat_30021004 = "사물을 관찰하는 것일지도 모르겠군요...\n당신은 어떻습니까?",
  str_homestory_chat_30021005 = "난 딱히 취미가 없어.",
  str_homestory_chat_30021006 = "사실 나도 잘 모르겠어.",
  str_homestory_chat_30021007 = "아마... 산책?",
  str_homestory_chat_30021008 = "잠깐만, 어쩌다 아나톨리 씨가 나한테\n질문하는 걸로 바뀌어 버렸잖아?!",
  str_homestory_chat_30021009 = "그게 바로 질문에 대한 제 답이라고 생각하시면 됩니다.",
  str_homestory_chat_30021010 = "그렇구나... 아나톨리 씨 취미는 정보 수집이었던 거네...",
  str_homestory_chat_30022001 = "아나톨리 씨는 기록을 좋아하지?",
  str_homestory_chat_30022002 = "맞습니다. 제아무리 뛰어난 두뇌라도,\n한 줄짜리 기록보다 못하다는 말도 있죠.",
  str_homestory_chat_30022003 = "매번 볼 때마다 뭔가 적거나 그리고 있던데, 그럼 힘들지 않아?",
  str_homestory_chat_30022004 = "익숙해지면 괜찮습니다. 나름의 비결이 있거든요.",
  str_homestory_chat_30022005 = "비결?",
  str_homestory_chat_30022006 = "바로 「속기법」입니다.",
  str_homestory_chat_30022007 = "이름만 들어도 엄청난 기술일 것 같단 느낌이 오는데?\n극소수의 사람들에게만 전수되는 수수께끼의 비법 맞지?",
  str_homestory_chat_30022008 = "줄임말, 기호, 부호 같은 걸 잔뜩 외워야 하고 말이야!",
  str_homestory_chat_30022009 = "아, 그렇지는 않습니다.\n사실 「속기법」은 개개인의 필기 습관에 기반하는 겁니다.",
  str_homestory_chat_30022010 = "어?",
  str_homestory_chat_30022011 = "대부분 줄임말은 본인만 내용을 이해할 수 있으면 됩니다.\n어차피 나중에 본인이 다시 한번 정리해야 하니까요.",
  str_homestory_chat_30022012 = "그렇구나.",
  str_homestory_chat_30023001 = "뭘 사려고 한다면서?",
  str_homestory_chat_30023002 = "관찰할 때 사용할 망원경을 하나 구입하고 싶습니다.",
  str_homestory_chat_30023003 = "아나톨리 씨는 동물이나 식물을 관찰하는 걸 좋아해?",
  str_homestory_chat_30023004 = "아... 동물이나 식물은 제 관찰 대상의 일부에 지나지 않습니다.",
  str_homestory_chat_30023005 = "일부라고?",
  str_homestory_chat_30023006 = "동물과 식물에 관한 정보 같은 경우,\n어느 정도는 관찰에 따라오는 부수적인 부분입니다...",
  str_homestory_chat_30023007 = "진짜 주가 되는 건 헤븐즈 가든의 일상입니다.\n예를 들면 저 츄브들이죠...",
  str_homestory_chat_30023008 = "왜 또 츄브들인데...",
  str_homestory_chat_30023009 = "「또」라니요?",
  str_homestory_chat_30023010 = "쟤들한테 관심 있어 하는 사람이 엄청 많은 것 같거든.",
  str_homestory_chat_30023011 = "그건 당신과 저보다는 츄브들이야말로 이곳의\n토박이이기 때문이 아니겠습니까.",
  str_homestory_chat_30023012 = "그런 츄브들을 조금 더 이해하면, 이곳에 대해 더 많은 걸\n알 수 있게 될 테고, 자연스럽게 당신에게도 도움이 되겠죠.",
  str_homestory_chat_30023013 = "내 생각엔... 그래도 관찰보단 역시 푹 쉬는 게 더 나을 것 같아.",
  str_homestory_chat_30024001 = "물고기를 기른다고?",
  str_homestory_chat_30024002 = "이곳은 물고기를 기르기 참 좋은 곳인 것 같아서요.\n혹시 물고기를 기를 만한 연못이 있습니까?",
  str_homestory_chat_30024003 = "물론 있지!",
  str_homestory_chat_30024004 = "지금은 없어...",
  str_homestory_chat_30024005 = "아나톨리 씨, 물고기 엄청 키우고 싶구나?",
  str_homestory_chat_30024006 = "네. 광장에 있는 연못을 보니, 갑자기 헤븐즈 가든에서\n물고기를 기르고 싶어졌습니다.",
  str_homestory_chat_30024007 = "하지만 제가 아끼는 아이는 조금 특이하기 때문에,\n그 연못에서는 가급적이면 그 아이 하나만 기를 수 있었으면 합니다.",
  str_homestory_chat_30024008 = "그 「파오파오」라는 녀석 말하는 거지?\n조금 위험하게 생기긴 했었지...",
  str_homestory_chat_30024009 = "그저 평범한 생물이니 오해하지 말아 주셨으면 좋겠군요.\n그 아이가 다른 녀석들과 어울리기 힘들까 걱정했을 뿐입니다.",
  str_homestory_chat_30024010 = "그랬구나... 알겠어, 가서 적당한 연못이 있나 찾아볼게.",
  str_homestory_chat_30299999 = "또 영지를 순찰하는 것인가.",
  str_homestory_chat_30221001 = "그냥 산책하고 있던 거예요.",
  str_homestory_chat_30221002 = "그대는 이곳의 안전 문제에 대해 생각해 본 적 있나?",
  str_homestory_chat_30221003 = "있어요.",
  str_homestory_chat_30221004 = "역시 이 땅의 주인답군. 그래서, 결과는 어땠지?",
  str_homestory_chat_30221005 = "좀 살펴봤는데, 헤븐즈 가든의 지형을 고려하면\n지금 이대로를 유지하는 게 가장 좋을 거 같았어요.",
  str_homestory_chat_30221006 = "지금 이대로를 유지한다라... 다소 허술해 보인다만.\n역시 경비를 강화하는 편이 좋을 것이다.",
  str_homestory_chat_30221007 = "한 번 고려해 볼게요.",
  str_homestory_chat_30221008 = "아직까진 없어요.",
  str_homestory_chat_30221009 = "그토록 허술해서야!",
  str_homestory_chat_30221010 = "여긴 외부인에게 발견될 일이 거의 없어요.\n다들 여기 오면 긴장을 조금 풀고 지내도 돼요.",
  str_homestory_chat_30221011 = "안전 문제 쪽은 염려하지 않으셔도 돼요.",
  str_homestory_chat_30221012 = "단언할 수 있나?",
  str_homestory_chat_30221013 = "분명히 문제없을 거예요!",
  str_homestory_chat_30221014 = "성주님은요?",
  str_homestory_chat_30221015 = "얼마 전 몇 차례 순시를 해 보았다.\n보편적인 의미로 무척 안전한 것은 사실이더군.",
  str_homestory_chat_30221016 = "그렇게 말씀해 주시니 저도 안심할 수 있겠네요.",
  str_homestory_chat_30221017 = "허나 절대 경계를 늦춰서는 안 된다.\n지혜로운 이도 한 번의 실수는 범하기 마련이다.",
  str_homestory_chat_30221018 = "아, 알겠어요.",
  str_homestory_chat_30221019 = "딱히 필요 없을 것 같아요.",
  str_homestory_chat_30221020 = "어찌 그토록 경솔할 수 있는 것이냐!\n그대는 진정으로 이곳을 위해 생각하고 있는가?",
  str_homestory_chat_30221021 = "그럼... 이제부터 진지하게 생각해 볼게요.",
  str_homestory_chat_30222001 = "이곳에 대해서 생각하고 있었어요.",
  str_homestory_chat_30222002 = "드디어 이 땅을 어떻게 다스려야 할지\n고심하기 시작한 모양이로군.",
  str_homestory_chat_30222003 = "맞아요.",
  str_homestory_chat_30222004 = "그런데 아직까진 생각에 두서가 좀 없네요.",
  str_homestory_chat_30222005 = "음... 아직은 아니에요.",
  str_homestory_chat_30222006 = "혹시 좋은 생각 있으세요?",
  str_homestory_chat_30222007 = "영지를 다스리기 위해서는 그 영지의 원래 주민을\n중용하는 것이 좋다.",
  str_homestory_chat_30222008 = "이곳의 원래 주민이라면... 설마...",
  str_homestory_chat_30222009 = "물론 저 츄브들을 말한 것이다.",
  str_homestory_chat_30222010 = "확실히 어느 정도 일리는 있네요.",
  str_homestory_chat_30223001 = "사실은...",
  str_homestory_chat_30223002 = "오늘따라 날씨가 좋은 거 같아서 산책하러 나온 거예요.",
  str_homestory_chat_30223003 = "그대도 이런 날씨에 산책하는 걸 좋아하는 모양이군.\n확실히 마음을 즐겁게 만들어 주는 일이지.",
  str_homestory_chat_30223004 = "맑은 날, 고요한 주위를 유유히 거니는 것은\n무언가를 골똘히 생각해 보기에 무척 좋은 일이지.",
  str_homestory_chat_30223005 = "꼭 무언가를 골똘히 생각하지 않아도 되지 않을까요?\n그냥 편히 쉬어도 될 것 같거든요.",
  str_homestory_chat_30223006 = "모처럼 여기 오신 김에 편안한 분위기를 즐겨 보시면 좋잖아요.",
  str_homestory_chat_30223007 = "이곳의 분위기가 편안한 것은 사실이다.\n허나 내게는 아무래도 익숙하지 않군.",
  str_homestory_chat_30223008 = "왜 그렇게 느끼시는 건가요?",
  str_homestory_chat_30223009 = "백야성에 있을 때는 제아무리 하늘이 푸르르다 해도,\n그 하늘을 짊어진 어깨는 언제나 무거운 법이다.",
  str_homestory_chat_30223010 = "「책임」이라는 부담은 날 언제나 사색하게 만들지.",
  str_homestory_chat_30223011 = "그러면 부담이 너무 크지 않나요?\n여기 오셨을 때라도 푹 쉬시면 좋을 것 같아요.",
  str_homestory_chat_30223012 = "아니다. 책임이라는 갑옷은 나를 지키고,\n나를 날카롭게 하여 안심하고 도전에 응하도록 하지.",
  str_homestory_chat_30223013 = "그래도... 조금은 마음을 느슨하게 가지셔도 될 거 같은데...",
  str_homestory_chat_30224001 = "며칠 전에 읽은 책에 대해 생각 중이었어요.",
  str_homestory_chat_30224002 = "어떤 책이었지?",
  str_homestory_chat_30224003 = "추리 소설이요.",
  str_homestory_chat_30224004 = "요즘 움브라톤에서 굉장히 유행 중인 소설인데,\n흡인력도 있고 인물의 감정 묘사 부분도...",
  str_homestory_chat_30224005 = "소설인가... 소설은 쉬어 가는 용도로는 괜찮겠지만,\n그 속에서 얻을 수 있는 지식은 매우 한정적이다.",
  str_homestory_chat_30224006 = "진정으로 독서를 원한다면,\n역사에 대한 서적을 읽는 편이 좋다.",
  str_homestory_chat_30224007 = "역사책이요.",
  str_homestory_chat_30224008 = "좋은 선택이로군.",
  str_homestory_chat_30224009 = "성주님도 역사책을 좋아하시나 봐요?",
  str_homestory_chat_30224010 = "그렇다.",
  str_homestory_chat_30224011 = "역사를 거울로 삼으면, 흥함과 쇠함을 알고,\n심지어는 앞으로의 일도 예측할 수 있다.",
  str_homestory_chat_30224012 = "미래를 예측한다는 것은 다소 과장된 표현이긴 하나,\n적어도 다양한 지식을 습득할 수 있는 것은 사실이다.",
  str_homestory_chat_30224013 = "인위적으로 만들어진 거짓된 이야기보다는\n훨씬 더 값진 내용들이지.",
  str_homestory_chat_30224014 = "알겠어요. 그럼 저도 그런 책을 많이 읽을게요.",
  str_homestory_chat_30225001 = "맞아요.",
  str_homestory_chat_30225002 = "「잠시도 멈춰 서지 말고, 밤낮으로 파종하라.」",
  str_homestory_chat_30225003 = "그게 무슨 뜻이죠?",
  str_homestory_chat_30225004 = "백야성의 속담이다. 언제나 근면해야 한다는 뜻이지.\n그대는 이미 그러하니, 계속 그 모습을 잃지 말도록.",
  str_homestory_chat_30225005 = "그럴게요.",
  str_homestory_chat_30225006 = "그대에게 작위를 내리는 것을 고려해 보아야겠군.\n백야성에 그대와 같은 귀족이 많아진다면 좋은 일이지.",
  str_homestory_chat_30225007 = "진짜요?!",
  str_homestory_chat_30225008 = "물론 농담이다.",
  str_homestory_chat_30225009 = "아... 그렇구나... 알겠어요.",
  str_homestory_chat_30199999 = "너도 혼자니?",
  str_homestory_chat_30121001 = "응.",
  str_homestory_chat_30121002 = "너, 너도 혼자 있는 걸 좋아하는구나...",
  str_homestory_chat_30121003 = "아니, 그렇진 않아. 그냥 산책하고 있던 거야.\n날씨가 좋기도 하고, 딱히 할 일도 없었거든.",
  str_homestory_chat_30121004 = "넌 쉴 때 주로 산책을 해?\n산책하는 걸 좋아하는 것 같은데.",
  str_homestory_chat_30121005 = "아니면 혼자서 시간을 보낼 때 쓰는 다른 방법도 있어?",
  str_homestory_chat_30121006 = "음... 산책은 여러 방법 중 한 가지일 뿐이야.\n가끔은 친구랑 만나서 이야기를 나누는 것도 좋아해.",
  str_homestory_chat_30121007 = "그, 그렇구나...",
  str_homestory_chat_30122001 = "아니.",
  str_homestory_chat_30122002 = "어? 그럼 다른 사람은 어디 있어?",
  str_homestory_chat_30122003 = "그, 그런 뜻이 아니라... 얘기할 사람을 찾고 있었는데,\n마침 널 만났으니까 혼자가 아니라는 뜻이었어...",
  str_homestory_chat_30122004 = "넌 사람들이랑 얘기하는 걸 정말 좋아하는구나?",
  str_homestory_chat_30122005 = "응, 맞아.",
  str_homestory_chat_30122006 = "가끔은 친구랑 얘기하고 싶단 생각이 들 때가 있어...\n미아 넌 안 그래?",
  str_homestory_chat_30122007 = "나도 그래.",
  str_homestory_chat_30122008 = "음... 넌 혼자 있는 것만 좋아하는 줄 알았어.",
  str_homestory_chat_30122009 = "그건 맞아. 하지만 그래도 가끔은 다른 사람하고\n이야기를 조금 나누고 싶어질 때도 있어.",
  str_homestory_chat_30122010 = "가끔은 그래.",
  str_homestory_chat_30122011 = "어라? 난 네가 사람들이랑 얘기하는 걸\n굉장히 좋아하는 줄로만 알았어.",
  str_homestory_chat_30122012 = "아닐 때도 있어. 다른 사람들이랑 얘기하는 것도 좋지만,\n가끔은 혼자 조용히 있고 싶기도 해.",
  str_homestory_chat_30122013 = "그러니까... 기분에 따라 바뀐다는 거지. 미아 넌 어때?",
  str_homestory_chat_30122014 = "난 대부분 혼자 있는 걸 좋아해. 하지만 가끔은 너처럼\n다른 사람이랑 이아기가 하고 싶어지기도 해.",
  str_homestory_chat_30122015 = "특히 그 아이하고 말이야...\n항상 이런 생각을 해. 언젠가 그 아이를 만나게 된다면,\n그 아이하고 더 많은 이야기를 나누고 싶어...",
  str_homestory_chat_30122016 = "그렇게 될 수 있길 바랄게...",
  str_homestory_chat_30123001 = "뭐 하고 있었어?",
  str_homestory_chat_30123002 = "여기서 어떻게 하면 「기사의 홍차」를\n만들 수 있을지 생각 중이었어.",
  str_homestory_chat_30123003 = "「기사의 홍차」?",
  str_homestory_chat_30123004 = "백야성에서 많은 사람들이 좋아하는 음료 중 하나야.",
  str_homestory_chat_30123005 = "들어 본 적 있어.\n근데 재료가 구하기 좀 까다로웠던 거 같은데.",
  str_homestory_chat_30123006 = "맞아. 만들려면 수입산 찻잎이 필요하거든...",
  str_homestory_chat_30123007 = "그리고 좋은 다구를 사용해서 세심하게 맛을 내야 해.",
  str_homestory_chat_30123008 = "맛있는 「기사의 홍차」를 제대로 만들고 싶다면,\n오후 내내 공을 들여야 할 수도 있어.",
  str_homestory_chat_30123009 = "그렇게 오래 걸려?!",
  str_homestory_chat_30123010 = "그렇지. 아무래도 「애프터눈 티」니까.",
  str_homestory_chat_30123011 = "그럼 오전부터 만들기 시작하면,\n점심쯤이면 마실 수 있는 거 아니야?",
  str_homestory_chat_30123012 = "그럼 「런치 티」가 되려나?\n아니지, 아예 더 일찍부터 만들면 「모닝 티」가 되겠네?",
  str_homestory_chat_30123013 = "그것까진 생각해 본 적 없었는데...",
  str_homestory_chat_30124001 = "미아, 넌 어떤 놀이를 좋아해?",
  str_homestory_chat_30124002 = "혼자서 할 수 있는 놀이가 좋아...",
  str_homestory_chat_30124003 = "혼자서 할 수 있는 거라면... 혼자 체스? 아니면 산책?",
  str_homestory_chat_30124004 = "가끔 혼자 포커 같은 걸 하곤 해. 넌?\n혼자 있을 땐 뭘 하면서 시간을 보내?",
  str_homestory_chat_30124005 = "난 낚시를 자주 해.",
  str_homestory_chat_30124006 = "좋은 취미구나. 마음이 많이 차분해진다고 들었어.",
  str_homestory_chat_30124007 = "들었다니? 아직 낚시해 본 적 없어?",
  str_homestory_chat_30124008 = "음... 별로 해 본 적이 없어. 밖에 나갈 기회도 거의 없었거든.",
  str_homestory_chat_30124009 = "여기선 해 볼 수 있으니까 꼭 도전해 봐!",
  str_homestory_chat_30124010 = "나도 카드게임?",
  str_homestory_chat_30124011 = "참, 카드게임 얘기가 나와서 말인데,\n아까 말했던 혼자 하는 포커는 어떻게 하는 거야?",
  str_homestory_chat_30124012 = "규칙이... 조금 복잡한 편이야.\n나중에 기회가 되면 가르쳐 줄게.",
  str_homestory_chat_30124013 = "알겠어!",
  str_homestory_chat_30125001 = "여기 생활은 어때?",
  str_homestory_chat_30125002 = "굉장히 좋아.\n특히 낮에 밖에 나와도 된다는 점이 아주 마음에 들어.",
  str_homestory_chat_30125003 = "낮에 밖에 나와도 된다고?",
  str_homestory_chat_30125004 = "응. 평소엔 아무래도 내 신분 때문에... 으음...",
  str_homestory_chat_30125005 = "무슨 말인지 알겠어.",
  str_homestory_chat_30125006 = "그치만 여기랑 움브라톤은 또 다른 느낌이지?",
  str_homestory_chat_30125007 = "응... 여긴 거기하고는 다르게 거리도 없고,\n상점들도 없으니까.",
  str_homestory_chat_30125008 = "혹시... 조금 따분하진 않아?",
  str_homestory_chat_30125009 = "저, 전혀 안 그래!",
  str_homestory_chat_30125010 = "움브라톤보다 수수한 편인 건 맞지만,\n아름다운 자연을 즐길 수 있는 것도 정말 좋거든.",
  str_homestory_chat_30125011 = "벌레와 새들이 지저귀는 소리도 듣고,\n따뜻한 태양 아래서 반짝이는 시냇물 감상도 하고...",
  str_homestory_chat_30125012 = "어째 엎드려 절받는 느낌인데...\n다음엔 츄브들한테 상품 종류를 좀 늘려 보라고 해 둘게.",
  str_homestory_chat_30125013 = "희망의 연못하고 바람의 탑,\n그리고 전시관도 정말 재미있다고 생각해...",
  str_homestory_chat_30125014 = "저기, 그, 알겠으니까 괜찮아...",
  str_homestory_chat_30399999 = "운세 한 번 보시겠어요?",
  str_homestory_chat_30321001 = "궁금한 게 있긴 해...",
  str_homestory_chat_30321002 = "앗?! 드디어 실력을 발휘할 수 있겠네요!\n그래서 어떤 게 궁금하시죠?",
  str_homestory_chat_30321003 = "사업운.",
  str_homestory_chat_30321004 = "재물운.",
  str_homestory_chat_30321005 = "연애운.",
  str_homestory_chat_30321006 = "다 정하셨죠? 그럼 시작할게요!",
  str_homestory_chat_30321007 = "잠깐만! 나 실은 점 보려던 거 아니야...",
  str_homestory_chat_30321008 = "그럼 뭘 하고 싶은데요? 벌써 준비도 다 했다구요.",
  str_homestory_chat_30321009 = "네가 말하는 운세점 말이야, 그거 진짜 맞는 거야?\n그걸 물어보고 싶었어.",
  str_homestory_chat_30321010 = "대체 지금 무슨 말을 하는 거예요?\n전 아주 어렸을 때부터 점술을 익혀 왔다구요!",
  str_homestory_chat_30321011 = "그, 그럼 미래를 예측할 수도 있단 거잖아?\n뭐든 다 점부터 치고 그 결과대로 하면 되는 거 아냐?",
  str_homestory_chat_30321012 = "딱히 그렇진 않아요. 우선, 점이란 건 때와 장소가 맞고,\n영감도 있어야 해요.",
  str_homestory_chat_30321013 = "그리고 가장 중요한 건 운이에요!\n점을 쳤는데 아무 결과가 없을 때도 많거든요!",
  str_homestory_chat_30321014 = "그러니까 점도 실패할 때가 있단 얘기예요!",
  str_homestory_chat_30321015 = "그렇구나.",
  str_homestory_chat_30323001 = "지금은 딱히 안 봐도 될 거 같아...",
  str_homestory_chat_30323002 = "어라? 방금까지만 해도 영감이 왔는데,\n그 얘길 들으니까 영감이 순식간에 사라져 버렸어요.",
  str_homestory_chat_30323003 = "아... 미안.",
  str_homestory_chat_30323004 = "어쩔 수 없네요.\n「가족티」 디자인이나 마저 생각해 봐야겠어요.",
  str_homestory_chat_30323005 = "「가족티」?",
  str_homestory_chat_30323006 = "위스퍼한테 줄 거예요.\n저랑 둘이 똑같은 옷을 입고 있어야 느낌이 살잖아요.",
  str_homestory_chat_30323007 = "위, 위스퍼도 옷을 입어야 하는 거야?",
  str_homestory_chat_30323008 = "물론이죠. 날이 너무 쌀쌀하거나 추우면,\n위스퍼도 견디기 힘들 테니까요.",
  str_homestory_chat_30323009 = "하지만 옷을 입으면 체온도 유지되고,\n저랑 이미지도 맞출 수 있어요!",
  str_homestory_chat_30323010 = "대단한 발상이네!\n근데 위스퍼한테 입힐 옷을 대체 어디서...",
  str_homestory_chat_30323011 = "그거야 제가 디자인해서 제가 만들면 되죠!",
  str_homestory_chat_30322001 = "이야기 들려주는 걸 좋아한다면서?",
  str_homestory_chat_30322002 = "맞아요! 특히 점을 볼 땐 더 그렇죠!",
  str_homestory_chat_30322003 = "점 보는 데 이야기도 들려줘야 돼?",
  str_homestory_chat_30322004 = "상대의 주의력을 사로잡아야, 그 사람이 제 점에\n완전히 집중할 수 있거든요.",
  str_homestory_chat_30322005 = "그래야 점을 보는 데 실패하더라도,\n상대가 손해 봤단 느낌을 안 받아요!",
  str_homestory_chat_30322006 = "그, 그거 뭔가 좀... 사기 같은데...?",
  str_homestory_chat_30322007 = "절대 아니에요!\n흥미진진한 이야기가 얼마나 가치 있는 건데요!",
  str_homestory_chat_30322008 = "그래서 전 자주 루이스랑 어울려 놀고, 어쩔 수 없이\n루이스를 데리고 여기저기 돌아다니기도 했어요!",
  str_homestory_chat_30322009 = "루이스?",
  str_homestory_chat_30322010 = "네, 루이스도 북방 사람이잖아요.\n그리고 이야기를 엄청 재미있게 잘하구요.",
  str_homestory_chat_30322011 = "음, 왠지 둘이 움브라톤에 가서 소설가로\n데뷔해도 될 거 같은데...",
  str_homestory_chat_30324001 = "돌을 찾고 있다고?",
  str_homestory_chat_30324002 = "네, 어디 가면 예쁘게 생긴 돌이 있는지 아세요?",
  str_homestory_chat_30324003 = "강가에 가면 있을 거야.",
  str_homestory_chat_30324004 = "숲속에 가면 많이 있을걸.",
  str_homestory_chat_30324005 = "알려줘서 고마워요!",
  str_homestory_chat_30324006 = "근데 예쁘게 생긴 돌을 왜 찾는 거야? 점 볼 때 쓰려고?",
  str_homestory_chat_30324007 = "아니요, 그게 아니라 액세서리 용도로 쓸 거예요.",
  str_homestory_chat_30324008 = "츄브들을 봤는데, 매일 똑같이 하얀색 옷만 입고\n돌아다니니까 너무 밋밋해서요.",
  str_homestory_chat_30324009 = "지금도 수수한 멋이 있긴 하지만,\n그래도 츄브들한테 알록달록한 돌로 만든\n목걸이를 걸어 주면 훨씬 좋을 거 같지 않나요?",
  str_homestory_chat_30324010 = "잠깐! 츄브들한테 어떻게 생각하냐고\n아직 물어보지도 않았잖아?!",
  str_homestory_chat_30324011 = "괜찮아요! 분명히 좋아할 거예요!",
  str_homestory_chat_30324012 = "그, 그래도 신중하게 행동하는 게 좋을 거 같아...",
  str_homestory_chat_30499999 = "또 만났네. 넌 정말이지 참 성실하구나.",
  str_homestory_chat_30421001 = "아, 마침 순찰하는 중이었어요.",
  str_homestory_chat_30421002 = "넌 많은 곳을 여행해 봤다고 들었어.\n혹시 은거하기 좋은 곳도 있었니?",
  str_homestory_chat_30421003 = "은거요? 혼자서도 잘 지낼 수 있는 그런 곳 말씀하시는 거죠?",
  str_homestory_chat_30421004 = "조금 달라. 사람들의 눈에 잘 띄진 않지만,\n근처에 이웃들은 있는 그런 곳 말이야.",
  str_homestory_chat_30421005 = "음... 잠깐 생각 좀 해 볼게요.",
  str_homestory_chat_30421006 = "움브라톤은 어떨까요?",
  str_homestory_chat_30421007 = "「나무를 숨기려면 숲에 숨겨야 한다」는 말도 있잖아요.",
  str_homestory_chat_30421008 = "움브라톤은 번화한 곳이니까 사람도 많을 거고,\n당연히 별별 사람이 다 있을 테니까\n조슈아 씨도 그렇게 눈에 띄지 않을 거예요.",
  str_homestory_chat_30421009 = "한 번 고려해 볼 가치는 있을 것 같네.",
  str_homestory_chat_30421010 = "북방은 어떨까요?",
  str_homestory_chat_30421011 = "세계의 등마루 밑 말이니...",
  str_homestory_chat_30421012 = "외진 곳에 있고 한적하기도 한 좋은 곳이네.",
  str_homestory_chat_30421013 = "땅은 넓은데 인구는 적은 편에 약간은 폐쇄적이기도 해서,\n북적거림이랑은 거리가 먼 곳이라고 생각해요.",
  str_homestory_chat_30421014 = "그런 점들을 대가로 치르고\n안전함과 은밀함을 얻은 거겠지...",
  str_homestory_chat_30421015 = "레디젤 사막은 어떨까요?",
  str_homestory_chat_30421016 = "어머? 거긴 사방팔방을 다니는 녀석들이 있지 않니?",
  str_homestory_chat_30421017 = "그렇긴 하지만 레디젤 렌치 중엔 원래는 다른 세력 출신이었던\n사람들도 많이 있다고 들었어요.",
  str_homestory_chat_30421018 = "근데 일단 레디젤 렌치의 일원이 돼서 그 분위기에 익숙해지면,\n세상에 둘도 없는 좋은 동료가 되는 것 같아요.",
  str_homestory_chat_30421019 = "그건 멋지구나.",
  str_homestory_chat_30421020 = "작은 마을은 어떨까요?",
  str_homestory_chat_30421021 = "그런 곳은 흔하잖니.\n그래도 마지막 선택지로 고려는 해 볼게.",
  str_homestory_chat_30421022 = "하긴 그렇네요.",
  str_homestory_chat_30422001 = "조슈아 씨는 잘 웃으시네요.",
  str_homestory_chat_30422002 = "난 이곳이 마음에 들거든.",
  str_homestory_chat_30422003 = "그렇게 말씀해 주셔서 감사해요.",
  str_homestory_chat_30422004 = "경치가 특별히 뛰어난 건 아니지만...\n마음이 편안해지는 느낌이 들어.",
  str_homestory_chat_30422005 = "이런 느낌이 들게 하는 곳은 매우 드문데 말이야.",
  str_homestory_chat_30422006 = "좀 외진 곳에 있어서 그런 걸까요?",
  str_homestory_chat_30422007 = "그게 아니라 전체적인 분위기 때문이야.\n여기 머무는 다른 사람들의 상태를 보면 알 수 있어.",
  str_homestory_chat_30422008 = "모두의 얼굴엔 웃음꽃이 피어 있고,\n츄브들은 봄바람처럼 산들산들...",
  str_homestory_chat_30422009 = "산들산들이라니... 츄브들이 또 게으름을 피우고 있었던 건가요?",
  str_homestory_chat_30422010 = "얘도 참, 요점을 잘못 짚었잖니.",
  str_homestory_chat_30423001 = "일찍 일어나셨네요.",
  str_homestory_chat_30423002 = "잠자리를 정리 정돈할 시간이 필요하거든.",
  str_homestory_chat_30423003 = "잠자리를요? 조슈아 씨가 직접 하시는 거예요?",
  str_homestory_chat_30423004 = "맞아.",
  str_homestory_chat_30423005 = "그런 집안일까지 직접 하실 줄은 몰랐어요.",
  str_homestory_chat_30423006 = "내 과거의 신분 때문에 그렇게 생각하는 거니?",
  str_homestory_chat_30423007 = "으음...",
  str_homestory_chat_30423008 = "괜찮아. 난 우리 아이들의 잠자리를\n정돈해 주는 걸 좋아했거든.",
  str_homestory_chat_30423009 = "가끔은 아침에 깨서 딸아이들이 침대에서 곤히 자는\n모습을 보고도 무심코 정리부터 할 정도였다니까.",
  str_homestory_chat_30423010 = "내가 정리를 시작하면 어쩔 수 없이 일어나야 하니까,\n아이들도 투덜거리곤 했단다.",
  str_homestory_chat_30423011 = "어떤 모습일지 상상이 되네요.",
  str_homestory_chat_30423012 = "하지만 그것도 필요한 교육이야. 늦잠은 좋지 않아.\n이건 너도 마찬가지란다~",
  str_homestory_chat_30423013 = "아? 그, 그렇죠...",
  str_homestory_chat_30424001 = "음악이요?",
  str_homestory_chat_30424002 = "그래, 넌 어떤 음악을 좋아하니?",
  str_homestory_chat_30424003 = "경쾌하면서도 부드러운 느낌을 주는 곡이요.",
  str_homestory_chat_30424004 = "저번에 백야성에 갔을 때 그런 곡을 몇 개 듣었는데,\n정말 좋더라고요.",
  str_homestory_chat_30424005 = "고상하고 잔잔한 느낌이 드는 곡이요.",
  str_homestory_chat_30424006 = "그런 경음악도 확실히 나쁘지 않지.",
  str_homestory_chat_30424007 = "강렬함이 느껴지는 곡이요.",
  str_homestory_chat_30424008 = "소음 같은 그런 음악 말이구나...",
  str_homestory_chat_30424009 = "나름대로 멜로디를 가지고 있어서 소음이라고 할 정돈 아니에요.",
  str_homestory_chat_30424010 = "그러니...",
  str_homestory_chat_30424011 = "그나저나 여긴 음악이 없는 것 같네.\n조금 적막하진 않니?",
  str_homestory_chat_30424012 = "주변에서 들리는 자연의 소리만 해도 충분해요.\n이 소리들도 일종의 음악이라고 할 수 있으니까요.",
  str_homestory_chat_30424013 = "격식있는 음악을 감상하고 싶으신 거라면,\n그런 음악을 전문적으로 다루는 곳이 좋을 것 같아요.",
  str_homestory_chat_30424014 = "하긴 그렇네.\n여기서는 이곳만의 음악을 즐기는 게 맞겠지.",
  str_homestory_chat_30425001 = "제가 싫어하는 거요?",
  str_homestory_chat_30425002 = "지금은 딱히 생각나는 게 없는 것 같아요. 갑자기 그건 왜요?",
  str_homestory_chat_30425003 = "며칠 전에 비가 내려서 그런지,\n오늘 아침에 보니까 숙소 안이 조금 눅눅했지 뭐니...",
  str_homestory_chat_30425004 = "그래서 전에 잠깐 움브라톤에 머물던\n때가 생각났거든.",
  str_homestory_chat_30425005 = "움브라톤도... 마침 비가 자주 왔었던 모양이네요?",
  str_homestory_chat_30425006 = "그래, 그 무렵은 장마철이라서 잠자리를 아무리\n정돈해도 개운한 느낌이 들지 않았어...",
  str_homestory_chat_30425007 = "저도 들어본 적 있는 것 같아요.\n특히 그 몇 달 동안 비가 많이 온다고 말이죠...",
  str_homestory_chat_30425008 = "그치만 헤븐즈 가든에선 그럴 일이 거의 없을 거예요.",
  str_homestory_chat_30425009 = "덕분에 여기 있으면 마음이 편안해지는 것 같아.",
  str_homestory_chat_30599999 = "뭐 하고 계신가요?",
  str_homestory_chat_30521001 = "향수를 사려고 하신다면서요?",
  str_homestory_chat_30521002 = "네. 헤븐즈 가든의 공기가 맑고 깨끗한 건 맞지만,\n향수로 포인트를 더해 봐도 좋을 것 같아서요.",
  str_homestory_chat_30521003 = "왜 향수로 포인트를 더하려고 하는 건데요?",
  str_homestory_chat_30521004 = "실은 제가 아니라 츄브들에게 사용하려는 거예요.\n안내자의 조수 역할로 무척 잘 어울리는 것 같거든요.",
  str_homestory_chat_30521005 = "문제는 누가 누군지 구분이 잘 안된다는 점이지만,\n향수를 뿌려 준다면 그 문제도 해결될 거예요.",
  str_homestory_chat_30521006 = "그, 그냥 누가 누군지 구분하려고 향수를 뿌리는 건가요?\n그러기엔 향수가 좀 아깝지 않을까요?",
  str_homestory_chat_30521007 = "그렇긴 하네요... 그럼 펜으로 번호를 쓰는 건 어때요?\n「1번」, 「2번」 이런 식으로 말이에요.",
  str_homestory_chat_30521008 = "그것도... 역시 아닌 것 같아요.",
  str_homestory_chat_30522001 = "음료 전문점이요?",
  str_homestory_chat_30522002 = "헤븐즈 가든에 음료 전문점은 없어요.",
  str_homestory_chat_30522003 = "아, 그게 아니라 제가 음료 전문점을 열고 싶거든요.\n그래서 조사를 진행하고 있어요.",
  str_homestory_chat_30522004 = "뭘 조사하는데요?",
  str_homestory_chat_30522005 = "기호 음료에 대해서요.\n예를 들면, 당신은 어떤 음료를 선호하시나요?",
  str_homestory_chat_30522006 = "우유요.",
  str_homestory_chat_30522007 = "음... 건강에 아주 유익할 것 같은 취향이네요.",
  str_homestory_chat_30522008 = "소다요.",
  str_homestory_chat_30522009 = "어머? 취향이 독특하시네요.",
  str_homestory_chat_30522010 = "커피요.",
  str_homestory_chat_30522011 = "커피도 나쁘지 않죠.",
  str_homestory_chat_30522012 = "홍차요.",
  str_homestory_chat_30522013 = "훌륭한 취향을 가지고 계시네요!",
  str_homestory_chat_30522014 = "그러고 보면 저 말고 다른 사람들 의견도 물어봤겠네요?",
  str_homestory_chat_30522015 = "진행 상황은 어때요?",
  str_homestory_chat_30522016 = "아직도 하는 중이에요. 게다가 시간대별 구분도 하고,\n기존 응답자도 일정 기간 뒤에 다시 확인해야 해요.",
  str_homestory_chat_30522017 = "엄청 복잡하네요...",
  str_homestory_chat_30522018 = "복잡하긴 해도 이렇게 해야 더 자세한 데이터를 얻어\n음료 전문점의 대표 메뉴를 정할 수 있을 테니까요.",
  str_homestory_chat_30522019 = "아무래도... 개업하긴 어려울 것 같은데요...",
  str_homestory_chat_30523001 = "무도회요?",
  str_homestory_chat_30523002 = "네, 며칠 전부터 갑자기 뭘 해도\n의욕이 잘 안 나더라고요.",
  str_homestory_chat_30523003 = "왜 그런가 가만히 생각해 보니,\n아무래도 무도회에 참석하지 않은 지\n너무 오래돼서 그런 것 같아요.",
  str_homestory_chat_30523004 = "그치만 헤븐즈 가든엔 딱히 무도회를 열 만한 곳이 없는데요...",
  str_homestory_chat_30523005 = "그렇다면 이참에 무도회를 한 번 열어 보죠.\n무도회장을 준비하는 게 그렇게 어렵진 않으니까요.",
  str_homestory_chat_30523006 = "광장, 테이블, 의자, 파티용 장식 끈과\n가랜드 정도만 있으면 돼요.",
  str_homestory_chat_30523007 = "악단을 섭외하는 게 조금 번거로울 수 있긴 하지만,\n도우미들을 구하면 어떻게든 되겠죠.",
  str_homestory_chat_30523008 = "츄브들에게... 도우미 역할을 맡겨 보는 건 어때요?",
  str_homestory_chat_30523009 = "잠깐만요, 츄브들은 악기를 다룰 줄 몰라요.",
  str_homestory_chat_30523010 = "그렇다면 이제부터라도 훈련을 시작해야겠네요.",
  str_homestory_chat_30523011 = "특별 훈련... 단기 속성 10일 완성 프로젝트면 되겠죠.",
  str_homestory_chat_30523012 = "여, 열흘 만에 악기를 마스터시키겠단 거예요?!",
  str_homestory_chat_30523013 = "너무 긴가요? 그렇다면 3일로 줄이도록 할게요.",
  str_homestory_chat_30523014 = "그냥 백야성에서 열리는 무도회에 가는 편이 낫겠어요...",
  str_homestory_chat_30524001 = "안내자요?",
  str_homestory_chat_30524002 = "네, 헤븐즈 가든에 처음 왔을 때부터 쭉 이곳은 참\n드넓은 곳이라고 생각해 왔어요.",
  str_homestory_chat_30524003 = "그러니 새로 온 동료가 길을 잃는 불상사를 막으려면\n반드시 안내자를 한 명 둬야 한다고 생각해요.",
  str_homestory_chat_30524004 = "으음...",
  str_homestory_chat_30524005 = "제 의견에 동의하시는 거죠?",
  str_homestory_chat_30524006 = "확실히 일리 있는 의견이에요.",
  str_homestory_chat_30524007 = "여긴 굉장히 넓은 편이니까, 안내자가 있다면 여러모로 유용할 테고요.",
  str_homestory_chat_30524008 = "조금만 더 생각해 볼게요.",
  str_homestory_chat_30524009 = "근데 그럼 누구한테 안내자를 맡기면 좋을까요?",
  str_homestory_chat_30524010 = "당연히 츄브들이죠!",
  str_homestory_chat_30524011 = "어? 츄브들이요?",
  str_homestory_chat_30524012 = "츄브들은 항상 여기 있고, 여길 잘 알고 좋아하잖아요.\n그러니까 가장 적임자죠.",
  str_homestory_chat_30524013 = "그런...가요... 음, 생각할 시간을 조금만 더 주세요.",
  str_homestory_chat_30699999 = "추천해 줄 사업 프로젝트 있어?",
  str_homestory_chat_30621001 = "놀이공원 만들기?",
  str_homestory_chat_30621002 = "아이디어는 꽤 좋지만, 여기는 아주 외진 편인데 사람들을 끌어모으려면 어떻게 해지? 차라리 여기 주민을 타깃으로 하는 게 나을까?",
  str_homestory_chat_30621003 = "츄브?",
  str_homestory_chat_30621004 = "그래! 수가 많지는 않아도, 미래를 생각해 본다면...",
  str_homestory_chat_30621005 = "츄브들은 출생률이 어떻게 돼?\n증식 속도는 빨라? 아이는 어떻게 낳아?",
  str_homestory_chat_30621006 = "오로리안하고... 비슷할걸?",
  str_homestory_chat_30621007 = "말하는 걸 들어 보니 너도 확실하게 모르는 모양이네.",
  str_homestory_chat_30621008 = "아이는 못 낳는 것 같아.",
  str_homestory_chat_30621009 = "진짜?",
  str_homestory_chat_30621010 = "그러고 보니까 츄브들이 태어나는 모습은 본 적이 없어.\n왠지 그냥 돌 틈에서 튀어나왔던 것 같아.",
  str_homestory_chat_30621011 = "재미있는 종족이네.\n근데 그럼 츄브들로 돈을 벌 수는 없겠어.",
  str_homestory_chat_30621012 = "잠깐만! 발상을 전환하면... 떠올랐어! 새 아이디어가!",
  str_homestory_chat_30621013 = "뭔데?",
  str_homestory_chat_30621014 = "수가 적다는 건 희귀하다는 거야. 희귀하다는 건 가치가 높다는 뜻이고, 가치가 높으면 보고 싶어 하는 사람들이 있을 거고, 보려면 돈을 내야 해!",
  str_homestory_chat_30621015 = "너 설마...",
  str_homestory_chat_30621016 = "츄브들을 대 스타로 만드는 거야!\n그리고 아스트라 대륙 곳곳에서 공연을 여는 거지!",
  str_homestory_chat_30621017 = "제목은 《재현! 신비로운 종족의 세계 여행!》, 어때?",
  str_homestory_chat_30621018 = "그런 생각은 하루라도 빨리 그만두는 게 좋겠어.",
  str_homestory_chat_30621019 = "왜?",
  str_homestory_chat_30621020 = "그렇게 하면 츄브들이 전시품이 돼 버리잖아...",
  str_homestory_chat_30621021 = "생각해 볼게.",
  str_homestory_chat_30621022 = "「대 스타 츄브」라니, 재미있는 제안이네.\n근데 일단 츄브들한테 의견을 물어봐야 할 것 같아.",
  str_homestory_chat_30621023 = "문제없어! 그럼 좋은 소식 기대할게!",
  str_homestory_chat_30622001 = "그냥 헤븐즈 가든 얘기나 하자.",
  str_homestory_chat_30622002 = "마침 너한테 헤븐즈 가든에 있는 건물들에 대해서\n물어보고 싶었어.",
  str_homestory_chat_30622003 = "건물에 대해 뭘 물어보고 싶은데?",
  str_homestory_chat_30622004 = "토지 개발에 대한 거.\n여기는 자연 느낌이 너무 진해서 불편하거든. ",
  str_homestory_chat_30622005 = "식당가도 없고, 상점가도 없고, 놀 만한 곳도 없으니까\n관광객이 올 리가 없잖아.",
  str_homestory_chat_30622006 = "관광객을 끌어모으고 싶은 생각은 없는데...\n그냥 동료들이 편하게 지내 주면 그걸로 돼.",
  str_homestory_chat_30622007 = "그러면 안 되지! 생각해 본 적 있어?\n지금은 그럭저럭 버티고 있지만, 앞으로는 어떨까?",
  str_homestory_chat_30622008 = "네 수입이 없어져도 여길 계속 유지할 수 있을까?",
  str_homestory_chat_30622009 = "미래를 걱정하느니, 차라리 현재에 집중해야지!\n나한테 헤븐즈 가든의 경영을 맡겨 보는 건 어때?",
  str_homestory_chat_30622010 = "뭘 하려는 거야?",
  str_homestory_chat_30622011 = "나한테 팔아! 내가 헤븐즈 가든을 이 대륙 최고의\n상업 구역으로 만들어 줄게!",
  str_homestory_chat_30622012 = "아무래도 지금 이 상태를 유지하는 게 더 좋을 것 같아.",
  str_homestory_chat_30623001 = "네 헤어스타일 얘기는 어떨까?",
  str_homestory_chat_30623002 = "내 헤어스타일?\n평범해서 딱히 이야기할 거리가 없지 않아?",
  str_homestory_chat_30623003 = "머리 그렇게 만들려면 엄청 번거롭지 않아?",
  str_homestory_chat_30623004 = "그냥 미용실에 가면 돼.\n한 번에 몇천 나이티움밖에 안 들거든.",
  str_homestory_chat_30623005 = "몇천?! 뭘 하길래 그렇게 돈이 많이 들어?!",
  str_homestory_chat_30623006 = "커트도 하고, 케어도 받고, 스타일링 같은 것도 하지.\n아, 말하다 보니까 마침 좋은 계획이 떠올랐어.",
  str_homestory_chat_30623007 = "뭔데?",
  str_homestory_chat_30623008 = "여기에 미용실을 하나 열면 어떨까?\n네 동료들한테 수요는 좀 있을 것 같은데.",
  str_homestory_chat_30623009 = "규모가 작고, 스태프가 몇 명 없어도, 설비만 잘 갖추면 될 거야. 재료는 움브라톤에서 들여오면 되고.",
  str_homestory_chat_30623010 = "내가 아는 살롱 점장이 마침 아는 거래처가 있으니까...",
  str_homestory_chat_30623011 = "사실은 네가 여기에서 헤어 스타일링을 받고 싶어서\n그러는 거 아니야?",
  str_homestory_chat_30623012 = "맞아! 내가 하는 가게라면 내가 가면 당연히 무료잖아.\n너랑 네 지인들은 20% 할인해 줄게!",
  str_homestory_chat_30623013 = "고작 20% 할인이라니...",
  str_homestory_chat_30623014 = "그럼 동의한 거다? 내일 바로 연락해야겠어!",
  str_homestory_chat_30623015 = "잠깐만! 그냥 생각만 해 보겠다는 거야!",
  str_homestory_chat_30624001 = "요즘 츄브들한테 눈독을 들이고 있다면서?",
  str_homestory_chat_30624002 = "맞아, 나한테 츄브들을 양도해 주는 건 어때?",
  str_homestory_chat_30624003 = "츄브들은 상품이 아니야!",
  str_homestory_chat_30624004 = "안 돼!",
  str_homestory_chat_30624005 = "알겠어. 츄브들이랑 계약을 맺은 거지?\n좋아, 그럼 가격을 제시해 줘.",
  str_homestory_chat_30624006 = "위약금, 양도금, 계약금, 뭐든 다 협상 가능해.",
  str_homestory_chat_30624007 = "그게 다 뭐야...\n근데 왜 갑자기 츄브들의 도움을 받으려는 거야?",
  str_homestory_chat_30624008 = "요즘 사업을 하나 크게 해 보려고 하는데,\n유능한 직원들을 좀 모아야 할 것 같아서.",
  str_homestory_chat_30624009 = "유능하다고? 츄브들이 네가 원하는 만큼 잘할 수 있을까?",
  str_homestory_chat_30624010 = "물론이지! 학자 츄브랑 상인 츄브만 봐도 딱 좋은걸!",
  str_homestory_chat_30624011 = "글 쓸 줄 알지, 계산도 할 줄 알지,\n적게 먹고, 잠도 안 자도 되는 것 같고.",
  str_homestory_chat_30624012 = "이렇게 완벽한 직원이 또 어디 있어!\n아, 걱정 마! 야근 수당은 줄 거니까!",
  str_homestory_chat_30624013 = "평일에는 2배, 주말 및 공휴일에는 3배 지급할게!",
  str_homestory_chat_30624014 = "잠깐만! 츄브들이 안 하려고 할 수도 있잖아!",
  str_homestory_chat_30625001 = "사업 생각은 잠깐 접어두고, 뭐라도 좀 마셔.",
  str_homestory_chat_30625002 = "그렇지만 헤븐즈 가든에는 마실 게 별로 없는걸.\n눈에 들어오는 건 찬물밖에 없잖아.",
  str_homestory_chat_30625003 = "커피나 홍차가 마시고 싶으면,\n따로 움브라톤에서 가져와야 해서 번거롭고.",
  str_homestory_chat_30625004 = "여기에는 지역 특색 음료 같은 건 없는 거야?",
  str_homestory_chat_30625005 = "어떤 환상수의 가지나 잎에선 특별한 향기가 난다던데,\n차로 끓이면 어떨지 모르겠어.",
  str_homestory_chat_30625006 = "환상수... 그런 쪽도 나쁘지 않겠네.",
  str_homestory_chat_30625007 = "설마 또 사업 아이템이 생각난 건 아니지?",
  str_homestory_chat_30625008 = "일단 한번 마셔봐야 사업 가능성을 따져볼 수 있겠어.",
  str_homestory_chat_30625009 = "기왕 네가 추천해 줬으니까, 시간 날 때 조사해 볼게.",
  str_homestory_chat_30799999 = "뭐 해?",
  str_homestory_chat_30721001 = "헤븐즈 가든을 순찰하는 중이에요.",
  str_homestory_chat_30721002 = "동생, 재미있는 일 같은 거 좀 하면 안 돼?",
  str_homestory_chat_30721003 = "저는 이게 재미있는데요.\n세나 씨는 너무 심심해서 당황스러운가 보죠?",
  str_homestory_chat_30721004 = "맞아... 여기 나한테 추천해 줄 만한 활동은 없어?",
  str_homestory_chat_30721005 = "낚시?",
  str_homestory_chat_30721006 = "너무 조용해. 게다가 물고기를 못 낚으면 낭패고.",
  str_homestory_chat_30721007 = "식물 기르기?",
  str_homestory_chat_30721008 = "여기엔 저렇게 이상하고 커다란 나무들밖에 없어?\n너무 구불구불하게 생겨서 마음에 안 들어.",
  str_homestory_chat_30721009 = "전시관 구경은 어때요?",
  str_homestory_chat_30721010 = "볼 게 별로 없을 것 같은데...",
  str_homestory_chat_30721011 = "뭘 얘기해도 다 마음에 안 든다는 거잖아요!\n그럼 그냥 숙소에 가서 푹 주무세요!",
  str_homestory_chat_30721012 = "이봐, 동생, 일단 좀 진정해. 아까 그 얘기는 그냥\n동생이 좀 쉬엄쉬엄했으면 해서 꺼낸 말이었어.",
  str_homestory_chat_30721013 = "매번 볼 때마다 넌 여길 순찰하고 있거나,\n계획 같은 걸 세우고 있으니까 걱정이 돼서 말이지...",
  str_homestory_chat_30721014 = "인생은 「헤븐즈 가든 건설」이라는 선택지만\n있는 게 아니잖아.",
  str_homestory_chat_30721015 = "괜찮아요. 저한테는 순찰하는 게 쉬는 거예요.\n그러니까 산책하고 있는 거라고 생각하면 돼요.",
  str_homestory_chat_30721016 = "그래, 알겠어. 그럼 하던 거 마저 해.",
  str_homestory_chat_30722001 = "쉬면서 돌아다니고 있었어요. 세나 씨는요?",
  str_homestory_chat_30722002 = "마침 널 찾고 있었어.\n시간 있으면 나하고 같이 움브라톤에 가지 않겠어?",
  str_homestory_chat_30722003 = "움브라톤에요? 지금요?",
  str_homestory_chat_30722004 = "고급 레스토랑 VIP 초대권을 두 장 받아서\n친구를 데려갈 수 있거든.",
  str_homestory_chat_30722005 = "갑자기 「세상에 공짜 식사는 없다」는 말이 생각나는데요...",
  str_homestory_chat_30722006 = "설마 저한테 부탁할 일이라도 있는 건가요?",
  str_homestory_chat_30722007 = "다른 사람은 안 불렀어요?",
  str_homestory_chat_30722008 = "아니면... 저 말고는 데려갈 사람이 없는 건가요?",
  str_homestory_chat_30722009 = "나랑 네 우정을 너무 얕보고 있구만!\n그냥 단순히 밥 한 끼 같이 먹자고도 못 해?",
  str_homestory_chat_30722010 = "생각 좀 해 볼게요.",
  str_homestory_chat_30723001 = "마침 환상수를 보러 가려고 했어요.",
  str_homestory_chat_30723002 = "환상수라... 환상수는 굉장히 매력적인 향을\n가지고 있다는 소문을 들었는데 말이지.",
  str_homestory_chat_30723003 = "그걸 활용해서 향수를 만들어 보면 어떨까 싶은데.",
  str_homestory_chat_30723004 = "저 나무들은 겨우겨우 키운 거니까, 마음대로 만지지 마세요.",
  str_homestory_chat_30723005 = "함부로 건드리면 저뿐만이 아니라, 츄브들도 싫어할 거예요.",
  str_homestory_chat_30723006 = "이거 야단났네. 그럼 데이트는 어떻게 하나...",
  str_homestory_chat_30723007 = "데이트?",
  str_homestory_chat_30723008 = "벌써 「특별하고 신기한 향수」를 가져가겠다고\n말해 뒀단 말이야.",
  str_homestory_chat_30723009 = "그건 또 뭐냐구요...",
  str_homestory_chat_30723010 = "환상수의 꽃가루랑 밤이슬을 조합해서,\n그녀를 위해 만든 이 대륙 하나뿐인 특별한 향수라고.",
  str_homestory_chat_30723011 = "진짜 향이 그렇게 좋아요?",
  str_homestory_chat_30723012 = "그건 장담 못 해. 그 향수는 상대방한테 특별함을\n느끼게 해 주는 용도일 뿐이거든.",
  str_homestory_chat_30723013 = "그게 바로 「데이트 기술」이라는 건가요...\n아무리 그래도 환상수에 손을 대는 건 안 돼요.",
  str_homestory_chat_30723014 = "알겠어. 그럼 다른 「기술」을 생각해 보는 수밖에.",
  str_homestory_chat_30724001 = "츄브들한테 무슨 볼일 있으세요?",
  str_homestory_chat_30724002 = "그래, 너하고 츄브들의 관리 문제에 대해\n이야기를 조금 해 보고 싶었어.",
  str_homestory_chat_30724003 = "무슨 일인데요?",
  str_homestory_chat_30724004 = "츄브들은 헤븐즈 가든의 관리인이라기엔\n개인적인 매력이 너무 떨어져.",
  str_homestory_chat_30724005 = "헤븐즈 가든이 잘 유지될 수 있게 해 주고,\n열심히 모두를 도와주면 그걸로 된 거 아니에요?",
  str_homestory_chat_30724006 = "아니지!",
  str_homestory_chat_30724007 = "관리인한테 매력이 없으면, 누가 여기 와서 살겠어?",
  str_homestory_chat_30724008 = "저 츄브들 좀 봐.\n머리가 네모나니까 영 모양새가 안 살잖아.",
  str_homestory_chat_30724009 = "헤븐즈 가든은 놀이공원이 아니니까,\n관광객을 끌어모을 필요는 없어요.",
  str_homestory_chat_30724010 = "다들 여기엔 편히 쉬러 오는 거니까, 츄브들도 그냥 여길\n평소대로 잘 유지될 수 있게만 해 주면 되고요.",
  str_homestory_chat_30724011 = "그런 경영 목표였던 건가... 알겠어.",
  str_homestory_chat_30725001 = "절 찾았다면서요?",
  str_homestory_chat_30725002 = "여기 땅을 조금 사고 싶어서 말이야.",
  str_homestory_chat_30725003 = "설마 또 누가 리조트 같은 걸 지은 다음에,\n세나 씨한테 지배인을 맡아 달라고 그런 건 아니죠?",
  str_homestory_chat_30725004 = "그게 아니야, 동생. 사실 은퇴하면 여기 와서\n지내고 싶어서 물어본 거야.",
  str_homestory_chat_30725005 = "그럼 아직 한참 남았잖아요.",
  str_homestory_chat_30725006 = "그냥 갑자기 든 생각이었어. 여긴 환경이 꽤 좋으니까.\n비밀스럽기도 하고, 소란스럽지도 않고...",
  str_homestory_chat_30725007 = "나중에 은퇴하면 여기서 지낼 수 있었으면 좋겠어.",
  str_homestory_chat_30899999 = "나 여기 있어~",
  str_homestory_chat_30801001 = "안녕! 보프.",
  str_homestory_chat_30801002 = "날 발견했구나?!",
  str_homestory_chat_30801003 = "네가 나한테 인사하고 있었으니까.",
  str_homestory_chat_30801004 = "레디젤 렌치의 동료들은 항상 날 무시해,\n내가 인사해도 대답을 안 해 줄 때도 많고.",
  str_homestory_chat_30801005 = "그거 너무하네! 그럼 너도 널 좀 더 표현해 본 적 있어?\n아이디어를 내 본다든지 말이야?",
  str_homestory_chat_30801006 = "그래서 내가 책사가 된 거야! 그렇지만 내 계획을\n들어 주려고 하는 건 왕도마뱀밖에 없는 것 같아...",
  str_homestory_chat_30801007 = "조금이라도 좋으니까, 언젠가는 사메야마 대장이\n내 계획을 채택해 주면 좋을 텐데...",
  str_homestory_chat_30801008 = "꼭 그런 날이 올 거야! 화이팅, 보프!",
  str_homestory_chat_30821001 = "뭐 하고 있어?",
  str_homestory_chat_30821002 = "이따가 뭘 먹을지 고민 중이야. 배가 좀 고파서.",
  str_homestory_chat_30821003 = "근데 헤븐즈 가든은 레디젤 사막이랑 좀 멀어서,\n내가 좋아하는 음식이 없을지도 몰라.",
  str_homestory_chat_30821004 = "레디젤 사막의 음식이라면... 말린 도마뱀, 선인장?",
  str_homestory_chat_30821005 = "그런 음식들만 있는 건 아니야.\n헤븐즈 가든에는 먹을 만한 게 뭐 있어?",
  str_homestory_chat_30821006 = "빵.",
  str_homestory_chat_30821007 = "엄청 평범한 음식인데, 그냥 그대로 먹는 거야?\n아무것도 안 바르고?",
  str_homestory_chat_30821008 = "그냥 빵만 먹어도 맛있거든.",
  str_homestory_chat_30821009 = "알겠어.",
  str_homestory_chat_30821010 = "커피.",
  str_homestory_chat_30821011 = "정신을 맑게 하고 싶을 때 마시면 좋아.\n조금 써서 설탕을 많이 넣어야 하긴 하지만...",
  str_homestory_chat_30821012 = "덮밥.",
  str_homestory_chat_30821013 = "반찬이 맛있으면 배부르게 먹기 딱 좋은 음식이야.",
  str_homestory_chat_30821014 = "과일 파이.",
  str_homestory_chat_30821015 = "너 디저트를 좋아했구나? 몰랐어.",
  str_homestory_chat_30821016 = "보프는 이런 음식들엔 별로 관심이 없는 모양이네?",
  str_homestory_chat_30821017 = "응, 음식 얘기가 나오자마자 레디젤 사막이 그리워졌어.",
  str_homestory_chat_30821018 = "모래바람이 심하기는 해도,\n거기 음식은 정말 맛있으니까...",
  str_homestory_chat_30821019 = "도마뱀 맛 아이스크림이랑 슈크림,\n레디젤 렌치 지렁이 튀김 같은 거 말이야.",
  str_homestory_chat_30821020 = "헤븐즈 가든에도 레디젤 렌치 스타일 식당을\n하나 열어 보면 어떨까? 장사가 잘되려나?",
  str_homestory_chat_30821021 = "내가 장담하는데, 망할 거야.",
  str_homestory_chat_30822001 = "안녕, 여기 생활에는 익숙해졌어?",
  str_homestory_chat_30822002 = "안녕, PlayerName! 여긴 좋은 곳이야.\n조용하고 편해. 다만...",
  str_homestory_chat_30822003 = "이제부터 안 좋은 점을 얘기하려는 거구나.",
  str_homestory_chat_30822004 = "여기 오고 나서부터 가끔 재채기가 나와.\n예를 들면... 에취!",
  str_homestory_chat_30822005 = "이유는 모르겠는데, 다른 데 가면 또 아무렇지도 않아.",
  str_homestory_chat_30822006 = "환경이 안 맞아서 그런 걸까? 아니면... 꽃가루 때문인가?",
  str_homestory_chat_30822007 = "에취! 그럴 수도 있을 것 같아.\n레디젤 사막은 꽃이 거의 없었으니까.",
  str_homestory_chat_30822008 = "여길 봐도 모래, 저길 봐도 모래, 눈에 들어오는 곳은 다 모래니까, 난 오히려 꽃보다 모래에 익숙한 것 같아.",
  str_homestory_chat_30822009 = "코에 들어가든, 눈에 들어가든,\n두어 번 털어 내기만 하면 되잖아.",
  str_homestory_chat_30822010 = "그렇지만 이 꽃가루라는 건... 에취! 진짜 짜증 나.",
  str_homestory_chat_30822011 = "꽃에서 조금 멀리 떨어져 있거나,\n다른 날에 다시 놀러 오는 것도 좋을 것 같아.",
  str_homestory_chat_30822012 = "아니면 며칠 참고 지내다 보면 익숙해져서 괜찮을지도 몰라.",
  str_homestory_chat_30822013 = "그래도 헤븐즈 가든의 이런 대자연스러운 느낌은\n확실히 레디젤 사막하고 다르네.",
  str_homestory_chat_30822014 = "마음이 편안해서... 푹 빠져 버릴 것 같아. 에취!",
  str_homestory_chat_30823001 = "뭐 보고 있어?",
  str_homestory_chat_30823002 = "참수리를 찾고 있었어. 어디에 세워 둔 거야?",
  str_homestory_chat_30823003 = "바깥에.",
  str_homestory_chat_30823004 = "혹시 참수리한테 위험한 일이 생기지는 않을까\n걱정되진 않아?",
  str_homestory_chat_30823005 = "스카이워커도 자길 지킬 힘 정도는 가지고 있어.\n그리고 도저히 안 되겠으면 날아가 버리면 되거든.",
  str_homestory_chat_30823006 = "근데 스카이워커는 왜 찾는데?",
  str_homestory_chat_30823007 = "그냥 어디 있는지 궁금해서.\n자길 지킬 수 있는지 궁금하기도 하고.",
  str_homestory_chat_30823008 = "분명히 괜찮을 테니까 걱정하지 마.",
  str_homestory_chat_30823009 = "근데 네가 헤븐즈 가든에 와 있으면,\n그동안 왕도마뱀은 어디 있는 거야?",
  str_homestory_chat_30823010 = "난 차 타고 왔어.\n왕도마뱀은 사막을 떠나기 싫어하거든.",
  str_homestory_chat_30823011 = "그래서 대부분은 사막 곳곳을 돌아다니곤 해.\n믿음직하지 않은 동료들이랑 같이...",
  str_homestory_chat_30823012 = "그래도 동료인데 그렇게 말하면 안 되지.",
  str_homestory_chat_30999999 = "뭐 하느라 그렇게 바빠?",
  str_homestory_chat_30921001 = "산책 중이었어요. 레이스 씨는요?",
  str_homestory_chat_30921002 = "뭔가 생각하고 있던 것 같아 보이던데, 맞아요?",
  str_homestory_chat_30921003 = "맞아. 네 의견도 좀 들어 보고 싶었는데, 마침 잘 왔어.",
  str_homestory_chat_30921004 = "무슨 일인데요...?",
  str_homestory_chat_30921005 = "넌 장군들 중에서 대원수 자리를 감당할 수 있는 건\n누구라고 생각해?",
  str_homestory_chat_30921006 = "음... 생각 좀 해 볼게요.",
  str_homestory_chat_30921007 = "시로나 씨요.",
  str_homestory_chat_30921008 = "좋은 선택이야. 통솔 능력, 전략적인 시야,\n그리고 충성도까지, 문제없는 인재지.",
  str_homestory_chat_30921009 = "아쉬운 점은 백야성 출신이라는 거야.\n과거랑 완전히 연을 끊었다곤 해도...",
  str_homestory_chat_30921010 = "「그 사람들」 눈엔 흠으로 보일지도 모르니까.",
  str_homestory_chat_30921011 = "그렇군요...",
  str_homestory_chat_30921012 = "바튼 씨요.",
  str_homestory_chat_30921013 = "바튼은 장군밖에 못 해.\n바튼한텐 전장이 곧 집이니까.",
  str_homestory_chat_30921014 = "평화로운 시기엔 모두의 문젯거리가 되든가,\n아니면 할 일 없이 빈둥거리는 한량이 되겠지.",
  str_homestory_chat_30921015 = "정말 매정한 평가네요.",
  str_homestory_chat_30921016 = "내가 해야 할 일을 할 뿐이야.",
  str_homestory_chat_30921017 = "히이로 씨요.",
  str_homestory_chat_30921018 = "의심할 여지 없는 용맹함을 가지고 있는 데다가,\n병사들에 대한 관리도 엄격하고 성실하지. 다만...",
  str_homestory_chat_30921019 = "너무 용맹한 나머지 전황을 고려하지 않을 때가 많아.",
  str_homestory_chat_30921020 = "군인이라면 물론 용맹해야 해. 하지만 전제가 있어.\n바로 승리를 얻기 위해서여야 한단 거지.",
  str_homestory_chat_30921021 = "네가 그 미묘한 차이를 알진 모르겠지만 말이야.",
  str_homestory_chat_30921022 = "조금은 알 것 같아요.",
  str_homestory_chat_30921023 = "그럼 아무래도 다들 안 되는 모양이네요.",
  str_homestory_chat_30921024 = "사실 다른 관점에서 보자면, 적합한 부관이나\n참모 같은 인재들이 보완해 준다면...",
  str_homestory_chat_30921025 = "다들 대원수 자리에 어울리는 인재들일 수도 있어.",
  str_homestory_chat_30922001 = "동료를 보러 가려던 참이었어요.",
  str_homestory_chat_30922002 = "동료 얘기가 나와서 말인데, 너한테 라인하르트는\n좋은 동료야? 아니면 좋은 상사야?",
  str_homestory_chat_30922003 = "좋은 동료죠.",
  str_homestory_chat_30922004 = "좋은 상사예요.",
  str_homestory_chat_30922005 = "근데 갑자기 그건 왜 물어보는 거예요?",
  str_homestory_chat_30922006 = "아마 알고 있겠지만 나랑 라인하르트는 동창이야.",
  str_homestory_chat_30922007 = "그리고 전엔 라인하르트가 내 상사라서,\n내가 지휘를 듣는 입장이었지만.",
  str_homestory_chat_30922008 = "나중엔 내가 걔 상사가 될 수도 있는 거잖아.",
  str_homestory_chat_30922009 = "이제 좀 이해가 되네요. 라인하르트 씨랑 어떻게\n지내야 좋을까 고민 중이었던 거죠?",
  str_homestory_chat_30922010 = "그래.",
  str_homestory_chat_30922011 = "복잡하게 생각할 거 없이 그냥 자연스럽게\n대하면 될 것 같아요.",
  str_homestory_chat_30922012 = "그렇게 대답할 줄 알았어.\n그래도 뭐 조언은 조언이니까.",
  str_homestory_chat_30922013 = "고마워, PlayerName.",
  str_homestory_chat_30923001 = "머리 좀 식히려고요.",
  str_homestory_chat_30923002 = "넌 평소에 머리를 식히고 싶을 땐 뭘 하지?",
  str_homestory_chat_30923003 = "산책을 해요.",
  str_homestory_chat_30923004 = "흔히들 하는 방법이네.",
  str_homestory_chat_30923005 = "낚시를 해요.",
  str_homestory_chat_30923006 = "정석적인 방법인걸.",
  str_homestory_chat_30923007 = "아이테르는 머리를 식힐 때 명상이란 방법을\n쓴다고 들었는데.",
  str_homestory_chat_30923008 = "전 거의 안 해서요.\n근데 왜 갑자기 명상에 관심이 생긴 건데요?",
  str_homestory_chat_30923009 = "레이스 씨도 한번 해 보시려고요?",
  str_homestory_chat_30923010 = "명상은 긴장 완화 방법이지만,\n일종의 훈련법이기도 하거든.",
  str_homestory_chat_30923011 = "머리를 식히면서 바른길을 찾고,\n나아가야 할 방향을 정할 수 있어.",
  str_homestory_chat_30923012 = "일종의 자체 「에너지 충전」이 가능하게 해 주는\n아주 중요한 훈련법이란 거지.",
  str_homestory_chat_30923013 = "그럼 이따 저도 한번 해 볼게요...",
  str_homestory_chat_30924001 = "산책하고 있었어요.",
  str_homestory_chat_30924002 = "넌 산책이랑 아주 잘 맞아 보이네.",
  str_homestory_chat_30924003 = "그래요?",
  str_homestory_chat_30924004 = "안색이 아주 좋아 보이거든.\n평소에 산책을 자주 해서 그런가?",
  str_homestory_chat_30924005 = "그건 아닐 거예요.",
  str_homestory_chat_30924006 = "그럼 다른 방법이 있나?",
  str_homestory_chat_30924007 = "전 그냥 잠을 충분히 자 주고, 규칙적인 생활을 유지하는\n것밖에 안 하는걸요.",
  str_homestory_chat_30924008 = "오히려 레이스 씨는 안색이 안 좋을 때가 많던데요.\n일 때문에 밤을 자주 새워서 그런가요? 너무 무리하진 마세요.",
  str_homestory_chat_30924009 = "어느 정도는 그렇지.\n책임을 짊어지게 된 대가라고 생각해.",
  str_homestory_chat_30925001 = "헤븐즈 가든을 순찰하는 중이에요.",
  str_homestory_chat_30925002 = "쉬운 일은 아닐 텐데, 수고가 많네.",
  str_homestory_chat_30925003 = "그렇진 않아요... 겸사겸사 산책도 할 수 있거든요.",
  str_homestory_chat_30925004 = "호오? 넌 그런 느낌으로 헤븐즈 가든을\n관리하는 건가?",
  str_homestory_chat_30925005 = "비슷해요. 일은 츄브들이 거의 다 하고, 저는 가끔 확인만 해요.",
  str_homestory_chat_30925006 = "하아, 일루미나를 관리하는 것도 헤븐즈 가든을\n관리하는 것처럼 간단하면 좋겠는데 말이야.",
  str_homestory_chat_30925007 = "일루미나랑 헤븐즈 가든은 놓인 상황이 서로 다른걸요.",
  str_homestory_chat_30925008 = "일루미나 연방은 암귀들의 침입에 맞서 싸워야 하니까,\n책임이 엄청 막중하잖아요.",
  str_homestory_chat_30925009 = "게다가 일루미나 연방은 규모도 헤븐즈 가든보다 훨씬 크고요.",
  str_homestory_chat_30925010 = "확실히 그렇지.",
  str_homestory_chat_30925011 = "레이스 씨도 항상 어깨에 무거운 짐만 지고 있지 말고,\n헤븐즈 가든에 왔으면 푹 쉬어 두세요.",
  str_homestory_chat_31099999 = "만물은 백야 아래에. 오늘 하루는 어땠나요?",
  str_homestory_chat_31001001 = "별로 특별한 건 없었어.",
  str_homestory_chat_31001002 = "특별한 게 없었단 건 이 땅이 평화로웠단 얘기니,\n좋은 일이네요.",
  str_homestory_chat_31001003 = "조셀린은 이런 평범한 날을 꽤 마음에 들어 하는 모양이구나.",
  str_homestory_chat_31001004 = "더스크 타운 사람들은 모두 여유롭지 못한\n생활을 보내고 있거든요.",
  str_homestory_chat_31001005 = "물질적인 면뿐만 아니라, 정신적인 면에서도요...",
  str_homestory_chat_31001006 = "암귀들이 너무 가까이 있으니까, 어쩔 수 없는 부분이긴 하지.",
  str_homestory_chat_31001007 = "그래서 헤븐즈 밸리에 오게 되면, 이곳의 평화로운\n모습에 감탄하게 되곤 한답니다.",
  str_homestory_chat_31001008 = "이런 빛이 아스트라 대륙 곳곳을 두루 비춰준다면\n얼마나 좋을까요.",
  str_homestory_chat_31021001 = "괜찮았어. 조셀린은?",
  str_homestory_chat_31021002 = "당신은 다른 지역을 어떻게 생각할까\n궁금해하고 있었어요.",
  str_homestory_chat_31021003 = "예를 들면?",
  str_homestory_chat_31021004 = "음... 백야성에 대해선 어떻게 생각하나요?",
  str_homestory_chat_31021005 = "문명의 중심이라고 생각해.",
  str_homestory_chat_31021006 = "아스트라 대륙의 통치자란 느낌이야.",
  str_homestory_chat_31021007 = "조셀린 넌 백야성을 어떻게 생각하는데?",
  str_homestory_chat_31021008 = "문명의 중심...이라고 해야 할까요...",
  str_homestory_chat_31021009 = "대답하는 거 보니까 별로 확신이 없나 보네.",
  str_homestory_chat_31021010 = "전 더스크 타운에서 오래 살았고,\n백야성엔 가 본 적이 거의 없는걸요.",
  str_homestory_chat_31021011 = "그럼 일루미나 연방에 대해선 어떻게 생각하나요?",
  str_homestory_chat_31021012 = "암귀랑 맞서 싸우는 최전선이지.",
  str_homestory_chat_31021013 = "단결된 조직이라고 생각해.",
  str_homestory_chat_31021014 = "근데 이런 건 왜 물어보는 거야?",
  str_homestory_chat_31021015 = "더스크 타운 일이 떠오를 때마다, 저도 모르게\n더스크 타운의 미래에 대해 고민하게 되거든요.",
  str_homestory_chat_31021016 = "마을 사람들의 앞날은... 어떻게 되는 걸까요?",
  str_homestory_chat_31021017 = "자주 그런 생각을 하는 거야?",
  str_homestory_chat_31021018 = "더스크 타운에 살다 보면 어쩔 수 없이\n이런 생각들을 하게 돼요...",
  str_homestory_chat_31021019 = "위대하신 빛의 신께서 제 기도에 응답해 주셔서,\n사람들에게 더 많은 가호를 내려 주셨으면 좋겠네요.",
  str_homestory_chat_31022001 = "여기저기 둘러보려던 중이었어.",
  str_homestory_chat_31022002 = "그래 보이네요. 느긋한 시간을 즐기려는 건가요?",
  str_homestory_chat_31022003 = "그렇다고 할 수 있겠네. 조셀린 넌 뭐 하는데?",
  str_homestory_chat_31022004 = "아직 못 정했어요.\n헤븐즈 가든에 적응이 조금 안 됐거든요.",
  str_homestory_chat_31022005 = "왜?",
  str_homestory_chat_31022006 = "헤븐즈 가든은 더스크 타운이랑 많이 달라서요.\n더스크 타운에선 매일 검을 들고...",
  str_homestory_chat_31022007 = "암귀들을 막아야 하니까?",
  str_homestory_chat_31022008 = "맞아요.",
  str_homestory_chat_31022009 = "그래서 매일 검을 지니고 다니지 않아도 되는 삶은\n어떤 모습일지 자주 상상해 보곤 했어요.",
  str_homestory_chat_31022010 = "이젠 그런 모습이 어떤지 직접 경험해 봤겠네!",
  str_homestory_chat_31022011 = "하아, 더스크 타운 사람들 모두가 이런 날을\n보낼 수 있다면 훨씬 더 좋겠죠.",
  str_homestory_chat_31023001 = "평소랑 똑같지 뭐. 조셀린은 뭐 하고 있었어?",
  str_homestory_chat_31023002 = "빛의 흔적을 느끼고 있었어요.",
  str_homestory_chat_31023003 = "빛의 흔적을 느낀다고? 아! 「일광욕」 중이었구나?\n일광욕은 건강에 엄청 좋아.",
  str_homestory_chat_31023004 = "일광욕을 하고 있던 게 아니라,\n실은 기도를 드리고 있었어요.",
  str_homestory_chat_31023005 = "기도?",
  str_homestory_chat_31023006 = "「빛」은 제 신앙이니까요...",
  str_homestory_chat_31023007 = "마침 헤븐즈 가든은 더스크 타운과 다르게\n흐린 날이 거의 없어요.",
  str_homestory_chat_31023008 = "이렇게 아름다운 곳에 머물다 보니 저도 모르게\n기도하고 싶은 마음이 생겼거든요.",
  str_homestory_chat_31023009 = "그럼 방해 안 할게.",
  str_homestory_chat_31199999 = "조종사, 뭐 하고 있어?",
  str_homestory_chat_31121001 = "안토니구나, 마침 난...",
  str_homestory_chat_31121002 = "유적을 탐사하러 갈 생각이야.",
  str_homestory_chat_31121003 = "유적? 아직 개척되지 않은 유적 말하는 거야?",
  str_homestory_chat_31121004 = "내가 따라가도 될까?!",
  str_homestory_chat_31121005 = "딱히 안 될 건 없는데.",
  str_homestory_chat_31121006 = "너무 큰 기대는 안 하는 게 좋을 거야.",
  str_homestory_chat_31121007 = "내가 가려는 유적은 벌써 여러 번 탐사했던 곳이거든.",
  str_homestory_chat_31121008 = "그럼, 너무 기대하면 안 된다는 건 잘 알아.",
  str_homestory_chat_31121009 = "그렇지만 별 볼 일 없어 보이는 돌멩이에\n굉장한 비밀이 숨겨져 있을 때도 있거든.",
  str_homestory_chat_31121010 = "안토니 넌 아는 게 많으니까,\n진짜 특별한 걸 발견할 수도 있을 것 같아.",
  str_homestory_chat_31121011 = "가서 좀 쉬려고.",
  str_homestory_chat_31121012 = "쉴 거라면, 내가 좋은 곳을 하나 추천할게.",
  str_homestory_chat_31121013 = "이 근처에 유적이 하나 있다는데.",
  str_homestory_chat_31121014 = "안에 고대의 벽화가 아주 많다고 하더라고.",
  str_homestory_chat_31121015 = "그거랑 쉬는 거랑은 아무런 관련도 없지 않아?",
  str_homestory_chat_31121016 = "당연히 관련 있지.",
  str_homestory_chat_31121017 = "유적 안에 누워서, 고개를 들어 그 벽화들을 바라보면...",
  str_homestory_chat_31121018 = "아주 오래전의 그 시대로 돌아간 느낌이 들거든.",
  str_homestory_chat_31121019 = "나는 그것도 일종의 휴식이라고 생각해.",
  str_homestory_chat_31121020 = "벽화? 갑자기 흥미가 생기는데?",
  str_homestory_chat_31121021 = "그럼 일단 돌아가서 갈 준비부터 좀 할게.",
  str_homestory_chat_31121022 = "좋아, 그럼 이따 봐.",
  str_homestory_chat_31122001 = "딱히 뭐 하고 싶은 게 없네. 안토니 넌?",
  str_homestory_chat_31122002 = "난 「다기능 트레킹 폴-Ⅶ」을 조정 중이야.",
  str_homestory_chat_31122003 = "새로운 개선 아이디어라도 떠오른 거야?",
  str_homestory_chat_31122004 = "그건 아니고, 그냥 조명 장치를 조금 강화할 생각이야.",
  str_homestory_chat_31122005 = "지금 달린 조명의 확산 효과가 아무래도\n살짝 부족한 것 같아서.",
  str_homestory_chat_31122006 = "콜로서스에서 배운 지식을 활용해서\n조명 효과를 손보고 있었어.",
  str_homestory_chat_31122007 = "구체적으로 어떤 원리인지 설명해 줄까?",
  str_homestory_chat_31122008 = "실제 출력을 높이기 위해서 적용해야 하는\n공식에 대해 자세히 설명해 보자면...",
  str_homestory_chat_31122009 = "아, 갑자기 해야 할 일이 있던 게 생각났어...",
  str_homestory_chat_31122010 = "일단 방해 안 할게!",
  str_homestory_chat_31123001 = "여기저기 둘러보고 있었어.",
  str_homestory_chat_31123002 = "이따간 아마 다른 오로리안들을 보러 갈 것 같아.",
  str_homestory_chat_31123003 = "다른 오로리안 얘기가 나와서 말인데,\n조종사 넌 33호를 어떻게 생각해?",
  str_homestory_chat_31123004 = "좋은 동료라고 생각해.",
  str_homestory_chat_31123005 = "음, 나도 그 생각에 동의해.",
  str_homestory_chat_31123006 = "하지만, 먼 옛날에 탄생한 오로리안이라는 존재가\n아주 신비롭게 느껴지진 않아?",
  str_homestory_chat_31123007 = "설마... 33호를 연구하고 싶단 건 아니지?",
  str_homestory_chat_31123008 = "하하, 내가 연구하고 싶은 건 33호의 헬멧뿐이야...",
  str_homestory_chat_31123009 = "굉장히 신비로운 소녀?",
  str_homestory_chat_31123010 = "역시! 너도 그렇게 생각하고 있었구나!",
  str_homestory_chat_31123011 = "먼 옛날에 탄생한 오로리안이라니,\n호기심을 안 가질래야 안 가질 수 없잖아.",
  str_homestory_chat_31123012 = "설마... 33호를 연구하고 싶단 건 아니지?",
  str_homestory_chat_31123013 = "하하, 내가 연구하고 싶은 건 33호의 헬멧뿐이야...",
  str_homestory_chat_31123014 = "그럼 가서 직접 물어봐도 될 것 같은데.",
  str_homestory_chat_31123015 = "궁금해하는 건 대부분 대답해 줄걸.",
  str_homestory_chat_31124001 = "책 좀 읽으려고 했어.",
  str_homestory_chat_31124002 = "마침 잘됐네.",
  str_homestory_chat_31124003 = "나도 책을 읽으러 온 거거든.",
  str_homestory_chat_31124004 = "무슨 책 읽고 있었어?",
  str_homestory_chat_31124005 = "《행성 궤적의 보정과 편이》야.",
  str_homestory_chat_31124006 = "나, 난해하네...",
  str_homestory_chat_31124007 = "사실 별로 어렵지 않아서 조종사도 읽어 보면\n뭔지 충분히 이해할 거야.",
  str_homestory_chat_31124008 = "그럼 한번 읽어 볼게...",
  str_homestory_chat_31125001 = "가서 방 정리 좀 하려고.",
  str_homestory_chat_31125002 = "오, 그럼 혹시 좋아하는 수납 방식도 있어?",
  str_homestory_chat_31125003 = "난 정돈에 신경을 쓰는 편이야.",
  str_homestory_chat_31125004 = "안토니 넌?",
  str_homestory_chat_31125005 = "내 가방을 예로 들자면, 난 편의성에 더 중점을 둬.",
  str_homestory_chat_31125006 = "필요도 순으로 물건을 넣는 거지.",
  str_homestory_chat_31125007 = "가장 필요한 물건은 맨 위에, 사용하지 않을 것 같은\n물건은 아래에 두는 거야.",
  str_homestory_chat_31125008 = "편의성에 신경을 쓰는 편이야.",
  str_homestory_chat_31125009 = "나랑 똑같네.",
  str_homestory_chat_31125010 = "난 가방 정리를 할 때 편의성에 신경을 쓰거든.",
  str_homestory_chat_31125011 = "마침 잘됐다. 나도 방 정리 도와줄게.",
  str_homestory_chat_31125012 = "그럼 부탁할게.",
  str_homestory_chat_31299999 = "오늘 하루는 어떻게 보낼 예정이야?",
  str_homestory_chat_31221001 = "아직 정해 놓은 건 없는데...",
  str_homestory_chat_31221002 = "넌?",
  str_homestory_chat_31221003 = "난 당연히 루미나틱스 연습을 할 거야.",
  str_homestory_chat_31221004 = "매번 똑같이 대답하는 것 같은데,\n항상 그렇게 연습하면 힘들지 않아?",
  str_homestory_chat_31221005 = "가끔은 긴장을 풀고 쉬어 주는 것도 좋아.",
  str_homestory_chat_31221006 = "계속 신경이 곤두서 있으면 오히려 역효과가 날걸.",
  str_homestory_chat_31221007 = "음... 그러려나...",
  str_homestory_chat_31222001 = "오늘 하루는 쭉 순찰하러 가야 돼...",
  str_homestory_chat_31222002 = "조종사 일도 쉬운 게 아니구나.",
  str_homestory_chat_31222003 = "매일 그렇게나 바쁘다니 말이야.",
  str_homestory_chat_31222004 = "내 도움이 필요한 부분이 있으면 언제든 편하게 말해 줘~",
  str_homestory_chat_31222005 = "아직까진 뭐 없는데...",
  str_homestory_chat_31222006 = "생각 좀 해 볼게...",
  str_homestory_chat_31222007 = "참! 나한테 좋은 생각이 하나 있어.",
  str_homestory_chat_31222008 = "얼음 마사지라는 거 들어 봤어?",
  str_homestory_chat_31222009 = "얼음을 몸의 적당한 위치에 올려 두면,\n긴장했던 근육들이 풀린대...",
  str_homestory_chat_31222010 = "왠지 나라면 별로 어렵지 않게 해낼 수 있는 일 같아~",
  str_homestory_chat_31222011 = "네가 한다면... 좀 무서울 것 같은데.",
  str_homestory_chat_31222012 = "좀 시원하겠다고 해야지!",
  str_homestory_chat_31222013 = "근데 순찰 다 끝내고 나면.",
  str_homestory_chat_31222014 = "진짜 마사지를 좀 받아야 할 것 같기도 해.",
  str_homestory_chat_31222015 = "잘됐네! 그럼 내 실력을 제대로 보여 줄게~",
  str_homestory_chat_31223001 = "외출해서 기분 전환 좀 할 거야.",
  str_homestory_chat_31223002 = "나도 같이 가도 돼?",
  str_homestory_chat_31223003 = "당연히 같이 가도 되지.",
  str_homestory_chat_31223004 = "어디 갈 거야?",
  str_homestory_chat_31223005 = "해변에 갈 거야~",
  str_homestory_chat_31223006 = "상점가에 갈 거야~",
  str_homestory_chat_31223007 = "내가 가 본 적 없는 곳이네...",
  str_homestory_chat_31223008 = "바깥세상을 여행하는 것도 네 꿈이었잖아?",
  str_homestory_chat_31223009 = "지금 가려는 덴 정말 정말 재미있는 곳이야!",
  str_homestory_chat_31223010 = "그럼 가서 준비 좀 하고 올 테니까, 잠깐만 기다려!",
  str_homestory_chat_31224001 = "동료를 만나러 갈 거야.",
  str_homestory_chat_31224002 = "어? 혹시 33호 보러 가는 거야?",
  str_homestory_chat_31224003 = "어떻게 알았어?",
  str_homestory_chat_31224004 = "그냥 느낌이 딱 왔거든.",
  str_homestory_chat_31224005 = "그리고 나 아까까지 33호랑 같이 있었어.",
  str_homestory_chat_31224006 = "내가 보니까 33호는 널 되게 중요하게\n생각하는 것 같아.",
  str_homestory_chat_31224007 = "아마 알리나 언니 때문일 거야.",
  str_homestory_chat_31224008 = "33호는 나한테서 언니의 모습을\n겹쳐 보고 있는 걸지도 몰라.",
  str_homestory_chat_31224009 = "나도 똑같이 하고 있긴 하지만 말이야.",
  str_homestory_chat_31224010 = "33호가 절대로 언니를 대신할 수 없다는 건 알지만...",
  str_homestory_chat_31224011 = "그래도 역시 난 33호의 여동생이 되고 싶어...",
  str_homestory_chat_31225001 = "앞으로의 여행 계획을 다듬어 볼까 해.",
  str_homestory_chat_31225002 = "그러고 보니까, 저번에 여행 갔을 때 그, 사진...?\n맞나? 혹시 내가 잘못 말한 거 아니지?",
  str_homestory_chat_31225003 = "응, 사진 맞아.",
  str_homestory_chat_31225004 = "아까까지 그때 찍은 사진이란 것들을 보고 있었어.",
  str_homestory_chat_31225005 = "이 시대의 기술은 정말 대단하다니까.",
  str_homestory_chat_31225006 = "어떻게 그런 작은 기계에 사람이랑 장소를\n「저장」해 놓을 수 있는 거야?",
  str_homestory_chat_31225007 = "설명하려면 좀 복잡한데...",
  str_homestory_chat_31225008 = "관심 있으면 안토니한테 물어보면 될 거야.",
  str_homestory_chat_31225009 = "분명히 엄청 신나서 대답해 줄걸.",
  str_homestory_chat_31399999 = "33호, 대기 중입니다. 명령을 입력해 주세요.",
  str_homestory_chat_31321001 = "가서 쉬는 게 좋겠어.",
  str_homestory_chat_31321002 = "명령에 오류가 있습니다.",
  str_homestory_chat_31321003 = "대기 상태는 휴식과 동일합니다.",
  str_homestory_chat_31321004 = "예측에 따르면 저는 현재 수면 상태에 진입해야 할\n이유가 존재하지 않습니다.",
  str_homestory_chat_31321005 = "진짜 안 피곤해?",
  str_homestory_chat_31321006 = "신경 써 주셔서 감사합니다.\n하지만 아직 피로감은 느껴지지 않습니다.",
  str_homestory_chat_31321007 = "다음 명령을 내리지 않으실 경우,\n계속 대기 상태를 유지하겠습니다.",
  str_homestory_chat_31322001 = "순찰을 부탁할게.",
  str_homestory_chat_31322002 = "명령을 접수했습니다.\n지금부터 작업 목록을 실행합니다.",
  str_homestory_chat_31322003 = "잠깐만! 그냥 하는 말이 아니었던 거야?!",
  str_homestory_chat_31322004 = "난 그냥 농담한 거였는데...",
  str_homestory_chat_31322005 = "제 실행 능력을 신뢰하실 수 없습니까?",
  str_homestory_chat_31322006 = "기록에 따르면 저는 누적 순찰 횟수 5005회라는\n매우 풍부한 경험을 보유하고 있습니다.",
  str_homestory_chat_31322007 = "33호 널 못 믿겠다는 게 아니라.",
  str_homestory_chat_31322008 = "그냥 순찰은 원래 내가 해야 하는 일이니까,\n내가 알아서 하는 게 맞단 거야.",
  str_homestory_chat_31322009 = "이해했습니다. 당신의 선택을 존중합니다.",
  str_homestory_chat_31323001 = "입력 안 할래.",
  str_homestory_chat_31323002 = "명령을 입력해 주세요...",
  str_homestory_chat_31323003 = "다시 한번 반복합니다. 명령을 입력해 주세요.",
  str_homestory_chat_31323004 = "혹시 「명령 입력」이라는 표현이 불편하신 겁니까?",
  str_homestory_chat_31323005 = "현재 더 적절한 표현을 검색 중입니다...",
  str_homestory_chat_31323006 = "「제가 해야 할 일이 있다면, 편하게 알려 주세요.」",
  str_homestory_chat_31323007 = "진짜로 아직까진 급하게 해야 할 일이 없는걸.",
  str_homestory_chat_31323008 = "알겠습니다. 그렇다면 필요할 때 다시 알려 주세요.",
  str_homestory_chat_31323009 = "33호가 모든 과정에서 도움을 드리겠습니다.",
  str_homestory_chat_31324001 = "가서 동료들이랑 놀아.",
  str_homestory_chat_31324002 = "예를 들면...",
  str_homestory_chat_31324003 = "자리야?",
  str_homestory_chat_31324004 = "자리야 말입니까?\n자리야는 확실히 제 소중한 동료입니다.",
  str_homestory_chat_31324005 = "그렇다면 자리야가 강해질 수 있도록\n새로운 루미나틱스 훈련 방식을 고안하겠습니다.",
  str_homestory_chat_31324006 = "아니야, 그럴 필요 없어.\n그냥 가서 자리야랑 서로 얘기 좀 하고 그 정도면 돼.",
  str_homestory_chat_31324007 = "안토니?",
  str_homestory_chat_31324008 = "너랑 안토니랑 같이 있으면, 서로 대화를 나눌 만한\n주제가 엄청 많을 것 같거든.",
  str_homestory_chat_31324009 = "안토니 님이 보유한 지식량과 지식에 대한 이해도가\n높다는 의미라면, 저 역시 이에 동의합니다.",
  str_homestory_chat_31324010 = "하지만 기존에 진행되었던 안토니 님과의\n50번의 교류를 토대로 보았을 때...",
  str_homestory_chat_31324011 = "안토니 님은 저의 기계 및 기술 측면의 지식에\n더 많은 관심을 보이는 것으로 파악됩니다.",
  str_homestory_chat_31324012 = "안토니 님이라면 정말로 저와의 대화 속에서\n제가 잊은 정보를 도출해 낼 수 있을지도 모릅니다...",
  str_homestory_chat_31324013 = "그럼 33호 너도, 안토니도 서로 좋은 일이겠네~",
  str_homestory_chat_31324014 = "그러니까 이따 한번 만나러 가 봐.",
  str_homestory_chat_31324015 = "나도 이제 볼일 때문에 가 볼게.",
  str_homestory_chat_28899999 = "뭘 하고 있는 게냐?",
  str_homestory_chat_28801001 = "아, 마침 저도 단당 씨한테 물어보려던 참이었어요.\n여긴 좀 익숙해졌나요?",
  str_homestory_chat_28801002 = "이곳은 아스트라 대륙의 다른 도시와는 전혀 다르고,\n물론 용주의 도시와도 다르구나.",
  str_homestory_chat_28801003 = "독특한 분위기가 있다는 게다.",
  str_homestory_chat_28801004 = "독특한 분위기요?",
  str_homestory_chat_28801005 = "실로 평온하여, 자연스레 바깥세상의 혼란을 잊게 된다.",
  str_homestory_chat_28801006 = "음... 익숙해진 모양이네요. 다행이에요.",
  str_homestory_chat_28821001 = "꽃을 기른다고요?",
  str_homestory_chat_28821002 = "그렇지, PlayerName공자.\n이곳에는 특이한 꽃이 있느냐.",
  str_homestory_chat_28821003 = "있어요.",
  str_homestory_chat_28821004 = "하면 그 꽃이 있는 곳으로 안내해 줄 수 있겠느냐.",
  str_homestory_chat_28821005 = "근데... 지금은 츄브들이 지키고 있는 것 같아요.\n아직 재배 중이거든요.",
  str_homestory_chat_28821006 = "알겠다...\n특이한 꽃이라면 응당 세심한 관리가 필요하겠지.",
  str_homestory_chat_28821007 = "근처에서 다른 꽃들을 봐도 좋을 거 같아요.\n헤븐즈 밸리에는 다른 식물들도 많으니까요.",
  str_homestory_chat_28821008 = "PlayerName 공자의 제안에 감사하마.",
  str_homestory_chat_28821009 = "없어요.",
  str_homestory_chat_28821010 = "아쉬운지고.\n하면 새로운 임무를 시작해야겠구나...",
  str_homestory_chat_28821011 = "헤븐즈 밸리에 용주의 꽃인 해당화를 심는 게다!\n공자는 어찌 생각하느냐.",
  str_homestory_chat_28821012 = "생각해 볼게요.",
  str_homestory_chat_28822001 = "장치요?",
  str_homestory_chat_28822002 = "정확히 말하면, 여러 장치로 만들어진 물건 말이다.\n아스트라 대륙에는 그런 것이 많다고 들었다.",
  str_homestory_chat_28822003 = "예를 들면요?",
  str_homestory_chat_28822004 = "일전에 정교하게 만들어진 시계를 본 적이 있다.\n그 시계는 시간을 일러 줄 뿐만 아니라,\n안에서 작은 새가 튀어나오기도 하더구나.",
  str_homestory_chat_28822005 = "작은 새가 튀어나온다고요?",
  str_homestory_chat_28822006 = "특정 시간이 되면, 작은 새가 「띵」하고 나와서\n울음소리를 내는 게지.",
  str_homestory_chat_28822007 = "「띵」? 그거 전 「꾹」인 줄 알았는데요...",
  str_homestory_chat_28822008 = "그래! 그 소리야!",
  str_homestory_chat_28822009 = "그건 비둘기 시계예요. 확실히 정교하긴 해요.",
  str_homestory_chat_28822010 = "그럼 언제쯤 내 방에도 그것을 하나 놓을 수 있을까?",
  str_homestory_chat_28822011 = "아... 그거 되게 비싼 물건이라서요. 좀 생각해 볼게요...",
  str_homestory_chat_28823001 = "음료요?",
  str_homestory_chat_28823002 = "그렇지. 이곳에 온 후로, 고향의 음료가 조금 그립구나.",
  str_homestory_chat_28823003 = "PlayerName 공자, 추천할 만한 음료가 있느냐.",
  str_homestory_chat_28823004 = "홍차요.",
  str_homestory_chat_28823005 = "그 차는 아스트라 대륙에도 있고,\n많은 사람들이 좋아한다고 들었어요.",
  str_homestory_chat_28823006 = "다만... 차를 마시는 것보다, 세트로 나오는 다과가\n더 주목받고 있긴 해요...",
  str_homestory_chat_28823007 = "그렇구나. 생각해 보마.",
  str_homestory_chat_28823008 = "소다요.",
  str_homestory_chat_28823009 = "그것은 무에냐...?",
  str_homestory_chat_28823010 = "조금 달콤하고, 마실 때 입맛도 특이한 느낌이 드는 음료예요.",
  str_homestory_chat_28823011 = "대체 어떤 특이한 느낌인 게냐?",
  str_homestory_chat_28823012 = "내부에서 가스가 소용돌이치는 느낌이라고 할까요.\n한 번에 마시면 트림이 나와요.",
  str_homestory_chat_28823013 = "아무래도 내게는 잘 맞지 않을지도 모르겠구나...",
  str_homestory_chat_28824001 = "아침 식사요?",
  str_homestory_chat_28824002 = "「하루의 식사는 아침에 달려 있다」라는 말처럼,\n아침 식사는 매우 중요하다.",
  str_homestory_chat_28824003 = "이상한 말이네요...",
  str_homestory_chat_28824004 = "허나 아스트라 대륙의 아침 식사는 무슨 연유인지\n이상한 것들이 많다고 느껴지더구나.",
  str_homestory_chat_28824005 = "예를 들어, 레디젤 렌치에서는 아침에 꼬치구이를,\n움브라톤에서는 아침에 물만 마신다고 들었다.",
  str_homestory_chat_28824006 = "아... 그건 아마 그게 특별한 사례들일걸요.",
  str_homestory_chat_28824007 = "꼬치구이가 말이냐?",
  str_homestory_chat_28824008 = "그건 레디젤 렌치 일부 사람들의 개인적인 취향이에요...",
  str_homestory_chat_28824009 = "그럼 물은?",
  str_homestory_chat_28824010 = "크흠, 그건... 다이어트라거나,\n아니면 그냥 생활비가 부족한 것뿐일 거예요.",
  str_homestory_chat_28824011 = "어쨌든 전부 아스트라 대륙의 일반적인 아침 식사가 아니에요.",
  str_homestory_chat_28824012 = "하면 일반적인 아침 식사는 무에냐?",
  str_homestory_chat_28824013 = "빵, 우유, 계란, 대충 이런 느낌이겠죠.",
  str_homestory_chat_28824014 = "역시 우리 고향과는 다르구나.\n허나 그 정도면 훨씬 평범하다 할 수 있겠지.",
  str_homestory_chat_28799999 = "무슨 일 있으십니까?",
  str_homestory_chat_28701001 = "한가해 보이네요.",
  str_homestory_chat_28701002 = "그럴 리가요! 마침 당신에게 볼일이 있던 참입니다.",
  str_homestory_chat_28701003 = "저요?",
  str_homestory_chat_28701004 = "네, 그렇습니다. 당신의 운명을 점쳐 보려고 합니다.",
  str_homestory_chat_28701005 = "왠지 지금 즉흥적으로 결정한 것처럼 들리는데...",
  str_homestory_chat_28701006 = "전혀 아닙니다! 이미 오래전부터 계획...\n아, 아니지, 소생은 항상 당신을 걱정하고 있습니다.",
  str_homestory_chat_28701007 = "제가 보니 이 점괘는 당신에게 「산만증」이 있다고\n말해주고 있는 듯하군요...",
  str_homestory_chat_28701008 = "진짜요?!",
  str_homestory_chat_28701009 = "그것은 환자가 너무 느긋하게 지내다 보니\n마음이 산만해져서 생기는 증상입니다...",
  str_homestory_chat_28701010 = "그거 제가 한가하다는 소리잖아요!",
  str_homestory_chat_28701011 = "그렇습니다.",
  str_homestory_chat_28721001 = "천간 씨는 여길 어떻게 생각해요?",
  str_homestory_chat_28721002 = "이곳은 참으로 풍수의 명당이라 할 수 있겠지요...",
  str_homestory_chat_28721003 = "소생이 여러모로 헤아려 보니, 이곳은 편안히 지내며\n휴식을 취하기 좋은 곳이더군요.",
  str_homestory_chat_28721004 = "특히 여러 동물들을 기르기 좋겠습니다.\n예를 들면 새라거나 말이지요...",
  str_homestory_chat_28721005 = "천간 씨가 기르고 싶은 건 아니고요?",
  str_homestory_chat_28721006 = "그것도 맞습니다.\n여긴 혹시 신기한 새가 있습니까?",
  str_homestory_chat_28721007 = "있어요.",
  str_homestory_chat_28721008 = "없어요.",
  str_homestory_chat_28721009 = "아... 참으로 아쉬운 일입니다.",
  str_homestory_chat_28721010 = "근데... 왜 새를 기르고 싶은데요?",
  str_homestory_chat_28721011 = "다언과 다어에게 친구를 만들어 주고 싶습니다.\n여기 온 지도 꽤 오래되었으니까요.",
  str_homestory_chat_28721012 = "친구라... 근데 그 애들은 천간 씨가 있으면\n충분해 보이던데요?",
  str_homestory_chat_28721013 = "현지의 관습에 적응하기 위해서는 아스트라 대륙의\n친구가 필요한 법입니다.",
  str_homestory_chat_28721014 = "새로운 우정을 만들 수 있다면 좋은 일 아니겠습니까?\n허구한 날 제 곁에만 있지 말고 말이지요.",
  str_homestory_chat_28721015 = "그 애들이 좀 귀찮아지신 모양이네요...",
  str_homestory_chat_28722001 = "사탕 사려고요?",
  str_homestory_chat_28722002 = "네. 식사도 충분하고, 잠도 잘 잤더니 마음이 한가해서\n무언가를 생각하고 있었습니다.",
  str_homestory_chat_28722003 = "그리고 마침 설탕 인형이 떠오르더군요.\n그래서 츄브한테 물어보았습니다만...",
  str_homestory_chat_28722004 = "이곳에는 설탕이 매우 적다는 것을 알게 되었습니다.\n설마 여기 사람들은 달콤한 것을 싫어하는 겁니까?",
  str_homestory_chat_28722005 = "그런 건 아니에요.\n백야성이나 움브라톤엔 달콤한 디저트도 많거든요.",
  str_homestory_chat_28722006 = "화려한 무늬도 있는 케이크라든지 말이죠...",
  str_homestory_chat_28722007 = "허면 설탕 인형이 얹혀 있는 「달콤한 떡」도 있습니까?",
  str_homestory_chat_28722008 = "「떡」이 아니고 케이크요!",
  str_homestory_chat_28722009 = "아무튼 달콤한 맛 아닙니까.\n그렇다면 차이는 없습니다.",
  str_homestory_chat_28722010 = "...뭐, 됐어요. 예쁜 꽃이 장식된 케이크를\n본 적 있긴 해요.",
  str_homestory_chat_28722011 = "설탕 인형이라면... 제 기억엔 없는 것 같네요.",
  str_homestory_chat_28722012 = "그럼 제가 나설 차례로군요.\n절 언제 데려가 주실 수 있으십니까?",
  str_homestory_chat_28722013 = "그건... 당분간은 힘들 것 같은데요.",
  str_homestory_chat_28723001 = "뭔가 계획이 있나요?",
