  str_homestory_chat_31824022 = "오늘은 날씨가 좋다.\n휴식 시간을 즐기러 가는 것도 좋을 거다.",
  str_homestory_chat_31824023 = "네!",
  str_homestory_chat_31825001 = "친구들을 만나러 갈 생각이에요.",
  str_homestory_chat_31825002 = "항상 친구들한테 도움을 받아 왔으니까요.",
  str_homestory_chat_31825003 = "그리고 이스타반 씨한테도...앗! 말해버렸네... 깜짝 방문은 글렀네요.",
  str_homestory_chat_31825004 = "자네의 마음을 들을 수 있어서 기쁘군.",
  str_homestory_chat_31825005 = "하지만 나 같은 나이가 되면,\n깜짝 선물은 필요하지 않게 된다.",
  str_homestory_chat_31825006 = "그럼 너무 지루하잖아요.",
  str_homestory_chat_31825007 = "그림자는 본래 평온하고, 동요하지 않는 법이다.",
  str_homestory_chat_31825008 = "그치만 재미있잖아요.",
  str_homestory_chat_31825009 = "의외의 일이 모두 재미있는 것은 아니지.",
  str_homestory_chat_31825010 = "나는 평온한 생활을 더 좋아한다.",
  str_homestory_chat_31825011 = "휴, 제가 말실수를 해서 계획이 재미없어졌네요.",
  str_homestory_chat_31825012 = "난 그 깜짝 선물이 뭔지 아직 모른다만.",
  str_homestory_chat_31825013 = "그러니 자네도 실패한 것은 아니다.",
  str_homestory_chat_31825014 = "그럼 지금 바로 갈 준비할게요!",
  str_homestory_chat_31825015 = "좋다, 되도록 캐묻지 않도록 하지.",
  str_homestory_chat_31825016 = "부디 자네의 깜짝 선물이 재미있길 바라지.",
  str_homestory_chat_31825017 = "걱정 마세요. 실망시키지 않을 테니까요!",
  str_homestory_chat_31825018 = "모처럼 돌아온 소중한 휴일이니까요.",
  str_homestory_chat_31825019 = "부디 그림자가 지켜보길 바라며...\n기다리고 있겠다.",
  str_homestory_chat_31999999 = "달링, 지금 뭐 해야 할 일 있니?",
  str_homestory_chat_31921001 = "딱히 없네요.",
  str_homestory_chat_31921002 = "지금 막 들어온 상품이 있는데, 주인을 찾고 있거든.",
  str_homestory_chat_31921003 = "관심 있니?",
  str_homestory_chat_31921004 = "상품이요? 어떤 상품인데요?",
  str_homestory_chat_31921005 = "용주 대륙에서 온 옥기야.",
  str_homestory_chat_31921006 = "옥기요?",
  str_homestory_chat_31921007 = "응, 처음 들어보니?",
  str_homestory_chat_31921008 = "네.",
  str_homestory_chat_31921009 = "그럼 한번 보러 와.\n절대 실망시키지 않을 테니까.",
  str_homestory_chat_31921019 = "크흠... 그치만 제가 감당할 수 있는 가격은\n아닐 것 같은데요...",
  str_homestory_chat_31921020 = "그럴 리가~ 뭐, 괜찮아. 마음이 바뀌면 언제든지 와.",
  str_homestory_chat_31922001 = "지금 마침 딱 할 일이 없네요.",
  str_homestory_chat_31922002 = "그러니까 할 일이 없어서 지루하다는 거지?",
  str_homestory_chat_31922003 = "그렇게 말할 수도 있겠죠.",
  str_homestory_chat_31922004 = "그럼 나랑 게임 하나 할래?",
  str_homestory_chat_31922005 = "게임이요? 어떤 게임인데요?",
  str_homestory_chat_31922006 = "아주 간단한 게임이야.",
  str_homestory_chat_31922007 = "여기 나이티움 하나가 있어.\n내가 그걸 공중에 던질 거야.",
  str_homestory_chat_31922008 = "그리고요?",
  str_homestory_chat_31922009 = "떨어졌을 때 앞면일지 뒷면일지 우리가 맞혀보는 거야.",
  str_homestory_chat_31922010 = "맞히면 이 나이티움은 네 거야.",
  str_homestory_chat_31922011 = "틀리면요?",
  str_homestory_chat_31922012 = "틀리면 그냥 틀린 거지.",
  str_homestory_chat_31922013 = "?",
  str_homestory_chat_31922014 = "다시 말해서 틀려도 상관없다는 거야.\n넌 아무것도 내놓을 필요가 없어.",
  str_homestory_chat_31922015 = "그러면 샤엘 씨가 손해 보는 거 아닌가요?",
  str_homestory_chat_31922016 = "어머, 신경 써 주는 거니? 고마워.\n하지만 고작 나이티움 한 개일 뿐이잖아?",
  str_homestory_chat_31922017 = "이게 가져다줄 가치는 본연의 가치 이상일 거야.\n게다가 내가 꼭 진다는 법도 없잖아? 안 그래?",
  str_homestory_chat_31923001 = "장부 확인하는 중이에요.",
  str_homestory_chat_31923002 = "장부에 무슨 문제라도 있니?\n필요하면 말해. 도와줄게.",
  str_homestory_chat_31923003 = "진짜요?",
  str_homestory_chat_31923004 = "후훗, 너무 서먹하게 굴지 마.",
  str_homestory_chat_31923005 = "내가 고민을 좀 덜어줄 테니까.",
  str_homestory_chat_31923006 = "...음, 그렇구나. 이 장부는 조금 대충 적은 것 같아.",
  str_homestory_chat_31923007 = "그건 좀...",
  str_homestory_chat_31923008 = "괜찮아, 이해해. 장부는 조직의 가장 중요한 정보니까.",
  str_homestory_chat_31923009 = "그래도 장부 관리는 내가 꽤 경험이 많은데,\n조언 좀 해줄까?",
  str_homestory_chat_31923010 = "정말요?\n샤엘 씨 조언이라면 분명히 큰 도움이 될 것 같아요!",
  str_homestory_chat_31923011 = "고마워요!",
  str_homestory_chat_31923012 = "후훗, 천만에.",
  str_homestory_chat_31923013 = "그저 약간의 경험과 노하우일 뿐이야.",
  str_homestory_chat_31923014 = "장부를 적을 땐 가능한 한 상세하게,\n그러면서도 명확하고 간결해야 돼.",
  str_homestory_chat_31923015 = "날짜는 말할 것도 없고, 용도도 따로 열을 만들고,\n금액을 두 형식으로 기록하면 착오를 줄일 수 있어.",
  str_homestory_chat_31923016 = "그렇게 하면 확인할 때도 더 편할 거야.",
  str_homestory_chat_31923017 = "오... 그랬군요.",
  str_homestory_chat_31923018 = "그리고...",
  str_homestory_chat_31923019 = "앗! 잠깐만요, 메모 좀 할게요!",
  str_homestory_chat_31924001 = "목이 말라서 뭔가 마실까 생각 중이었어요.",
  str_homestory_chat_31924002 = "그럼 커피는 어때?",
  str_homestory_chat_31924003 = "커피요?",
  str_homestory_chat_31924004 = "응, 마침 좋은 원두를 샀거든.",
  str_homestory_chat_31924005 = "네가 시음해 주면 좋을 것 같아.",
  str_homestory_chat_31924006 = "전 커피에 대해선 잘 모르는데요...",
  str_homestory_chat_31924007 = "걱정 마. 마신 뒤에 느낀 점을 말해주기만 하면 돼.",
  str_homestory_chat_31924008 = "그럼 얼마든지요. 저 맛보는 거 좋아하거든요.",
  str_homestory_chat_31924009 = "샤엘 씨는 커피 좋아하시나요?",
  str_homestory_chat_31924010 = "특별히 좋아하는 건 아니지만, 물론 싫어하지도 않아.",
  str_homestory_chat_31924011 = "그럼 왜 굳이 손이 많이 가는 원두를 사신 건데요?",
  str_homestory_chat_31924012 = "특별한 이유는 없어.\n원두는 원래부터 공중상회에서 다루던 품목이거든.",
  str_homestory_chat_31924013 = "그냥 갑자기 직접 맛을 확인하고 싶어졌을 뿐이야.",
  str_homestory_chat_31925001 = "이제 공부할 시간이에요.",
  str_homestory_chat_31925002 = "공부?",
  str_homestory_chat_31925003 = "책 읽는 거죠.",
  str_homestory_chat_31925004 = "그렇구나. 어떤 책을 읽는지 물어봐도 될까?",
  str_homestory_chat_31925005 = "인문지리학에 관한 책이에요.",
  str_homestory_chat_31925006 = "그거라면 나도 조금 아는 분야네.\n재미있는 책이 있는데, 소개해 줄까?",
  str_homestory_chat_31925007 = "샤엘 씨는 이쪽 지식도 있으신 건가요?",
  str_homestory_chat_31925008 = "상인이라면 지식은 많을수록 좋거든.\n다른 업계 고객과도 대화가 쉬워지니까.",
  str_homestory_chat_31925009 = "역시 훌륭한 상인이 되는 것도 힘든 일이네요...",
  str_homestory_chat_31925010 = "경제학에 관한 책이에요.",
  str_homestory_chat_31925011 = "어머, 경제학에 관심이 있니?",
  str_homestory_chat_31925012 = "관심이 있다기보다는 그냥 호기심이랄까요.",
  str_homestory_chat_31925013 = "그리고 책을 많이 읽으면 손해 볼 일 없잖아요?",
  str_homestory_chat_31925014 = "맞아, 나도 그렇게 생각해.",
  str_homestory_chat_31925015 = "내 서재엔 너한테 추천할 만한 책이 많이 있어.",
  str_homestory_chat_31925016 = "기회가 되면 꼭 한번 와 줘.",
  str_homestory_chat_32099999 = "사무실을 개조하고 싶어!\n어떤 스타일이 좋을 것 같아?",
  str_homestory_chat_32021001 = "북방 스타일은 어떨까요?",
  str_homestory_chat_32021002 = "오? 북방의 건물이나 장식은 동화 같은 분위기잖아.",
  str_homestory_chat_32021003 = "넌 낭만적인 애였구나.",
  str_homestory_chat_32021004 = "알골 씨는 과학자니까...",
  str_homestory_chat_32021005 = "「낭만」이란 말을 별로 안 좋아하시겠죠?",
  str_homestory_chat_32021006 = "알골 씨는 일루미나 연방 사람이니까...",
  str_homestory_chat_32021007 = "「낭만」이라는 실속 없는 단어에 거부감이 있겠죠?",
  str_homestory_chat_32021008 = "그건 아주 큰 오해야!",
  str_homestory_chat_32021009 = "뭐, 그래.\n사실 「과학자」나 「일루미나 연방」이라고 하면...",
  str_homestory_chat_32021010 = "첫인상은 확실히 낭만과는 거리가 멀어 보이겠지.",
  str_homestory_chat_32021011 = "하지만 그건 「낭만」에 대한 이해가 너무 좁은 거야.",
  str_homestory_chat_32021012 = "미지의 것을 아는 것으로 만들고,\n황야에 도시를 건설하는 것도...",
  str_homestory_chat_32021013 = "어떻게 보면 일종의 낭만 아닐까?",
  str_homestory_chat_32021014 = "그렇게 말하니까 왠지 일리가 있는 것 같네요.",
  str_homestory_chat_32021015 = "알골 씨가 웅변가일 줄은 정말 몰랐네요.",
  str_homestory_chat_32021016 = "난 친구의 조언을 받아들이는 것도 잘하는 사람이야.",
  str_homestory_chat_32021017 = "그럼 사무실의 새로운 스타일은 「북방」으로 하자!",
  str_homestory_chat_32022001 = "백야성 스타일은 어떨까요?",
  str_homestory_chat_32022002 = "백야성 스타일은 무척 클래식하고,\n종교적인 분위기가 가득해.",
  str_homestory_chat_32022003 = "배선과 기계들로 가득 찬 내 사무실과는\n안 어울릴 것 같은데...",
  str_homestory_chat_32022004 = "알골 씨 스스로가 이미 개성이 넘치잖아요.",
  str_homestory_chat_32022005 = "그런 상반된 분위기도 어울릴 것 같아요!",
  str_homestory_chat_32022006 = "미스매치도 일종의 멋인걸요.",
  str_homestory_chat_32022007 = "꼭 조화만이 「아름다움」인 건 아니니까요.",
  str_homestory_chat_32022008 = "아하하하하... 그것도 그렇네!",
  str_homestory_chat_32022009 = "넌 식견도 있고, 문제를 보는 시각이 참 영리하구나.",
  str_homestory_chat_32022010 = "아마 평소에 여기저기 여행하면서 전 세계를\n돌아다녀서 그런 거겠지?",
  str_homestory_chat_32022011 = "알골 씨랑 알고 지내서 그런 걸지도 모르죠...",
  str_homestory_chat_32022012 = "그건 칭찬으로 받아둘게~",
  str_homestory_chat_32023001 = "움브라톤 스타일은 어떨까요?",
  str_homestory_chat_32023002 = "그건 꽤 어려운 문제 같은데 말이지.",
  str_homestory_chat_32023003 = "「움브라톤 스타일」이란 건 대체 어떤 스타일일까?",
  str_homestory_chat_32023004 = "거긴 어떤 고정된 스타일에도 얽매이지 않는 걸\n추구하는 곳 아니었어?",
  str_homestory_chat_32023005 = "그, 그게 딱 좋지 않나요...?",
  str_homestory_chat_32023006 = "제가 드린 건 한 가지 제안처럼 보이지만,\n잘 생각해 보면...",
  str_homestory_chat_32023007 = "이건 수천수만 개의 제안이 될 수 있는 거잖아요!",
  str_homestory_chat_32023008 = "앞으로 50년 동안의 사무실 스타일을\n정하는 난제를 해결해 드린 거라구요!",
  str_homestory_chat_32023009 = "오... 말하고 보니까 왠지 철학적인 느낌까지 있네요.\n역시 저라니까요.",
  str_homestory_chat_32023010 = "그냥 답하기 곤란하니까 애써 둘러댄 거겠지...",
  str_homestory_chat_32023011 = "헤헤... 들켰어요?",
  str_homestory_chat_32023012 = "됐어. 네가 이렇게 된 건 내 책임도 있으니까,\n따지진 않을게.",
  str_homestory_chat_32023013 = "알고 있었어요?!",
  str_homestory_chat_32023014 = "이 천재를 얕보지 마, 여러 의미로.",
  str_homestory_chat_32024001 = "용주 스타일은 어떨까요?",
  str_homestory_chat_32024002 = "우와, 잘도 말하네...",
  str_homestory_chat_32024003 = "그 대륙의 인테리어는 나도 항상 동경해 왔어...",
  str_homestory_chat_32024004 = "근데 너 거기 돈이 얼마나 드는지 알아?",
  str_homestory_chat_32024005 = "나무 의자 하나 가격으로...",
  str_homestory_chat_32024006 = "사무실의 컴퓨터를 전부 업그레이드할 수 있다고!",
  str_homestory_chat_32024007 = "우리 같은 평범한 사람들은 꿈꿀 수 없는 거야.",
  str_homestory_chat_32024008 = "「평범한 사람」이요?",
  str_homestory_chat_32024009 = "제가 살면서 알골 씨가 자길 「평범한 사람」이라고\n말하는 걸 들을 줄은 몰랐네요...",
  str_homestory_chat_32024010 = "게다가 저도 동급으로 쳐준다니...",
  str_homestory_chat_32024011 = "고마워, 용주 대륙!",
  str_homestory_chat_32024012 = "진짜요?",
  str_homestory_chat_32024013 = "용주의 가구가 그렇게 비싼 줄은 몰랐어요...",
  str_homestory_chat_32024014 = "실례했어, 용주 대륙!",
  str_homestory_chat_32024015 = "...크윽, 용주 가구가 또 갖고 싶어져 버렸잖아.",
  str_homestory_chat_32024016 = "책임져!",
  str_homestory_chat_32024017 = "그런 돈 없거든요!",
  str_homestory_chat_32025001 = "아이테르 스타일은 어떨까요?",
  str_homestory_chat_32025002 = "자길 추천하다니, 완전 의외의 대답이네.",
  str_homestory_chat_32025003 = "제가 추천한 건 아이테르 일족의 인테리어인데요...",
  str_homestory_chat_32025004 = "네가 직접 리모델링해 주러 올 거지?",
  str_homestory_chat_32025005 = "그런 의미로 말한 게 아닌데요?!",
  str_homestory_chat_32025006 = "하지만 지금 이 세상에서...",
  str_homestory_chat_32025007 = "아이테르 스타일을 잘 아는 건 너뿐이잖아?",
  str_homestory_chat_32025008 = "꼬, 꼭 그렇진 않을지도 모르잖아요?",
  str_homestory_chat_32025009 = "일루미나나 백야성 같은 곳엔 역사학자나\n고고학자들이 많이 있으니까...",
  str_homestory_chat_32025010 = "아이테르 스타일에 대한 연구도 많이 했을 거예요.",
  str_homestory_chat_32025011 = "하지만 널 제쳐두고 굳이 그들한테 부탁하러 갈 이유를...",
  str_homestory_chat_32025012 = "하나라도 떠올릴 수 있겠어?",
  str_homestory_chat_32025013 = "...없는 것 같아요.",
  str_homestory_chat_32025014 = "반대로 제가 아니면 안 될 이유라면\n얼마든지 떠올릴 수 있지만요.",
  str_homestory_chat_32025015 = "예를 들면 비용이 더 저렴하다거나... 저렴하다거나...\n더 많이 저렴하겠죠...",
  str_homestory_chat_32025016 = "아하하, 그렇게까지 자길 낮출 필요는 없어.",
  str_homestory_chat_32025017 = "너라면 내 방을 멋지게 만들어 줄 거라고 믿거든.",
  str_homestory_chat_32025018 = "그리고 너랑 얘기하면 즐거워.",
  str_homestory_chat_32025019 = "이유는 그거면 충분해.",
  str_homestory_chat_32199999 = "그대의 소원은 무엇이냐?",
  str_homestory_chat_32121001 = "세계 평화.",
  str_homestory_chat_32121002 = "오오, 그런 이타적인 소원을 빌다니!",
  str_homestory_chat_32121003 = "소원을 진지하게 생각하지 않았거나...",
  str_homestory_chat_32121004 = "큰 뜻을 품은 것이겠구나.",
  str_homestory_chat_32121005 = "PlayerName 그대는 어느 쪽이냐.",
  str_homestory_chat_32121006 = "진지하게 생각 안 했어.",
  str_homestory_chat_32121007 = "후후, 역시 그대답구나.",
  str_homestory_chat_32121008 = "미래를 기도에 맡기면 안 되느니라. 무언가를 바란다면 먼저 그것을 실현하기 위해 행동해야 하는 법...",
  str_homestory_chat_32121009 = "난 큰 뜻이 있어.",
  str_homestory_chat_32121010 = "하면 「세계 평화」가 그대의 진짜 목표라는 것이로구나.",
  str_homestory_chat_32121011 = "한 걸음 한 걸음, 어떻게 하면 거기에 가까워질 수 있는지, 진지하게 생각하고 있겠지...",
  str_homestory_chat_32121012 = "수천 년을 살아온 이 몸은 그대 같은 인간이 가장 골치가 아프니라.",
  str_homestory_chat_32121013 = "어? 왜?",
  str_homestory_chat_32121014 = "왜냐하면 세상을 바꾸는 것은 바로 그러한 사람들이기 때문이니라.",
  str_homestory_chat_32122001 = "가족이나 친구의 평안?",
  str_homestory_chat_32122002 = "그런 소원은 이 몸도 사당에서 자주 듣느니라.",
  str_homestory_chat_32122003 = "이 몸은 종종 생각한다. 그렇게 소원을 빌고 있는 사람은 과연 행복한가, 불행한가 말이야.",
  str_homestory_chat_32122004 = "물론 행복하지!",
  str_homestory_chat_32122005 = "그건 그 사람 주변에 친구들이 있고, 그 사람한테 즐거움을 준다는 뜻이잖아...",
  str_homestory_chat_32122006 = "그런데 어떻게 불행하겠어?",
  str_homestory_chat_32122007 = "허나 즐거움은 언제나 쉬이 지나가는 것이니라.",
  str_homestory_chat_32122008 = "......!",
  str_homestory_chat_32122009 = "소원을 빌고 있는 자도 그것을 알고 있기에 소원을 빌러 오는 것이 아니겠느냐.",
  str_homestory_chat_32122010 = "...맞는 말이네.",
  str_homestory_chat_32122011 = "암귀가 활개치는 이 세상에선 누구나 언제든지 위험에 처할 수 있어.",
  str_homestory_chat_32122012 = "그래서 나도 내 친구들을 지키기 위해 최선을 다하고 있어.",
  str_homestory_chat_32122013 = "그게 설령 「소원 빌기」 같은 사소한 방법이라 해도 말이야.",
  str_homestory_chat_32122014 = "흐음, 하늘의 뜻은 변덕스럽다만, 인간은 항상 그 변덕 속에서 힘을 얻곤 하지.",
  str_homestory_chat_32122015 = "하여 인간이 존경하고 두려워할 만한 것이니라.",
  str_homestory_chat_32123001 = "세계 곳곳을 가고 싶어.",
  str_homestory_chat_32123002 = "호오? PlayerName, 신기한 소원을 비는구나.",
  str_homestory_chat_32123003 = "허나 세상을 누비고 싶다면 그저 가면 되는 것이 아니더냐? 어찌 굳이 소원을 비는 게냐?",
  str_homestory_chat_32123004 = "혹여 무슨 어려움에라도 부딪힌 것이냐?",
  str_homestory_chat_32123005 = "돈이 없어.",
  str_homestory_chat_32123006 = "「한가함을 즐기는 자도 있으나, 궁핍과 굶주림에 시달리는도다.」",
  str_homestory_chat_32123007 = "허나 그것은 간단한 문제 아니더냐! 이 몸의 보석을 전당포에 맡기거라.",
  str_homestory_chat_32123008 = "암귀가 너무 많아.",
  str_homestory_chat_32123009 = "「곰이 길에서 나를 보고 웅크리고, 맹호와 표범이 길가에서 울부짖네.」",
  str_homestory_chat_32123010 = "허나 이 몸이 그대와 함께 있다면, 맹수나 암귀도 두려워할 것이 없지 않느냐?",
  str_homestory_chat_32123011 = "그나저나 PlayerName 그대는 이 몸이 읊는 시를 이해할 수 있느냐?",
  str_homestory_chat_32123012 = "용주에서 여행할 때 자주 보긴 했어.",
  str_homestory_chat_32123013 = "잘 듣고 생각하다 보면 이해가 되긴 해.",
  str_homestory_chat_32123014 = "과연 PlayerName 그대는 여행하면서 성장하는 것에 참으로 능숙한지고.",
  str_homestory_chat_32123015 = "칭찬 고마워!",
  str_homestory_chat_32123016 = "근데 진예 넌 내 소중한 여행 친구야. 그러니까 힘든 일을 죄다 떠맡기고 싶진 않아.",
  str_homestory_chat_32123017 = "난 세계 여행이라는 내 목표를 위해 계속 노력해서 성장할게!",
  str_homestory_chat_32123018 = "좋은 마음가짐로구나, 이 몸도 기다리고 있으마.",
  str_homestory_chat_32124001 = "콜로서스에 틀어박힐래.",
  str_homestory_chat_32124002 = "이 몸도 이해한다! 자신의 둥지에 틀어박혀 있는 것보다 안심이 되는 일이 또 무엇이 있겠느냐.",
  str_homestory_chat_32124003 = "그치? 가끔은 안 나가고 집에서 휴일을 보내는 것도 참 편하다니까~",
  str_homestory_chat_32124004 = "특히 눈이 내리는 겨울엔...",
  str_homestory_chat_32124005 = "간식이랑 음료를 준비해서 이불 속에서 밤새 좋아하는 책을 읽어...",
  str_homestory_chat_32124006 = "그렇게 많은 일을 한단 말이냐?",
  str_homestory_chat_32124007 = "이 몸은 계속 잠만 자느니라.",
  str_homestory_chat_32124008 = "그럼 다음에 너도 나처럼 한번 해 봐.",
  str_homestory_chat_32124009 = "생각만 해도 재미있을 것 같구나!",
  str_homestory_chat_32124010 = "그럼... 이 몸은 먼저 몸을 덮을 큰 이불을 주문해야겠다!",
  str_homestory_chat_32124011 = "그럼 다음에 나도 진예 너처럼 해볼게.",
  str_homestory_chat_32124012 = "좋다! 하면 이 몸도 옆에서 함께 있어주마. 용과 함께 잠드는 게다~",
  str_homestory_chat_32124013 = "그리하면 PlayerName 그대가 제시간에 이 몸을 깨워줄 테니 말이야.",
