  str_homestory_chat_32124015 = "「일족의 부활」 같은 소원을 빌 것이라 생각했다만...",
  str_homestory_chat_32124016 = "그건 이미 바꿀 수 없는 일이잖아...",
  str_homestory_chat_32124017 = "「소원」이란 건 지금 자신이나 친구들을 더 행복하게 만드는 것이어야 하지 않을까?",
  str_homestory_chat_32124018 = "좋은 일이로구나. 필요할 때 결단을 내릴 수 있는 것 또한 용기가 아니겠느냐?",
