  str_homestory_chat_32125002 = "하아? 얻기 어려운 소원의 기회를 어찌 이 몸을 위해 쓰는 게냐.",
  str_homestory_chat_32125003 = "이유가 무엇이냐.",
  str_homestory_chat_32125004 = "「소원」을 이란 건 당연히 친구를 위해서 쓸 수도 있는 거잖아?",
  str_homestory_chat_32125005 = "그리고 난 내가 원하는 건 소원을 비는 것보단 스스로 이루고 싶어.",
  str_homestory_chat_32125006 = "...하하, 방금 그 대사 좀 멋있지 않았어? 항상 말해보고 싶었어!",
  str_homestory_chat_32125007 = "...음.",
  str_homestory_chat_32125008 = "웃어넘길 것 없느니라. 이 몸도 비웃거나 하진 않을 테니 말이야.",
  str_homestory_chat_32125009 = "그럼 이 몸도 소원을 빌어보마.",
  str_homestory_chat_32125010 = "어? 신이 소원을 비는 거야? 그거 엄청 보기 힘든 일 아냐?",
  str_homestory_chat_32125011 = "태양과 달은 늘 밝게 빛나고, 강과 바다는 유유히 흐른다.",
