  str_homestory_chat_32399999 = "좋아하는 동물로 변신할 수 있다면,\n뭐가 되고 싶어?",
  str_homestory_chat_32321001 = "눈여우.",
  str_homestory_chat_32321002 = "오! 그래, 눈여우 좋지!",
  str_homestory_chat_32321003 = "움직임도 민첩하고, 사냥에 능숙할 뿐만 아니라,\n눈의 풍경에 녹아들어 몸을 지킬 수 있으니까!",
  str_homestory_chat_32321004 = "생존 능력이 아주 강하다고!\n너 뭘 좀 아는구나.",
  str_homestory_chat_32321005 = "음... 사실 난 그냥...",
  str_homestory_chat_32321006 = "귀여운 게 좋을 뿐이야.",
  str_homestory_chat_32321007 = "눈여우는 털이 복슬복슬하고 정말 귀엽잖아.",
  str_homestory_chat_32321008 = "모든 사냥꾼이 너처럼 대단하다면...",
  str_homestory_chat_32321009 = "마음 약하게 만드는 귀여운 동물로 변하는 게\n좋을 것 같거든!",
  str_homestory_chat_32321010 = "네가 눈여우를 소중히 여기니까...",
  str_homestory_chat_32321011 = "눈여우가 되면 네 보호를 받으면서\n평화롭게 살 수 있을지도 모르잖아...",
  str_homestory_chat_32321012 = "아주 합리적이지?!",
  str_homestory_chat_32321013 = "그건 완전히 오로리안식 마인드잖아!",
  str_homestory_chat_32321014 = "설원에서 살아가는 동물들은 결코 오로리안에게\n잘 보이려 하지 않아.",
  str_homestory_chat_32321015 = "크흠... 미안한데 난 동물도 아니고 오로리안도 아냐.",
  str_homestory_chat_32321016 = "늘 생존을 최우선으로 생각하는 나약한 아이테르라고.",
  str_homestory_chat_32322001 = "곰.",
  str_homestory_chat_32322002 = "......",
  str_homestory_chat_32322003 = "PlayerName...",
  str_homestory_chat_32322004 = "왜 그래? 갑자기 그런 동정하는 눈빛으로 보고.",
  str_homestory_chat_32322005 = "그럴 리가 없잖아? 그런 거 아냐. 난 다 이해해.",
  str_homestory_chat_32322006 = "넌 힘도 없고, 가볍게 밀기만 해도 쓰러지니까.\n그래서...",
  str_homestory_chat_32322007 = "튼튼하고 강인한 곰을 동경하는 것도\n당연하다고 생각해.",
  str_homestory_chat_32322008 = "응, 다 이해한다니까!",
  str_homestory_chat_32322009 = "...대체 뭘 이해한다는 거야?!",
  str_homestory_chat_32322010 = "「힘도 없고, 가볍게 밀기만 해도 쓰러진다」는 건\n좀 심하잖아...!",
  str_homestory_chat_32322011 = "난 그냥...",
  str_homestory_chat_32322012 = "그냥?",
  str_homestory_chat_32322013 = "그냥 곰은 겨울 동안 계속 잘 수 있으니까,\n그게 부러웠을 뿐이야!",
  str_homestory_chat_32322014 = "PlayerName...",
  str_homestory_chat_32322015 = "...너 왜 아까보다 더 동정하는 눈빛으로 보는 거야?",
  str_homestory_chat_32323001 = "갈매기.",
  str_homestory_chat_32323002 = "오...! 수수께끼의 음식 「감자튀김」을 먹고 사는\n그 새 말이지?",
  str_homestory_chat_32323003 = "뭐? 잠깐만...",
  str_homestory_chat_32323004 = "갈매기가 왜 감자튀김을 먹고 살아? 틀렸잖아!",
  str_homestory_chat_32323005 = "정확히 말하자면... 갈매기는 편식을 안 해.",
  str_homestory_chat_32323006 = "과일, 해조류, 물고기, 곤충... 뭐든지 다 먹거든,\n물론 감자튀김도 먹고.",
  str_homestory_chat_32323007 = "자유로운 마음으로 뭐든지 도전하는 거지...",
  str_homestory_chat_32323008 = "내 이상적인 삶의 방식과도 딱 맞다니까!",
  str_homestory_chat_32323009 = "으음, 그렇게 말하니까 확실히 네가\n그런 말을 했었던 것 같아...",
  str_homestory_chat_32323010 = "세상의 구석구석을 다니면서 뭐든지 보러 가고 싶다고 말이야.",
  str_homestory_chat_32323011 = "그럼 새가 정말 딱 맞겠네!",
  str_homestory_chat_32323012 = "세상을 누비려면 당연히 날개가 있어야지.",
  str_homestory_chat_32323013 = "콜로서스가 내 날개야.",
  str_homestory_chat_32323014 = "티아라 너도 원한다면 나랑 함께 여행해도 좋아!",
  str_homestory_chat_32323015 = "설마 감자튀김만 먹고 사는 건 아니겠지...?",
