  str_homestory_chat_32324001 = "토끼.",
  str_homestory_chat_32324002 = "호오? 무척 특별한 선택이네.",
  str_homestory_chat_32324003 = "토끼는 싸울 힘이 거의 없어.\n그래서 자연계에서 먹이사슬의 바닥에 있어.",
  str_homestory_chat_32324004 = "근데 넌 왜 그렇게 약한 동물이 되고 싶은 거야?",
  str_homestory_chat_32324005 = "토끼는 약하지 않아.",
  str_homestory_chat_32324006 = "그 누구도 토끼에겐 경계심을 갖지 않잖아?",
  str_homestory_chat_32324007 = "그 온순하고 무해해 보이는 외모가 바로\n토끼가 가진 최강의 무기인 거야.",
  str_homestory_chat_32324008 = "아니면 노비오 씨가 왜 토끼를 정보 수집을\n맡기는 동료로 삼았겠어?",
  str_homestory_chat_32324009 = "난 선수를 치는 것보다는 상대의 공격을 보고\n대응하는 쪽이 더 익숙해.",
  str_homestory_chat_32324010 = "토끼는 청각이 예민하잖아.",
  str_homestory_chat_32324011 = "보이지 않는 곳에 숨어서, 주변의 조그만 움직임도\n귀로 들을 수 있어.",
  str_homestory_chat_32324012 = "그렇게 얻은 정보는 분명 모두에게 도움이 될 거야.",
  str_homestory_chat_32324013 = "그런 점이 감응 능력을 가진 아이테르랑\n닮았다고 생각하지 않아?",
  str_homestory_chat_32324014 = "일리가 있네. 역시 아이테르라니까.\n오로리안과는 다른 시각을 가지고 있잖아?",
