  str_homestory_chat_32522012 = "사냥감을 찢어 삼키고, 두개골을 물고\n둥지로 가져가는 거지──",
  str_homestory_chat_32522013 = "아, 아니, 잠깐만!",
  str_homestory_chat_32522014 = "왜 네가 말하면 왜 이상한 느낌이 드는 건데?!",
