  str_homestory_chat_32523005 = "창고 정리를 강요하는 바이스,\n의뢰 수락을 강요하는 바이스...",
  str_homestory_chat_32523006 = "방 청소를 강요하는 바이스,\n암흑 요리를 먹으라고 강요하는 바이스...",
  str_homestory_chat_32523007 = "...모든 말에 「강요」란 단어가 있는 게 신경 쓰이지만,\n네가 하고 싶은 말은 알겠어.",
  str_homestory_chat_32523008 = "아무튼 그러니까 바이스 중위의 다양한 모습을\n보고 싶다는 거지?",
