  str_homestory_chat_32621002 = "운동하러 가려고.",
  str_homestory_chat_32621003 = "그렇구나, 육체 단련의 수련이야?",
  str_homestory_chat_32621004 = "역시 내가 선택한 동료답게 평일에도\n게으른 모습을 보이지 않는구나.",
  str_homestory_chat_32621005 = "제타 너도 평소에 훈련하고 있는 거야?",
  str_homestory_chat_32621006 = "난 지력계와 매력계의 용사니까,\n훈련하지 않아도 강해.",
  str_homestory_chat_32621007 = "예를 들어서, 너 사자가 훈련하는 거 본 적 있어?",
  str_homestory_chat_32621008 = "태어날 때부터 강한 사람이 더 강해지기 위해\n노력하는 건 매우 비열한 행위야!",
  str_homestory_chat_32621009 = "잠깐 쉬려고.",
  str_homestory_chat_32621010 = "그렇구나, 앞으로의 힘든 전투에 대비하려는 거야?",
  str_homestory_chat_32621011 = "역시 내가 선택한 동료답게 평일에도\n워라밸을 중요시하고 있네.",
  str_homestory_chat_32621012 = "제타도 맨날 편식한다는 소리를 듣고,\n사탕도 너무 많이 먹지만...",
  str_homestory_chat_32621013 = "대신 적극적으로 비타민 사탕을 먹어서\n영양 균형을 중요시하고 있거든.",
  str_homestory_chat_32621014 = "아, 이런. 그 녀석들이랑 약속한 시간이네. 먼저 갈게.",
  str_homestory_chat_32621015 = "응, 나중에 또 보자.",
  str_homestory_chat_32622001 = "이따가 중요한 일을 할 게 있거든.",
  str_homestory_chat_32622002 = "중요한 일? 뭔가 좀 수상한데...",
  str_homestory_chat_32622003 = "동료한테도 비밀로 해야 할 정도로 중요한 일이야?",
  str_homestory_chat_32622004 = "과거의 나쁜 인연을 끊기 위해 조용히 떠나\n혼자 운명에 맞서는 건가...",
  str_homestory_chat_32622005 = "걱정 마, 넌 혼자가 아냐. 제타가 같이 있어 줄 테니까!",
  str_homestory_chat_32622006 = "그냥 콜로서스의 유지보수 작업인데.",
  str_homestory_chat_32622007 = "엥? 재미없게.",
  str_homestory_chat_32622008 = "서류 정리 좀 도와줄래?",
  str_homestory_chat_32622009 = "아? 그게 다야?",
  str_homestory_chat_32622010 = "콜록... 갑자기 할 일이 생각났어.",
  str_homestory_chat_32622011 = "용사도 바쁜 사람이거든! 그럼 이만!",
  str_homestory_chat_32623001 = "딱히 할 일 없어.",
  str_homestory_chat_32623002 = "할 일이 없다는 건 아무 일도 생기지 않는다는 거네.",
  str_homestory_chat_32623003 = "하지만 세상을 구할 용사 일행의 일원으로서\n긴장을 늦추면 안 돼.",
  str_homestory_chat_32623004 = "잠복 중인 악마를 찾아내는 안목이 있어야 한다구.",
  str_homestory_chat_32623005 = "괜히 사고 치지 마.",
  str_homestory_chat_32623006 = "넌 그냥 세상이 혼란스러워지길 바라는 거 아니야?",
  str_homestory_chat_32623007 = "걱정 마, 난 용사 제타라구.\n사람들한테 폐를 끼치는 일은 안 해.",
  str_homestory_chat_32623008 = "네가 그런 다짐을 하니까 오히려 걱정이 된단 말이지...",
  str_homestory_chat_32624001 = "간식을 좀 먹고 싶어.",
  str_homestory_chat_32624002 = "간식? 그럼 마침 잘 만났네.",
  str_homestory_chat_32624003 = "봐, 나한테 사탕이 잔뜩 있다구. 마음껏 먹어.",
  str_homestory_chat_32624004 = "근데 난 짭짤한 게 먹고 싶은데...",
  str_homestory_chat_32624005 = "짭짤한 사탕도 있어. 예를 들면... 부트 졸로키아 사탕.",
  str_homestory_chat_32624006 = "부트 졸로키아를 써서 만든 사탕인데,\n숨을 못 쉴 정도로 매워.",
  str_homestory_chat_32624007 = "근데 난 한 번도 안 먹어봤어.\n그래서 진짜 그렇게 매운진 잘 모르겠어.",
  str_homestory_chat_32624008 = "그래 놓고 나한테 그걸 먹으라고...?",
  str_homestory_chat_32624009 = "그럼 사양 안 할게.",
  str_homestory_chat_32624010 = "응, 마음껏 먹어. 대신 먹을 때 조심해.\n폭탄이 하나 섞여 있거든.",
  str_homestory_chat_32624011 = "포...폭탄? 어느 건데?",
  str_homestory_chat_32624012 = "왜, 구분 못 하겠어? 이렇게 알아보기 쉬운데?",
  str_homestory_chat_32624013 = "전혀 구분이 안 된다고...",
  str_homestory_chat_32624014 = "어쩔 수 없네. 그럼 내가 골라줄게. 자, 이거 먹어.",
  str_homestory_chat_32624015 = "그럼 난 다른 할 일이 있으니까, 먼저 갈게~",
  str_homestory_chat_32799999 = "요즘 해보고 싶은 게임 있어?",
  str_homestory_chat_32721001 = "RPG.",
  str_homestory_chat_32721002 = "음~ 근본 장르네.",
  str_homestory_chat_32721003 = "그럼 이유는?",
  str_homestory_chat_32721004 = "게임 속 환경이 좋아서? 아니면 스토리?",
  str_homestory_chat_32721005 = "환경이 좋아.",
  str_homestory_chat_32721006 = "다른 세계에 들어간 듯한 느낌이 들어서,\n되게 신선한 기분이 돼.",
  str_homestory_chat_32721007 = "아하, 체험 중시형이구나. 알겠어.",
  str_homestory_chat_32721008 = "스토리가 좋아.",
  str_homestory_chat_32721009 = "대부분 용사가 악당을 물리치는 내용이긴 하지만...",
  str_homestory_chat_32721010 = "그래도 전혀 안 질려.",
  str_homestory_chat_32721011 = "왕도를 좋아하는 타입이구나... 이해했어.",
  str_homestory_chat_32721012 = "바티아 넌 안 좋아해?",
  str_homestory_chat_32721013 = "좋아. 다만... 특별히 어느 하나를\n좋아하는 건 아냐.",
  str_homestory_chat_32721014 = "많은 종류가 있으니까, 선택하는 과정도 즐거운 거지.",
