  str_homestory_chat_32722002 = "그럴 줄 알았어.",
  str_homestory_chat_32722003 = "난 아이테르로서 내 조종과 전투 지휘 능력을\n향상시키고 싶거든.",
  str_homestory_chat_32722004 = "그러면 암귀와 맞서 싸울 때도\n조금은 여유가 생기겠지?",
  str_homestory_chat_32722005 = "그러니까...",
  str_homestory_chat_32722006 = "전략 게임으로 암귀에 맞서는 능력을\n향상시키고 싶다는 거야?",
  str_homestory_chat_32722007 = "히, 힘들겠네...\n게임할 때까지 그런 걸 생각한다니...",
