  str_homestory_chat_32723006 = "전혀 진행이 안 될 정도야.",
  str_homestory_chat_32723007 = "얼마나 복잡한데?",
  str_homestory_chat_32723008 = "온갖 괴상한 선행 조건이 붙어서 준비만 한참 걸려.",
