  str_homestory_chat_32821001 = "돈을 만드는 기계?",
  str_homestory_chat_32821002 = "어머, 그건 정말...\n확실히 일종의 「마법」이네.",
  str_homestory_chat_32821003 = "창피한 일이지만...\n요즘 콜로서스의 유지비가 정말 부족하거든.",
  str_homestory_chat_32821004 = "이미 하루에 일을 8개나 하고 있다니까!",
  str_homestory_chat_32821005 = "그럼 진리의 결사에서 일해볼래?",
  str_homestory_chat_32821006 = "보수는 왈라키아의 명예에 절대 부끄럽지 않을 거야.",
  str_homestory_chat_32821007 = "이력서는 어디 내면 되는데?!",
  str_homestory_chat_32821008 = "그런 세속적인 건 필요 없어. 진리가 이끄는 기회가 오면 자연스레 너와 손을 잡게 될 테니까.",
