  str_homestory_chat_32821011 = "그림의 떡 같은 건 아니겠지?",
  str_homestory_chat_32821012 = "그런 생각을 하다니 정말 놀랍네.",
  str_homestory_chat_32821013 = "네가 보기엔 진리의 결사가 입으로만\n신자들을 속이는 단체 같니?",
  str_homestory_chat_32821014 = "그런 뜻은 아냐!\n그냥 최근에 양심 없는 고용주를 많이 만나서...",
  str_homestory_chat_32822001 = "투명 인간이 되는 옷?",
  str_homestory_chat_32822002 = "호오...?",
  str_homestory_chat_32822003 = "왜... 그런 눈으로 보는 거야?",
  str_homestory_chat_32822004 = "후훗...",
  str_homestory_chat_32822005 = "게다가 왜 웃는데?!",
  str_homestory_chat_32822006 = "부끄러워할 거 없어, 조종사. 그 나이면 그런 생각을 가지는 것도 자연스러운 일이니까.",
  str_homestory_chat_32822007 = "무슨 소리야?! 난 투명 인간이 될 수 있는 옷이 있으면 비밀 잠입에 편리하다고 생각했을 뿐이야!",
  str_homestory_chat_32822008 = "물론 그렇겠지. 아니면 네가 왜 그걸 원하겠어.",
  str_homestory_chat_32822009 = "대체 어떤 오해를 하고 있는 거냐고!",
  str_homestory_chat_32823001 = "자동으로 청소하는 빗자루?",
  str_homestory_chat_32823002 = "오, 「마법 도구」라는데 고작 빗자루면 되는 거야?\n네 욕망은 정말 담백하구나.",
  str_homestory_chat_32823003 = "자기가 청소하기 싫다면 하인을 고용하면 되는 거 아닐까?",
  str_homestory_chat_32823004 = "빅토리아 씨처럼 그렇게 지위가 높은 사람은 이해할 수 없겠지...",
  str_homestory_chat_32823005 = "남한테 명령하는 건 설령 돈을 주고 고용한다 해도, 좀 어색할 때가 많아.",
  str_homestory_chat_32823006 = "그치만 마법의 빗자루라면 마음껏 지시할 수 있잖아!",
  str_homestory_chat_32823007 = "그렇구나, 넌 참 상냥한 사람이네.",
  str_homestory_chat_32823008 = "하지만 너무 「자신」을 억누르고 남의 일만 생각하다 보면, 오히려 진리에서 멀어지게 될 거야.",
  str_homestory_chat_32823009 = "다른 사람을 생각하는 마음도 「자신」의 일부인걸.",
  str_homestory_chat_32823010 = "좋은 반론이네. 네 지혜와 자각은 훌륭하구나.",
