  str_homestory_chat_32823012 = "분명 자기희생의 정신으로 넘쳐나는 성도가 될 수 있을 거야. 나일즈처럼──",
  str_homestory_chat_32823013 = "그, 그럼 역시 포기할래.\n난 그냥 평범하게 살고 싶으니까!",
  str_homestory_chat_32823014 = "오만한 사람이 아니면 진리에 가까워질 수 없는 거야?",
  str_homestory_chat_32823015 = "후훗... 그 말엔 가시가 있구나. 정말 귀엽네.",
  str_homestory_chat_32823016 = "맞아. 결과로 보면 진리를 엿볼 수 있는 건 오만한 사람들뿐이야.",
  str_homestory_chat_32823017 = "그리고 네 가시 돋친 장미 같은 면도, 진리가 네게 나타나고 있다는 증거...일지도 몰라.",
  str_homestory_chat_32823018 = "그 「진리」란 분, 역시 어려운 상대 아닐까...",
  str_homestory_chat_32824001 = "시간을 거꾸로 돌리는 모래시계?",
  str_homestory_chat_32824002 = "시간을 거꾸로 돌린다... 흔한 선택이네.",
  str_homestory_chat_32824003 = "실례되는 질문이겠지만, 넌 17년 전으로 돌아가서 헤븐즈 밸리의 역사를 바꾸고 싶니?",
  str_homestory_chat_32824004 = "당연하지.",
  str_homestory_chat_32824005 = "네게 있어 그건 매우 자연스러운 생각이야.",
  str_homestory_chat_32824006 = "만약 정말 그런 기회가 있다면... 난 네 편이 될지도 모르겠네.",
  str_homestory_chat_32824007 = "어? 그렇게 역사를 크게 바꾸는 거, 다들 반대할 줄 알았는데...",
  str_homestory_chat_32824008 = "그렇게 크게 바꾸진 않을 거야.",
  str_homestory_chat_32824009 = "그랬다간 온 아스트라가 영향을 받을 테니까...",
  str_homestory_chat_32824010 = "기껏해야 그저께로 돌아가서 잃어버린 돈을 주워 오는 정도겠지... 아하하.",
  str_homestory_chat_32824011 = "...시간의 구조는 매우 심오한 거란다.",
  str_homestory_chat_32824012 = "「과거」의 형성은 보통 사람들이 생각하는 것보다 훨씬 복잡해.",
