  str_homestory_chat_32825001 = "자면서도 공부할 수 있는 약?",
  str_homestory_chat_32825002 = "......",
  str_homestory_chat_32825003 = "비, 빅토리아 씨 눈에서 깊은 반대의 감정이 느껴져...",
  str_homestory_chat_32825004 = "후훗... 네가 총명한 사람이라서 정말 다행이야.",
  str_homestory_chat_32825005 = "세상엔 「마법」을 소재로 한 소설이 참 많아...",
  str_homestory_chat_32825006 = "하지만 네가 꿈꾸는 약을 다룬 소설은 거의 없어. 왜 그런지 아니?",
  str_homestory_chat_32825007 = "작가가 대담하지 않아서?",
  str_homestory_chat_32825008 = "지식은 진리로 이어지는 유일한 길이거든.",
  str_homestory_chat_32825009 = "배우는 것만큼은 속여서는 안 돼.",
  str_homestory_chat_32825010 = "알겠니?",
  str_homestory_chat_32825011 = "...완전히 이해했어, 빅토리아 선생님!",
  str_homestory_chat_32999999 = "지금까지 참회한 일은 뭐가 있습니까?",
  str_homestory_chat_32921001 = "게임에 빠져서 3일 동안 잠을 못 잔 거.",
  str_homestory_chat_32921002 = "「게임」...? 그건 무엇입니까?",
  str_homestory_chat_32921003 = "악마야.",
  str_homestory_chat_32921004 = "악마...! 암귀나 사도 같은 비열한 괴물입니까?",
  str_homestory_chat_32921005 = "제가 지켜드리겠습니다, PlayerName 씨. 그것이 곧 주께서 제게 「성혈」의 힘을 주신 이유입니다.",
  str_homestory_chat_32921006 = "「성혈」도 게임 앞에선 무력해...",
  str_homestory_chat_32921007 = "게임이라는 이름의 악마는 즐거움을 미끼로, 내 청춘을 망쳐놓고 재산을 매장시켜...",
  str_homestory_chat_32921008 = "아무리 강한 전사라도 녀석의 손아귀에서 벗어날 수 없어!",
  str_homestory_chat_32921009 = "하지만... 그건 그저 당신이 저항하지 않고 유혹에 몸을 맡겼기 때문인 듯합니다.",
  str_homestory_chat_32921010 = "날 지켜줘...",
  str_homestory_chat_32921011 = "다음에 또 그로누가 게임으로 유혹해 오면, 네가 내 앞에 서서 지켜줬으면 좋겠어!",
  str_homestory_chat_32921012 = "그로누...?",
  str_homestory_chat_32921013 = "지옥에서 게임을 다스리는 마왕이야. 걔가 없었으면 나도 이렇게 되진 않았을 텐데...",
  str_homestory_chat_32921014 = "그건... 다른 사람에게 책임을 떠넘기고 있는 거 아니십니까?",
  str_homestory_chat_32921015 = "당신이 진정으로 참회해야 할 것은 그게 아니었습니까?",
  str_homestory_chat_32921016 = "으앗...! 이 이야기는 여기까지 하자. 그럼, 안녕!",
  str_homestory_chat_32922001 = "레스토랑에서 과일 탑을 만든 거.",
  str_homestory_chat_32922002 = "과일 탑?",
  str_homestory_chat_32922003 = "그런 레스토랑 있잖아? 메인 요리를 주문하면 과일샐러드 바를 자유롭게 먹을 수 있는 곳 말이야.",
  str_homestory_chat_32922004 = "양은 원하는 만큼 가져갈 수 있지만, 대신 담는 건 한 번만 가능해.",
  str_homestory_chat_32922005 = "어떻게 한 접시에 많은 샐러드를 담는지는 약간의 솜씨가 필요한 일이거든.",
  str_homestory_chat_32922006 = "그래서 당신은 접시에 과일로... 탑을 만들었다는 것입니까?",
  str_homestory_chat_32922007 = "그, 그런 슬픈 눈으로 보지 마...",
  str_homestory_chat_32922008 = "진짜 고급 기술이 필요한 거라구!",
  str_homestory_chat_32922009 = "...그렇게 자랑할 일이라면 왜 참회하셨습니까?",
  str_homestory_chat_32922010 = "다 먹었는데, 집에 와서 3일 동안 배탈이 났거든...",
  str_homestory_chat_32922011 = "그럼 당신은 이미 주님의 벌을 받고 죄를 씻어내셨군요, PlayerName 씨.",
  str_homestory_chat_32922012 = "네 눈빛이 다시 부드러워진 건 좋은데, 뭔가 좀 이상한 느낌이란 말이지...",
  str_homestory_chat_32923001 = "과속 운전...",
  str_homestory_chat_32923002 = "과속...? 콜로서스에도 제한 속도가 있었던 겁니까?",
  str_homestory_chat_32923003 = "지금은 하늘을 자유롭게 날 수 있지만...",
  str_homestory_chat_32923004 = "많은 콜로서스들이 날아다니던 시절에는 암묵적인 「속도 제한」이 있었다고 해.",
  str_homestory_chat_32923005 = "다른 콜로서스나 새의 안전을 위해서 만들어진 건데, 난 평소에 습관처럼 그걸 지켜왔어.",
  str_homestory_chat_32923006 = "그럼 왜 과속을 하셨던 겁니까?",
  str_homestory_chat_32923007 = "바이스의 생일이었거든.",
  str_homestory_chat_32923008 = "하루 50개 한정 초호화 과일 케이크를 사려고 급하게 움브라톤에 가던 참이었어.",
  str_homestory_chat_32923009 = "카렌의 생일이었거든.",
  str_homestory_chat_32923010 = "난 급하게 백야성 생일 파티로 향하고 있었고, 중간에 세탁소에서 연회복을 받아야 했거든...",
  str_homestory_chat_32923011 = "그랬습니까...",
  str_homestory_chat_32923012 = "그 아가씨를 위해서였다면 당신 탓을 할 순 없겠군요.",
  str_homestory_chat_32923013 = "게다가 이미 충분히 참회하셨겠죠?",
  str_homestory_chat_32923014 = "무, 물론이지!",
  str_homestory_chat_32923015 = "누구에게도 속박받지 않으면서도, 당신은 일족의 관습을 지키고, 게다가 그걸 어긴 것을 참회하시는군요.",
  str_homestory_chat_32923016 = "당신의 고결한 도덕심에 감복했습니다.",
  str_homestory_chat_32923017 = "진리의 주인의 가호가 당신과 함께하길.",
  str_homestory_chat_32923018 = "고마워... 아니, 나도 그분한테 감사할게!",
  str_homestory_chat_32924001 = "작심삼일...",
  str_homestory_chat_32924002 = "무슨 일이든 꾸준히 하질 못하는 겁니까?",
  str_homestory_chat_32924003 = "응... 특히 운동을 하기로 결심했을 때는 항상... 크흠...",
  str_homestory_chat_32924004 = "몸을 단련하는 것은 고통스러운 일입니다. 저도 경험해 보았고, 당신의 마음은 이해합니다.",
  str_homestory_chat_32924005 = "무리할 필요는 없습니다. 당신의 힘은 육체에 있는 것이 아닙니다.",
  str_homestory_chat_32924006 = "운동에는 적합하지 않더라도, 당신에게 계속할 수 있는 일이 있을 겁니다. 그렇지 않습니까?",
  str_homestory_chat_32924007 = "아마... 있을 거라고 생각해...",
  str_homestory_chat_32924008 = "예를 든다면요?",
  str_homestory_chat_32924009 = "먹는 거... 자는 거...",
  str_homestory_chat_32924010 = "......",
  str_homestory_chat_32924011 = "다른 것도 있어! 예를 들어...",
  str_homestory_chat_32924012 = "...숨 쉬는 거...?",
  str_homestory_chat_32924013 = "......",
  str_homestory_chat_33099999 = "어떤 책을 좋아하느냐.",
  str_homestory_chat_33021001 = "소설이요.",
  str_homestory_chat_33021002 = "재미있군.",
  str_homestory_chat_33021003 = "알고 있느냐? 너희들이 「소설」이라고 부르는 것은 사실 역사가 그리 길지 않다.",
  str_homestory_chat_33021004 = "내 시대에도 이제 막 발전을 시작하던 정도였지.",
  str_homestory_chat_33021005 = "처음 들었어요!",
  str_homestory_chat_33021006 = "소설은... 오래전부터 있던 거 아닌가요?",
  str_homestory_chat_33021007 = "그것은 흔한 인식의 오류다. 인문, 사회와 관련된 새로운 개념들을 오래전부터 있었던 것으로 오해하는 것이지.",
  str_homestory_chat_33021008 = "소설뿐만 아니라, 「유년기」, 「애정」, 「이성」 같은 개념들도 모두 근대에 생겨난 산물이다.",
  str_homestory_chat_33021009 = "너희들은 한번 익숙해지고 나면 그것이 없는 삶을 상상할 수 없게 되고...",
  str_homestory_chat_33021010 = "그래서 「예로부터 있다」는 오해가 생기는 것이다.",
  str_homestory_chat_33021011 = "조금 믿기 어려워요.",
  str_homestory_chat_33021012 = "옛날 오로리안들한테는 읽을 이야기가 없었던 건가요?",
  str_homestory_chat_33021013 = "옛날에는 서사시, 연극, 우화가 있었다. 그것들은 이야기의 요소가 있긴 했지만, 소설과는 크게 다르지.",
  str_homestory_chat_33021014 = "나도 최근에 서점에서 잘 팔리는 소설 몇 권을 읽어봤다. 서사시와 비교해 본다면...",
  str_homestory_chat_33021015 = "줄거리가 더 복잡해졌고, 감정은 더 섬세해졌다. 이것은 사회가 풍요로워지면서 생겨난 결과일 것이다.",
  str_homestory_chat_33021016 = "100년 전의 오로리안들에겐, 이렇게 많은 「무용」한 것을 생각할 여유는 없었다.",
  str_homestory_chat_33021017 = "역시... 빌헬름 씨랑 이야기하면 정말 식견이 넓어진다니까요!",
  str_homestory_chat_33022001 = "역사책이요.",
  str_homestory_chat_33022002 = "그 나이에 역사에 관심을 가지다니 드문 일이군.",
  str_homestory_chat_33022003 = "역사책을 읽는 것은 좋지만, 한 권의 책에 기록된 것이 진실의 전부라고 생각하지 말아야 한다.",
  str_homestory_chat_33022004 = "알고 있어요, 빌헬름 씨. 「역사는 승자에 의해 이야기된다」고 말하고 싶은 거죠?",
  str_homestory_chat_33022005 = "그 말은 권력자가 일부러 역사를 왜곡한다는 것만을 반영하나, 실제로는 더 복잡하다.",
  str_homestory_chat_33022006 = "설령 역사학자가 역사를 쓸 때 「진실을 복원한다」는 선의밖에 없더라도...",
  str_homestory_chat_33022007 = "자신이 살아가는 시대의 정신적 풍조의 영향을 받게 된다.",
  str_homestory_chat_33022008 = "그들이 남긴 것은 「자기 시대의 사람들이 본 역사」일 뿐이지 「역사」 그 자체는 아니다.",
  str_homestory_chat_33022009 = "그럼... 역사는 정확히 복원될 수 없다는 건가요?",
  str_homestory_chat_33022010 = "역사책을 읽은 젊은이답군. 이른바 「역사와 진실」의 역설을 간파하고 있다니 말이야.",
  str_homestory_chat_33023001 = "시요.",
  str_homestory_chat_33023002 = "훗, 너는 때로는 성숙해 보이면서도, 젊은이다운 취향도 가지고 있군.",
  str_homestory_chat_33023003 = "「청춘이 지나기 전에 요절하는 것은 시인에게 있어 행운이다」, 이 말에 대해 어떻게 생각하느냐.",
  str_homestory_chat_33023004 = "동의해요.",
  str_homestory_chat_33023005 = "그 생각은 위험하다.",
  str_homestory_chat_33023006 = "시를 쓰려면 청춘의 열정이 필요하지. 그리고 그 열정이 사라지면 시정도 고갈된다. 그렇다면 일찍 죽는 것이 낫다...?",
  str_homestory_chat_33023007 = "태울 수 없는 생명에 살 가치는 없다, 그렇게 생각하는 거냐?",
  str_homestory_chat_33023008 = "물론 저 자신은 그렇게 생각하지 않아요. 하지만 시인에겐 어떨까요?",
  str_homestory_chat_33023009 = "어떤 사람은 어떤 일을 자기 인생의 전부로 여기기도 하잖아요.",
  str_homestory_chat_33023010 = "인생의 전부라... 내게는 주께 다가가는 길이 그것이라 할 수 있겠지.",
  str_homestory_chat_33023011 = "너는 강한 통찰력이 있군, PlayerName.",
  str_homestory_chat_33023012 = "동의할 수 없어요.",
  str_homestory_chat_33023013 = "설마 너는 「선천설」에 비판적인 것이냐.",
  str_homestory_chat_33023014 = "그게 왜 그렇게 되죠?",
  str_homestory_chat_33023015 = "모든 문학 중에서도 시만큼 재능을 필요로 하고, 재능을 연소시키는 것은 없다.",
  str_homestory_chat_33023016 = "많은 대시인들은 십 대나 이십 대에 유명해졌고, 맹렬하게 타오른 후에 재가 되어 조용히 사라져갔다.",
  str_homestory_chat_33023017 = "허나 너는 그런 운명을 부정하는 것이겠지.",
  str_homestory_chat_33023018 = "살아있는 한, 세상을 있는 힘껏 보아 온 영혼을 통해 신이 주시는 시정을 따라잡을 수 있다.",
  str_homestory_chat_33023019 = "그렇게 생각하는 것이냐.",
  str_homestory_chat_33023020 = "음... 왠지 맞는 것 같아요. 전 「청춘」 같은 걸로 삶을 제한하는 건 나쁘다고 생각해요.",
  str_homestory_chat_33023021 = "잘 생각해 보면 결국 빌헬름 씨 말이랑 같은 뜻이네요.",
  str_homestory_chat_33023022 = "근데 전 아무리 노력해도 빌헬름 씨처럼 표현하진 못하겠어요! 빌헬름 씨는 정말 대단한 것 같아요...!",
  str_homestory_chat_33024001 = "과학 서적이요.",
  str_homestory_chat_33024002 = "「과학」이라... 대중에게 혜택을 가져다주는 면에서는 확실히 중요한 역할을 하지.",
  str_homestory_chat_33024003 = "하지만 현재의 과학 체계에서 오로리안은 진리로부터 점점 더 멀어질 뿐이다.",
  str_homestory_chat_33024004 = "네? 왜요?",
  str_homestory_chat_33024005 = "빅토리아가 「진리란 다차원적인 것」이란 말을 네게 한 적이 있었나?",
  str_homestory_chat_33024006 = "네! 자주 그랬어요!",
  str_homestory_chat_33024007 = "비밀은 거기에 있다.",
  str_homestory_chat_33024008 = "과학은 예측 가능한 기초 위에 성립되지.",
  str_homestory_chat_33024009 = "1만 번 반복해서, 매번 같은 결과가 나와야 「과학적 결론」이라 할 수 있는 것이다.",
  str_homestory_chat_33024010 = "허나 진리는 만에 하나의 불꽃 속에 존재한다.",
  str_homestory_chat_33024011 = "그걸 엿볼 수 있는 것은 한순간이지. 그리고 그 순간을 몇 번 보아도 매번 다를 것이다.",
  str_homestory_chat_33024012 = "이해할 수 있느냐.",
  str_homestory_chat_33024013 = "이해했어요.",
  str_homestory_chat_33024014 = "거짓말이다. 내가 이 정도 말한 것으로도 이해할 수 있다면, 진리의 결사는 뭘 위해 존재한단 말이냐.",
  str_homestory_chat_33024015 = "......",
  str_homestory_chat_33024016 = "모르겠어요.",
  str_homestory_chat_33024017 = "문제없다. 과학을 좋아한다면 더 많이 배워두는 것도 좋다.",
  str_homestory_chat_33024018 = "과학이 궁극의 수준까지 발전한다면, 그 또한 진리에 이르는 길이 될지도 모르니 말이야.",
  str_homestory_chat_33025001 = "신학 서적이요.",
  str_homestory_chat_33025002 = "?",
  str_homestory_chat_33025003 = "...음, 이해했다.",
  str_homestory_chat_33025004 = "최근에 네가 읽고 있다던... 그, 뭐라고 했었지? 「판타지 소설」이라고 했었나? 게다가 신화를 원전으로 삼는 그런 서적 말이다.",
  str_homestory_chat_33025005 = "그래서 그 안의 개념이나 설정에 관심을 가지게 된 건가?",
