  str_homestory_chat_33025010 = "맞아요. 빌헬름 씨 이야기는 늘 재미있는데, 저도 가끔은 뭔가 대답할 수 있었으면 좋겠거든요.",
  str_homestory_chat_33025011 = "...아, 혹시 이런 마음으로 신학 책을 읽는 건 너무 경솔한 건가요?",
